DELETE FROM reflections;

INSERT INTO reflections (day, month, title, text) VALUES (1, 'Январь', 'МЕН – ЕРЕКШЕ АДАММЫН', 'Бүгін өміріміздегі ең маңыздысы – ғажайып орнап, Жаратушының жүрегіміз бен өмірімізге енгеніне шынайы сенім білдіру. Ол біз үшін, өз күшімізбен істей алмаған дүниені істей алды.

Бүгінгі күн - бұл өмірімнің шындығы және шынайы ғажайыбы. Мен әрқашан Құдайға сенетінмін, бірақ, сол сенімімнің мәнін өміріме енгізе алған емеспін. Бүгін Анонимді Алкоголиктердің арқасында, Жаратушыға сенемін және оған арқа сүйеймін. Мен Оны өзімнің таным-түсінігіме қарай қабылдаймын. Соның арқасында бүгін саумын! Мен, өз бетімше Құдайға сенуді және оған арқа сүйеуді үйрене алмаған адаммын. Енді, ғажайыптарға сенемін, себебі өзім де ғажайып жанмын!');
INSERT INTO reflections (day, month, title, text) VALUES (2, 'Январь', 'АЛДЫМЕН ІРГЕТАС', 'Мүмкін, рухани оянудан күткеніміз тек сау болу шығар? Жоқ, сау болу – бұл тек бастамасы.

АА бағдарламасын қолдану үйдің құрылысына ұқсас. Біріншіден, мен үйдің қабырғасын көтеру үшін берік іргетасын құюым керек. Бұл - ішімдікті қоюдың белгісі. Бірақ, сіз іргетаста ыстық, суық, жел мен жаңбырдан қорғансыз өмір сүре алмайсыз. Сондықтан, мен бағдарламаны іс жүзінде қолдана отырып, іргетастың үстіне үй тұрғыздым. Алғашқы үйім тәжірибем аз болғандықтан сапасыз болды. Алайда уақыт өткен сайын Бағдарлама бойынша жұмыс істеп жақсырақ салуды үйрендім. Қаншалықты көп жұмыс істесем, соншалықты жайлы және бақытты үйді сәтті салып, қазіргі уақытта мен сонда тұрамын.');
INSERT INTO reflections (day, month, title, text) VALUES (3, 'Январь', 'ӘЛСІЗДІК', 'Біз, алкогольдің алдында әлсіздігімізбен қатар, өзімізді бақылай алмайтынымызды мойындадық.

Әлсіздік Бірінші Қадамда айтылуы кездейсоқ емес. Алкогольдің алдында әлсіздігіңді мойындау, бәрін қалпына келтірудегі іргетастың ең негізгі бөлшегі. Ақырында бойымда өзім ойлаған

«күш пен бақылау» жоқ екенін түсіндім. Басқалардың мен туралы не ойлайтынын өзгертуге дәрменсізбін. Автобусқа кешіккен кезде шарасызбын. Өзгелер Қадамдар бойынша қалай жұмыс істейтінін немесе жұмыс істемейтінін бақылауға дәрменсізбін. Бірақ, кейбір нәрселер алдында дәрменсіз емес екенінімді білдім. Айналамдағы адамдарға деген көзқарасыма, сондай-ақ, әлемді теріс қабылдауға дәрменсіз емеспін. Өз қалпыма келуіме жауапты болуға дәрменсіз емеспін. Мен, өзімнен бөлек, жақындарыма және өмір сүріп жатқан ортама оң әсер етуге мүмкіндігім бар.');
INSERT INTO reflections (day, month, title, text) VALUES (4, 'Январь', 'ЖАҚЫНДАРЫҢА БЕТ БҰРУ', 'Біз ішуді тоқтату бұл тек бастамасы деп санаймыз. Бірақ қағидаларымызды өз үйімізде, жұмысымызда және жалпы барлық іс- әрекеттерімізде көрсету әлдеқайда маңызды.

АА-дағы адамдармен жақсы қарым-қатынаста болу маған әдетте қиын емес. Мен сау болуға тырысқанда, АА-дағы серіктестеріммен маскүнемдіктің тозағынан құтылғанымызды атап өтемін. Көп жағдайда Бағдарлама бойынша ескі және жаңа достармен қуанышты жаңалықтармен бөлісу қиын емес. Алайда, үйде немесе жұмыста жағдай басқаша болуы мүмкін. Бұл жерде күнделікті өмірдің ұсақ-түйек қиындықтарында күлімсіреп немесе жылы сөз айтып, тыңдауға дайын болу қиын. Сол сәтте АА-дан тыс уақытта Он Екі Қадам сынға түседі.');
INSERT INTO reflections (day, month, title, text) VALUES (5, 'Январь', 'ТОЛЫҚ ҚАБЫЛДАУ', 'Ол алкогольсіз өмірді елестете алмайды. Содан кейін, ол, тек алкогольсіз ғана емес, сонымен қатар ішімдіксіз өмірді де елестете алмайтын уақыт келеді. Ол тек бірнеше адамға ғана белгілі жалғыздыққа тап болып, өзін жардың шетінде тұрғандай сезінеді. Өлгісі келеді.

Мұндай мәлімдеменің шынайы мәнін тек маскүнем ғана түсіне алады. Мені белсенді маскүнемдік үрей мен абыржуда қалдырып екіұшты ойға жетеледі. «Егер, ішпесем, өлемін» немесе «егер, ішуді жалғастырсам, бұл менің түбіме жетеді» деген оймен күрестім. Екі ой да мені құрдымға қарай сүйреді. Бірақ бұл құлдырау менің маскүнемдігімді толық қабылдаудың бастамасы болып, қалпыма келуім үшін керек дүние еді. Бұрын-соңды дәл мынадай таңдауға түспегенмін. Осы жағдай Бағдарламада табысқа жетуім үшін қажет екенін түсіндім.');
INSERT INTO reflections (day, month, title, text) VALUES (6, 'Январь', 'ЖЕҢІЛІС - ЖЕҢІС ӘКЕЛЕДІ', 'Біз айқын жеңіліс тапқан кезде ғана, күш пен еркіндік жолына түсуге мүмкіндік алатынымызды түсінеміз. Толық дәрменсіздікті мойындау, түптеп келгенде бақытты, мақсатты өмір құруға болатын нық негіз болып табылады.

Алкоголь өмірімнің барлық қырларына ықпал етіп, шөлмексіз өзімді жеңіл сезіну тұрмақ, тіпті, қозғала алмай қалғанда, ішімдікті өз күшіммен жеңе алмайтынымды түсіндім. Ақыры тізе бүгуден басқа амалым қалмады. Тізе бүктім. Артынша жеңіске жеттім. Қандай жеңіс десеңіз, бойымдағы менмендік, қырсықтықты жуып- шаюға тырысқан көңіл кеселімен күресте жеңіске жеттім. Бәрімен және барлығымен күресуді тоқтатқан кезде ғана сау-салауатты жан тыныштығына жетелейтін жолмен жүре бастадым.');
INSERT INTO reflections (day, month, title, text) VALUES (7, 'Январь', 'БҰРЫЛЫС СӘТІ', 'Жағдайға салғыртық танытып, ат үсті қарау бізді ештеңеге жеткізбеді. Біз бұрылыс сәтіне келдік. Бәрінен бас тартып, Тылсым Күштің өз қамқорлығына алып, қорғауын өтіндік.

Мен, күн сайын жолайрық алдында тұратынмын. Санамдағы ойлар мен әрекеттерім өсуіме септігін тигізгенмен, бірақ, олар мені ескі әдеттеріммен қатар, ішімдікке итермелеуі мүмкін. Дұрыс таңдау барлық істің бастамасы. Мысалы, біреуді айыптаудың орнына қолдау көрсетесің, өзіңе сенудің орнына өзгелердің көмегіне жүгінесің. Бұрылыс сәтінде ешқандай өкпе-реніштің негізсіз екенін түсініп, өзімді аяп, іштей жеудің қажет еместігіне көз жеткіземін. Күн сайын тұрмыстағы кемшіліктер көзден тасада қалмай, әрдайым мені азғырумен болады. Сол себепті мінезім де құбылып тұрады: өзімді айыптау, ашу, қорқақтық, тәкаппарлық, кекшілдік және менмендік. Бұл кемшіліктерді жоюға қарыс қадам жасап әрекет ету менің өзгеруге деген талпынысымды тежейді. Тек Жаратушыға шынайы сеніммен жүгінгенде ғана, шын мәнінде өзгергім келеді және өзгерте аламын.');
INSERT INTO reflections (day, month, title, text) VALUES (8, 'Январь', 'МЕНІҢ ТАҢДАУЫМ БАР МА?', 'Шындығында, қандай да бір себептермен алкогольге қатысты таңдау мүмкіндігін жоғалтқан адамдардың көбі — алкоголиктер. Біздің ерік-жігеріміз деп аталатын нәрсе іс жүзінде жойылады.

Мен ішуді тоқтатқан кейін, алкогольдің алдында дәрменсіздігім жоғалып кетпейді. Сау кезімде де менің әлі таңдауым жоқ, мен іше алмаймын. Менде бар мүмкіндік — бұл «рухани құралдар жиынтығын» пайдалану («Анонимді Алкоголиктер», 24-бет). Сол рухани құралдар жиынтығын пайдалағанда, Тылсым Күш мені таңдау болмауынан босатып, тағы бір күн сау етеді. Егер, ішпейтініме өзім кепіл бола алсам, маған, АА мен Тылсым Күш не үшін қажет болды?');
INSERT INTO reflections (day, month, title, text) VALUES (9, 'Январь', 'ҚҰДАЙДЫҢ ҚАЛАУЫ', 'Алкогольге деген ессіз құштарлық бойымызды билеп алғаны соншалық, тек Құдайдың қалауымен ғана одан құтыла алатынымызды мойындамасқа амал жоқ.

Менің өмірімдегі Құдайдың ықпалы маскүнемдікке байланысты құлдырауға жеткен кезде орын алды. Бір кезде өмірімде маңызды болғанның бәрі өз құнын жоғалтты. АА-ға қоңырау шалдым, және сол сәттен бастап өмірім түбегейлі өзгерді. Осы ерекше бұрылыс сәті туралы ойланған сайын, рухани құндылықтарды мойындап, қабылдауға мүмкіндік алғанға дейін, мені Құдай сақтап келгенін түсіндім. Құдайдың қалауымен қолыма стакан ұстамадым да, сау да, сергек жолмен жүріп өттім. Бар өмірім Құдайдың қамқорлығымен және оның көрсеткен бағытында дамып келеді. Мен алкогольдің алдында дәрменсіз екенімді және өмірімнің бақылаусыз екенін мойындаған бірінші Қадам маған күннен-күнге өміріме мән дарытады. Сондай-ақ, жанымызды сақтап қалатын, жаңа ғұмыр сыйлайтын жол Анонимді Алкоголиктер Достастығында.');
INSERT INTO reflections (day, month, title, text) VALUES (10, 'Январь', 'КЕМЕДЕГІНІҢ ТІЛЕУІ БІР', 'Біз, бәрін қалпына келтірудің алғашқы Қадамы алкоголик екенімізді толық мойындау екенін түсіндік. Біз, басқа адамдар сияқты емес екенімізді немесе бір күні сондай болатынымыз туралы елесті толығымен тастауымыз керек.

Мен, АА-ға алкоголь алдында өзімді бақылай алмайтыным үшін келдім. Мүмкін, әйелімнің ішімдікке қатысты наразылығы немесе шерифтің АА жиналыстарына қатысуға мәжбүрлеуі, жүрегімнің түкпірінде басқа адамдар сияқты іше алмайтынымды білетінім итермелеген шығар... Бірақ, оны мойындауға дайын емес едім. Себебі, ішімдікті тоқтату туралы ойдың өзі, мен үшін қорқынышты болды. Анонимді Алкоголиктер – бұл өлімге әкелетін

ауруға қарсы бірігетін ерлер мен әйелдердің Достастығы. Біздің өміріміз ашық теңізде суға батқан адамдар сияқты. Яғни, кемедегінің тілеуі бір. Егер, барлығымыз бірге жұмыс жасасақ, жағалауға сәтті жете аламыз.');
INSERT INTO reflections (day, month, title, text) VALUES (11, 'Январь', 'ЖҮЗ ПАЙЫЗ', 'Біз, тек Бірінші Қадамда, яғни, алкогольдің алдында дәрменсіз екенімізді жүз пайыз мойындаған кезде ғана, шексіз кемелдікке қол жеткіземіз.

АА-да саулыққа жетпей тұрып-ақ, алкоголь мені өлтіретінін білетінмін. Бірақ мұны білсем де, ішімдікті қоя алмадым. Сондықтан, Бірінші Қадаммен танысқанда ішімдік алдында дәрменсіз екенімді мойындау маған қиынға түспеді. Бірақ, ешқашан өмірімді басқара алмай жүргенімді мойындаған емеспін?! АА-ға келгеннен кейін, бес ай өткен соң, мен қайтадан іше бастадым. Бірақ себебін түсіне алмадым. Кейінірек, маңдайға тиіп, АА-ға қайта оралған кезде, Бірінші Қадам жүз пайыз жасалуы мүмкін жалғыз Қадам екенін түсіндім. Жүз пайыз жасау үшін жалғыз әдіс — бұл Қадамды жүз пайыз орындау. Бұл жағдай көп уақыт бұрын болды. Сондықтан, маған Бірінші Қадамды қайтадан жасау қажет емес.');
INSERT INTO reflections (day, month, title, text) VALUES (12, 'Январь', 'ҚАЗІРГІ ЖАҒДАЙДЫ ҚАБЫЛДАУ', 'Біздің ең негізгі міндетіміз — өміріміздің жағдайларын, өзімізді және айналамыздағы адамдарды да сол қалпында қабылдау. Бұл саналы түрде мойынсұну алға жылжуды қажет ететін дүние. Біз қайта-қайта осы бейтарап сәтке оралуымыз керек. Бұл «қабылдау» жаттығуын күнделікті істеп тұрудың пайдасы болмаса, зияны жоқ.

Егер, бойымыздағы үрейді, әр істе сылтау айтатын немесе енжарлық танытып қолды бір сілтейтін кертартпа қылықтарымызды өмірге шынайы баға бере алатын қасиетке алмастыра алсақ, эмоционалды денсаулықтың берік негізі бола алады. Сондай-ақ, рухани дамуға қажетті материал болмақ.

Айналаммен қарым-қатынасым қиындағанда, қалыптасқан жағдайды қабылдауда бір ауырлық сезінсем, осы үзіндіге жүгінемін. Ол мені өзгелерге деген немесе өмірдегі жағдайларға қатысты көптеген жасырынып жатқан қорқыныштарымнан босатады. Бұл ой маған кемелдіктен гөрі, адам болып қалуға және жан тыныштығымды сақтауға мүмкіндік береді.');
INSERT INTO reflections (day, month, title, text) VALUES (13, 'Январь', 'БІР КҮНДЕ БОЛМАЙДЫ', 'Біз алкоголизмнен айықпадық. Тек бізге күн сайын рухани өсу жолындағы шартта теріс әдепті кейінге қалдыруға үкім береміз.

Бәлкім, алкоголь туралы ең көп тараған иллюзия: «Егер мен жай ғана ішпесем, бәрі жақсы болады». Бірақ тұман сейілгенде, өмірімнің қандай ретсіз екенін көрдім. Отбасыммен, жұмысыммен, ақшамен және әділет жолына келгенде мәселелер туындады. Ескі діни-нанымдарға жармасып қалдым. Мінезімдегі кемшіліктер үмітсіздікке бой алдырып, қайтадан құлдырауға итермелеуі мүмкін еді. Барлық мәселелерімді шешуді Үлкен Кітапқа тапсырдым. Бірақ бәрі бірден болған жоқ. Әрине, өздігінен де болмады. Бұл елеулі күш-жігерді қажет етті. Маған кез келген мәселеге тап болғанда Құдайдың мейірімі мен шапағаты қажет болды.');
INSERT INTO reflections (day, month, title, text) VALUES (14, 'Январь', 'ӨКІНІШКЕ ЖОЛ ЖОҚ', 'Біз өткенімізге өкінбейміз және оны толық ұмытып кеткіміз келмейді.

Мен, сау болған кезде, өмірімнің қандай бостыққа толғанын көріп, өзімді айыптау мен өкініш сезімдерін бастан кешірдім. Бағдарламаның Төртінші және Бесінші Қадамдары осы азапты өкініштерден айығуға пайдасын тигізді. Ішімдікке байланысты өзімшіл және әрдайым алкоголик екенімді жалтарып, ішкенімді

түсіндім. Енді өзімнің өткендегі ең жағымсыз тәжірибелерімнің де алтынға айнала алатынын көріп отырмын. Себебі сау алкоголик ретінде тәжірибемді серіктестеріммен, әсіресе жаңадан келгендермен бөлісе аламын. Мен, АА-да бірнеше жылдан бері саумын және өткеніме өкінбеймін. Мен, жай ғана Құдайдың сүйіспеншілігін түсінгеніме және Достастықтағы басқа адамдарға көмек көрсете алатыныма ризамын.');
INSERT INTO reflections (day, month, title, text) VALUES (15, 'Январь', 'ІШТЕГІ ҚАЙНАР-БҰЛАҚ', 'АА мүшелері өз ішінде бұрын беймәлім болған іштегі қайнар- бұлақты ашқанын және оны қазіргі түсінігінде өздерінен мықты Тылсым Күшпен сабақтастыратыны сирек құбылыс емес.

АА-дағы алғашқы күндерден бастап, әлі де сау өмір үшін күресіп жүргендіктен, осы сөздерден үміт табамын. Мені әрдайым:

«олар бұрын белгісіз болған іштегі қайнар-бұлақтың көзін қалай ашты?!» деген ой мазалады. Бірақ өзім дәрменсіз бола тұра іштегі күшті қалай табуға болатынын білмедім. Уақыт өте келе, Достастықтың негізін қалаушылары уәде еткендей: мен, әрқашан жақсылық пен жамандықтың, ізгілікпен пен өзімшілдіктің, мойынсұну мен үрейдің арасында таңдау болғанын түсіндім. Күнделікті АА-ның Он Екі Қадамы арқылы, сау өмірімді құрғанға дейін, менен мықты Күш, мен, ойламаған ырыздық пен берекені беретінін түсінбедім.');
INSERT INTO reflections (day, month, title, text) VALUES (16, 'Январь', 'ТҰҢҒИЫҚҚА ҚҰЛДЫРАУ', '«Тұңғиыққа  құлдыраудың»	не қажеті бар деп тұжырымдаймыз?! Себебі, бастарына тимей адамдардың көпшілігі шынайы түрде АА Бағдарламасының қағидаларын сақтай алмайды. АА мүшесі болғаннан кейін, қалған Он бір Қадамнан өту үшін кез келген маскүнемнің ойына келмейтін көзқарастарды қабылдап, іс- әрекеттер жасау керек.

«Тұңғиыққа құлдырау» менің көзімді ашты, және басқаша өмір сүруге тырыстым. Мен, АА-ны сынап көрдім. АА-дағы жаңа өмірім велосипед тебуді үйренуге ұқсас болды. АА велосипед рөлі және қолдаушы қолым болды. Сол кезде бұл көмекті қатты қалай қойған жоқпын, тек қайтадан құлап, соққы алғым келмеді. Құлдыраудан қорыққаным, ішімдікке деген құштарлығымды тежеді. Алғашында осы ниетім мені сау қалпымды сақтауға көмектесті. Бірақ біраз уақыттан кейін, Қадамдар бойынша бар күшімді салып жұмыс істеп жатқанымды байқадым. Көп уақыт өтпей-ақ, ойларым мен әрекеттерім аздап өзгергенін түсіндім. Күн сайын өзімді жақсы сезіне бастадым, басқа адамдармен қарым-қатынасым жақсарып, жан жарасына шипа табылып жазыла бастады. «Анонимді Алкоголиктер» деп аталатын бағыттаушы мен қолдаушы күш үшін, Құдайға алғысымды білдіремін.');
INSERT INTO reflections (day, month, title, text) VALUES (17, 'Январь', 'БАҚЫТ ҮНСІЗ КЕЛЕДІ', '«Біз, алкоголиктер, өзіміз қалаған ғаламның бақыт пен жан тыныштығына алкоголь арқылы жеткіміз келді. Алайда, жеңіліс таптық. Бірақ кейбір рухани заңдарды біліп, оларды терең қабылдап, іс жүзінде қолданған кезде, біз шынымен бақыт пен жан тыныштығына қол жеткізе аламыз. Бізді бақыт пен жан тыныштығына жеткізе алатын айқын ережелер кімге болмасын қол жетімді».

АА Бағдарламасының қарапайымдылығы бақытты «талап етуге» болмайтынын үйретеді. Ол өзгелерге қызмет еткен кезде үнсіз келеді. Мен, жаңадан қадам басқандарға немесе қайтадан қайтып келгендерге қол ұшын созғанда, саулығымның нығайып, ризашылық пен бақытқа бөленетінімді байқаймын.');
INSERT INTO reflections (day, month, title, text) VALUES (18, 'Январь', 'ІШІМДІКТЕН ПАЙДА БАР МА?', 'Өткендегі ішімдікке қатысты оқиғаларды еске түсірсек, бақылауды  жоғалтуымыз,  жылдар  бойғы  алкогольге  деген

құштарлығымыз жәй әдет болмағанын түсінеміз. Бұл құлдыраудың бастамасы еді.

Мен ішкенде, өзге сау адамдар сияқты, өмірлік жағдайларды шеше алмайтынмын. Болмашы бір оқиға мені сол сәтте-ақ шешім қабылдауға мәжбүр етті: бұдан құтылу үшін маған ішу керек. Бірақ ессіздік жағдайды жақсартпады, сонда да, қайтадан бөтелкеге жүгіндім. Бүгін өзімнің алкоголизмімнен қандай қасырет шеккенімді есте ұстауым керек. Өзімді алкоголь алдында бақылай аламын деп айта алмаймын. Ондай ойға ерік берсем, өмірімді бақылауда ұстаймын деген сенімнің жетегінде кетемін. Бұл «бәрін бақылауда ұстай аламын» деген жалаң түсінік, менің қалпыма келуіме кедергі келтіреді.');
INSERT INTO reflections (day, month, title, text) VALUES (19, 'Январь', '24 САҒАТ БОЙЫ СЕНІМНЕН АЖЫРАМАУ', 'Сенім, бізге 24 сағат иелік етіп жұмыс істеуі керек, әйтпесе, біз құримыз.

Менің руханиятым мен саулығымның негізі - Жоғары Күшке үздіксіз сенімімде. Мен мұны есте сақтап, күнделікті іс- әрекеттерімде Құдайға деген сенімімді жоғалтпауым керек. Құдайдың өзгелер арқылы белгі беретіні қандай жұбаныш! Тәулік бойы Құдайдың бар екеніне күмән келтірмей тұра аламын ба?! Оның ғажайыптарын сезініп, қуанамын ба?! Қалпыма келтірген Құдайдың ықпалына ризамын. Бұл Құдіретті Күш, менің барлық істеріме септігін тигізбесе, ауруымның түбіне түсіп, өлетін едім.');
INSERT INTO reflections (day, month, title, text) VALUES (20, 'Январь', 'КІДІРІС ЖАСАУ, СҰРАУ', 'Күні бойы қандай да бір күмән немесе алаңдаушылық туындаса, бір минут аялдап, Құдайдан дұрыс ой немесе әрекет сұрау керек.

Бүгін, Жоғары Күштен бір іске әрекет етердің алдында шамалы үзіліс жасап, шын ниетпен сұраймын. Әрекет етуге дайын болғанда, салқын желдің соғуын өтінемін. Тілім шабуылдауға немесе қорғануға оқталғанда, ашуымды көркем мінезге, зұлымдығым мейірімділікке айналғанша үнсіздікке жүгінемін.

Жоғары Күштен үкім сұрауға әрбір мүмкіндікті пайдаланамын. Бұл Күштің қай жерде екенін білемін. Бұрын белгісіз болған қайнар ішімде жасырынып тұрған екен.

Ғаламның шындығы мен жарық нұрға қарай, көзқарасымды бағыттауға мүмкіндік берген Жоғары Күшке алғыс айтамын. Жүйелі ой тауып, дұрыс әрекет етуіме ықпал ететініне үміттімін. Бұл жолда маған қолдау көрсетіп, қамқоршы болатынына сенімім мол.');
INSERT INTO reflections (day, month, title, text) VALUES (21, 'Январь', 'БАУЫРЛАРЫҢА КӨМЕК', 'АА мүшесі жаңадан келген адамға өзінің ықпалын емес, кішіпейілділік пен ізгілігін көрсетеді.

A. Comes of Age, 279-бет АА-да жүргенде Құдайдан ойларым мен сөздерімді оң бағытқа бағыттауын сұраймын. Достастық жұмысына қатысқанда, әрдайым сөз сөйлеу мүмкіндігіне ие боламын. Сондықтан, үнемі Құдайдан біздің Бағдарламамызды дұрыс жағынан көрсету үшін, әр ойымды, әр сөзімді түсінікті етсе деген тілегім бар. Сондай-ақ, руханият пен

кішіпейілдіктен алыстатпауын тілеймін.

Бүгін біреудің қолайсыз мінез-құлқы немесе жағымсыз мәлімдемесімен бетпе-бет келуім мүмкін. Бұл әлі де зардап шегіп жүрген алкоголик үшін қалыпты жағдай. Егер, бұлай болса, сабырлы кейіппен түсіністік танытып, ізгі ниетпен көмек көрсету үшін, бір минут кідіріс жасап, Құдайға қарай бет бұрамын.');
INSERT INTO reflections (day, month, title, text) VALUES (22, 'Январь', 'БӘРІ ҚАРАПАЙЫМ БОЛСЫН', 'Бірнеше сағаттан кейін доктор Бобтан кетуге дайындалып жатыр едім... Ол бір ерекше шырай танытты да, әзілдеп: «Билл,

ұмытпа, мұны бұзбайық. Бәрі қарапайым болсын!», - деді. Мен бұрылып ештеңе айта алмай қалдым. Бұл оны соңғы рет көргенім.

Бірнеше жылдық сау өмірден кейін, кейде өзімнен: «Шынымен бәрі осылай қарапайым ба?», - деп сұраймын. Содан кейін жиналыстарда АА жолымен тозақтан шығып, өмірлерін ішімдіксіз

24 сағатқа бөліп тастаған, бұрынғы пасықтар мен күмәншіл жандарды кездестіремін. Осы 24 сағат ішінде олар әрқайсысы өз мүмкіндіктеріне сәйкес АА-ның бірнеше қағидаларын іс жүзінде қолданды. Осы жағдайға қарап, бұл оңай емес екенін түсінемін. Сәйкесінше, қарапайым ережелерді сақтай алатын болсам, Бағдарламаның тиімділігі де сақталады.');
INSERT INTO reflections (day, month, title, text) VALUES (23, 'Январь', 'ҚУАНЫШТЫ КҮНДЕР АЛДА', '...біз қандай да бір жүзі солғын тартқан мұңды жандар емеспіз. Жаңадан қосылғандар кейінгі өмірімізден ешқандай қуаныш көрмесе, олар бізбен бірге болмас еді. Біз өмірден рахаттана алатынымызға сенімдіміз. Біз әлемдегі елдердің жағдайы туралы пасық пікір айтып, жаһандық мәселелерді өз мойнымызға алмаймыз.

Өз үйім ретті, әрі таза болғанда ғана, өмірімнің басқа мәселелерін шеше алатынымды көремін. Мен, маскүнемдіктің көптеген жылдарын қамтыған өзімді айыптау мен өкініш сезімдерінен құтылған кезде ғана, шынайы әлемде өз орнымды таптым. Бірақ бұл жағдайды қызғыштай қорып сақтау керек. Кейде өзімнен: "Менің қабағым жазылып, көңілім көтеріле ме?", - деп сұрауым керек. Егер, бұл сұрақ маған ауыр тиіп, жауап беруге қиналсам, онда әлі де өзімді тым маңызды сезініп жүргенім. Демек, Бағдарламадан ауытқығанымды, яғни, рухани шаңырағымның керегесі сөгіле бастағанын көрсетеді. Менің ойымша, Жоғарғы Күш ауыртпалық арқылы назарымды өзіне аударып, істеп жүрген әрекеттерімді қайта бағалауға үндейді. Бағдарлама бойынша жұмыс

істеп	шығындалған	уақыт	пен	күш-жігерім,	әлі-ақ	өміріме келтірілген залалды, еселеп қайтарады.');
INSERT INTO reflections (day, month, title, text) VALUES (24, 'Январь', 'ІСКЕ КІРІСУ', 'Әрдайым әрекет қажет. «Әрекетсіз сенім - өлі»... біздің жалғыз мақсатымыз — басқа адамдарға көмек көрсету.

Қызмет көрсету өмірді қалыпқа келтірудің маңызды бөлігі екенін түсінгеніммен, бірақ «Мен не істей аламын?» деген бір сұрақ бар. Сіз тек жақын ортаңыздан бастай аласыз! Бірінші кезекте айналаға қараймын да, қолымнан не келетінін саралаймын. Күлсалғыштар темекі тұқылдарына толы ма? Оларды тазалау алғашқы әрекетім болмақ! Үздік көшбасшының өте нашар кофе дайындауы, жаңадан келгендермен жақсы қарым-қатынас жасай алатын АА мүшесі оқығанда қиналып, ғимаратты жақсы тазалай алатын кісі банктік шотқа қатысты мәселелер туындатуы мүмкін. Бірақ, бұл адамдардың әрқайсысы және олардың жұмысы топтың тиімділігі үшін маңызды. Қызмет көрсетудің ерекшелігі неде?! Қолымнан келетін нәрсені істеген кезде, өзім ойлағаннан әлдеқайда көп мүмкіндіктер ашылатынын байқаймын.');
INSERT INTO reflections (day, month, title, text) VALUES (25, 'Январь', 'БІР-БІРІМІЗГЕ КЕРЕКПІЗ', 'Біз әр алкоголикке: «Егер, сіз, «АА мүшесімін» деп мәлімдесеңіз, сізді ешкім Достастық мүшесі болу құқығынан айыра алмайды...», - деп айтамыз.

Көптеген жылдар бойы мен Үшінші Дәстүр туралы ойлана отырып («АА мүшелігінің жалғыз шарты — ішуді тоқтатуға ниет білдіру»), бұл тек жаңадан келгендерге арналған деп ойладым, олар үшін АА-ға кіру мүмкіндігі жабылмайтынына кепілдік берді. Бүгінде бұл Дәстүрдің маған берген рухани дамуына үлкен алғысымды білдіремін. Өзімнен елеулі түрде ерекшеленетін адамдарды іздемеймін. Үшінші Дәстүр, мен үшін және басқа АА

мүшелерімен жалғыз ортақ нәрсені көрсетеді. Бұл маған әр түрлі алкоголиктерді түсініп, көмектесуге мүмкіндік берді, және олар маған көмектесті. Атеист Шарлотта маған этика мен ар-намыс стандарттарын көрсетсе, басқа нәсіл өкілі Клей маған шыдамдылықты үйреткен еді. Ал менің 30 жыл саулығымды көріп, жас Меган жиналыстардан қалмайтын болды. Үшінші Дәстүр бір- бірімізге керек нәрсені қамтамасыз етті.');
INSERT INTO reflections (day, month, title, text) VALUES (26, 'Январь', 'АДАЛДЫҚ КЕРЕК', 'Кім мінсіз, адал және төзімді болғысы келеді? Кім өзінің кемшіліктерін мойындап, басқа адамдарға келтірген залалды өтегісі келеді? Медитация мен дұға туралы айтпағанда, кімді Жоғары Күш ойландырады? Кім АА идеяларын басқа зардап шегушілерге жеткізу үшін, өз уақытын, энергиясын құрбан еткісі келеді? Егер, өмір сүруге деген ниет мәжбүрлемесе, өз уайымымен әуре болып жүрген маскүнемді мұндай мәселелер қызықтырмайды.

Мен - алкоголикпін. Егер, ішетін болсам, өлемін. Құдайым, қарапайым шындық бойымда бір ғажап күш энергия мен сезімдер тудырады! Бұл бүгінгі күні білуім тиіс дүние. Бүгін тірі қалғым келе ме? Бүгін сау болғым келе ме? Қазіргі сәтте өзім үшін көмек сұрауға және тағы бір зардап шегіп жүрген алкоголикке көмектесуге дайынмын ба? Жағдайымның өлімге әкелетін қауіптілігін түсіндім бе? Бүгін сау қалпымды сақтау үшін не істеуім керек?');
INSERT INTO reflections (day, month, title, text) VALUES (27, 'Январь', 'АЙЫПТАУДАН АРЫЛУ', 'Өзгелерге келетін болсақ, біз өз әңгімелеріміздегі, ойларымыздағы «кінә» сөзінен бас тартуымыз керек.

Мен дәрменсіздігімді қабылдауға тырысқанда, өмірімдегі барлық сәтсіздікке өзімді кінәлауым, мені қайтадан үмітсіздікке итермелейтінін түсінемін. Көмек сұрау және Қадамдар мен Дәстүрлердегі идеяларға терең назар аударсам, қалпыма келуге кедергі келтіретін факторлар өздігінен жоғалады. АА-ға келмей тұрып, өзіме сенімділікті табу үшін, ықпалды адамдардың қолдауына мұқтаж болатынмын. Бұл маған үнемі сәтсіздіктен басқа ештеңе бермеді. Бағдарламада мені жақсы көретін, түсінетін және шынайы болмысымды айқындауға көмектесетін жанашыр достарды таптым. Он Екі Қадамның көмегімен ар азабынан арылып, жақсы өмір сүре аламын.');
INSERT INTO reflections (day, month, title, text) VALUES (28, 'Январь', 'ӨТКЕН КҮННІҢ ҚАЗЫНАСЫ', '... өзгелер бізге ұқсас жағдайға тап болғанда, көмек қалай көрсетілгенін көрсету. Бұл өмірімізді құнды етеді. «Құдайдың қолындағы қара түнек өткеніміз, басқа да жандардың бақытқа жету жолындағы ең негізгі құндылығына айналады» деген ойдан ажырамағанымыз жөн. Сіздің бұралаң жолда сүрінгеніңіз бәзбіреудің өлім мен қайғыдан аулақ болуына септігін тигізеді.

Мен үшін бос өткен жылдардың, босқа кетпегенін анықтау қандай қуаныш! Бір кездегі құлдыраған, боркеміктігім басқа жандардың сауғуына ықпал ететін мықты құрал болып табылады. Ар-ұят пен үмітсіздікті басымнан өткеріп, терең сезінгендіктен, ыстық ықыласыммен жақыныма жанашырлық таныта аламын. Құдайдың да рақымынан кенде қалмайтыным түсінікті.');
INSERT INTO reflections (day, month, title, text) VALUES (29, 'Январь', 'БӨЛІСУ ҚУАНЫШ СЫЙЛАЙДЫ', 'Сіздің өміріңізге жаңа мән-мағына жүктеледі. Адамдардың қалай қалпына келіп, өз кезегінде өзгелерге көмектесе бастағанын, қалай жалғыздықтан арылғанын, сіздің айналаңызда бауырластық пайда болғанына назар аударыңыз. Ауқымды достар ортасы құнды

тәжірибелермен толыға түспек. Оны көзден таса қалдырып, елемеу жөн болмас. Біз сіздің одан бас тартпайтыныңызға сенімдіміз. Жаңадан келгендермен тығыз қарым-қатынаста болу, өміріңізге мән дарытып, әр күніңізді көркем ете түседі.

Достастықта, мен, қол жеткізген жеңілдіктерге, жаңадан келген жандар да, сол рахатты сезініп жатса, көңілім қуаныш пен шаттыққа бөленеді. Мен, алған әсерімді естен шығарған емеспін. Олар ұсынылған мүмкіндікті пайдаланып Бағдарламаны қабылдаса, АА Өз Уәделерін орындайтынына сенемін.');
INSERT INTO reflections (day, month, title, text) VALUES (30, 'Январь', 'ЖАҢАША ЕРКІНДІК', 'Біз жаңа еркіндікті сезінеміз...

Мен үшін «бостандық» деген - бір нәрседен азат болып, еркіндікте бір нәрсе істеу. Мен ләззат алатын бірінші еркіндік - алкоголь құлдығынан құтылу. Қандай жеңілдік! Кейіннен адамдардан, ақша жетіспеушілігінен, полицияның тұтқындауынан, сәтсіздіктен қорқу еркіндігіне қол жеткіземін. Әрмен қарай сау қалыпты таңдау, өзіммен өзім болу, өз пікірімді білдіру мен жан тыныштығын сезіну, сүю және сүйікті болу, сондай-ақ, рухани өсу еркіндігін ұната бастаймын. Бірақ, мен, бұл бостандықтарға қалай қол жеткізе аламын? Үлкен кітап маған келтірген залалдың жартысын өтегенде, жаңа еркіндікті біле бастайтынымды айтады. Бірақ бұрынғы түсініктегі сияқты, басқаларға назар аудармай қалағанымды істеу емес. АА Уәделерінің орындалуын қамтамасыз ететін жаңа Қадамдар жасау. Еркіндікте болу қандай қуаныш!');
INSERT INTO reflections (day, month, title, text) VALUES (31, 'Январь', 'БІЗДІҢ ОРТАҚ ИГІЛІГІМІЗ – БІРІНШІ ОРЫНДА', 'Біздің Дәстүрлерімізде тозаңдай тәкаппарлыққа жол берілмеуі тиіс. Бұл салауатты өмірге қол жеткізумен қатар, сау қалпымызды сақтау үшін қажет. Бірінші Дәстүр сау қалыпта жүруімді өз еңбегім ретінде бағалап, еншілеуге құқық бермейді. Сол себепті ортақ игілігімізді бірінші орынға қоямын. Мен, бұл Бағдарламада емші емеспін. Мен әлі де науқастардың бірімін. Атаққа таласпай, бұл аурухананы ардагер АА мүшелері салды. Онсыз, мен, аман қалмас едім. Топтан тыс қалпына келу мүмкіндігі бар алкоголиктер бар ма?

Тағы да өз еркімді кішірейте отырып, мен, үстемдік ету және атаққұмар ұмтылысынан аулақ боламын. Бұл ұмтылыстар менің алкоголизмнен айығу жолында басты рөл атқарды. Топтың ортақ игілігі үшін пасықтық жеке қалауымнан арылып АА бірлігіне үлес қоса аламын. Бұл қадам сау қалыпта ғұмыр кешуіме кепілдік береді. Үлкен ғаламның бөлшегі екенімді еске түсіруге көмектеседі.');
INSERT INTO reflections (day, month, title, text) VALUES (1, 'Февраль', 'СЕНІМГЕ КЕЛУ', '«...Екінші Қадамның мәні өміріме біртіндеп баяу ене бастады. Қазіргі сәтте өзімнен күшті Күшке сенгеніммен, бірақ қай кезден бастап, қандай себептерге байланысты сене бастағанымды нақты айта алмаймын».

«Сенімге келу!» Мен өз сенімімді тек сөз жүзінде ғана мойындайтынмын. Бұл әрекетім көңіл толқыған кездегі көзбояушылық еді. Шын мәнінде, Құдайға, оның шарапатына сенбейтінмін. Өзгерте алмайтын дүниелерді өзгерту үшін тырысатынмын. Кейіннен: «Егер, құдіретті болсаң, онда, Сен, бұл мәселені шеш», - деп бәрін Құдайға тапсыруды үйрендім. Сол сәттен бастап, ең өзекті мәселелеріме жауап таптым. Өзім шешімін таппаған мәселелерге жұмысқа бара жатқанда, түскі ас кезінде немесе ұйықтап жатқанда, қысқасы, күтпеген жерден Құдыретті Күштен үндеу ала бастадым. Менің сенбеске амалым болмады!');
INSERT INTO reflections (day, month, title, text) VALUES (2, 'Февраль', 'АМАН ҚАЛУДЫҢ АМАЛЫ БАР', 'Кәдімгі алкоголик өзін-өзі сүйетін өзімшілдік «менмендікпен» сипатталады. Өз қадіріне шаң жуытпас үшін барын салмақ. Іштей алкоголик қандайда бір бақылауды, не адам тарапынан, не Құдай тарапынан қабылдамайды. Алкоголиктің ойынша, ол, өз тағдырының иесі болуы керек. Алкоголик осы жағдайды сақтау үшін соңына дейін күреседі.

Құпияның құдыреті мынада: неге біреулер өз өркөкіректігінен бас тарта алмай алкогольден өледі, ал, басқалары керісінше, аз күш жұмсап, АА-да сау қалпын сақтап қалады? «Саулық» дейтін Жоғары Күштің шапағаты, маған, түсініксіз түрде ішімдікті қоюға деген ниетім арқылы бұйырды. Сондай-ақ, АА мүшелерінен көмек қабылдауға дайын болуыммен тұспа-тұс болған жайы бар. Мен, тек

Құдай мен достарымның көмегімен жан сақтай алғандықтан, өз дертімді мойындап, берілмеске амалым қалмады.');
INSERT INTO reflections (day, month, title, text) VALUES (3, 'Февраль', 'КЕУДЕДЕГІ БОСТЫҚТЫ ТОЛТЫРУ', 'Біз өзімізге тек бір қысқа сұрақ қоюымыз керек болды: «Мен өзімнен мықты Күштің бар екеніне сенемін бе немесе сенуге дайынмын ба?» Адам сенетінін немесе сенуге дайын екенін мойындаған бойда, біз оның дұрыс жолда екенін түсіндіруге тырысамыз.

Мен әрқашан ғылыми принциптерді зерттеумен әуестенетінмін. Шексіз білімге ұмтылу барысында, мен, адамдардан эмоционалды және физикалық тұрғыдан алшақ болдым. Құдай мен руханият мағынасыз теориялық идеялар болды. Мен ғылымның заманауи адамы едім, білім менің Жоғары Күшім болды. Өмір жай ғана дұрыс теңдеулер жиынтығын қажет ететін бір тапсырма болып көрінді. Сонымен қатар, алкоголь өмірімнің мәніне айналды. Біліміме қарамастан, алкоголь менің Жоғары Күшім еді. Тек АА жиналыстарындағы адамдардың шартсыз сүйіспеншілігі мен көмегінің арқасында, алкогольді Жоғары Күш ретінде қарамайтын болдым. Кеудемдегі үңірейген бос кеңістік толтырылды. Енді бұрынғыдай жалғыз қалып, өмірден бөлек болмадым. Мен өзімнен мықты шынайы Күшті таптым. Енді мен үшін маңызды жалғыз теңдеу бар. Ол: Құдай АА-да.');
INSERT INTO reflections (day, month, title, text) VALUES (4, 'Февраль', 'СЕНІМ ЖОҚ КЕЗДЕ...', 'АА қағидаларын сенімнен айырылған немесе сенімнен бас тартқандардың қабылдауы қиын. Себебі жалаң сенімге жүгінгендіктен, бұл әрекетті бос әуре санайды.

«Маған Құдайдың қайыры түспес» деген тым жалаң сенімде болдым. Мен не істеу керектігін жақсырақ білетінмін және соңғы рет ішімдікке осылай салындым. Менің сенімім ашуға айналды.

Үлкен сенім арқалағандықтан қатты құладым. Тіпті АА-ға келгеннен кейін де, сенімімді қайта тірілту үшін уақыт қажет болды. Ақырында, жантүршігерлік құлдыраудан аман қалғаныма ризашылығымды білдіргеніммен, жүрегім жабық қалды. Дегенмен, АА Бағдарламасынан айырылмадым, айрылған күні құритынымды түсіндім. Мен, жиналыстарға баруды жалғастырдым, біртіндеп сенімім қайта тірілді.');
INSERT INTO reflections (day, month, title, text) VALUES (5, 'Февраль', 'АРМАНДАҒАН ЕРКІНДІК', 'Мен, дауласуды тоқтатқанда ғана, көкірек көзім ашылып, әлемді қабылдай бастадым. Дәл сол кезде Екінші Қадамның қағидасы баяу болса да, өміріме мән дарытқан жайы бар. Мен, қазір өзімнен мықты Жоғары Күштің барына сенгеніммен, бірақ, Ол Құдыретке қай кезден, қандай жағдайлардан кейін сене бастағанымды айта алмаймын. Бұл жетістікке жету үшін барлық дау-дамайдан бас тартып, АА Бағдарламасының барлық тармақтарын ынта-жігермен орындауға тура келді.

Мен, көп жылдар бойы теріс әдетпен өмір сүрдім. Сол себепті жалғыз едім. Екінші Қадам арқылы толық жалғыздықтан құтылдым. Енді менің жолымда ауырлық немесе жете алмайтын жетістік, аса алмайтын асу жоқ. Енді әрқашан өмірдің қиындықтарымен бөлісетін Сырласым бар. Екінші Қадам менің Құдаймен байланысымды нығайтты. Енді менің ессіздігім мен менмендігім тығыз сабақтастықта екенін түсінемін. Мойнымдағы бірінші жүктен арылу үшін, екінші жүкті өзімнен мықты Біреудің арқасына артуым керек.');
INSERT INTO reflections (day, month, title, text) VALUES (6, 'Февраль', 'БАСТАПҚЫ НҮКТЕ', 'Сондықтан, Екінші Қадам бәріміз үшін бастапқы нүкте болып табылады. Агностиктер, атеистер және бұрынғы сенім иелері ретінде, біз, бұл Қадамды бірге жасай аламыз.

Мен, АА Бағдарламасы Құдайдың қалауымен құрылғанына, сондай-ақ, әр АА жиналысында Жаратушының бар екеніне көз жеткіземін. Бүгін сау қалпымды сақтауға септігін тигізген, АА мені құтқаратынына еш күмән келтіре алмаймын. Мен, АА жиналыстарына қатысу арқылы, өмірімді АА мен Құдайға арнаймын. Егер, Құдай менен бөлек, өзгелердің де жүрегінде болса, мен жеке тұлға емес, бөлінбес бір тұтаспын. Егер, Құдай менің жүрегімде болса, өзгелер арқылы маған жүгініп, мен арқылы басқа жандарға бір белгі береді. Мен, Жаратушының рухани қағидаларын ұстансам, ақысына мені кемел ақылмен, сау ақылмен және көркем мінезбен сүйіншілейді.');
INSERT INTO reflections (day, month, title, text) VALUES (7, 'Февраль', 'СЕНІМГЕ АПАРАР ЖОЛ', 'Шынайы кішіпейілділік пен бейтарап қарым-қатынас бізді сенімге апара алады. Егер, біз Құдайға түзу ниетпен бет бұрсақ, Ол біздің ақылымызды қайта қалпына келтіреді.АА-ның әр жиналысы оған кепіл бола алады.

Соңғы мас болуым шала-жансар күйімде ауруханаға жеткізді. Сол кезде бүкіл өмірім көз алдымнан өтті. Ішімдікке салынғандықтан, бір сүреңсіз, ит өмірмен ғұмыр кешкенімді көрдім. Менің ішімдікке деген құмарлығым мені елестің жетегінде жетелеп, есімнен тандырып, үмітсіздікке ұшыратты. Ақыры, мен Құдайдың көмегіне жүгіндім. Оның қалауымен сенімге бет бұрдым. Ішімдікке деген құмарлығым мен көңіл толқулары жоғалды. Мен енді қорықпаймын. Енді менің өмірім ауыртпалықсыз, саналы да, мәнді болмақ.');
INSERT INTO reflections (day, month, title, text) VALUES (8, 'Февраль', 'ЖҮРЕКТЕГІ КҮДІКТЕН АРЫЛУ', 'Табысқа жетсек те, шаттық пен тыныштық әлі де бізге алыстан қол бұлғайды. Мұнда көптеген АА-ның бұрынғы мүшелері сүрінеді. Бұл шынымен қарғыс атқан жер. Бойымызды билеген үрейден, бақылаусыз құмарлық пен жалған талапшылдықтан арылғымыз

келеді. Біздің қатал, мылқау күпірліктің көлеңкесі түскен жүрегімізді сендіру біздің басты міндетіміз болмақ.

Жиналыстарға жүйелі түрде қатысу, қызмет көрсету, өзгелерге көмектесу, бұл көптеген адамдар сынақтан өткізген тәжірибе. Осы негізгі қағидалардан ауытқығанда, ескі әдеттер қайта пайда болмақ. Бұрынғы үрей мен кемшіліктер кісінің бойында қайтадан үстемдік құрады. Әрбір АА мүшесінің басты мақсаты — тұрақты саулық, ол бір күнде жүзеге асады.');
INSERT INTO reflections (day, month, title, text) VALUES (9, 'Февраль', 'РУХАНИЛЫҚҚА ҚОЛ ЖЕТКІЗУ', 'АА жиналыстарында спикерлердің алкогольмен байланысты өзгерістерден бөлек, өмірлік көзқарасының толық өзгергенін сипаттап сөз соңында: «Бірақ мен әлі руханилыққа қол жеткізе алмадым» деп жиі айтатынын естиміз. Қатысушылардың бәріне оның бойына құт дарығаны көрініп тұрады. Бірақ ол бойда бар қасиетін сезіне алмайды. Алайда, бұл құт дарыған кісі алты айдан кейін немесе бір жылдан кейін Құдайға сенімі оң бағытқа бұрылғанын айтады. Расымен, солай болмақ.

Бұрын бос және мағынасыз болып көрінген өмір бүгінгі күні шаттық пен қуанышқа толы. Бұл түсінік менің рухани тәжірибеме айналды. Ішіп жүрген кезімде орындалмастай көрінген жан тыныштығы күнделікті дұға мен медитация, Он екі Қадаммен өмір сүру арқылы жүзеге асты.');
INSERT INTO reflections (day, month, title, text) VALUES (10, 'Февраль', 'БАСҚАРУ ТЕТІГІ МЕНДЕ ЕМЕС', 'Алкоголик кезімізде күйзелістің жетегінде кетіп, өзіміз қазған ордан шыға алмай әлекке түстік. «Құдайдың құдыреті бәріне жете ме? Әуелі, Құдай бар ма, жоқ па? Біздің таңдауымыз қандай болмақ?» деген бейтарап сұрақтарға жауап беруіміз керек болды.

Бүгін, мен, Құдайды таңдадым. Ол — барлық ғалам. Мен, бұған шынымен ризамын. «Басқару тетігі менің қолымда» деп ойлаған кезде, мен, Құдайдың өміріме кіруіне жол бермеймін. Сол себепті бойымды мақтаныш кернегенде жоғарыда айтылған сөзді есте сақтау үшін дұға етемін. Бастысы, бүгін рухани өсуді таңдадым, ал Құдай мен үшін – барлық ғалам. Мен өз бетімше ішуді тоқтатуға тырысқанда бәрі сәтсіз аяқталды. Ал, Құдайға бет бұрып, АА-ның көмегіне жүгіну арқылы маскүнемдіктен арыла алдым. Бұл алкоголиктің күрделі психикасы үшін түсінікті тұжырым болса керек.');
INSERT INTO reflections (day, month, title, text) VALUES (11, 'Февраль', 'ӨЗІМШІЛДІКТІ ШЕКТЕУ', 'Бізді: «Бойымыздағы үрей қайдан пайда болды?» деген сұрақ мазалады. Себебі, біз өзімізге сенім артқанбыз, ал бұл бізді алдады емес пе?

Бойымдағы кемшіліктер мені Құдайдың еркінен алшақтатады. Мен Онымен байланысымды үзген кезде әлеммен және өз алкоголизміммен жалғыз қалып, бәріне өзім жауапты болуға мәжбүрмін. Өзіме сенген кезімде тыныштық пен қауіпсіздік сезімі болмады. Нәтижесінде, үрей мен өкпе-реніште өмір сүрдім. Құдайға бет бұрсам, үйлесімділік пен тыныштыққа оралу жолын көрсетеді. Бірақ алдымен өз қорқыныштарымды көріп, маған қалай әсерін тигізіп жатқанын түсінуге тырысуым керек. Сондықтан, Құдайдан өзінен алыстатпауын жиі сұраймын.');
INSERT INTO reflections (day, month, title, text) VALUES (12, 'Февраль', 'БАРЛЫҚ ҚИЫНДЫҚТЫҢ ТҮБІРІ', 'Өзін-өзі сүю — эгоцентризм! Бұл, біздің ойымызша, барлық мәселелеріміздің түбірі.

Мен болмасам да әлем көркейіп, тірі жандар тіршілігін жалғастыра алатыны таңқаларлық жаңалық емес. Өзгелердің менің бақылауым мен басқаруымсыз-ақ жақсы өмір сүре алатынын білу

қандай жеңілдік. Менен мықты Күштің менен бөлек және тәуелсіз өмір сүретінін түсіну қандай керемет. Бұл ерекше сезім мәңгілік болмауы да мүмкін. Алайда, қазір осы сенім арқылы өмірімнің мәнін табуға тырысамын.');
INSERT INTO reflections (day, month, title, text) VALUES (13, 'Февраль', 'ТЕК АҚЫЛДЫҢ КҮШІ САУЛЫҚҚА ЖЕТКІЗЕ АЛМАЙДЫ', 'Тек ақылға сенетіндерге көптеген АА мүшелері: «Иә, біз сіздер сияқты өзімізге зиян келтіретіндей ақылды болдық. Жасырын түрде біз өзіміздің санамызға сүйене отырып, басқалардан жоғары бола аламыз деп ойладық» деген сөзді айта алады.

Тіпті ең кемелденген ақыл да алкоголизмнен қорғай алмайды. Менің саулыққа ақылмен жетуім мүмкін емес. Мен, ақыл-қабілетті Құдайдың берген қасиеті деп қабылдаймын. Сол себепті, бұл ақыл- қабілетімді сурет салғанда, би өнерінде немесе архитектурада қолдана аламын. Бұл мені басқалардан артық ететін, я болмаса, қалпыма келтіретін сенімді құрал емес. Себебі, кемелдігім немесе университет дипломы сау ақылымды қайтаруға дәрменсіз. Мені, тек менен биік Күш қана түзу жолға бағыттай алады.');
INSERT INTO reflections (day, month, title, text) VALUES (14, 'Февраль', 'ҮМІТТЕНУ', 'Алкоголиктің санасына «өзгелер не істесе де, айыға аламын» деген ой сіңуі керек. Жалғыз шарт: өзін Құдайға тапсыру және моральға сүйене отырып, үй шаруасын жақсы істеу.

Жиналыстарда үкілеген үміт жайында жиі талқыланады. Өміріңізді жақсартуда немесе өзгелерге деген құрметіңіздің қайтымын күту табиғи нәрсе. Мен күткен дүние талаптарға айналған кезде қиындықтар пайда болады. Мен қалаған адам бола алмаймын, кез келген іс менің қалауымдай жүрмейді, себебі адамдар үмітімді ақтамайды. Осы орайда: «Осындай сәтте не істеуім керек? Ашуланып, өзімді аяп, жағдайды ушықтырым керек пе, әлде, мен, жасаған ақымақтықты түзететін Құдайдың күшіне сенуім керек пе?

Одан мен не үйренуім керектігін сұрағаным жөн бе? Өзім жақсы істей алатын нәрсені жалғастыруым керек пе? Өз сенімім мен барымды басқалармен бөлісуім керек пе?» деген сұрақ туындайды.');
INSERT INTO reflections (day, month, title, text) VALUES (15, 'Февраль', 'ӘРЕКЕТ ЕТУ', 'Бұл тым көп Уәде болып көрінеді ме? Жоқ. Мұның бәрін кейбіреулер ерте, енді бірі кейін басынан өткерді. Аянбай күш салсақ, бұл шындыққа айналады.

Мас болмау еркіндігінен басқа, АА маған «дұрыс әрекеттерді» жасау қабілетін берді. Жүйелі жұмыс істесем АА уәделері орындалатыны айтылады. Ол жайында дауласып пікірталасқа түсу опа бермейді. Егер, ондай әрекетке барсам бақытсыз, екіжүзді маскүнем болмақпын. Он Екі Қадам бойынша әрекет ете отырып, мен, ешқашан армандамаған өмірге қол жеткіземін.');
INSERT INTO reflections (day, month, title, text) VALUES (16, 'Февраль', 'МІНДЕТТЕМЕ', 'Түсіну дұрыс қағида мен қарым-қатынастың кілті болып табылады, ал дұрыс әрекеттер — бақытты өмірге апарар жол…

Сауығу Бағдарламасында бір сәт болды, онда жан тыныштығы дұғасының үшінші бөлігінде: «...Адамдар бір-бірінен даналық арқылы ажыратылады» деп айтылды. Бұл сөз менің санамда мәңгілікке сақталып қалды. Сол сәттен бастап, менің әрбір сөзім, ісім немесе ойым Бағдарлама қағидаларына сай келуін анықтауым керек болды. Мен, өз ауруымның ессіздігін жасырып немесе өз- өзімді ақтап тасаға тығылғаным жарамас. Өзімнен бөлек, жақындарым үшін жарық та, жарқын ғұмырға қол жеткізуге ұмытылуым керек. Ал, АА - маған міндет жүктеп, тәртіп пен жауапкершілікті талап ететін жалғыз жол.');
INSERT INTO reflections (day, month, title, text) VALUES (17, 'Февраль', 'СҮЙІСПЕНШІЛІК ОЛАРДЫҢ КӨЗІНДЕ', 'Біреулер Құдайға сенгісі келмесе, енді бірі сенімін жоғалтқан. Ал бір жандар Құдай бар екеніне сенгенімен, Оның аурудан айықтыра алатын құдыретіне күмән келтіреді.

Достастыққа жаңадан келген жандардың бойындағы өзгерістер, менің қорқыныштан арылып, теріс түсініктегі өмірлік ұстанымымды оң бағытқа қарай бағыттады. Көздерінен сүйіспеншілікті көріп, олар үшін тек бүгінгі күннің саулығы қаншалықты маңызды екенін түсініп таң қалған жайым бар. Олар Екінші Қадамды ой елегінен өткізіп, өздерінен күшті Құдырет жоғалтқан ақылын қайтаратынына еш күмән келтірмеді. Бұл жағдай менің Достастыққа деген сенімімді арттырып, барлық мүмкіндіктерге ие бола алатынымды көрсетті. АА-ға келгеннен сәттен бастап Құдайдың жазалаушы емес, керісінше сүйіспеншілікке толы Құдырет иесі екенін түсіндім. Әр өмірдің өткеліндегі қиындықтарда Жаратушының шарапатында болғаныма көзім жетті. Ақырында мені АА-ға алып келді. Бұл менің Құдайдың назарынан тыс қалмаған бір ерекше жан екенімді көрсетеді.');
INSERT INTO reflections (day, month, title, text) VALUES (18, 'Февраль', 'ӘРКІМНІҢ ӨЗ ЖОЛЫ БАР', '...аяғымыздың астындағы рухани құралдардың қарапайым жиынтығын қабылдаудан басқа амалымыз қалмады.

Мен Қадамдармен жұмыс істеуді міндеттілік пен қажеттілікті негізге ала отырып бастадым. Нәтижесінде батылдық, кемелдік, мойынсыну, адалдық, жалғыздық сынды дүниелермен бетпе-бет келіп шарасыздықты басымнан өткердім. Биллдің таңқаларлық рухани тәжірибеден өткендіктен жұлдызы жанды деген ойға келдім. Бірақ уақыт өте келе менің өз жолым бар екенін түсіндім. АА-ның бірнеше жиналысынан кейін өзгелердің әңгімелерін тыңдай отырып, әркімнің Қадамдар арқылы ілгерілеуде өзіндік жолы бар екеніне көзім жетті. Бірте-бірте Достастықтың қағидаларына сай өмір сүруді

үйреніп жатырмын. Қадамдар бойынша ілгерілеуімнің нәтижесінде бүгінгі таңда өмірге, адамдарға және Құдайға байланысты жалпы барлық нәрсеге деген көзқарасым өзгеріп, жақсарғанын айта аламын.');
INSERT INTO reflections (day, month, title, text) VALUES (19, 'Февраль', 'МЕНІҢ ЕРЕКШЕЛІГІМ ЖОҚ', 'Алғашқы әйел-алкоголикке көмек көрсету үшін АА-ға төрт жыл қажет болды. Құлдырауға түскен көптеген алкоголиктер сияқты әйелдер де өзін ерекшемін деп санады. Бұл сөзді әр қаңғыбастан бөлек, суретшілер мен инженерлер, байлар мен кедейлер, Құдайға сенетіндер мен сенбейтіндер де, үндістер мен эскимостар, ардагерлер мен сотталғандар да айтқан болатын. Осы сынды мыңдаған жандардың бәрі ішімдік ішкенде өзге алкоголиктерден еш айырмашылығы жоқ екенін саналы түрде мойындайды.

АА-да ешкім өзін «ерекше» сезінбеуі керек. Осындай көзқараста болсам, мен, өзімді өзгелерден және Жоғары Күштен алыстатар едім. Егер, мен, АА-да оқшауланғанымды сезінсем, бұл үшін адамдар кінәлі емес. Мен өзімнің қандай да бір «ерекше» екенімді сезінгенімде. Бүгінде, мен, әлемдік АА Достастығындағы тағы бір алкоголикпін.');
INSERT INTO reflections (day, month, title, text) VALUES (20, 'Февраль', 'КҮЛКІ ҚҰДЫРЕТІ', 'Оны қолдайтын АА мүшесі әдетте күле бастайды.

Алкоголизмнен арылмай тұрып, күлкі, мен, үшін ең жағымсыз нәрселердің бірі болды. Мен, ешқашан күлмейтінмін және басқалар әрқашан маған күлетін сияқты көрінетін. Жүрегіме жиналып қалған өкпе-ренішім мен өзіме деген аяушылық сезім, мені ең қарапайым жан тыныштығынан айырды. Ішімдікке салынған кезімнің соңғы кезеңінде тіпті, алкоголь де менің бойыма шаттық сыйлай алмады. АА-дағы тәлімгерім менің өзіме деген аяушылық сезімім мен

өзімшілдігімді қоздыратын қателіктерімді көрсетіп күлгенде ашуландым, ренжідім. Бірақ бұл жағдайдан жаным жеңілдеп, сауығуды басты назарға алдым. Көп ұзамай өзімнің кей қылықтырыма күлуді үйрендім, кейіннен өзім тәлімгерлік еткен жандарға да күлуді үйретуге тырыстым. Күн сайын Құдайдан бейне бір қайғы арқалаған кейіптен айыруын сұраймын.');
INSERT INTO reflections (day, month, title, text) VALUES (21, 'Февраль', 'МЕН ҒАЛАМНЫҢ БӨЛШЕГІМІН', 'Мен бірден ғаламның кішкентай бөлшегі болдым...

АА-ға алғаш келгенде, «олар» өте жақсы адамдар деп шештім, бәлкім сәл аңғал және шамадан тыс көпшіл, бірақ негізінен жақсы және шынайы қарым-қатынаста (олармен менің ортақ ештеңем болмады). Мен «оларды» тек жиналыстарда көрдім және «олар» тек сол жерде бар сияқты көрінді. «Олармен» қол алыссам да, далаға шыға сала «оларды» ұмытып кететінмін. Бірақ бір күні өзім сенбейтін Жоғары Күш менің АА-дан тыс аймақта көптеген АА мүшелерімен бірге бір жобаға қатысуыма себепші болды. Біз бірге жұмыс істегендіктен мен «оларды» адамдар ретінде тани бастадым.

«Оларға» таңғалдым. Маған ұнағаны соншалық, «олармен» қарым- қатынаста болу жаныма шаттық сыйлай бастады. Мені олардың Бағдарламаны күнделікті өмірде қолдануы, жиналыстарда сөз сөйлесуі қызықтырды. «Оларда» бар қасиет менің де бойымнан табылғанын қаладым. Кенеттен бұл «олар» деп жүргенім, «бізге» айналды. Осыдан кейін ешқашан ішпедім.');
INSERT INTO reflections (day, month, title, text) VALUES (22, 'Февраль', 'ЖЕТЕКШІЛІК', 'Бұл Жаратушыға сенуді білдіреді, ол күшті, әділдік пен сүйіспеншілікті бейнелейді. Баяу болса да менің мақсатымды айқындап, өміріме мән-мағына дарытып қана қоймай, Жоғарғы Күштің шарапатына қарай қадам жасауға мүмкіндік береді.

Өзімнің дәрменсіз, Құдайға тәуелді екенімді түсіне бастағанда бұл жолға ертерек бет бұрар едім. Шын мәнінде тек Достастықта жүріп Қадамдар арқылы үздіксіз жұмыс істеп бағытталған жол табуға болатынын көрдім. Құдай туралы көбірек білген сайын, Жоғарғы Күштің нұсқауларын тереңнен ұғынып, құдыретіне сенімім артты. Тым жылдам болмаса да, мен Тәңірдің шарапатына ұмтылуды құп көремін.');
INSERT INTO reflections (day, month, title, text) VALUES (23, 'Февраль', 'СЫРҒА ТОЛЫ ҚАЙШЫЛЫҚТАР (ПАРАДОКС)', 'АА-дағы қайта туылу қайшылықтары: толық жеңіліс пен әлсіздіктен туындайтын күш, жаңа өмір табудың шарты ретінде ескі өмірден айыру.

A. Comes of Age, 46-бет Қайшылықтар қандай ғажайып құпияларға толы! Оларды есептеп есебіне жетпейсің. Бірақ олардың бар екенін сезініп қабылданған кезде адам логикасынан тыс әлемде тағы бір дүние барын растайды. Қорқынышпен бетпе-бет келсем, маған батылдық беріледі. Бауырымды немесе қарындасымды қолдағанда, өзіме деген сүйіспеншілігім артады. Ауыртпалықты өмірдің бір бөлігі ретінде қабылдасам, басқа түскен қиыншылықтан да өзімді бақытты сезінемін. Өзімнің көлеңкелі тұсыма қараған кезде, жаңа жарық әлемге бет аламын. Әлсіздігімді мойындап, өзімді Жоғары Күшке

тапсырғанда, маған бұрын-соңды болмаған күш беріледі.

Мен АА есігіне зорға дегенде ұяттан өртеніп келдім. Ештеңеден үмітім болмаса да, ғажайып орнап үміт оты қайта жанып, қадір- қасиетке кенелдім. Кім болса да Бағдарламаның ғажайып сыйларын өзіңде сақтап қалу үшін оларды басқаларға сыйлауға мүдделі. Бұл жалғыз жол болмақ!');
INSERT INTO reflections (day, month, title, text) VALUES (24, 'Февраль', 'РИЗАШЫЛЫҚ', 'Мен ризашылыққа кенелген жанның өзін-өзі дәріптеуге жол бермейтіні туралы ақиқатты берік ұстауға тырысамын. Ризашылық әр толқынымен дүниедегі ең керемет сезім сүйіспеншілікті бойымымызға дарытады.

Менің тәлімгерім маған «ризашылық сезімінен» айрылмай, ризашылыққа кенелген алкоголик болуым керек екенін айтты. Ризашылық мойынсынудың негізі болса, ал мойынсыну анонимдіктің негізі болмақ. Анонимдік - барлық Дәстүрлеріміздің рухани түп тамыры. Негізгі қағидалар жеке тұлғалардан маңызды екенін үнемі еске салып отырады. Осы басшылықтың арқасында әр күнді тізерлеп тұрып бастаймын. Құдайға үш нәрсе үшін алғыс айтамын: мен тірімін, саумын және АА мүшесімін. Содан кейін, мен,

«ризашылық сезімімен» өмір сүруге тырысамын және АА өмір салтына бет бұрып 24 сағат бойы рахатқа бөленемін. АА, мен, қосылған ұйым емес, бұл, мен, өмір сүретін орта.');
INSERT INTO reflections (day, month, title, text) VALUES (25, 'Февраль', 'СӘТСІЗДІКТЕРГЕ ҚАРСЫ ТҰРА БІЛУ', 'Құдайдың құзыретінде ештеңе ысырап болмайды. Жанға ауыр тисе де сәтсіздік арқылы бізге мойынсыну сабағы беріледі.

Бүгін, мен, өзімнің барлық өткен сәтсіздіктерім маған қазіргі тұрған жеріме жету үшін қажет болғанын білетініме ризамын! Ауыртпалық арқылы тәжірибе жинадым. Азап шегу арқылы сабама түстім. Мен Құдайға, ақылым қабылдай алатын Құдайға ұмтылдым. Ниетіме қарай Жаратушы шарапатынан кенде қылмады. Тәжірибе мен мойынсұну арқылы рухани өсу басталып, ризашылықтың не екенін түсіндім. Кейіннен сау қалыпта өмір сүріп, сол сау қалыпта өмір сүру дағдысын өзгелермен бөлісіп сабырлыққа кенелдім.');
INSERT INTO reflections (day, month, title, text) VALUES (26, 'Февраль', 'ТАҢҚАЛАРЛЫҚ ОҚИҒАЛАР', 'АА бұл сөздің тура мағынасындағы табысқа жеткізетін оқиға емес. Бұл — рақымшылық арқылы рухани өрлеуге айналған азап шегу оқиғасы.

Мен АА-ға келгенде жалғыздық, қорқыныш және ауыртпалыққа тап болған жандардың ішімдік жайында шынайы оқиғаларын тыңдадым. Тыңдауымды жалғастыра бердім. Кейіннен мүлдем басқаша дүние естідім. Ол сау қалыпта өмір сүрудің шындығы еді. Бұл бостандық пен бақыттың, мақсат пен бағыттың, тура жол мен сабырдың, Құдаймен ара-қатынастағы, өзімнен бөлек, өзгелердің шындығы болатын. Жиналыстарға қатысқан сайын бұл шындыққа қайта-қайта ораламын. Мен оны айналамдағы адамдардың көздерінен көріп, дауыстарынан естимін. Бағдарлама бойынша жұмыс істеу арқылы өзіме қажетті бағыт-бағдар мен күш аламын. Бұл жаңа шындық әрдайым мен үшін қолжетімді. АА-ның бар құдыреті осы болмақ!');
INSERT INTO reflections (day, month, title, text) VALUES (27, 'Февраль', 'ЕРЕКШЕ ТҰРАҚТЫЛЫҚ', 'АА-ның жұмысын кім басқарады? Бұл дүниемен топ мүшелері іс-жүзінде Екінші Дәстүрде танысады. АА-дағы Достастықта мейірімді Құдайдан басқа ешкімнің беделді, ықпалды емес екенін түсінеді. Ертеректе келген АА мүшесі орнынан айырылып қалған жағдайда топ шешіміне құрметпен қарап еш ренжімейді. Ол өмірлік тәжірибелеріне арқа сүйеп, оқиғалардың одан әрі дамуын күтіп үнсіз қалады.

Дәстүр оралып тұр. Қалпыма оралған сайын бұл мата, мен, үшін пішінделіп арнайы тігілген киім екенін түсіндім. Топтың бұрынғы мүшелері өзгеріс қажет кезде көңілге тимейтіндей ұсыныстар жасайды. Әр адамның тәжірибесі өте құнды Достықтың мәні болмақ. Мен, Достастықта кез келген алкоголикке өмірдің барлық қиындықтарында көмектесетін қажеттіліктер бар екенін білемін. Көптеген қиындықтармен бетпе-бет келгенде, мен, осы ерекше тұрақтылыққа деген сенімімді жоғалтпаймын. Бұл саулықтың сыйын бағалаймын. Мен, осы Достастықтың барлық мүшелерінің игілігі үшін, осы жерден алған күш-қуатым үшін Құдайға алғысым шексіз.');
INSERT INTO reflections (day, month, title, text) VALUES (28, 'Февраль', 'ПРЕЗИДЕНТ ЖОҚ', 'Біздің Достастықтың басқарушы өкілетке ие Президенті жоқ екенін, болмаса, қарызын төлеуге қандай да бір мүшені мәжбүрлейтін қазынашымыз жоқ екенін білген достарымыз таңғалып: «Бірақ бұл мүмкін емес...» деп айтады.

Мен АА-ға келгенде онда мені «айықтыру жарнасын төлеуге мәжбүрлейтін» қазынашы жоқ екеніне сенбедім. Мен, қызмет көрсету үшін қаржылық жарналарды талап етпейтін ұйымды елестете алмадым. Бұл өмірімде маған «тегін» берілген алғашқы және әзірге жалғыз тәжірибем. АА-да мені біреу пайдаланып немесе алдап жатыр деп ойламағандықтан, Бағдарламаға бейтарап және әділ көзқараспен қарай алдым. Олар менен ештеңе алғысы келмеді. Менде жоғалтатын не бар еді?! Менің ойымша, бұл АА негізін қалаушылардың даналығы үшін Құдайға шүкірлік айтамын. Олар алкоголиктің бәзбіреудің билеп-төстегенін ұнатпайтынын жақсы түсінген.');
INSERT INTO reflections (day, month, title, text) VALUES (29, 'Февраль', 'БІЗ ҚҰДАЙДЫ ҚАЛАЙ ТҮСІНЕМІЗ?', 'Азғырулар болғанмен ішу туралы ой оған қайта оралмады. Ал азғыру кезінде жиіркеніш сезімін тудырды. Ол тіпті қаласа да, іше алмаған сияқты. Құдай оған ақыл-есін қайтарды.

Мен, алғаш рет АА-ның Он Екі Қадамымен байланысты «Құдай» сөзін көріп, үрейлендім. Ішімдікті тастау үшін барлық жолдан өткендіктен, бұл шешімім ұзаққа бармайтынын түсіндім. Дегенмен, ішпесем де, ішсем де мені тұңғиық үмітсіздікке батырған Құдайға қалай сенемін?! Жауабы бар. Мен үшін өзімнен әлдеқайда мықты Күштің шарапатын сезіну. Сол Құдыретке сенуге дайын болғанда сау қалыпты өмір бұйырады. Ақырында көптің бірі болғанымды мойындадым. Сондай-ақ, бойымда сенім болмаса да тәлімгерімнің және АА-ның басқа мүшелерінің тәжірибесінің ізімен жүре бастағанда өміріме мән- мағына дарып, жаңа бағытқа бет бұрдым.');
INSERT INTO reflections (day, month, title, text) VALUES (1, 'Март', 'ӘСЕРІ БАР', 'Мұның шын мәнінде әсері бар, бізге сеніңіз.

Бастапқы сауығу кезеңінде тек Анонимді Алкоголиктер Бағдарламасына сенетінмін. Менің айығуым тек үмітсіздік пен қорқынышқа негізделді. Жоғары Күшке кейіннен сене бастадым. Жиналыстарда өз тәжірибелерімен бөліскен әр жанды тыңдаған сайын тіпті, сау кезімде болмаған тәжірибе жинадым. Олар сенім арқылы қол жеткізген тәжірибесімен бөліскен сайын, бұл сенім менің де бойыма дари бастады. Олардың әңгімелері арқылы белгілі бір Жоғары Күшті таба аламын деген үмітке ие болдым. Уақыт өте келе кез келген жағдайда әрекет ететін Жоғары Күштің «сенім» екенін білдім. Бүгін сенім мен адалдық, ашықтық және Бағдарлама Қадамдары бойынша жұмыс істеуге дайындық, мен, іздеген жан тыныштығын береді. Шынымен оң әсері бар!');
INSERT INTO reflections (day, month, title, text) VALUES (2, 'Март', 'ҮМІТ', 'Үмітіңізді үзбеңіз.

Тез сауығу, мен үшін тым қолжетімді бағада. Көбінесе менің шынайы емес үміттерімнің нәтижесі түңілу, өзімді аяу және аптаның аяғына қарай әлемді өзгертуге тырысудан шаршау болды. Үмітсіздік, менің Құдайдың орнын басуға тырысып жатқанымды ескертетін белгі. Менің әлеуетімді пайдаланудың құпиясы мүмкіндіктерімнің шегін мойындау. Уақыттың баға жетпес сый екенін, ешқандай қауіпті еместігін түсіну.

Үміт — үмітсіздік есігін ашатын кілт. Бағдарлама бүгін ішпесем, әлі де үміт бар екенін Уәде етеді. Мен, бөлісетін нәрсені сақтаймын және оған сенгенде әр уақытта жаңа күш пен батылдық аламын. Мен, Құдайдың рақымы және АА Достастығы арқылы бақытты тағдырдың қиын жолымен жүре аламын. Мен, өмірімдегі

кез келген қорқыныштан әлдеқайда мықты Күштің ішімде екенін әрдайым есте сақтаймын. Әрқашан шыдамды болайын, себебі, дұрыс жолдамын.');
INSERT INTO reflections (day, month, title, text) VALUES (3, 'Март', 'ӨЗІМШІЛДІКТІ ТЕЖЕУ', '...қиындықтарымызға өзіміз себеп боламыз. Олардың бастамасы; алкоголик — бұл еріксіз бүліктің аяқталған мысалы. Бірақ ол олай деп ойламайды. Алдымен біз, алкоголиктер, бұл эгоцентризмнен құтылуымыз керек. Біз, мұны істеуге күш салғанымыз жөн. Әйтпесе, менмендік біздің түбімізге жетеді.

Сан жылдар бойы менің бар қайғым өзімнің қара басымнан аспады. Өзімнен басқа ешкімді көрмедім. Өзіме деген аяушылық, өзімшілдіктің басында тәкаппарлық тұрған болатын. Анонимді Алкоголиктер Достастығының Қадамдар мен Дәстүрлерін күнделікті қолдану арқылы, топ пен тәлімгерімнің көмегімен, өзімнің қалауым бойынша тәкаппарлықты өмірімнен алып тастай аламын. Өзіме шынайы қарамайынша, барлық мәселе өзімде екенін көрмейінше, сыртқы және ішкі әлеміме сай әрекет ете алмаймын. Алдамшы үміттерімді тастамай, жан тыныштығына жетпейтінімді түсінбедім. Мен сабырға келіп, тұрақты түрде сау қалпымды сақтай алмадым.');
INSERT INTO reflections (day, month, title, text) VALUES (4, 'Март', 'ТАЗАЛАУ', 'Рухани өсудің мәні әр істі жақсы жаққа өзгертуге ұмтылып, одан кейін кез келген жауапкершілікті алуға дайын болу.

Үшінші Қадаммен танысу кезінде алкогольдік тәуелділіктен құтылдым. Бірақ ащы тәжірибе маған ұзаққа созылатын саулық қажымас күш-жігерді қажет ететінін айтты. Мен анда-санда тоқтап, қайда бара жатқанымды жақсылап қарап аламын. Кетпен арқалаған

диқаншы сынды ақыл-естің бақшасын арамшөптерден тазартып отырамын. Мен, мінездің арамшөптерін тамырланбай тұрып жұлып тастауға тырысамын. Сол сәтте жайқалған көкөністер мен гүлдерге сүйсіне қараймын. Менің еңбегім әрқашан марапатталады. Әлі-ақ менің саулығым өсіп, жемісін береді.');
INSERT INTO reflections (day, month, title, text) VALUES (5, 'Март', 'ӨМІР БОЙҒЫ ТАПСЫРМА', 'Менің жағдайымда кім маған: «сабырға келсеңші» деп айта алады? Осыны білгім келеді.

Төзімділік менің ең мықты қасиетім емес. Мен қанша рет сұрадым: «Егер, менде бәрі қазір болса, неге күтуім керек?». Алғаш рет Он Екі Қадаммен танысқан кезде, мен, «кәмпит дүкеніндегі бала» сияқты болдым. Он Екінші Қадамға қашан баратынымды тағатсыздана күттім. «Бұл бірнеше айлық жұмыс шығар», - деп ойладым! Қазір, АА-ның Он Екі Қадамы өмір бойғы жұмыс екенін түсінемін.');
INSERT INTO reflections (day, month, title, text) VALUES (6, 'Март', 'СЕНІМ ИДЕЯСЫ', 'Рухани терминдермен байланысты көзқарасыңыз сізді шынайы сұрақтан алыстатпасын: терминдер сіз үшін нені білдіреді?

Мен қорқынышқа, күмәнға және ашуға толы болсам сенімге жол беруім қиын. Кейде бәрін «бұрынғыдай істеу керек пе?» деген сияқты сансыз сауалдарға көміліп қаламын. Бұл жағдайда өзімді қолға алмасам, сол сәттегі көңіл-күй сеніміме айналуы мүмкін. Егер, сәтсіздікке тап болып, бәрі «құрдымға кетті» деген ойға қалсам, жиналысқа қатысып, немесе басқа алкоголикпен сөйлесу арқылы дүрбелең ойларымнан арыла аламын.Сондай-ақ салиқалы сұхбат үмітсіз емес екеніме сендіре алады. Жиналыстарға қатысу немесе басқа алкоголикпен сөйлесу сенім әрекеттері болып табылады. Осылайша, өзімнің ауруыммен күресіп жатырмын деп сенемін. Бұл қадамдар арқылы Жоғары Күшке деген сенімімді күшейтемін.');
INSERT INTO reflections (day, month, title, text) VALUES (7, 'Март', 'ЖАН ТЫНЫШТЫҒЫНЫҢ КІЛТІ', 'Бір кезеңде көңіл қалауын құлыпты ашатын кілт ретінде пайдаланып тар қапастан шыға алдық. Осы әдіс арқылы басқа да есіктер ашылатынына көз жеткіздік.

Менен әлдеқайда мықты Күшке менмендігімді және қыңырлығымды билету, бүгінгі күннің барлық мәселелерін шешетін жалғыз жол болды. Құдайдың менің өміріме еніп, кез келген мәселемді, ауруымды немесе тәуелділігімді өз жауапкершілігіне алуы үшін шынайы ықылас жеткілікті. Менің әл-ауқатымның деңгейі өз еркімнен бас тартып, өміріме Құдайдың үстемдік етуіне мүмкіндік беруіммен өлшенеді. Көңілдің қалау кілтімен алаңдаушылығым мен қорқынышымды жан тыныштығына оңай алмастыра аламын.');
INSERT INTO reflections (day, month, title, text) VALUES (8, 'Март', 'ТАПСЫРУ', 'Анонимді Алкоголиктер Достастығына қосылуға ниеті бар кез келген жан өзі түсінбесе де, Үшінші Қадамға аяқ басады. Сіз алкогольмен байланысты барлық мәселелерді шешуді Анонимді Алкоголиктер Достастығына тапсырып, Оның қамқорлығы мен басшылығына сенім білдіресіз бе?... Достастыққа өз еркімен қосылғандар қиындыққа ұшыраған жан үшін бұл жер жалғыз пана екеніне сенеді. Егер, өз еркіңіз бен өміріңізді бір Құдыретке тапсыра алмасаңыз, бұл қалай болғаны?!...

Құдайға мойынсыну — менің сауығуыма жасаған алғашқы қадамым. Менің ойымша, біздің Достастық Құдаймен жаңа туыстық деңгейге жол ашып, рухани бастамаларға жетекші болмақ. Қадамдар жолымен жүруге тырысқан кезде, өзім туралы ойлануға мүмкіндік беретін еркіндікті сезінемін. Зиянды әдетім мені бұл ерікті түрмеде мәңгілік тұтқында ұстап, одан босауға ешқандай үміт бермеді. Бірақ АА маған алға жол көрсетеді. Өзгелермен бөлісу, назар аудару және

қамқорлық жасау — бұл бізге және басқа жандарға табиғи сый. Ал, Құдайға деген қарым-қатынасым өзгерген сайын, сәйкесінше менің де несібем артады. Құдайдың еркіне мойынсұнуды, өзіме құрмет көрсетуді және бойымда бар дүниемен бөлісуді үйренемін.');
INSERT INTO reflections (day, month, title, text) VALUES (9, 'Март', 'ӨЗ ЕРКІҢНЕН БАС ТАРТУ', '«Ерік-жігеріміз	бен	өмірімізді	өзіміз	түсінетін	Құдайға тапсыруды шештік».

Адамның бірдеңе жасағысы келетіні қаншалықты маңызды емес. Маңыздысы, өзінің еркі мен өмірін өзі түсінетін Құдайға тапсыра ала ма, жоқ па? Бұл сұраққа жауап іздеу кезінде Үшінші Қадамның барлық даналығын түсіндім. Бұл Қадам екі бөліктен тұрады.

Бұрынғы өмірімде бірнеше рет өліп қалмасам да, мүгедек болуым мүмкін еді, бірақ олай болған жоқ. Бір Тылсым Күш мені қорғаумен болды. Мен «әрқашан Құдай қамқорлық жасайды» деп сенгім келеді. Тек бір Жаратушы ғана маған берілген өмір сағатын анықтай алады.

Ерік-жігер мәселесі (өз еркі немесе Құдайдың еркі) мен үшін бұл Қадамның ең қиын бөлігі. Тек эмоционалды ауырсынуды бастан өткергенде ғана өмірімді Құдайдың еркіне тапсыруға дайын екенімді түсіндім. Тапсыру — бұл дауылдан кейінгі тыныштық. Менің еркім Құдайдың еркімен үйлескен кезде, жан тыныштығын табамын.');
INSERT INTO reflections (day, month, title, text) VALUES (10, 'Март', 'БҮГІНГІ КҮН – МЕНІҢ ТАҢДАУЫМ', '...біз әрдайым бір кездері өзіміз туралы ғана ойлап таңдау жасағанымызды білеміз, ақырында соның зардабынан тартып келеміз.

Мен, өмірімнің қалай қалыптасуында өзімнің қандай рөл ойнағанымды  түсініп,  қабылдадым.  Бұл  менің  көзқарасымды

түбегейлі өзгертті. Сол кезде АА бағдарламасы маған жұмыс істей бастады. Бұрын барлық қиындықтарым үшін үздіксіз өзгелерді немесе Құдайды кінәлайтынмын. Өмірімді өзгертуге таңдау бар екенін білмедім. Менің шешімдерім қорқынышқа, менмендікке немесе эгоизмге негізделген еді. Нәтижесінде бұл шешімдер мені құрдымға жіберді. Қазір мені ақыл-ой жолына түсіргісі келген Құдайдың ықпалына қарсы шықпаймын. Нәтижесіне қарамастан өз әрекеттерім мен әрекетсіздігім үшін жауап беремін.');
INSERT INTO reflections (day, month, title, text) VALUES (11, 'Март', 'ЖАЛҒЫЗ ДҰРЫС БАҒЫТ', 'Тек қана өз еркімізді Құдайдың ықпалына бергенде ғана оны дұрыс пайдалана бастаймыз. Бұл біз үшін тың жаңалық болды. Барлық қиындықтар өз еркімізді дұрыс пайдаланбауымыздан туындады. Біз өз мәселелерімізді Құдайдың қалауымен үйлестірмей өз ерік күшімізбен шешуге тырыстық. АА Он Екі Қадамының мақсаты Құдайдың қалауына қарай әрекет ету мүмкін екенін түсіндіру. Үшінші Қадам осы айтылған жағдайға жол ашады.

Маған керек нәрсе — бұл өзімнің өткеніме қарап, өз еркіммен қайда жеткенімді көру. Мен үшін ең тиімдісі не екенін білмеймін, алайда, менің Жоғары Күшім оны біледі деп ойлаймын. Мен үшін қайырлысы Құдай көрсеткен бағыт деп санаймын. Бұл бағыт ешқашан мені орға жыққан емес. Дегенмен, өзімді жиі алдадым. Өз еркімен әрекет ету мозаикалық ойын іспесттес. Фигулар тиісті өз орнына түспей қалса жүйкені жұқартып, мезі қылады. Үшінші Қадам бүкіл Бағдарламаның есігін ашады. Құдайдан тура жол сұрағанда, Тәңірім дәл мен қалағандай немесе күткенімдей болмаса да, ең тиімді бағытқа бағыттайды. Құдайдың ықпалына қарсыласуымды тоқтатсам мен үшін өзімнің қолымнан келмейтін игілікті бұйыртады.');
INSERT INTO reflections (day, month, title, text) VALUES (12, 'Март', 'КҮНДІК ЖОСПАР', 'Таңертең оянғанда, алдағы 24 сағаттық өмірімізді ойлауымыз керек.   Біздің   жоспарларымызды   қарастырайық.   Өзімізді

аяушылықтан, қыңыр қылықтан және өзімшілдіктен аулақ ұстау үшін күннің басында, біз, Құдайдан ойларымызды дұрыс бағытқа бағыттауын сұраймыз,.

Күн сайын Құдайдан мені сүйіспеншілікке бөлеп, өлі жүрегімді тірілтіп, саф алтындай ойларымды жалтыратуын сұраймын. Бұл тілегім қарсыласпай Құдайдың қалауын мүлтіксіз орындауға мүмкіндік береді. Күні бойы сыртқы жағдайлар көңіл-күйіме теріс әсер еткенде, Құдайдан жәрдем сұраймын. Көңілімді кірлетіп алсам, мен, күнді қайта бастай аламын. Бұл әрекетімді жүз рет болса да қайталуға бармын.');
INSERT INTO reflections (day, month, title, text) VALUES (13, 'Март', 'РУХАНИ ӘЛЕМ', 'Біз, Рухтар әлеміне кірдік. Келесі міндетіміз: түсінігімізді дамытып, күш-жігеріміздің тиімділігін арттыру. Бұл бір күнде істелетін іс емес. Бұл өмір бойғы міндет.

«Кірді» сөзі және «Рухтың әлеміне кірді» деген сөз тіркесі үлкен маңызға ие. Олар рухани өсуіме қадам жасағанымның белгісі.

«Рух» — менің материалдық емес бөлігім. Менің рухани өсуімнің кедергілері — эгоцентризм, материалдық және күнделікті тұрмысқа жегіліп қалу. Руханият дегеніміз — күнделікті рухани өмірді таңдап, Құдайдың еркіне бағынуды білдіреді. Өз түсінігімде руханиятты:

«ешқандай шартсыз махаббат, қуаныш, төзімділік, мейірімділік, жомарттық, адалдық, өзін-өзі басқару және кішіпейілділік сынды қасиеттердің адам бойынан табылуы» деп түсінемін. Өзімшілдікке, өкпе-ренішке және қорқынышқа бой алдырсам, мен үшін руханияттың есігі жабылады. Егер, әрдайым сау қалпымды сақтай алсам, рухани өсу тұрақты болмақ. Рухани кемелдіктің шегі болмаса да, менің мақсатым — рухани өсу!');
INSERT INTO reflections (day, month, title, text) VALUES (14, 'Март', 'ҚАМАЛДАҒЫ АСЫЛ ТАС', 'Пайдалы идеялардың көпшілігі қарапайым. Бұл қағидаларды сақтай отырып, тас қамалдың құрсауынан шығып еркіндікке қол жеткіздік.

Асыл тас көңіл қамалының бөліктерін бекітіп, ұстап тұрған сына іспеттес. Көңіл қамалындағы басқа тастар Бірінші, Екінші, Төртінші, Он Екінші қадамға дейінгі қадамдар. Кей жағдайда Үшінші Қадам ең маңыздысы болып көрінеді. Ал қалған Он Бір Қадам тек осы Үшінші Қадамды жәй ғана тіреп тұрған тіреуіш сынды. Шын мәнінде, Үшінші қадам — Он Екі қадамның бірі ғана. Үшінші Қадам асыл тас болғанымен қалған Он Бір Қадамсыз қамалдың қабырғасын тіктей алмайды. Он Екі Қадамның бәрін күнделікті орындау арқылы ғана, көңіл қамалының мұнарасына көтеріле аламын.');
INSERT INTO reflections (day, month, title, text) VALUES (15, 'Март', 'ҚҰДАЙ ИДЕЯСЫ', 'Өзгелердің Ғаламдық Рухқа сүйеніп, өз мәселелерін қалай шешетінін көргенде, біз, Құдайдың бар екеніне күмәндануды тоқтаттық. Біздің өз идеяларымыз дәрменсіз болып шықты, ал, Құдай идеясы бізге көмектесті.

Көзі біртіндеп сауығып келе жатқан зағип жан сияқты, мен, Үшінші Қадамға апаратын жолды ақырын сезіндім. Мені бұл шыңыраудан тек менен мықты Күш шығара алатынын түсінгенде, қайткен күнде осы Құдыретті ұстап қалу керектігін түсіндім. Өмір дейтін теңіздің асау толқындарында ағысқа жібермей ұстап түратын зәкірім екенін білдім. Сол кездегі менің сенімім тозаңдай болса да, өзіме сыни қарап менмендіктен арылуыма септігін тигізді. Кеудемдегі тәкаппарлықты өзімнен мықты Күштің тірегіне ауыстыру қажет.');
INSERT INTO reflections (day, month, title, text) VALUES (16, 'Март', 'БІЗ ОНЫ ҚАЛАЙ ТҮСІНЕМІЗ?', 'Досым маған бір ұсыныс айтты... «Неліктен, сіз, Құдай туралы өз түсінігіңізді дамытпасқа?». Сол сәтте бұл маған қызық көрінгенмен,кейіннен таңқалдым. Сан жылдар бойы зардап шеккен ақылдың мұзды тауы еріді. Өне-бойыма күн сәулесі түсіп жылынғандай әсерде болдым. Менен талап етілгені тек қана Жоғарғы Күштің бар екеніне сенім білдіру еді. Қадам жасау үшін осы дүние ғана қажет болды.

Кейде аспанға қарап, бәрін кім және қалай жаратқанын ойлайтыным есімде. АА-ға келгенде, кейбір рухани ұғымдарды түсіну үшін тұрақты саулық қажет болды. Үлкен жарылыс болжамын қоса алғанда, кейбір ғылыми болжамдармен танысқаннан кейін қарапайым жолмен жүрдім. Түсінуімше, ғалам үлкен жарылыстан пайда болған күннің өзінде, сол жарылысқа себепші болған - Құдай. Осындай үлкен Ғаламға иелік ете алған Құдыреттің ойларымды және әрекеттерімді басқаруға шамасы жететініне күмән жоқ. Әлбетте, ол үшін қарсыласпай Жаратушының басшылығын қабылдауға дайын болуым керек. Егер, Құдайдан теріс айналсам, Оның шарапатынан құр қалып, арқа сүйей алмай қаламын. Мен оның құдіретіне сенгендіктен, 26 жыл бойы тұрақты түрде сау қалпымды сақтап, шаттыққа кенеліп жүрмін.');
INSERT INTO reflections (day, month, title, text) VALUES (17, 'Март', 'БЕЙМӘЛІМ ЖОЛДАР', '...Құдайдың тарапынан берілетін қайғы-қасірет пен азап, қатал және тіпті, әділетсіз болып көрінгенмен, бұл бізге жаңа өмір сабақтарын береді. Бізді өмір жолында шыңдап, батылдыққа үйретеді. Құдай кей кезде өз ғажайыптарын бұралаң жолда сүріндіру арқылы көрсетеді.

Жұмысымнан, отбасымнан және денсаулығымнан айрылсам да өмір салтымды қайта қарау керек екенін түсіне алмадым. Ішімдік пен есірткі мені өлтірді. Бірақ, мен, сауығып келе жатқан адамды

немесе АА мүшесін ешқашан кездестірмедім. Мен, жалғыз өлуім керек деп ойладым. Сондай-ақ, бұл ит өлім маған лайық деген түсінікте болдым. Мен, қазірдің өзінде толық үмітсіздікке ұшыраған едім, аяқ асты біздің емшектегі нәресте ауырып қалды. Ол сирек кездесетін аурудан зардап шегіп, жағдайы ауыр болды. Дәрігерлердің күш-жігері сәтсіз аяқталды. Мен, қайғы-қасыретімді ішімдіктің күшімен тыныштандыруға қанша тырыссам да, еш әсері болған жоқ. Менің жалғыз қорғаным Құдайға бет бұрып, Одан көмек сұрадым. Бірнеше күннен кейін бірқатар таңғаларлық жағдайлар болып АА-ның табалдырығын аттадым. Содан бері сау қалыпта өмір сүріп келемін. Ұлым аман қалды және сауығып келеді. Бұл жағдай менің дәрменсіздігім мен өмірімді басқара алмауымды көрсетті. Қазір ұлым екеуміз, бізге, дем беріп, қорған болған Құдайға шүкірлік етеміз.');
INSERT INTO reflections (day, month, title, text) VALUES (18, 'Март', 'ШЫНАЙЫ ЕРКІНДІК', '...Жоғарғы Күшке бағынуға дайын болсақ, соғұрлым тәуелсіз боламыз.

Бойымда күмән басым болса да, Құдайға сене бастаймын. Бұл әркетім жүректегі күмәнді сейілтіп, сенімімді арттырады. Құдайға сенуге қаншалықты ниеттенсем, соғұрлым сенімім күшейе бермек. Жаратушыға тәуелділігім, рухани өсуіме және оған сеніміме байланысты. Оның еркіне мойынсұнбай тұрып, мен, өзіме сендім. Бірақ менің мүмкіндігім шектеулі еді. Өзім Құдай деп таныған Жоғары Күшке сенуді бастағанда барлық қажеттіліктерім өздігінен қамтамасыз етіле бастады. Әлі де керегімді қанағаттандыратынына сенім мол. Мені жақсы білетін Құдырет қана мені кемелдендіріп, менің қолыммен өзгелерге жақсылық жасай алады. Әлемде мен сияқты адам болмайды. Бұл шынайы тәуелсіздік.');
INSERT INTO reflections (day, month, title, text) VALUES (19, 'Март', 'ДҰҒАНЫҢ ӘСЕРІ БАР', 'Бір кісі жақсы айтыпты: «Дұғаны көбінесе дұрыс дұға тілемегендер мазақ етеді».

Мен, агностиктер отбасында өстім. Дұға етуге алғаш тырысқанымда, өзімді ыңғайсыз сезіндім. Менің өмірімде қандай да бір Жоғары Күштің бар екенін білдім (әйтпесе мен қалай сау болар едім?). Бірақ ол Құдыреттің дұғаларымды естігісі келетінін білмедім. Кейіннен Дұға ету Бағдарлама бойынша жұмыстың маңызды бөлігі екені ескертілді. Мен, қолға алған істі табандылықпен меңгердім. Күн сайын дұға ете бастағаннан кейін тыныштық пен жайлылықты көбірек сезінетінімді байқадым. Басқаша айтқанда, өмір жеңілдеп, күрес азайды. Әлі де менің дұғаларымды Кім немесе Не тыңдап отырғанын білмеймін. Ол Құдыреттің жанды, жансыз екені маған түсініксіз. Бірақ бұл әрекетім өміріме оң әсер етіп жатқандықтан, дұға оқуды ешқашан тоқтатпаймын.');
INSERT INTO reflections (day, month, title, text) VALUES (20, 'Март', 'СҮЙІСПЕНШІЛІК ПЕН ТӨЗІМДІЛІК', 'Өзгелерге деген сүйіспеншілік пен шыдамдылық біздің қағидалар жиынтығымызды анықтайды.

Мен, шынайы рухани өрлеуді тоқтатпас үшін барлық жағдайларда адамдарды кешіруім керек екенін түсіндім. Кешірудің қаншалықты маңызды екені бір қарағанда айқын болмауы мүмкін. Бірақ, «кешірімді болу» руханиятқа иелік еткен барлық ұлы тұлғалардың ең негізі қасиеті екенін білемін. Маған келтірілген зиянды жай ғана сөзбен немесе ресми түрде емес, жүрегімде кешіруім керек. Мұны мен басқа адам үшін емес, өзім үшін істеймін. Өкпе, ашу немесе біреуді жазаланғанын көру ниеті менің жанымды улайды. Мұндай сезімдер мені шынжырмен байлап, өзіме қатысы жоқ басқа да дауға итермелейді.');
INSERT INTO reflections (day, month, title, text) VALUES (21, 'Март', 'МАТЕРИАЛДЫҚ ЖӘНЕ РУХАНИ ИГІЛІК', '...қорқыныш пен экономикалық әл-ауқатқа деген сенімсіздік жоғалады.

Үрейден арылу және материалдық жағдайды жақсарту - бұл екі түрлі нәрсе. АА-да жаңа бастаған кезде, мен, осы екі ұғымды шатастырдым. Табыс таба бастасам, үрейден арыламын деп үміттендім. Бірақ қаржылық қиыншылыққа тап болған кезімде Үлкен Кітаптағы: «Біз үшін материалдық байлық руханидан кейін екінші орында тұрады, ешқашан керісінше болмайды» деген сөзге кездейсоқ көзім түсті (123-бет). Мен бұл мәлімдеменің кепілдік екенін кенеттен түсіндім. Бұл басымдықтарды дұрыс белгілейтінін көрдім. Рухани өрлеу басқа қорқыныштарды сейілткені сияқты, жоқшылықтың да үрейінен арылтады. Қазір, Құдай берген дарынымды адамдарға пайда әкелу үшін қолдануға тырысамын. Сәйкесінше, олар осы игі істерім үшін жоғары бағалайтынын байқаймын. Мен, енді тек қана өзім үшін жұмыс істемейтінімді естен шығармаймын. Тек Құдай берген байлықты қолданамын, оны ешқашан иемденбегенмін. Менің мақсатым дүние-мүлікке иелік ету емес, жай ғана басқа жандарға пайдалы болып, көмек көрсету. Бұл әрекетім өмірлік мақсатымды әлдеқайда айқын, түсінікті қылады.');
INSERT INTO reflections (day, month, title, text) VALUES (22, 'Март', 'БІЗ ЕНДІ КҮРЕСПЕЙМІЗ', 'Тағы бір айта кететін жайт: біз алкогольмен де, басқа да істермен күресуді тоқтаттық.

АА мені тапқан кезде, алкогольмен күреседі деп ойладым. Достастық ішімдікті жеңуге күш береді деген түсінікте болдым. Бәлкім, бұл күресте жеңіске жетсем, тағы қандай шайқастарды жеңе алатынымды кім біледі? Бұған дейінгі өмірлік тәжірибем дәлелдегендей, қалай болғанда да, мен күшті болуым керек еді. Бүгінгі таңда мен күресіп немесе ерік-жігерімді көрсетуге тиісті емеспін. Егер, осы Он Екі қадаммен жүріп, Жоғары Күштің жұмысына қарсыласпасам, менің алкогольдік мәселем өздігінен жоғалады. Менің өмірім де күрес болмайды. Тек әр мәселеде: «мен бұл жағдайды қабылдауым керек пе? Әлде, өзгертуім керек пе?» деп

сұрауға мүдделімін. Менің емес, Жоғарғы Күштің қалауы болуы тиіс.');
INSERT INTO reflections (day, month, title, text) VALUES (23, 'Март', 'БҰРЫЛУҒА ЖОҚ', 'Біз «егер, сіз, алкогольге тәуелді болсаңыз, бұл мәңгілік» деген мәлімдеменің шынайылығына сенімдіміз... Егер, сіз, ішімдікті тастауға шешім қабылдасаңыз, бұл шешім сөзсіз орындалуы керек. Ешқашан өзгелер сияқты қалыпты ішімдік ішу туралы ойланбаңыз... Алкоголизмге бейім адамдар бірнеше жыл ішінде алкоголикке айналады, бұл әйелдерге де қатысты.

Бұл сөздер менің кітабымда жазылған. Айтылған пікір алкогольге тәуелді ерлер мен әйелдер үшін шындық. Мен, бұл бетке бірнеше рет жүгініп, осы үзінді туралы ойландым. Өзімді алдап қайтемін?!  Ішімдік  ішіп  жүрген  кезімді  еске  алып   немесе

«сауықтым» деп ойламауым керек. Егер, сауығу мен үшін Құдайдың сыйы болса, менің сау өмірім Құдайға деген сыйым деп ойлағанды ұнатамын. Құдай Өзінің сыйлығына мен сияқты қуанады деп үміттенемін.');
INSERT INTO reflections (day, month, title, text) VALUES (24, 'Март', 'БЕЙЖАЙЛЫҚ ЕМЕС, БЕЛСЕНДІЛІК КЕРЕК', 'Адам автоматтандырылған тіршілік иесі емес. Адам ойлау мен әрекет ету үшін жаратылған.

АА-ға қосылмас бұрын, көбінесе адамдар мен жағдайларға еш ойланбай жай ғана реакция білдіреді екенмін. АА мүшесі бола отырып, күн сайын өзімнен мықты Күштің басшылығын іздей бастадым және Оның нұсқауларын тыңдауды үйрендім. Содан кейін шешім қабылдап, жай ғана әрекет етпей, жағдайға қарай әрекет ете бастадым. Оң нәтижелер пайда болды: енді өзгелердің мен үшін шешім қабылдап, кейіннен сол үшін мені сынға алуына жол бермеймін.

АА-дағы алкоголик-серіктестеріммен өзімнің өмірлік тәжірибеммен бөліскен сайын Құдайдың қалауы мен арқылы жүзеге асып жатыр деген ойда боламын. Себебі менің қателіктерімнен өзгелер сабақ алып, тура жолға бет бұрады.');
INSERT INTO reflections (day, month, title, text) VALUES (25, 'Март', 'АЛҒЫСҚА ТОЛЫ ЖҮРЕК', 'Мен «алғысқа толы жүрек өзімшілдікке жол бермейді» деген ақиқатты ұстануға тырысамын. Алғысқа толы жүрек соққы тисе де, ең әдемі сезім сүйіспенщілікпен үн қатады.

Біз, АА мүшелері, алғыс айту қажеттілігі туралы және біздің саулығымыз үшін алғыс айтудың маңыздылығы жайлы үнемі еске түсіретінімізге қуаныштымын. АА бағдарламасы арқылы, Құдайдың берген саулығына шексіз ризамын және маған ақысыз берілген нәрсені қайтаруға қуаныштымын. Тек саулық үшін ғана емес, салауатты өмір сапасы үшін де алғысым шексіз. Құдай маған сау күндер мен тыныш өмір ғана сыйлап қойған жоқ. Сүйіспеншілікпен біздің Достастыққа, отбасыма, айналама қызмет ету мүмкіндігін берді. Әлбетте, бұл ырыздық үшін «алғысқа толы жүрегімді» ұсынамын!');
INSERT INTO reflections (day, month, title, text) VALUES (26, 'Март', 'ОҚУ ЕШҚАШАН АЯҚТАЛМАЙДЫ', 'Өз түсінігіңіздегі Құдайға сеніңіздер. Жоғарғы Күш пен достарыңыздың алдында өз қатеңізді мойындаңыз. Өткен күннің қоқыстарынан арылыңыз. Алған біліміңізбен бөлісіңіз және бізге қосылыңыз. Біз сізбен бірге боламыз, бізді рухани бауырластық біріктіреді. Ақ пен қара қатар жүретін бақытқа апарар жолда, сан алуан жандармен тағдыр түйістіретініміз сөзсіз. Баршамызға Жаратқан жар болсын!

Осы сөздерді оқыған сайын менің кеудемде түйін түйінделеді. Бастапқыда бұл «Жоқ, оқу аяқталды! Енді мен өзім үшін бармын. Мен бәрін қайтадан бастауды жоспарлап отырған жоқпын» деп

ойладым. Енді осы үзіндіні оқыған кезде, мен, АА мүшелеріне деген терең құрмет сезімін сезінемін. Бұл ортада, мен, сенетін және ұмтылатын барлық нәрсе бар. Сондай-ақ, Құдайдың рақымымен оқу ешқашан бітпейтінін түсіндім. Мен ешқашан жалғыз болмаймын. Әр күн, мен үшін жаңа күн!');
INSERT INTO reflections (day, month, title, text) VALUES (27, 'Март', 'АА-НЫҢ ЕРКІНДІГІ', 'Біз, еркіндігіміз шын мәнінде қай жерге алып баратынын білеміз: сонымен қатар - болашақ анонимді алкоголиктер буынының ешқайсысы оларды шектеу туралы ойламайды. АА-дағы еркіндік шынайы сүйіспеншілік өсетін жерді өңдеп, құнарландырады.

Мен еркіндікке құштар болдым. Бастапқыда ішімдік ішу бостандығы, кейінірек алкогольден бостандық. АА қалпына келтіру Бағдарламасы - менің еркін таңдауым. Ешқандай мандаттар, заңдар немесе тапсырыстар жоқ. Он Екі Қадамда баяндалған АА-ның рухани бағдарламасы және бұрын-соңды болмаған еркіндіктерді алға тартатын ұсыныс іспеттес. Мен оны қабылдай аламын немесе бас тарта аламын. Тәлімгерлік ұсынылғанмен мәжбүр етілмейді, мен қалаған уақытта келіп, кетемін. Осы және басқа да еркіндіктер тұрақты сергектікті сақтап, өз қадірімді қалпына келтіруге мүмкіндік береді.');
INSERT INTO reflections (day, month, title, text) VALUES (28, 'Март', 'БІРЕГЕЙЛІК', 'Біз алкоголизмнен зардап шеккендердің барлығын қабылдауымыз керек. Қалпына келген жанның ешқайсысынан бас тартуға болмайды. АА мүшелігі ақша үшін емес, игі істер үшін ұмтылуы тиіс. Ешқандай ұйымға кіріп, ресми тіркелмесе де, сергектікке ұмтылған кез келген екі немесе үш алкоголикті АА тобы деп атауға болады.

АА-ға  дейін,  мен,  жиі  араласатын  адамдардың  ортасына

«сыймайтынымды» сезетінмін. Әдетте, «олардың» әл-ауқаты әр түрлі еді. Ол өз алдына. Менің пікірім «олардың» пікірімен сәйкес келмейтін. Мұның бәрі қоғамда адамдар менмендікке салынып қуыс кеуделікке ұрынғанына дәлел бола алады. АА-ға қосылғаннан кейін, көптен бері іздеген өмір салтын таптым. АА-да оның ешбір мүшесі жақсы да, жаман да емес; біз жай ғана алкоголизмнен арылуға ұмтылған алкоголиктерміз.');
INSERT INTO reflections (day, month, title, text) VALUES (29, 'Март', 'СЕНІМ АРТҚАН ҚЫЗМЕТКЕРЛЕР', 'Олар топқа қызмет етеді. Кейде әртүрлі дайындық жұмыстарын орындаудың риясыз артықшылығы болады.

Грек Зорба кітабында Никос Казанзакис басты кейіпкердің ағаш отырғызып жатқан қарт адаммен кездесуін сипаттайды. Зорба: «Сіз не істеп жатырсыз?», - деп сұрайды. Қарт адам: «Сіз не істеп жатқанымды жақсы көріп тұрсыз. Ағаш отырғызып жатырмын», - дейді. Зорба болса: « Егер, сіз, оның жеміс бергенін, игілігін көрмесеңіз бұл әрекеттің мәні бар ма?», - деп сұрайды. Ал қария:

«Балам, мен, ешқашан өлмейтіндей өмір сүремін», - деген екен. Мұндай жауап Зорбаның жүзіне күлкіні ұялатып, кетер кезінде мысқылдап: «Қызық, мен, ертең өлетін сияқтымын!», - деп айқайлайды.

АА-ның  мүшесі  ретінде  айтар  болсам,   Үш  Қағидадағы

«Қызмет көрсету» ұғымы саулығымның ағашын отырғызу үшін берекелі егістігі деп санаймын. Саулығымның ағашынан тыныштық, қауіпсіздік, түсіністік және жиырма төрт сағаттық шексіз руханият сыйлайтын дәмді жемістер жинап аламын. Дұрыс ойлана алсам, өз ар-ұжданымның даусын естимін. Сол сәтте ішкі түйсігім: «Сен қызмет етуің керек. Басқалары егін егіп, егін жинайды» деп үндейді.');
INSERT INTO reflections (day, month, title, text) VALUES (30, 'Март', 'БІЗДІҢ ТОПТЫҚ САНА', '«...кейде жақсы іс - ізгіліктің жауы болады».

«Бақытқа апарар жолымызда» менің өміріме енгенін қалаймын (Анонимді Алкоголиктер, 160-бет). Билл У. жиі қайталатын бұл сөзді оған біздің топтық санамыз ұсынған. Екінші Дәстүрдің мәнін көрген Билл У.: «Біздің көшбасшылар - тек сенім артқан қызметшілер, олар ешқашан бұйырмайды».

Бір кездері топтық сана Билл У-ды бұл сөздерді есте сақтауға итермелегендей, менің ойымша, топтық пікірталастарымызда біз

«жақсыдан» тоқтап қалмай, әрқашан «ең жақсыға» ұмтылуымыз керек деп ойлаймын. Бұл ортақ ұмтылыстар - Құдайдың біздің топтық санамыз арқылы өзін қалай көрсететінінің тағы бір мысалы. Мұндай тәжірибе маған сауығу жолында дұрыс бағытта қалуға көмектеседі. Мен бар ынтамды қарапайымдылықпен, жауапкершілікпен, ризашылықпен үйлестірсем, 24 сағат бойы Бағдарламамен өмір сүру мәртебесіне ие боламын.');
INSERT INTO reflections (day, month, title, text) VALUES (31, 'Март', 'МЕНІ СҮЙІСПЕНШІЛІКТЕН ЕШКІМ ШЕКТЕМЕЙДІ', 'АА-ның екінші жылы болатын... Жиналыстардың бірінде жаңадан келген адам есік қағып, өзін кіргізуді өтінді... Көп ұзамай ол үмітсіз жағдайда екенін көрсетті, бірақ соған қарамастан, ол сауығып кеткісі келеді... [Ол айтты]... «Маған қосылуға рұқсат етесіз бе, өйткені мен маскүнемдіктен де жаман нәрсенің құрбанымын...»

Мен сендерге күйеуін, балаларын, отбасын тастап кеткен, маскүнем, дәріге тәуелді, бір сөзбен айтқанда, құны жоқ әйел болып келдім. Дегенмен, маған сүйіспеншілік сыйлап қана қоймай, қамқорлық көрсетті, менен ешкім теріс айналмады. Бүгінде, Құдайдың рақымымен, жақсы тәлімгердің сүйіспеншілігімен және үй тобымның арқасында, мен, АА арқылы ана, әже және әйелмін деп айта аламын. Саумын. Дәрілерден арылдым. Жауапкершілігім жоғары. Достастықта тапқан Жоғары Күшсіз өмірім мағынасыз болар еді. АА-ның сенімді мүшесі болғаныма шексіз ризамын.');
INSERT INTO reflections (day, month, title, text) VALUES (1, 'Апрель', 'ӨЗІҢЕ ҮҢІЛУ', 'Батыл қадам жасап, өзімізді және өмірімізді моральдық тұрғыдан терең бағаладық.

Төртінші Қадам - бұрынғы және қазіргі ауытқуларымды түсіну үшін батылдықты қажет ететін ауыр жол. Менің табиғи қалауым қашан және қалай өзгеріске ұшырағанын нақты түсінгім келеді. Сол бір бақытсыз кезеңдерде өзіме және басқаларға қандай зиян келтіргенімді білуге ниеттімін. Эмоционалды толқуларымның қандай екенін түсінген соң, жағдайды түзетіп бастаймын. Осы бағытта табанды күш-жігерсіз толық саулық немесе жан тыныштығына жете алмаймын. Бойымдағы қарама-қайшы сезімдерден арылу үшін, өзім туралы айқын түсінікке ие болуым керек. Мұндай түсінік бірден келмейді және өзім туралы түсінігім үнемі өзгеріп отырады. Тек шындықты шынайы бағалау арқылы әрқайсымыз рухани өсіп, өзімізді көбірек тани аламыз. Мен, мәселелерден қашпай бетпе-бет келіп, батылдықпен шешкенде ғана олардың саны азаяды.');
INSERT INTO reflections (day, month, title, text) VALUES (2, 'Апрель', 'МІНЕЗДІ ШЫҢДАУ', 'Өзгелердің назар аударуын, қамқорлық жасауын немесе сүйіспеншілікті талап ету; бұл талаптар бағытталған адамдардың сізге деген жиіркеніш сезімін тудырып, өзіңізді билеп-төстеуге мүмкіндік бересіз.

Төртінші Қадаммен жұмыс істеп, басқа адамдардың қошеметіне мұқтаж екенімді анықтадым. Бірақ бұл мінезімнің ақауы екенін білмедім. Керісінше, мұны «ізгі қасиет» деп есептедім (яғни адамдарға жақсылық жасауды қалауым). Бұл «қажеттілік» маған зиян екендігі айқындалды. Әлі де маған өзгелердің сый-құрметі ұнайды, бірақ сол қошеметке ие болу үшін бұрынғыдай барымды салып  жанталаспаймын.  Біреуге  ұнау  үшін  шектен  тыс  иіле

бермеймін. Мен сіздің қошеметіңізге ие болсам, бұл құптарлық іс. Егер, марапатсыз қалсам жағдайым бәз баяғыдай болмақ. Мен өзге жандардың естігісі келген дүниені емес, өзім түсінген ақиқатты айтуға жауаптымын.

Сондай-ақ, бойымдағы жалған мақтаныш, әрдайым мені өз беделім үшін алаңдауға итермеледі. АА Бағдарламасына келгеннен кейін, ең басты мақсатым мінезімді шыңдау екенін түсіндім.');
INSERT INTO reflections (day, month, title, text) VALUES (3, 'Апрель', 'ӨЗ БОЛМЫСЫҢДЫ ҚАБЫЛДАУ', 'Біз, бұл жол өзгелердің өзіміз туралы пікіріне жалтақтамай, моральдық болмысымызды бүтіндеу екенін түсіндік. Осылайша, өз қателіктерімізді мойындап, кемшіліктерімізді түзетуге ниеттіміз.

Неліктен маскүнем жауапкершілікті өз мойнына алғысы келмейді? Мен айналамдағы жандардың қылығына күйініп ішетінмін. АА-ға келгенімде қателескенімді түсіндіріп берді. Мен не істеуім керек еді?! Жанға жайсыз оқиғалардың, өзімнің де ықпалыммен жүзеге асқанын мойындадым. Аталған жәйттің бәрін қағазға түсіріп, жай ғана адам екенімді көре алдым. Менен ешкім жетілуді талап етпейді! Менің қателіктерім көп, алдағы уақытта да қателеспеуіме кепіл бере алмаймын. Қателіктерімді мойындау арқылы өзімнен бөлек, өзгелерді қабылдап үйрендім. Сондай-ақ, әр түрлі көзқарастағы жандарға түсіністікпен қарауға бейімделдім. Осы нүктеден қарай алсақ айығудың ауылы алыс емес.');
INSERT INTO reflections (day, month, title, text) VALUES (4, 'Апрель', 'МҮМКІН ЕМЕСТІ ТАЛАП ЕТУ', 'Дәл осы кемшілік сезімі адамды бейне бір бала кейіпке түсіріп, тойымсыз, ақыл қабылдауы мүмкін емес биікке ұмтылтырады. Балалық кейпінен шыға алмай, мүмкін болмаса да аспандағы айға қол созады.

Ішімдік ішкен кезде өзімнің ешкім емес екенімді сезінсем, енді бірде өзімді ғаламның кіндігі сезінетінмін. Осы аралықта тепе-теңдік

сақтап тұрғандай күйде болатынмын. Екі күйдің арасындағы иллюзиялық тепе-теңдікті іздеу, менің қалпыма келуімнің бір бөлігі болды. Мен армандаған аспандағы ай толық көзге көріне бермейді. Ол маған әртүрлі фазаларда көрінгенмен, әрқайсысында бір сабақ бар. Шынайы білім көбінесе қара түнек қараңғылықтан кейін келеді. Бірақ қалпына келтірудің әрбір сатысында жарық күшейіп, ал, маған болып жатқан құбылыстар анық та, айқын көріне бастайды.');
INSERT INTO reflections (day, month, title, text) VALUES (5, 'Апрель', 'ШЫНАЙЫ БАУЫРЛАСТЫҚ', 'Біз, талай рет отбасының толық мүшесі, достарымызға нағыз дос, жұмыста жақсы қызметкер және қоғамның пайдалы мүшесі болуға тырыстық. Біз терең құзда болсақ та, шыңға көтерілуге ұмтылдық. Бұл өзімшіл мінез-құлық басқа адамдармен дұрыс қарым-қатынас орнатуға кедергі келтірді. Нағыз серіктестік орнатуға келгенде, біз әрқашан бір нәрседен қауіптенетінбіз.

Төртінші Қадамда баяндалған ой маған алғаш рет анық та, айқын түсінік берді. Бұған дейін өзім туралы мұндай нәрсені оқымаған едім! АА-ға келмес бұрын адамдар арасында тұлға болуды үйрете алатын жерді білмедім. Ең алғашқы жиналыстан бастап басқалардың мұны қалай істеп жатқанын көрдім және олардың бойында бар қасиетті өз бойыма дарытқым келді. Бүгінде бақытты және сау алкоголик болуыма септігін тигізген маңызды сабақты үйрену үстіндемін.');
INSERT INTO reflections (day, month, title, text) VALUES (6, 'Апрель', 'ӨМІР БОЙҒЫ ҮДЕРІС (ПРОЦЕСС)', 'Басқа адамдармен қарым-қатынасымыз қиын болды, өзімізге тән эмоцияларды басқара алмай күйзелісті бастан өткердік. Өзімізді ешкімге керексіз сезініп, әрдайым үрейге бой алдырдық. Өміріміз қара түнекке айналып, өзгеге көмектеспек түгілі, бір басымызды алып жүру мұң болды.

Бұл сөздер маған алкогольден басқа көптеген мәселелерім бар екенін еске салады. Алкоголь бойымды билеген сансыз дерттің белгісі ғана. Мен ішуді тоқтатқанда, еркімнен тыс істелетін эмоциялардан арылып, күрделі қарым-қатынастарды қалпына келтіру әрекеті басталды. Бір қызығы, бұл үрдіс өмір бойы жалғасады. Көпшілігімізге Жоғары Күш пен Достастықтың көмегінсіз осы рухани жолда кемелденуіміз қиын. Мен Қадамдар бойынша жұмыс істей бастағанда, көптеген шиеленістер шешіліп, өмірімнің ең бұрмаланған тұстары бірте-бірте түзеле бастады. Бірден көзге көрінбесе де, күн сайын айығуға бет бұрдым. Бойымда үрей жоғалды. Барға қанағат етіп, шүкірлік сезімі жүрегіме ұялады. Менің қыңыр қылығым азайып, азамат ретінде қоғамға қайта оралдым.');
INSERT INTO reflections (day, month, title, text) VALUES (7, 'Апрель', 'БӘРІН ҚАМТИТЫН ІЗГІЛІК', 'АА есігіне жетіп аман қалмасам әйеліме, ата-анама және достарыма құрмет көрсетіп, шексіз алғыс білдіре алар ма едім?! Мен осы жолда еңбек етемін. Жоғары Күштің мен үшін дайындаған жоспарларын түйсігіммен сезінуге тырысамын. Бұл біздің өмірімізді салауатты өмірмен сабақтастыратын жоспар.');
INSERT INTO reflections (day, month, title, text) VALUES (8, 'Апрель', 'ӨЗ-ӨЗІҢЕ ЗЕР САЛУ', 'Біздің табиғи қалауларымыз қашан және қай жерде бұрмаланғанын нақты анықтау керек. Мұның бізге және басқаларға қандай бақытсыздық әкелгенін ашық мойындағымыз келеді. Эмоционалды ауытқуларды тапқаннан кейін ғана, оларды түзетуге кірісе аламыз.

Бүгін мен алкогольдің құлы емеспін. Бірақ «құлдық» деген ұғым көңіл қалауымның, тіпті арманымның құлы болуға үндейтіндей көрініп, қауіптенемін. Бірақ армансыз өмір сүре алмаймын. Армансыз мені алға жылжытатын ештеңе жоқ.

Өзімді еркін сезіну үшін бірінші кезекте өзіме қарауым керек. Жүздесуге батылым жетпей жүрген жандармен бетпе-бет келіп, Құдай жаратқан болмысымды көрсету үшін Жоғарғы Күштің қолдауына мұқтажбын. Бұлай әрекет етпесем, шынайы еркіндікке жете алмай, ғұмыр бойы өзімді қабылдай алмай кетемін. Күн сайын, Құдайдан маған осы еркіндік жолын көрсетуін сұраймын!');
INSERT INTO reflections (day, month, title, text) VALUES (9, 'Апрель', 'АЛКОГОЛЬ ПАТШАСЫНАН» ЕРКІНДІК АЛУ', '...біз еркін екенімізді бір сәтке де ойламайық... Бұрынғы зұлым

«алкоголь патшамыз» бізді қайтадан басып алуға әрқашан дайын. Сондықтан алкогольден алыс болу, бұл біздің есіміз ауып немесе өліп қалмауымыз үшін қажет дүние.

Мен ішіп жүргенде рухани, эмоционалды, кейде физикалық қамауда болдым. Менің санамдағы түрме өз еркіммен және бітпейтін сылтауларымнан құралған еді. Олардан арыла алмадым. Еркіндікке ұмтылған кездейсоқ «құрғақ» уәделер жәй ғана үкімді кейінге қалдыру болды. Құлыпты ашып, шынайы бостандыққа жету үшін дұрыс әрекеттер талап етілді. Мен дайын болып, дұрыс әрекет жасасам түрменің құлпы ашылып, қабырғасы құлайды. Үздіксіз дайындық және ешқашан тоқтамайтын әрекеттер бостандығымды қамтамасыз етеді. Бұл мен үшін күнделікті сынақтың бір түрі.');
INSERT INTO reflections (day, month, title, text) VALUES (10, 'Апрель', 'РУХАНИ ӨСУ', 'Кез келген рухани өсудің мәні жақсылыққа ұмтылып, әр істе жауапкершілік арқалауға дайын болу.

Кейде, өзім істеуге тиісті емес, істі істесем қоғам тарапынан қошемет пен мақтау күткенім.	Неғұрлым басқаша әрекет етуге

дайын болсам, өмірім соғұрлым қызықты болады. Басқа жандарға көмектесуге дайын болсам, көбірек құрметке бөлемін. Бұл қағидаларды дәл осы қалпында түсінемін. Мен үшін қуанышқа бөленіп, олжалы болу, тез келетін нәтиже емес, әрекет етуге дайын болу. Біршама мейірімді, сабырлы болып, айналама сүйіспеншілік сыйлай алсам әр күнім жақсара түседі.');
INSERT INTO reflections (day, month, title, text) VALUES (11, 'Апрель', 'КІНӘЛАУ» ДЕЙТІН СӨЗДЕН БАС ТАРТУ', 'Біз өзіміздің эмоциялық тұрақсыздығымыздың құрбаны екенімізді түсіну үшін біраз уақыт қажет. Өзгелердің көңіл-күйінің құбылысын бірден байқағанымызбен, өзімізге келгенде салғырттық таныттық. Ең алдымен осы кемшіліктеріміз бар екенін мойындауымыз керек болды. Бұл жағдай бізге ауыр тиіп, қорлағандай көрінді. Өзгелерге қатысты «айыптаймын» деген сөзді сөздік қорымыздан, ойымыздан алып тастау керек болды.

Үлкен Кітаптағы нұсқауларды орындап, Төртінші Қадаммен жұмыс істеп бастадым. Сол сәтте реніштерімнің тізімінен өз қабілетсіздігіме, өз әлеуетіме сай өмір сүре алмай жатқаныма өзгелерді кінәлайтынымды байқадым. Сонымен қатар басқалар сияқты емес, «мен қарабайыр біреумін» деген түсінікте болғанымды айқындадым. Бұл Қадаммен жұмыс істеу кезеңінде осы сезімдерден құтылу үшін ішкенімді түсіндім. Тек сау қалпымды сақтап, өзімді моральдық тұрғыдан бағалауды қолға алып өзгелерді кінәлауды тоқтаттым.');
INSERT INTO reflections (day, month, title, text) VALUES (12, 'Апрель', 'ЕССІЗДІКТЕН БАС ТАРТУ', '…Алкоголь туралы сөз болғанда, біз жай ғана есімізді жоғалтып алатынбыз.

Мен қаласам да, қаламасам да алкоголь менің ішуімді талап етті. Мастық өмірімді билеп, дертімнің өзегіне айналды. Бұл жағдай алкогольді  ішу,  ішпеу  дейтін  таңдау  еркімнен  айырды.  Ішіп

жүргенде өмірдің кез келген жағдайында ақылмен шешім қабылдай алмай, өз өміріме иелік етуден қалдым. Сол себепті Құдайдан алкоголизмді ауру ретінде түсінуімді сұраймын.');
INSERT INTO reflections (day, month, title, text) VALUES (13, 'Апрель', 'ӨЗ-ӨЗІҢДІ АЯУ — ЖАЛҒАН ЖАЙЛЫЛЫҚ', 'Өзіңізге деген жанашырлық — адам бойындағы ең сұрқия және күйрететін ақаулардың бірі екені белгілі. Бұл шамадан тыс назар мен жанашырлықты талап етеді. Ақырында рухани өрлеуде кедергі келтіріп, достарымызбен барлық пайдалы қарым-қатынастарды бұзуы мүмкін. Жайшылықта өзіміздің батылымыз жетпейтін қорланудың сезімтал түрі.

Өзіме деген жалған аяушылық, мені шынайы жағдайдан біраз уақытқа қана оқшаулады. Кейіннен есірткі сияқты ол одан да көп дозаны қажет етті. Егер өзіме аяушылық танытсам, бұл мені күйретуі мүмкін. Мен не істей аламын? Назарымды біртіндеп, менен қайғысы көп жанға, турасын айтқанда басқа алкоголиктерге аудару. Оларға шын жүректен аяушылық танытқан сайын, өзіме деген асыра сілтеген аяушылығым азаяды.');
INSERT INTO reflections (day, month, title, text) VALUES (14, 'Апрель', 'БІРІНШІ ЖАУ – АШУ', 'Ашу - «бірінші жау». Ол алкоголиктерді кез келген істе күйретеді. Ол барлық рухани аурулардың түп тамыры. Себебі біз тек психикалық және физикалық емес, сондай-ақ, рухани аурумыз.

Төртінші Қадаммен жұмыс істеу кезінде, біреуге істеген қиянатымды, «мені аяп жатқан біреу бар ма?!» деген түсінікпен ақтауға тырысатынымды анықтадым. Егер, өткен күннің реніштеріне оралуға тырыссам, бұл сезім ашуға айналады. Ал ашу жаныма түсетін күн сәулесінің көзін жабады. Ескі жаралардың аузын тырнап өшпенділік теретін болсам, күйзеліске түсіп өзімді жек көремін. Көп жылдар бойы өкпе-реніштің қараңғылығында болғаннан кейін, мен күн сәулесін таптым. Өз өкпе-реніштерімнен арылуым керек.');
INSERT INTO reflections (day, month, title, text) VALUES (15, 'Апрель', 'РЕНІШТЕР КІСЕНІ', '...реніштерді жасыру өте ауыр, себебі, бұл бізге түсетін Рухтың сәулесін тұмшалайды.

«Ашу - бұл маған арналмаған сән-салтанат» деген пікір бар. Бұл осы адамдық сезімді жоққа шығарамын дегенді білдіре ме? Олай деп ойламаймын. Мен, АА бағдарламасын білмей тұрып, алкоголикке тән мінез-құлық үлгілерінің құлы болдым. Жағымсыз сезімдерге кісенділдім, сол кісеннің құрасауынан шығатындай бойымда ешқандай үміт болмады. Қадамдар маған балама жол ұсынды. Төртінші Қадам осы тізбектердің аяқталуының бастамасы болды. «Құтылу» кезеңі өз-өзімді талдаудан басталды. Мен қорқатын ештеңе болмады, себебі алдыңғы Қадамдар менің жалғыз еместігіме сендірді. Жоғарғы Күшім мені осы есікке алып барып, маған таңдау еркіндігін берді. Бүгінде еркіндікке есік ашып, рухымды тазарту кезінде Қадамдардың сәулесіне қуана аламын.');
INSERT INTO reflections (day, month, title, text) VALUES (16, 'Апрель', 'АШУДЫҢ САЛДАРЫ', 'Өмір сүру үшін біз ашудан арылуымыз керек. Реніштер мен ашу біз үшін қауіпті. Ол қалыпты жандарға лайықты бір уақыттық шаттық болуы мүмкін, бірақ алкоголиктер үшін ашу «у» іспеттес.

«Күмәнді рахат» сөзі есіме жиі түседі. Бұл тек ашуға қатысты емес. Мен бұл тізімге өзімді ақтайтын сәтсіздіктерді, өзін-өзі аяуды, басқаларды кінәлауды, тәкаппарлықты, жалған мақтаныш пен жалған қарапайымдылықты қосамын. Үлкен кітаптан үзінді оқығанда әрдайым таң қаламын. Бағдарлама принциптері менің жүрегіме терең енгені сонша, әрдайым: «Мен барлық кемшіліктерімді тізіп қойдым ба?» деп ойлаймын. Құдай керағар қасиеттерден менің бойымды тазалағанына шүкіршілік етемін.');
INSERT INTO reflections (day, month, title, text) VALUES (17, 'Апрель', 'СҮЙІСПЕНШІЛІК ПЕН ҚОРҚЫНЫШ ҚАРАМА-ҚАЙШЫ СЕЗІМДЕР', 'Барлық кемшіліктер үрей тудырады, бұл өздігінен психикалық аурудың бір түрі саналады.

«Қорқыныш есік қақты, сенім жауап беріп еді, ол жерде ешкім жоқ болып шықты». Бұл нақыл сөздің авторы кім екенін білмеймін, бірақ ол қорқыныштың иллюзия екенін түсіндіреді. Мен, бұл иллюзияны өзім жасаймын. Ерте кезде үрейді бастан өткергендіктен, бойымда үрейдің болуы мені қорқақ етеді деген қате түсінікте болдым. Батылдықтың анықтамаларының бірі: «қорқынышқа қарамастан дұрыс әрекет ету екенін» түсінбедім. Батылдық біржола үрейден арылу еместігін білдім. Өмірімде сүйіспеншілік болмаса, мені қорқыныш басқаратыны сөзсіз. Құдайдан қорқу дегеніміз - қуаныштан қорқу. Артыма қарап, Құдайдан қорыққан кезде өмірімде қуаныштың болмағанын көремін. Құдайдан қорықпай, қуанышқа бөленуді үйрендім.');
INSERT INTO reflections (day, month, title, text) VALUES (18, 'Апрель', 'ӨЗІҢЕ ДЕГЕН АДАЛДЫҚ', 'Өзгелерді алдау, әдетте, өзімізді алдаудан басталады... Біз басқа адамға адал болғанда, бұл өзімізбен және Құдаймен шынайылығымызды растайды.

Мен ішкен кезде шындықты өзім қалағандай көріп, өзімді алдадым. Өзгелерді алдау бұл - мінез-құлықтың кемшілігі. Тіпті, басқа жандардың мен туралы жоғары пікірде болуы үшін шындықты аздап бұрмалап, көркемдеуге де болмайды. Менің Жоғары Күшім мінездің бұл кемшілігін жоя алады. Бірақ алдымен, мен өзіме көмектесіп, өтіріктен бас тартып, ол көмекті қабылдауға дайын болуым керек. Мен күн сайын өзімді алдау арқылы сәтсіздіктерге тап болып, Анонимді Алкоголиктердің базынасына қалатынымды есте сақтауым керек. Жоғары Күшпен тығыз және адал қарым-

қатынас - бұл өзіңізбен және адамдармен шынайы қарым-қатынас орнатудың ең негізгі жалғыз жол.');
INSERT INTO reflections (day, month, title, text) VALUES (19, 'Апрель', 'ОРТАҚ КЕМШІЛІГІ БАР БАУЫРЛАСТАР', 'Біз, айығатын алкоголиктер, бақытсыздықпен емес, өз кемшіліктерімізбен және оларды түзетуге деген ортақ ұмтылысымызбен бауырласпыз.

Алкоголиктер арасындағы болмыстық, рухани ұқсастық бір түсініксіз құпия. Бірақ ол бар. Мен оны «сеземін». Бүгін адамдарға көмектесе алатынымды және олардың маған көмектесе алатынын сеземін. Мен үшін адамдарға қамқорлық жасау бұл - жаңашыл қызық сезім. Олардың не сезінетінін, не үміттенетінін, не тілейтінін білу; олардың қайғылары, қуаныштары, қорқыныштары, өкініштері туралы білу;

Біреу жеңілдеу үшін осы сезімдердің бәрін олармен бөліскіңіз келеді. Мен мұны қалай жасау керектігін білмедім. Бұл туралы ешқандай түсінік болған жоқ. Маған АА Достастығы мен Құдай адамдарға қалай қамқорлық жасауды үйретеді.');
INSERT INTO reflections (day, month, title, text) VALUES (20, 'Апрель', 'ӨЗ-ӨЗІҢДІ ТАЛДАУ', '...біз Құдайдан біздің ойларымызды дұрыс арнаға бағыттап, өзімізге деген жанашырлықтан, адал емес әрекеттерден, эгоизмнен сақтауды сұраймыз.

Шын жүректен айтылған бұл дұға маған нағыз жанқиярлық пен кішіпейілділікті үйретеді. Себебі, тіпті жақсы істер жасасам да, мен өзім үшін қошемет пен атақ іздедім.

Мен, барлық әрекеттерімнің себептерін зерттей отырып, Құдай мен адамдарға қызмет ете алатынымды түсіндім. Егер, қарсыласпай өзімді Құдайдың ықпалына берсем, көптеген қажетсіз алаңдаушылық жойылып, мені күні бойы Өз қорғанына алатына сенемін. Өзіме деген аяушылық, арсыздық пен эгоизм туралы ойлар

туындаған кезде, бірден арылуға тырысамын. Бұл керағар ойлардан құтылсам, мен Құдайдың назарында өзіммен-өзім, жақындарыммен шаттықта өмір сүремін.');
INSERT INTO reflections (day, month, title, text) VALUES (21, 'Апрель', 'СЕНІМДІ НЫҒАЙТУ', 'Біз айналысып жүрген ісімізді үнемі жетілдірмей, жақсы дүние жасай аламыз деп ойламаймын. Әлемде жақсы нәрсе жасап, АА да жақсы нәтижеге жетуіміз үшін үнемі дамып отыруымыз керек. Біз қызмет көрсетуге ұмтылған рухымызды әркез шыңдап, жігерлендіруге мүдделіміз. Қазіргі қоғамның принциптерін ұстанып, материалист болып келген адамға қиын болуы мүмкін. Бірақ, біз, бойымыздан сарқылмас сенім мен қайтпас қажыр-қайратты табуға тырысуымыз керек. Сенімділікке қол жеткізуге болады, алайда, сенімділік қанымызда қайнау үшін бау ағашы сынды күтімді қажет ететінін ұмытпау керек. Мен үшін бұл оңай болған жоқ, кез келген жанға да қиын іс болады деген ойдамын.

«Қорқыныш» менің сенімді болып, өзіме бекем болуға кедергі келтіретін күш болып табылады. «Қорқыныш» менің сұлулықты, төзімділікті, кешірімділікті, қызмет көрсетуді және жан тыныштығын түсінуіме кедергі келтіреді.');
INSERT INTO reflections (day, month, title, text) VALUES (22, 'Апрель', 'ЖАҢА ЖЕР — ЖАҢА ТАМЫРЛАР', 'Адам түсініктік кезеңде жан тыныштығын құру элементтері ретінде қызмет ете алатынына дәлелдерім бар. Ақиқат тамырлары бізді жоюға бағытталған дауылдарға қарамастан, невротикалық дүмпулерді ығыстыра алады.

Мен АА-ға келгенде жасыл, тамыры ашық, қалтыраған өсімдік сияқты болдым. Бастапқыда аман қалу үшін келдім. Мен өстім, дамыдым, иілдім, бірақ адамдардың көмегімен менің рухым ақыры сыртқа шықты. Мен еркін болдым. Мен көрегендік келгенше әрекет еттім,  әлсіредім,  сүріндім,  дұға  еттім,  қайтадан  әрекет  еттім,

тереңдедім. Менің тамырларымнан шыңдарға дейін созылған жасыл күшті рухани бұтақтар өсті, олар менің биікке ұмтылуыма серпін берді.

Бұл жер бетінде Құдай ешқандай шартсыз жоғары сүйіспеншілік миссиясын жалғастырады. АА Қағидалары бойынша өмір мені "басқа негізге қойды ... [менің] тамырларым жаңа топыраққа ұмтылды." (Анонимді Алкоголиктер, 11 бет).');
INSERT INTO reflections (day, month, title, text) VALUES (23, 'Апрель', 'АА — ПАНАЦЕЯ ЕМЕС (ПАНАЦЕЯ – БҰЛ МИФОЛОГИЯЛЫҚ, БАРЛЫҚ АУРАДАН ЕМДЕУШІ)', 'АА-ны, тіпті алкоголизмнің панацеясы деп атау жалған болар

еді.

Мен, сауығудың алғашқы жылдарында АА-ның бақытты өмірге

жеткізетін жалғыз жол екеніне сенімді болдым. Әрине, бұл менің сауығуымның негізгі қасиеті болды.Қазір де, Бағдарламада он екі жылдан астам уақыт жүргеніме қарамастан, жиындарға белсенді қатысып, тәлімгерлік етіп, қызмет көрсетумен айналысамын. Айығудың алғашқы төрт жылында кәсіби мамандардың көмегіне жүгінуді қажет деп санадым. Себебі, өзімді эмоционалды түрде өте нашар сезінетінмін. Басқа ұйымдарда саулық пен бақытқа қол жеткізген адамдар бар. АА маған сауығуды нығайту үшін тоқтамау керектігін үйретті. АА панацея болмауы мүмкін, бірақ ол менің салауатты өмірімнің орталығы болып табылады.');
INSERT INTO reflections (day, month, title, text) VALUES (24, 'Апрель', 'ӨЗ-ӨЗІҢДІ СҮЮДІ ҮЙРЕНУ', 'Бізді жақсы көретін адамдар болса да, алкоголизм бізді жалғыздыққа әкелді. Біз өзгелерді өзімізге тәуелді ету немесе оларға тәуелді болу арқылы эмоционалды тұрақтылыққа ұмтылдық… Біз үстемдік құрып немесе бағыну арқылы қауіпсіздікті қамтамасыз етуге тырыстық.

Мен, өзіме моральдық есеп берген кезімде көп жандармен, достармен немесе отбасыммен, дұрыс емес қарым-қатынаста болғанымды байқадым. Мен әрдайым оқшауланып, өзімді жалғыз сезінгендіктен жан тыныштығын ішімдіктен іздейтінмін.

Саулықтың, жақсы тәлімгердің және Он Екі Қадамдық Бағдарламаның арқасында, өзіме деген құрметімді арттыра алдым. Алдымен, Он Екі Қадам маған өзіммен қалай достасуды үйретті. Кейіннен, өзімді жақсы көре алғанда, адамдармен жақындасып, оларды да жақсы көре бастадым.');
INSERT INTO reflections (day, month, title, text) VALUES (25, 'Апрель', 'ЖАҢА ӨЛШЕМГЕ ҚАДАМ БАСУ', 'Ішкіліктің соңғы кезеңінде бізде қарсылық таныту қабілеті жоғалды. Бірақ біз толық жеңілісімізді мойындап, АА қағидаларын сынап көруге дайын болған кезде, бізді тәуелділік тастап кетті, біз жаңа өлшемге — Құдай астындағы еркіндікке кіреміз.

Мен өз өмірлерінде осы керемет өзгерістерді басынан өткергендердің арасында екенімді қуанышпен қабылдаймын. Мен, жалғыздық пен үмітсіздік сезімін бастан өткеріп, АА есігін ашқанда естігенімнің бәріне сенуге дайын болдым. Естігенімнің ішінде: "Бұл сенің соңғы қателігің болуы мүмкін, немесе сен шеңберде қаласың," деген сөз қатты әсер етті. Мұны айтқан адам менен әлдеқайда жақсы жағдайда болды. Жеңілісімді мойындау идеясы маған ұнады. Осы сәттен бастап мен еркін болдым! Менің жүрегім бұрын-соңды тыңдамағанды естіді: "Алкоголь алдындағы дәрменсіздігіңді мойындауда тұрған ештеңе жоқ." Мен еркінмін және ризамын!');
INSERT INTO reflections (day, month, title, text) VALUES (26, 'Апрель', 'МӘСЕЛЕ БАҚЫТТА ЕМЕС', '"Бақытты болу" талпынысымда жұмысымды өзгерттім, үйленіп, ажырастым, тұрғылықты жерімді өзгерттім, қаржылық, эмоциялық және рухани қарызға батып кеттім. АА-да мен есеюді үйренемін. Адамдардан, қызметтен, дүние-мүліктен бақыт іздемей, Құдайдан өзімді осы қалпымда қабылдауды үйретуін сұраймын. Бір мәселе мені мазаласа, АА-ның Он Екі Қадамы маған ауыртпалықты жеңуге көмектеседі. Менің алған білімім осындай мәселелерден зардап шегетін, басқа адамдар үшін таптырмас қазына бола алады. Билл айтқандай: «Мүмкін, біз басқаларға үйрету үшін ауыртпалыққа тап боламыз. Сол себепті әр істен сабақ ала білу қажет. Қуанышты күндерде біз оны сыйлық ретінде қабылдап, Құдайға алғысымызды айтамыз ғой. Сол сияқты қиын сәттерде де шүкірлігімізді жоғалтпауымыз керек»');
INSERT INTO reflections (day, month, title, text) VALUES (27, 'Апрель', 'ҚУАНЫШТЫ ЖАҢАЛЫҚ', 'Біз біліміміздің шектеулі екенін түсінеміз. Құдай сізге және бізге үнемі жаңалық ашып отырады. Таңертеңгі ойлану кезінде Тылсым Күштен ауруларды жеңілдету үшін не істей алатыныңызды сұраңыз. Сіз өзіңіздің үй шаруашылығыңызда тәртіп орнатсаңыз, көп сұраққа жауап аласыз. Әрине, өзіңізде жоқ нәрсені басқа адамдарға бере алмайсыз. Құдаймен қарым-қатынасыңызды қадағалаңыз, сол кезде сіздің де және басқа жандардың да өмірінде үлкен өзгерістер болады. Бұл біз үшін – ақиқат.

Саулық — қуанышты жаңалықтарға сапар. Әрбір жаңа күн, жаңа тәжірибе, жаңа түсінік, үлкен үміт, терең сенім, үлкен төзімділік әкеледі. Мен бұл қасиеттерді сақтауым керек, әйтпесе, өзгелермен бөлісер ештеңем болмайды.

Сауығу жолындағы алкоголик үшін Құдайдың рақымында тағы бір күн өмір сүрсе, бұл күнделікті қуанышымен қатар, маңызды оқиға болмақ.');
INSERT INTO reflections (day, month, title, text) VALUES (28, 'Апрель', 'ЕКІ ҒАЖАЙЫП ҰҒЫМ', 'АА-да сауығуды екі ұғыммен бағалауға болады: кішіпейілділік пен жауапкершілік. Біздің бүкіл рухани дамуымыз осы тамаша қасиеттерге деген адалдығымызбен өлшенеді.

Басқалардың көзқарастарын, жетістіктерін, құқықтарын ескеру, құрметтеу, сондай-ақ, өз қателіктерімді мойындау кішіпейілділікке жол көрсетеді. АА қағидаларын барлық істерде қолдану мені жауапкершілікке жетелейді. Осы принциптердің барлығын сақтау, біздің Достастықтың Төртінші дәстүріне де, басқа да барлық дәстүрлерге деген сенімділікті тудырады. Анонимді Алкоголиктер ақылға қонымды тілектерге толы, принциптермен және этикалық құндылықтармен байытылған өмір философиясын жасады. Олар алкоголиктерге ғана емес, басқа адамдардың қажетіне жарайтын көзқарас қалыптастырды. Осы принциптерді ұстану үшін маған тек дұға етіп, серіктестеріме бауырларым сияқты қамқорлық жасауым керек.');
INSERT INTO reflections (day, month, title, text) VALUES (29, 'Апрель', 'ТОПТЫҢ ТӘУЕЛСІЗДІГІ', 'Кейбіреулер топтың тәуелсіздік қағидаларын шегіне жеткіздік деп ойлауы мүмкін. Мысалы, өзінің "кеңейтілген формасында" Төртінші Дәстүрде: "Жан серігін тапқан кез келген екі немесе үш алкоголик басқа бірлестіктермен байланысы жоқ болса да, өзін АА тобы деп атауға құқылы..." деп баяндалады. Бірақ бұл шамадан тыс еркін болып көрінгенмен айтарлықтай қауіп жоқ.

Белсенді алкоголик ретінде, мен, өмір берген кез келген еркіндікті асыра пайдаландым. Төртінші Дәстүр ұсынған "шамадан тыс еркіндікке" құрметпен қарағанымды АА қалай қабылдайды?! Құрмет көрсетуді үйрену менің күнделікті жұмысым болды.

АА мені тәртіптің қажеттілігін, олай болмаған жағдайда оның өтемін жасауға тура келетінін толық мойындатты. Бұл топтарға да қатысты.

Төртінші Дәстүр, менің алкогольге бейімділігіме қарамастан, маған рухани бағыт береді.');
INSERT INTO reflections (day, month, title, text) VALUES (30, 'Апрель', 'БІР ҚЫЗЫҚ ҚҰБЫЛЫС', 'Алкоголиктердің ортасында бастан өткен азаптарды талқылап, шипагерлік сұхбат құру оңай. Мұндай байланыс қабілеті бізге Құдайдан берілген сыйлық. Бүкіл әлемдегі АА топтарының басты мақсаты осы әдісті басқаларға жеткізу.

АА-ғы бір қызық құбылыс – мен, бағалы саулық сыйлығын бөліспесем, оны сақтай алмайтынымды білемін. Менің басты міндетім – сау қалпымды сақтау. АА-да менің басқа мақсатым жоқ. Бұл мен үшін маңыздылығы соншалық, өмір мен өлім мәселесі. Осы жолдан тайсам, ұтыламын. Бірақ АА мен үшін ғана емес, АА әлі де зардап шегіп жатқан алкоголиктер үшін жұмыс істейді. Сауығып жатқан алкоголиктер өз бауырластарымен салауатты өмір салтын бөлісу арқылы, сау қалыптарын сақтайды. Қалпыма келу жолымды баяндау арқылы АА-дағы басқа жандарға үлгі бола алсам, біз бәріміз Жоғарғы Күштің шарапатына бөленіп, мәнді-мағыналы өмір сүреміз.');
INSERT INTO reflections (day, month, title, text) VALUES (1, 'Май', 'ЖҮРЕК ПЕН АҚЫЛДЫ ЕМДЕУ', 'Біз, Құдаймен қатар, өзіміздің және басқа жандардың алдында адасқанымызды мойындадық.

«Құдай адамдар арқылы әрекет етеді» деген пікірге сәйкес, мен адамдардан алыстаған сайын, өзім де Құдайдан алыстайтынымды байқаймын. Құдай мен ойлағаннан әлдеқайда жақын. Жаратқанның құдыретін өзімнен бөлек, өзгелерге сүйіспеншілік танытқанда ғана сезінбекпін. Бірақ бұл жолда шынайылық танытпасам, мен өзгелерді жақсы көріп, жақсы көріне де алмаймын.

Көлеңкемен көлегейлеп назар аударғым келмейтін әлсіздігім маған үстемдік құрады. Ақыл мен жүректі емдеу — бұл менің еркіндікке апаратын жолым. Сол себепті қараңғы жағымды назарсыз қалдырмауым керек. Жарықты табу үшін қараңғылықты, жан тыныштығын табу үшін үрейді бастан өткеруге мүдделімін.

Бойымда жасырынып жатқан сырды ашу арқылы өзімді айыптау сезімінен арылып, ойымды өзгерте аламын. Ойымды өзгертсем, өзімді өзгертемін. Менің ойларым болашағымды қалыптастырады. Менің ертең қандай болатыным, бүгінгі ойларыммен анықталады.');
INSERT INTO reflections (day, month, title, text) VALUES (2, 'Май', 'ҚАРА ТҮНЕК ӨТКЕНІМІЗДІ ЖАРЫҚТАНДЫРУ', 'Құдай сіздің қараңғы күндеріңізді кілт ретінде пайдаланып, басқа жандарды бақытқа жеткізеді. Бұл ойдан ажырамаңыз. Сіздің өмірлік тәжірибеңіз өзгелерге өнеге болып, өлім мен қайғыдан құтылуға септігін тигізеді.

Менің өткенім - енді өмірбаян емес. Бұл сансыз сұраққа жауап беретін бағыттаушы нұсқаулық. Бүгін жұмысқа келіп, керемет көріністі көремін. Осы күн бұлыңғыр болса да, кейбір күндерге сәйкес келетініне сенімдімін. Бірақ біраз уақыттан кейін жұлдыздар жарқырайды. Бұл жақын болашақта болатын құбылыс. Мен де бұл

жарық нұрдан кенде қалмайтыным анық. Осы күнге дейін бейне бір құлып сынды өткенім кілтке айналып, менің бір бөлігім болады.');
INSERT INTO reflections (day, month, title, text) VALUES (3, 'Май', 'ТАЗАЛЫҚ ЖАСАУ', 'Неге біз басқа адаммен бірге болудан гөрі, Құдаймен жалғыз қалуға ұмтыламыз?! Біз жанымызды жегідей жеген ойларымызды өзгелермен талқыламай «үй тазалауға» деген ниетімізді оята алмаймыз. Бұл теорияда бар әдіс.

Мен үшін мінезімнің кемшіліктерін Құдайға немесе өзіме айту өте оңай. Бірақ басқа адаммен бетпе-бет отырып, қыңыр қылығымды талқылау әлдеқайда қиын болды. Еш қысылмай бар сырыммен бөлісе бастағанда, алғаш рет өзімді «алкоголик» деп таныған кездегідей жеңілдік сезіндім. Мен Бағдарламаның рухани мәнін бағалай бастадым. Бұл Қадам басқа Қадамдардың кіріспесі ғана екенін түсіндім.');
INSERT INTO reflections (day, month, title, text) VALUES (4, 'Май', 'ШЕКСІЗ ШЫНАЙЫЛЫҚ', 'Егер, осы әлемде ұзақ өмір сүріп, бақытты болғымыз келсе, кімге болмасын шынайы болуымыз керек.

Шынайылықты, басқа да қасиеттер сияқты өзгелермен бөлісу керек. Мен "... бүкіл өмірбаянымды басқа біреумен бөліскенде..." ғана шыншылдыққа қол жеткіздім. Бұл әрекет Достастықта өз орнымды табуға септігін тигізді. Кейінірек жаңадан келгендер қатарға қосылып, өз орнын табу үшін өз тәжірибеммен бөлістім. Мұндай тәжірибе алмасу барлық істерімде адал болып, шынайы ашықтығымды айқындай түспек. Сондай-ақ, Құдай ниетім мен дайындығым арқылы игі істерді жүзеге асырып жатқанына сенгім келеді.');
INSERT INTO reflections (day, month, title, text) VALUES (5, 'Май', 'АҒАШТАР МЕН ОРМАН', 'Біз өзіміз жалғыз болғанда өмірдің жағдаяттарын өз ыңғайымызға қарай бұрмалауымыз мүмкін. Біз сұхбаттасу арқылы өзгелердің пікірін тыңдап, кеңес ала аламыз.

«Ағаштардың артындағы орманды көрмеймін!» деп ашуланған, ренжіген кездерімде есеп жоқ. Ақыры осындай ауыр сәттер ағаштарды орманнан ажырату үшін бағыт-бағдар беретін қажеттілік екенін түсіндім. Маған жақсы жол ұсынып, өрттерді сөндіріп, жартастар мен шұңқырлардан өтуге көмектесетінін түсіндім.

«Орманда» болған кезімде, Құдайдан АА мүшелерінің біріне қоңырау шалуға батылдық беруін сұраймын.');
INSERT INTO reflections (day, month, title, text) VALUES (6, 'Май', 'ЕШНӘРСЕНІ ІШТЕ ҰСТАМАУ', 'Таңдауыңыздың дұрыстығын дәлелдейтін ең жақсы дәлел — бұл адамдарға ашық болып, өткеніңіздің моральдық өлшемімен бөлісуге дайын болу.

...Егер, сіз ештеңе жасырмасаңыз, жеңілдік сезімі минут сайын артады. Адам баласы шер тарқатқанда, жылдар бойы жиналған барлық жиіркенішті эмоциялар, ғайыптан жоғалып, барлық кедергіні бұзып өтетіндей күш-қуатқа ие болады. Ауыртпалық сейіліп, оның орнын тыныштық басады.

Алғашқы бірнеше АА жиналыстарына қатысқаннан кейін ұзақ уақыт бойы сақталған кішкентай сезім дәнегі өне бастады. Сол кезде өзімді-өзім зерттей бастадым. Өзін-өзі түсінудің жаңа деңгейі, менің өмірлік жағдайларға деген көзқарасымды өзгертті. Менде таңдау бар екенін түсіндім, ал, ескі әдеттердің нұсқауы бірте-бірте әлсіреді.

Мен Құдайға бет бұрсам, өзім үшін қолайлы өмір салтын ұстана аламын деген ойдамын. Сондықтан, Тылсым Күштен күн сайын маған байсалды өмір беруін сұраймын.');
INSERT INTO reflections (day, month, title, text) VALUES (7, 'Май', 'ӨЗГЕЛЕРДІ ҚҰРМЕТТЕУ', 'Біз өз сырымызды түсінетін, бірақ, біздің айтқан сырымыз ол адамға зиянын тигізбеуі тиіс. Ереже: біз өзімізге талапшыл, бірақ басқаларға ықыласты болуымыз керек.

Дәйексөзден мен үйренетін сабақ — бұл басқаларға деген құрмет. Егер, өзім іздеген жан дүниемнің жағдайына жеткім келсе, өз еркіндігім үшін бәрін жасауым керек. Алайда бұл еркіндік ешбір жағдайда басқа адамдардың есебінен болмауы тиіс. АА қағидаларының негіздемесінде эгоизмге орын берілмейді.

Бесінші Қадаммен жұмыс істегенде, өзіммен мүдделес жандарды таңдау орынды болмақ. Егер, адамдар мені түсінбесе, онда менің рухани өсуім тоқтап, тіпті артқа кету қаупі бар. Сондықтан, біреуді сенімді тұлға ретінде таңдаудан бұрын, Құдай басшылық беруін сұраймын.');
INSERT INTO reflections (day, month, title, text) VALUES (8, 'Май', 'ДЕМАЛУ ОРНЫ', 'АА-ның барлық Он Екі Қадамы біздің табиғи ұмтылыстарымызға қарама-қайшы келеді... олар бізді "менмендіктен" арылтады. Менмендіктен арылудың соңғы кезеңдеріне келгенде, Бесінші Қадам ең қиыны болмақ. Бірақ одан кейінгі байсалды, салауатты өмір салты мен жан тыныштығы үшін бұл ең қажетті Қадам ретінде саналады.

Мен мінез-құлқымның кемшіліктерін қағазға жазғаннан кейін де, олар туралы айтқым келмеді. Бірақ ақырында бұл жүкті арқалап жүруді тоқтататын кез келді деп шештім. Бұл өте ауыр болды. Мен бұл кемшіліктер туралы біреуге айтуым керек еді. Егер, бұлай істемесем, байсалды болып қалу мүмкін емес екенін оқыдым (маған ескертілді). Бесінші Қадамды күнделікті өмірімде қолданған кезде, қарапайымдылық пен жан тыныштығымен қатар, адамдармен дұрыс қарым-қатынасқа қол жеткіздім. Мінез-құлқымның кемшіліктерін Бесінші Қадамда айтылған тәртіпке сәйкес: "Құдайдың, өзімнен

бөлек, басқа бір жанның алдында" мойындау маңызды болды. Әуелі, қыңыр қылығымды Құдайдың алдында мойындауым, өзімнен бөлек, өзгелердің алдында мойындауыма жол ашты. Бесінші Қадамда жазылғандай, Құдаймен және жолдасыммен бірлікте болу, мен үшін бір демалыс еді. Бұл демалыс аясында алдағы уақытта өте маңызды, терең саулыққа жетелейтін қалған Қадамдар бойынша жұмыс істеуге дайындала алдым.');
INSERT INTO reflections (day, month, title, text) VALUES (9, 'Май', 'ҚОРҚЫНЫШТАН АТТАП ӨТУ', 'Егер, бойымыздағы жамандықтан арылғымыз келмесе, Құдайдан пейілімізді түзеп, осы тілекке қол жеткізуін сұраймыз.

Бесінші Қадаммен жұмыс істеу барысында мінез-құлқымдағы барлық кемшіліктер қауіпсіздік пен сүйіспеншілік қажеттілігінен туындайтынын түсіндім. Бұл кемшіліктермен тек өз еркіммен жұмыс істеу ессіздік болар еді. Алтыншы Қадамда күш-жігерімді арттыра бастадым. Атап айтқанда, мен медитация жасадым, қадамның мазмұнын үнемі қайталадым, жиналыстарға бардым, тәлімгердің кеңестеріне құлақ астым, оқыдым, ішкі әлемімнен күш-қуат іздедім.

Саулықтың алғашқы үш жылында лифтке жалғыз кіруден қорқатынмын. Бірде осы қорқыныштан аттап өтуге бел будым. Құдайдан көмек сұрап, лифтке кіргенімде жылап тұрған әйелді көрдім. Ол күйеуін жерлегеннен бері лифттен өлердей қорқатынын айтты. Мен қорқынышымды ұмытып, оны жұбатуға тырыстым. Бұл рухани тәжірибе «дайындық». Бұл Он Екі Қадам Бағдарламасы бойынша жұмыс істеп, қалпыма келуімнің кілті екенін түсіндім.

«Әрекет еткенге Құдай әрдайым жәрдем береді».');
INSERT INTO reflections (day, month, title, text) VALUES (10, 'Май', 'БОСТАНДЫҚҚА ҚОЛ ЖЕТКІЗДІМ', 'Басқа адамдардың алдында кемшіліктерімізді мойындағанымыз үшін берілетін марапат - бұл мойынсұну... алайда, осы сөздің мағынасын қате түсінуіміз мүмкін. Бірақ бұл біз өзіміздің кім екенімізді біліп, өзімізді кім санайтынымызды түсінумен тең. Сондай-ақ, ізгілікке ұмтылудың мәнін тереңнен түсіндіреді.

Егер, бақытты және еркін болғым келсе, өткен өмірім туралы біреумен бөлісуім керек екенін түсіндім. Бұл істен кейін, мені қандай қуаныш пен жеңілдік сезімі баурап алғанын сипаттау мүмкін емес. Бесінші Қадамнан кейін мен үшін тұзақ болған алкогольдің құлдығынан босап қалғанымды сезіндім. Бұл еркіндік отыз алты жыл бойы күн сайын сақталады. Мен өзім үшін қайырлы іс жасай алмасам да, бірақ бұл істі Құдай істей алатынын білемін.');
INSERT INTO reflections (day, month, title, text) VALUES (11, 'Май', 'ЖАҢА ІСКЕ АРАЛАСУ', 'Біз даулы мәселелерімізді ашық талқыламай және басқалардың дәл солай істегенін тыңдамайынша, әлі де толық іске араласа алмадық.

АА-да төрт жыл жүргеннен кейін, жанды жегідей жеп, жасырынып жатқан эмоциялардың ауыртпалығынан құтылу мүмкіндігін көрдім. Кәсіби мамандардың кеңесімен және АА көмегі арқылы ауыртпалықтан арылып, толық іске араласып, жан тыныштығының рахатын сезіндім. Мен бұрын-соңды сезінбеген Құдайдың қуанышы мен сүйіспеншілігіне қол жеткіздім. Бесінші Қадамның күшіне бас иемін.');
INSERT INTO reflections (day, month, title, text) VALUES (12, 'Май', 'ӨТКЕН КҮН ЕНДІ ЖОҚ', 'Басқа АА мүшелерінің тәжірибесі өзіміз шеше алмайтын сансыз мәселелерді, сондай-ақ, осы мәселелерді тудырып, ушықтырған қыңыр қылығымызбен өмір сүре алмайтынымызды көрсетті. Егер, біз Төртінші Қадамды орындап, барлық өмірімізді шаммен жарықтандырып, еске алғымыз келмейтін өткенімізді анық көрсете аламыз. Қыңыр ойлар мен қырсық әрекеттер өзімізге және айналамыздағыларға зиян тигізгенін түсінетін болсақ, өткен күннің тауқыметін арқаламауға үндейді. Біз ол жайында шер тарқатып, сыр бөлісіп отыруымыз керек.

Болар іс болды, бояуы сіңді. Өткенді өзгерту мүмкін емес. Бірақ өзімнен бұрын бұл жолдан өткен тәлімгерлердің кеңесімен өткеніме деген көзқарасымды өзгертуге болады. Өткенімді мүлдем жауып тастай алмаймын. Алайда, болған оқиғаға қатысты әрекеттерімді өзгертсем, көзқарасым да өзгереді. Басымнан өткен олқылықтарға өз сезімдерімді және көзқарасымды өзгерте аламын. Дегенмен, бұл іске тек дұрыс әрекет етіп, алкоголик достарымның көмегімен ғана қол жеткіземін.');
INSERT INTO reflections (day, month, title, text) VALUES (13, 'Май', 'ЖЕҢІЛ ЖӘНЕ ЖАЙЛЫ ЖОЛ', '... егер біз бұл маңызды кезеңнен өтпесек, ішуді тоқтата алмаймыз.

Ішімдік ішуімнің азабы әлі де үстімде бұлт сияқты төніп тұрса да, бұрынғы қалпыммен бетпе-бет кездесуге мүмкіндігім бар екеніне қуаныштымын. Бірақ көп ұзамай жиналыстарда Бесінші Қадаммен жұмыс істегісі келмейтін АА мүшесі туралы естідім. Ол жиналыстарға қатысуды жалғастырса да, өткен күннің әлегі жадысында қайта жандануынан қатты қорқатын. Айықпас ауруымыздан арылып, азаттыққа жету үшін Қадамдарды орындап, біздің Достастық пен Жоғарғы Күшке сену әлдеқайда оңай және қарапайым жол.');
INSERT INTO reflections (day, month, title, text) VALUES (14, 'Май', 'ӨЗІҢМЕН ӨЗІҢ БОЛУ ЖАҚСЫ', 'Кейде жаңадан келгендер өмірлерінің көлеңке тұстарын жасыруға тырысып, жеңіл әдістерді пайдаланды. Бірақ іс жүзінде олар мойынсұнудың не екенін білмеді...

Мойынсұну көпшілікке қорлау болып көрінеді. Бірақ шын мәнінде бұл өзіңізге шынайы қарай алатын қабілет. Енді маған барлық істе «ең ақылды», «ең жақсы» болудың қажеті жоқ. Ақырында, жай ғана өзіммен өзім болғаным жақсы. Мен өткен өміріммен бөліссем, өзімді қабылдау оңайырақ болады. Егер, кездесулерде өзім туралы ашылып айта алмасам, тәлімгер табуым керек. Сол тәлімгеріме мені қайтадан ішімдікке, яғни өлімге қайтаратын «белгілі бір фактілерді» айтып сыр бөлісе аламын. Маған барлық қадамдарды жасау керек. Маған шынайы кішіпейілділікті үйрену үшін Бесінші Қадам қажет. Жеңіл әдістердің қайыры болмайды.');
INSERT INTO reflections (day, month, title, text) VALUES (15, 'Май', 'ҚҰДАЙДЫ ТАНУ - ЖАН ТЫНЫШТЫҚТЫҒЫНЫҢ КЕПІЛІ', 'Өмірге риза болмай өмірдің мәні жоқ. Тағдыр тәлкегіне түсіреді. Рухани тәжірибені сақтап, өсуге ұмтылған алкоголиктер үшін наразылық қажетсіз дүние.

ҚҰДАЙДЫ ТАНУ АРҚЫЛЫ ТЫНЫШТЫҚҚА ҚОЛ ЖЕТКІЗЕСІҢ.

ҚҰДАЙ БОЛМАЙ — ТЫНЫШТЫҚ ЖОҚ.');
INSERT INTO reflections (day, month, title, text) VALUES (16, 'Май', 'БІЗ КЕШІРЕМІЗ…', 'Көбінесе осы Қадаммен тәлімгермен немесе рухани кеңесшімен жұмыс істегенде, өзгелер бізді қанша ренжітсе де, оларды кешіре алатынымызды алғаш рет сезіндік. Өзімізге моральдық баға беру әрдайым кешірім жасаудың орынды екенін көрсетті. Бірақ Бесінші Қадаммен шындап жұмыс істеген кезде ғана біз кешіру мүмкіндігі мен кешірім сыйлау қабілетін ішкі тұрғыдан түсінеміз.

Кешіру қандай тамаша сезім! Эмоционалды, психологиялық және рухани болмысымда қаншама жаңа дүниелер ашылады! Мұның бәріне жету үшін тек кешірім жасауға дайын болсам болғаны, қалғанын Құдай өзі реттейді.');
INSERT INTO reflections (day, month, title, text) VALUES (17, 'Май', 'ТАҒЫ ДА КЕШІРУ', 'Өмірімдегі ең қиын жағдайларда басқаларды қайта-қайта кешіре алуым, өзімді кешіруімді білдіреді.

Өзіңді кешіру және басқаларды кешіру бұл бір өзеннің екі ағысы іспеттес. Өкпе-реніш бұл ағысқа бөгет сынды кедергі келтіреді. Егер сол бөгетті алып тастасаңыз, екі ағыс қайта аға бастайды. АА Қадамдары реніш сезімінің қалай пайда болып, өмірімнің бағытын қалай жауып тастағанын көруге мүмкіндік береді. Қадамдар менің түсінігімдегі Құдайдың шарапаты арқылы бұл сезімді жоюдың жолын көрсетеді. Осы шешімнің нәтижесінде өзімді және өзгелерді кешіруге мүмкіндік аламын.');
INSERT INTO reflections (day, month, title, text) VALUES (18, 'Май', 'ӨЗІҢМЕН ӨЗІҢ БОЛУ ЕРКІНДІК', 'Егер дамуымыздың бұл кезеңі біз үшін ауыр болса, жарты жол артта қалған кезде таң қаламыз. Бізді еркіндік пен шаттық күтіп тұрғанын білеміз.

Менің алғашқы және шынайы еркіндігім — бүгін ішімдіктен алыс болу. Егер шын жүректен ішкім келмесе, Он Екі Қадаммен жұмыс істеймін. Тәуелсіздіктің бақыты маған Қадамдар арқылы келеді. Бұл жағдай бәлкім жақын арада, бәлкім баяу жүзеге асуы мүмкін. Осы сәтте бұрын-соңды болмаған еркіндікке қол жеткіземін. Осы тәуелсіздік өміріме жаңа серпін беретін жаңаша еркіндіктің жаршысы болмақ. Бүгін өзіммен өзім болу еркіндігін иеленсем, маған тағы бір жаңаша еркіндік сыйға беріледі. Бұрынғыдан да жақсы болу еркіндігі менің қолымда!');
INSERT INTO reflections (day, month, title, text) VALUES (19, 'Май', 'ҚАЙТЫМЫН КҮТПЕЙ ЖАҚСЫЛЫҚ ЖАСАУ', '(шартсыз беру)

Ол өзгелерден ештеңе талап етпестен жақсылық жасағаны үшін өмірінің құндылықтарға толғанын жақсы біледі. Бұл оған Тәңір тарапынан берілген қосымша сыйақы іспеттес.

Бағдарламамен алғаш танысқан кезде «шартсыз беру» тұжырымдамасын дұрыс түсінбедім. Маған көмектесуге тырысқан кез келген адамға күмәнмен қарадым. Бастапқыда: «Олар ақысына не сұрайды екен?», — деген ойда болдым. Бірақ көп ұзамай өзім де басқа алкоголиктерге көмектесіп қуанышқа бөлендім. Ақырында, олар не себепті маған жақсы қарым-қатынаста болғанын түсіндім. Өзгелерге көмектесуге деген ниетім оянып, көзқарасым өзгерді. Кейде сәл қобалжыдым. Себебі өзім көмек көрсеткен жандардың қуанышқа кенеліп, өмірдің қандай көркем екенін сезінгенін жан- тәніммен қаладым. Өз түсінігімдегі Құдайға деген сүйіспеншілігім артқан кезде, бұл сүйіспеншілікті өзіммен серіктес-алкоголиктермен бөлісемін. Ерекше байлыққа ие болғандай түсініксіз бір ғажап сезім пайда болады.');
INSERT INTO reflections (day, month, title, text) VALUES (20, 'Май', 'КҮН САЙЫН', '...Ең бастысы күніне бір жақсы іс істеңіз.

Өмір бойы ішпеу керек екенін біле тұра, не себепті өзімді бір күн ғана ішпеуім керек деп алдаймын?! Бұл өзімді алдағаным емес. Менің түсінігімде күн сайынғы кішкентай Қадамдар арқылы, ұзақ уақыт сау қалпымды сақтай аламын.

Егер «өмір бойы ішпеймін» деп шешім қабылдасам, өзімді қоршауда қалғандай сезінемін. Болашақта не күтіп тұрғанын білмегендіктен, қалайша ішпеймін деп сенімді айта аламын?!

«Күн сайын, бүгін ғана» тұжырымдамасына сай ішімдіксіз бір күн шыдай алатынымды білемін. Мен осы сенімге сүйене отырып,

әр күнімді бастаймын. Күн аяқталғанда «өз мақсатыма жеттім» деген марапатқа ие боламын. Бір іске қол жеткізсем ерекше әсерге бөленіп, сол жағымды әсерден айрылғым келмейді.');
INSERT INTO reflections (day, month, title, text) VALUES (21, 'Май', 'СЫЙЛЫҚТАР ТІЗІМІ', 'Айналысатын жаттығуларымның бірі атқарған игі істерімнің толық тізімін жасау...

Қандай дүниеге ризашылық білдіре аламын? Мен оқшауланып, өз еңбегіммен келмеген ырыздықтардың тізімін жасадым; есім дұрыс және денім сау болып дүниеге келуімнен бастадым. Мен өмірімнің жетпіс бес жылын басынан бастап қазіргі уақытқа дейін қарастырдым. Тізім екі бетке созылды. Бұл істе екі сағат жұмсап, назарымнан ештеңені тыс қалдырмауға тырыстым; денсаулық, отбасы, ақша, АА сияқты бөлімдерді де жаздым.

Мен күн сайын дұғаларымда Құдайдан осы тізімді есте сақтап, сол ырыздықтар үшін тәубе ете алатындай ақыл сұраймын. Осы шүкіршілік тізімі есімде тұрған кезде, Құдайды әділетсіз деп ойлауға дәтім бармайды.');
INSERT INTO reflections (day, month, title, text) VALUES (22, 'Май', 'БІРІНШІ ҚАДАМ', 'Біз… (Бірінші Қадамның бірінші сөзі)

Мен ішкенде тек: «Мен, мен, мен» немесе «Маған, маған, маған» деп ойлайтынмын. Мұндай өте ауыр ауру мені менмендікке шоғырландырып, өмірімнің жартысынан көбін шөлмекке байлады.

Күн сайын Құдайды іздеу және Оның еркін орындау жолдары Бірінші Қадамның «БІЗ» деген бірінші сөзінен басталды. Осы «БІЗ» дегенде билік бар, күш бар, қауіпсіздік бар. Мен сияқты алкоголик үшін осы «БІЗ» деген өмір бар. Егер, өз бетімше сауығуға тырыссам, мен өлген болар едім. Құдаймен және басқа алкоголикпен байланыстыратын өмірлік қасиетті мақсат бар... Мен Құдайдың сүйіспеншілігін жеткізуші жанға айналдым.');
INSERT INTO reflections (day, month, title, text) VALUES (23, 'Май', 'РУХАНИ ДЕНСАУЛЫҚ', 'Біз рух ауруын жеңген кезде, психикалық және физикалық тұрғыдан да сауықтық.

Материалдық әл-ауқат пен интеллектуалды әлеуетке негізделген шамадан тыс мақтанышымның салдарынан, өзімнің рухани ауру екенімді қабылдау қиын. Егер, мойынсұнуды бірінші орынға қоя алсам, интеллект қарапайымдылықпен үйлеседі. Қазіргі қоғамдағы көптеген жандардың түпкі мақсаты мәнсап пен байлыққа ұмтылу. Бәрінен биікте болуға ұмтылу, жақсы болып көріну үшін жасандылыққа бой алдыру — бұл рухани ауру.

Мен өз әлсіздігімді түсініп, мойындауым — рухани сауығудың басы. Күн сайын Құдайдан мені нұрландыруын, өз еркімді білуімді, және сол еркіндікті дұрыс пайдана алатындай мүмкіндік сұрау, рухани саулықтың белгісі болмақ. Ісім оңынан жүрген сайын, соғұрлым Тылсым Күштің көмегіне мұқтаж екенімді түсіне алсам, рухани сау болмақпын.');
INSERT INTO reflections (day, month, title, text) VALUES (24, 'Май', 'БАҚЫТТЫ, ҚУАНЫШТЫ ЖӘНЕ ЕРКІН', 'Құдай бізді бақытты, қуанышты және еркін адам ретінде көргісі келетініне сенеміз. Біздің өміріміз қайғы-қасыреттен тұратын көз жастың көлшігі емес. Бірақ кім болса да өз бақытсыздығына өзі кәнәлі екенін түсінеді. Құдай бізге тауқымет бермеді. Қасақана қасырет әкелетін жағдайлар жасаудан аулақ болыңыз. Бірақ қиындық болса, сол қиындыққа Жаратқанның құдыретінен күдер үзбеңіз.

Мен ұзақ жылдар бойы жазалайтын Құдайға сендім. Өзімнің аянышты өміріме сол Құдайды кінәладым. Мен АА Бағдарламасының «құралдарын» алу үшін, өзімнің «қаруымды» қоюым керектігін білдім. Бағдарламаға қарсы тұрмаймын. Себебі бұл ізгілік. Мен сол ізгілікке қарсы шықпадым. Ал әлі де күресу

үстінде болсам, онда, ескі	түсініктерімнен ажырамағанымның белгісі. «...нәтиже нөлге тең» болады.');
INSERT INTO reflections (day, month, title, text) VALUES (25, 'Май', 'ШҮКІРШІЛІКТІ АРТТЫРУ', 'Шүкіршілікті көбейту керек, азайтуға болмайды.

Менің Жоғарғы Күшім маған лайықты өмір сүруге тағы бір мүмкіндік бергеніне өте ризамын. Менің ақыл-ойым Анонимді Алкоголиктер арқылы қайта оралады. Қадамдардың маған берген Уәделері орындалып жатыр. Мен алкогольдік құлдықтан құтылғаныма ризамын. Мен жан тыныштығы мен рухани өсу мүмкіндігі үшін ризамын. Бірақ менің шүкіршілігім көбейіп, азаймағаны жөн. Тек алға жылжып, артқа шегінбеуім керек. Бүгінгі шүкіршілігімді іс-әрекетке айналдырмай, кешегі жиналыстардың немесе Он Екі Қадамды орындаудың арқасында сау бола алмаймын. Осы жүйенің негізін қалаушылардың бірі айтқандай, Достастықтың идеясын басқаларға жеткізу арқылы разылығымыздың көрінісін көрсете аламыз. Іс-әрекеттерсіз разылығым жай ғана жағымды эмоция. Он Екінші Қадам бойынша жұмыс істеп, яғни біздің идеяларымыздың мәнін жеткізіп, АА принциптерін барлық істе жүзеге асыруым керек. Бүгінде өз идеяларымыздың мәнін өзгелерге жеткізу мүмкіндігіне ие болғаныма ризамын!');
INSERT INTO reflections (day, month, title, text) VALUES (26, 'Май', 'ЖАҒЫМСЫЗ ІСТІ ЖАҒЫМДЫ ҚЫЛУ', 'АА-дағы рухани және эмоционалдық өсуіміз сәттілікке емес, сәтсіздіктер мен қателіктерге байланысты. Егер мұны есте сақтасаңыз, менің ойымша сүрінуіңіз сізді төменге емес, жоғары қарай итермелейді.

АА негізін қалаушылардың бірі Билл У басынан өткерген ауыртпалықтар мен қиындықтарға сүйене отырып, бізге нақты нұсқаулық қалдырды. Қайтадан ішімдікке бет бұру байсалдылық пен салауатты өмірге апаратын оң тәжірибе болуы мүмкін. Бұл жағдай

жиналыстарда жиі еститін: «Бірінші рюмканы ішпе!» деген сөздің шындығын растайды. Аурудың үдемелі сипатын растап, рухани Бағдарламамыздың қажеттілігін, сондай-ақ, тартымдылығы мен шыдамдылығын көрсетеді. Егер, мені пасықтығым билесе, бұл қарапайым шындықды өте ауыр жолмен түсінемін.');
INSERT INTO reflections (day, month, title, text) VALUES (27, 'Май', 'АР АЗАБЫНАН АРЫЛУ', 'Күн сайын біз Құдайдың кемелдігіне қарай баяу қадам жасауға тырысамыз. Сондықтан біз ар азабына берілмеуіміз керек...

АА — «Істеме» емес, «Істе» бағдарламасы. АА — бұл соғыс заңы емес; бұл бостандық.

АА — бұл кемшіліктерді жою емес, оларды түзетудің амалы. АА — бұл қасырет емес, құтқару.

АА — бұл менің қазіргі және бұрынғы күнәларым үшін «Ар азабы» емес.

АА — бұл бүгінде мені рухани өсірген «Құдайға мадақ!» айту.');
INSERT INTO reflections (day, month, title, text) VALUES (28, 'Май', 'ТЕҢ ҚҰҚЫҚТАР', 'Кейде көптеген АА топтары ережелер әзірлеу туралы қызу пікірталастар	жүргізеді...		Уақыт	өте		 келе	қорқыныш	пен шыдамсыздық		 жоғалады.	Біз	ешкімді		алкоголизмнен	сауығу мүмкіндігінен		айырғымыз			келмейді.	Біз	мүмкіндігінше	 көп қабылдағымыз келеді және ешқаншан ешкімді топтан шығармаймыз. АА дәстүрлері – Олардың қалай дамығаны туралы

AA Tradition: How It Developed, pp. 10, 11, 12 АА-да маған толық еркіндік ұсынылып, Достастыққа шынайы болмысыммен қабылдады. Менің мүшелікке өтуім қаржылық жағдайыма немесе білім деңгейіме, болмаса қандай да бір кесімшарт арқылы жүзеге аспады. Әлбетте, бұл жағдайға ризамын. Әрдайым мені: « өзім басқаларға осындай теңдік ұсына аламын ба?»,- деген ой

мазалайды. Бүгін мен қорқыныш пен шыдамсыздықты сенімге, шыдамдылыққа, сүйіспеншілікке алмастыруға тырысамын. Мен бұл күштердің құдыретін АА тобында, үйімде және жұмыста сақтауға талпынамын. Қайда барсам да, позитивті қарым-қатынас жасауға күш саламын.

Басқаларды сынауға ешқандай құқығым жоқ. Өмірлік міндетіме де кірмейді. АА-дағы жаңадан келгендерді, отбасымды, достарымды дос немесе қас тұтуым өзіме байланысты. Кейде өткен ұстанымдарымды есіме алсам, «өзімшілдігім» рухани болмысыма қалай зиян тигізгенін айқын көремін.');
INSERT INTO reflections (day, month, title, text) VALUES (29, 'Май', 'ШЫНАЙЫ ШЫДАМДЫЛЫҚ', 'АА мүшесі болудың жалғыз шарты – ішімдік ішуді тоқтатуға деген ниет.

Үшінші Дәстүрдің қысқаша формасын алғаш рет құжаттардың кіріспесінде естідім. АА-ға келгенде бастапқыда өзімнің алкоголик екенімді мойындап, Жоғарғы күшті қабылдай алмадым. Егер АА мүшелігі үшін физикалық, ақыл-ой, моральдық немесе діни талаптар болса, мен қазірдің өзінде өліп қалатын едім. Билл У. дәстүрлер туралы аудиожазбасында: «Үшінші Дәстүр — бұл жеке бас бостандығының хартиясы (ресми мадақтама)» дейді. Ең бастысы, мені АА мүшелерінің Үшінші Дәстүрге сай қабылдағаны қатты әсер етті. Әлемді осы қалпында қабылдау – сүйіспеншілік, ал сүйіспеншілік – біз орындайтын Құдайдың еркі деп білемін.');
INSERT INTO reflections (day, month, title, text) VALUES (30, 'Май', 'БІЗДІҢ НЕГІЗГІ МАҚСАТЫМЫЗ', 'АА өзінің негізгі мақсатын қаншалықты ұстанса, оның пайдасы соғұрлым маңызды болады.

Мен, Достастағымыздың бастапқы кезеңі туралы ойлаған сайын, алғашқы түлектердің: «басты мақсатымыздан ауытқымауымыз керек» деп жариялаған даналықтарына тәнтімін.

АА өзінен басқа ешқандай іспен айналыспайды. Оны анық білгендіктен алкоголизм саласында жұмыс істейтіндердің бәріне құрметпен қараймын. АА қоғамда монополия орнатып, үстемдік құруға тырыспайды. Осы Достастықтың бар болғаны үшін мейірімі шексіз Құдайға дән ризамын.');
INSERT INTO reflections (day, month, title, text) VALUES (31, 'Май', 'ӨЗГЕЛЕРГЕ ҚЫЗМЕТ ЕТУГЕ ДАЙЫН БОЛУ', 'Біздің Достастық бір ғана миссиямыз бар деген шешімге келді.

Ол: АА идеясын өзгелерге жеткізу...

Егер, біз шын жүректен рухани өсуге ұмтылсақ, менен бөлек, АА-дағы серіктестерім бостандық «нұрына» бөленеді. Өзін-өзі жетілдіруге апаратын «Қадамдар» кішкентай адымдардан басталады. Әрбір Қадам «сатының» бір баспалдағы іспеттес. Бұл рухани сатыны дұрыс пайдалану арқылы кім болса да сәтсіздік шыңырауынан шыға алады. Әділдік мені байлап тұрған «тізбектертен» ажырату үшін қажет. Тәлімгер жан дүниемді түсіну арқылы еркіндікке бағыттап, тура жол табуға көмектеседі.

Құдайдың бар екендігінің куәсі болған Достастық өміршеңдігін жоғалтпағанын қалаймын. Бұл жолдағы борышым өз жетістіктеріммен бөлісіп, өзгелерге қызмет етіп қана қоймай, рухани өсу болмақ.');
INSERT INTO reflections (day, month, title, text) VALUES (1, 'Июнь', 'ӨЗГЕРГЕН КӨЗҚАРАСТАР', 'Біздің дүниетанымымыз өзгереді.

Мен ішіп жүргенде, барлық жағдаяттарға деген көзқарасым шексіз эгоистік және менменшіл болды. Өз рахатым мен жайлылығым бірінші орында тұрды. Қазір, сауығу жолында жүргендіктен, эгоцентризм әлсірей бастады. Өмірге және адамдарға деген көзқарасым өзгеруде. Мен үшін біздің атауымыздағы алғашқы

«А» (attitude – көзқарас. ауд.) — бұл қарым-қатынас, ұстаным. Менің өмірлік ұстанымым екінші «А» (іс-әрекет) арқылы өзгереді. Қадамдармен жұмыс істеу, жиналыстарға қатысу және идеяларымызды тарату ақыл-ойды қалпына келтіруге көмектеседі. Іс-әрекет – сиқырлы сөз! Өмірге деген оң көзқарас пен АА-дағы тұрақты белсенділік бойыма байсалдылық дарытады. Сондай-ақ, басқа алкоголиктерді салауатты өмірге қарай бағыттай аламын. Бүгінгі таңда сау қалпымды сақтау үшін кез келген жолдан өтуге дайынмын!');
INSERT INTO reflections (day, month, title, text) VALUES (2, 'Июнь', 'БИІККЕ АПАРАР ЖОЛ', 'Міне, біз қабылдаған Қадамдар…

Бұл мені Он Екі Қадамға апаратын сөздер. Өзінің тура мағынасындағы қарапайымдылық, Қадамдардың дұрыстығы мен барлық психологиялық және философиялық пайымдауларын жоққа шығарады. Олар мен істеген істі ғана сипаттап: «Қадамдар жасалды, нәтижесінде сауықты» дейді. Бұл сөздер өзгелердің жүріп өткен ізіне түсу керек дегенді білдірмейді. Мен үшін сау өмірге жетудің өзіме тән жеке жолы бар. Мен бұл жолды табуым керек. Бұл шексіз жарыққа апаратын жаңа жол. Қадамдар маған сенімді тіректер қай жерде жарық-нұр бар екенін үндейді. Қадамдар жан әлеміне жалғыз саяхатқа шыққан кезде, қажетті құралдармен қамтамасыз етіп, құз, жыралардан айналып өтудің жолдарын көрсетеді. Ал, осы жан

әлеміне саяхатым туралы айтқан кезде өз тәжірибеммен, бойда бар әлеуітіммен бөлісемін.');
INSERT INTO reflections (day, month, title, text) VALUES (3, 'Июнь', 'ӘРДАЙЫМ ДҰҒАДА БОЛЫП ҚАНАТТАНУ', '...Алтыншы Қадамға көшуіміз мүмкін. Бірақ ниетіміз болмаса, біз емделмейміз.

Мен үшін Төртінші және Бесінші қадамдар қаншалықты қиын болды! Бірақ жемісін берді. Қазір Алтыншы қадамда тұрып қалдым. Көңілім жабырқап Үлкен Кітапты қолыма алып, осы үзіндіні оқыдым.

Мен көшеде тұрып, жаңа Қадамды қабылдауға дайын болу үшін дұға еттім. Кенеттен аспанға қарап, ұшып бара жатқан үлкен құсқа көзім түсті. Ол құс қуатты әуе ағындарына қарамастан біресе төмен құлдырап, енді бірде жоғары көтеріліп қалықтап жүрді. Бұл бір мүмкін еместей құбылыс еді. Осы жағдай кез келген тіршілік иесі өмірін Жоғары Күшке «тапсырмай» биікте самғай алмайтынын көрсетті. Бір Тылсым Күштің құдыреті болмаса бұл құс «өз еркімен» қанат қағып, көкке көтеріле алмас еді. Санамда шырмалған сансыз ойларды түсіну үшін Жетінші Қадамның дұғасын оқуға мәжбүр болдым.

Кез келген жағдайда Құдайдың қалауын түсініп, оны аңғару оңай емес. Арналарды тауып, ағысқа қосылуыма дұға мен медитация көмектеседі! Мен ешкім емеспін. Сол себепті Құдайдан Оның қалауын түсініп, соған сай әрекет ететін күш-қуат беруін сұраймын.');
INSERT INTO reflections (day, month, title, text) VALUES (4, 'Июнь', 'ЕСКІ «МЕННЕН» АРЫЛУ', 'Алғашқы Бес Қадамды оқығаннан кейін: «Бірдеңе жоғалтқан жоқпыз ба?» деген сұрақ туындайды. Біз бостандыққа шығатын өткел салып жатырмыз... Құдай бізді өзімізге қажетсіз дүниелердің бәрінен тазартқанын қалаймыз ба?

Алтыншы Қадам — бұл «дайындық» қадамдарының соңғысы. Мен алғашқы Алты Қадамда көп дұға еттім. Бірақ әлі де Жоғарғы Күшімнен тікелей көмек сұраған жоқпын. Өз мәселемді анықтап, оның шешімі бар екеніне сендім. Осы шешімді іздеуге дайындық ретінде «үйімді жинап, ретке келтірдім». Енді өзімнен: «Ескіліктің шекпенін шешіп, сау қалыпта ғұмыр кешіп, салауатты өмір-салтын ұстануға дайынмын ба?!» деп сұраймын. Бұл істе шынымен де өзгеруге дайын екенімді түсінуім керек. Мен әр ісімді саралап, талдаймын. Құдайдан мінезімнің барлық кемшіліктерінен арылтуын сұрауға дайындалып жатырмын. Себебі келесі Қадамда Жаратушыма дайын екенімді айтып, Одан көмек сұрамақпын. Осы тарауды аяқтап, өзгергім келетінін түсінсем, келесі қадамға дайынмын. «Ал, әлі де ескі әдетке жабысып, ажырағымыз келмесе, Құдайдан ниетімізді түзеуін сұраймыз». (Анонимді Алкоголиктер, 74 бет).');
INSERT INTO reflections (day, month, title, text) VALUES (5, 'Июнь', 'ТОЛЫҚТАЙ ДАЙЫН БОЛУ', '«Бұл Қадам ересек адам мен жас баланы айқындайды... Ересек адам мен жас баланың айырмашылығы — өз мақсаттарына ұмтылуы мен Құдай белгілеген кемелдікке ұмтылу арқылы өлшенеді. Кемелденуге ұмтылыс		толық дайындықты қажет етеді. «Жоқ, ешқашан!»	деп	айтар		болсақ,	өзімізді		шектеп,	Құдайдың шарапатынан		кенде	қаламыз.	Дәл	осы	жерде	біз		шектеулі мақсаттарымыздан бас тартып, Құдайдың еркін қабылдауға көшеміз. Он Екі Қадам және Он Екі Дәстүр, 73, 79, 80 беттер

Twelve Steps and Twelve Traditions, pp. 63, 68, 69 Құдай менің барлық кемшіліктерімді жойғанын қалаймын ба? Сондай-ақ, сол ескі әдеттерсіз өмір сүруге дайынмын ба? Өзімді құтқара алмайтынымды түсіндім бе? Әлбетте, осылай екеніне көзім жетті. Расымен, тілеуі қара басынан аспайтын, мүмкіндігі, қабілеті мен білімі шектеулі біреу болсам, онда мен Құдайдың қалауын

қабылдап, өз өміріме енгізуге дайынмын...');
INSERT INTO reflections (day, month, title, text) VALUES (6, 'Июнь', 'БІЗ ІСТЕП ЖАТҚАН ІСТІҢ БӘРІ ТАЛПЫНЫС', 'Ол бізді осының бәрінен босата ала ма?

Алтыншы Қадаммен жұмыс істеу маған «рухани өрлеуге» шын мәнінде ұмтылатынымды түсінуге көмектесті. Иә, өмір бойы мінезімнің кейбір кемшіліктерінен ажырамауым мүмкін. Алайда, кей теріс қылықтарым бұрынғыдай көзге түсе бермейді. Тіпті, бір жаман әдеттерім жойылып кетті. Алтыншы Қадам мені барлық кемшіліктерді мойындап, мүмкіндігінше сол теріс қылықтан арылуға үндейді. Бағдарламаның рухани даму жолында өзімнің кейбір кемшіліктерім бұрынғыдай мені мазаламайтынын байқаймын. Демек, Алтыншы Қадамды қайталауым керек. Сонда, өзіммен өзім болып, жаным жай таппақ.');
INSERT INTO reflections (day, month, title, text) VALUES (7, 'Июнь', 'КӨПТЕН КҮТКЕН ҮМІТ', 'Біз табиғи тілек-қалауларымызбен (нәпсі) дүниеге келеміз. Бірақ сол нәпсі тікелей міндетінен ауытқып кетуі жаңалық емес. Біз соқыр сеніммен бір сәттік рахат үшін нәпсінің қалауларын орындай берсек, бойымызда бар әлеуетімізді жоқ қылып, Құдайдан алыстаймыз. Бұл біздің мінезіміздің бұзылуының өлшемі, ауыр тисе де күнәларымыздың да өлшемі болмақ.

Осы кезде көптен күткен ауруымның табиғаты мен емделу жолдарын анықтаудың сәті түседі. АА-ның көркемдігі — Құдайдың көмегімен өмірдің жақсара түсетінін түсіну. АА-ның мәні түсінікке, түсінік ақиқатқа, шындық арманымызға, арманымыз шындыққа ұласып, «бүгініміз» мәңгілікке айналады.

Мен АА-ның жарық әлеміне қадам басқанда, жүрегіме Құдайдың нұры төгілмек.');
INSERT INTO reflections (day, month, title, text) VALUES (8, 'Июнь', 'ӨЗГЕРІСТЕРГЕ АШЫҚТЫҚ', 'Өзін-өзі талдау — бұл болмысымыздың қараңғы және жағымсыз жақтарына жаңа көзқарас. Сондай-ақ, сол олқылықтың орнын толтыру үшін басқаша әрекет етіп, жүрегімізге Құдайдың шарапатын енгізудің құралы. Бойымызда жағымды қасиеттерді жетілдіре алсақ, мейірімі шексіз Құдай жаңа мүмкіндіктерге жол ашады. Біз бірте-бірте кемел келешектегі мәнді-мағыналы ғұмырымыз үшін, баянсыз өткенімізден бас тарта алатынымызды түсінеміз.

Мен жетістікке емес, жай ғана өрлеуге ұмтылатын болсам, күн сайынғы жан күйзелісінен алыс болуға мүмкіндігім бар. Егер, әрдайым өзгеруге дайын болсам, өміріме рең беретін оң өзгерістерді қабылдау қиынға түспейді. Кейбір кемшіліктерім АА және басқа адамдардың өміріне пайдасынан гөрі, зиянын тигізіп жатқан жағдайда медитация жасап, Жоғарғы Күштен нұсқаулықтар күтемін.

«Кейбіреулеріміз ескі ұғымдарымызды ұстануға тырыстық. Алайда, олардан толық бас тартпайынша, ешқандай нәтиже алған жоқпыз». (Анонимді Алкоголиктер, 58 бет). Өзгерістерге дайын болуым үшін, бәрін бір Құдайға тапсыруға мүдделімін. Мен енді күресіп, өмірімді басқаруға тырыспаймын. Бірақ Құдайдың жәрдемімен өмірімде оң өзгерістер болатынына сенемін. Бұл сенімді нығайтқан сайын, жаңа өзгерістерге дайын боламын. Әр күнді үмітпен қарсы алу үшін өзімді теріс ойлардан алыстатып, жанымды жарық нұрға, сүйіспеншілікке толтырамын.');
INSERT INTO reflections (day, month, title, text) VALUES (9, 'Июнь', 'ҚАЗІРГІ СӘТПЕН ӨМІР СҮРУ', 'Ең алдымен, сау болу үшін бүгінгі күнмен өмір сүруге тырысамыз. Бұл түсініктің көмегі болмаса, зияны тимейді. Осы идея біздің санамызға енген бойда, бір тәуліктік жоспар өміріміздегі көптеген басқа мәселелерді оң бағытқа өзгерте алатын құрал екенін байқаймыз.

Сау қалыпта өмір сүру, 12 бет

Living Sober, p. 7

«Бүгінгі күнмен өмір сүру». Жаңадан келген адам үшін бұл АА- ның ұрандары ақылсыз болып көрінуі мүмкін. Бірақ олар осы ой арқылы абыржаған кезеңнен құтыла алады. Әрбір күн өзімнен Жоғары Күштің қалауына қарай ашылатын раушан гүлге ұқсас болуы мүмкін. Менің Бағдарламам тиісті жерге егілуі тиіс. Себебі оны баптап құнарландырып және зиянкестерден қорғап отыру қажет. Мен еккен шыдамдылық басқа гүлдерге қарағанда қарағанда ерекше болатынын түсінуге мүдделімін. Гүл жапырақтарының ашылу кезеңдерінің әрқайсысы таңдану мен қуанышқа кенелтуі мүмкін. Бірақ бұл үрдіске араласып, шектен тыс үміт күтпеуім маңызды болмақ. Егер, бәрін бақылауға тырыссам жан тыныштығын таба алмаймын.');
INSERT INTO reflections (day, month, title, text) VALUES (10, 'Июнь', 'ШЫДАМ ЖОҚ ПА? БҰЛ ЖАҒДАЙҒА ЖОҒАРЫДАН ҚАРАП КӨРІҢІЗ', 'Біз келеңсіз жағдайларда қалыпты адамдарға қарағанда әрекетіміз басқаша болды.

Өзгелермен қарым-қатынастағы шыдамсыздық — менің басты кемшіліктерімнің бірі. Көлік жүргізген кезде жоғары жылдамдыққа шектеу қойылған жерде баяу қозғалу, мейрамханада есеп айырысу үшін даяшыны ұзақ күтіп қалу сынды дүниелер жүйкеме тиеді. Құдай маған сабыр бермесе, жарылып кете жаздаймын. Егер, осындай сәттерде ашуға бой алдырсам «Құдайдан бұрын іс қылдым» деп баға беремін. Мен үшін келеңсіз жағдайларға Құдайдың көзімен қарап көрсем қалай болады?! Не істеуім мүмкін?! Өз сезімдерім мен мінез-құлқымды дұрыс басқара алатын едім. Бір күні жолыма кедергі жасап, баяу қозғалып бара жатқан көлікті озып кетпек болдым. Қуып жеткен сәтімде бұрылып қарасам, қартайған ерлі- зайыптылар мен немересін көрдім. Шамасы немелерінің қызығы мен шыжығын сөз қылып, мәз болып келе жатса керек. Бір түрлі өзімді ұятты сезініп, дереу жылдамдықты азайтып қарт кісілердің соңынан ердім. Ешқайда асығып бара жатпасам да, не себепті күйгелектеніп кеткенімді түсіне алмадым. Әр іске Құдайдың көзімен қарау жүрекке тыныштық сыйлайды.');
INSERT INTO reflections (day, month, title, text) VALUES (11, 'Июнь', 'ОТБАСЫ АЛДЫНДАҒЫ МІНДЕТТЕР', '...отбасы алдындағы міндеттемелерді жоққа шығаратын рухани өмірді, кемелденген өмір деп айта алмаймыз.

Бағдарламамен жұмыс істеу арқылы жиналыстарда, жұмыста, қызметте табысты бола аламын. Алайда, отбасыма келгенде жағдай күрт өзгереді. Жақындарымның түсіністікпен қарағанын қалаймын. Өкінішке қарай менің қалауым бола бермейді. Олар менің рухани өсуімді байқап, баға беруін күтемін. Бірақ өзімді сөзбен емес, іспен көрсетпейінше, мені ешкім бағаламайтыны анық. Бәлкім, оларға қамқор болып, қажеттіліктері мен тілектерін елеп-ескеріп, назар аудармайтын шығармын?! Бәлкім, олармен бірге уақыт өткізу қызықсыз болғандықтан зерігіп ашуланатын шығармын?!  Бәлкім,

«Кешіріңіз, менің кінәм» деп міңгірлеп, әр жағдаятқа шыдамдылық танытып жүрмін бе? Бәлкім, оларды «сабасына түсіруге» тырысып, оларға дәріс оқығым келе ме?! Бір кездері олармен бірге бір іс атқарып па едім?! «Рухани өмір — бұл талқылап қоя салатын теория емес. Сіз іс жүзінде рухани өмір сүруіңіз керек». (Анонимді Алкоголиктер, 80 бет).');
INSERT INTO reflections (day, month, title, text) VALUES (12, 'Июнь', 'ШЫНАЙЫ ЫНТЫМАҚТАСТЫҚ ОРНАТУ', 'Көптеген жандар отбасымен, достарымен және жалпы айналасындағылармен дұрыс қарым-қатынас орната алмауынан зардап шекті. Дәл осы жағдаятқа байланысты біз де көп қыңыр мінез көрсеттік. Біз мойындағымыз келмесе де, өзгелермен ынтымақтастықта қарым-қатынас орната алатындай қабілетіміз жоқ.

Бүгінде бұл сөздер мен үшін қаншалықты өзекті?! Бұл көзқарас әлі де басқа адаммен шынайы ынтымақтастық орнатуға қабілетсіз екенімді көрсете ме?! Міне, осы түсініктер менің сау қалыпта өмір сүруіме қалай кедергі бола алады?! Сау кезімде медитациямен айналысып, әрқашан сенімді дос, жолсерік болуым үшін дұға етемін.');
INSERT INTO reflections (day, month, title, text) VALUES (13, 'Июнь', 'ШЫҒЫНДЫ ҚАЛПЫНА КЕЛТІРУ', 'Уақыт өте келе алкоголиктің әйелі мен баласы невротикке айналады. Бүкіл отбасы белгілі бір деңгейде ауруға шалдығады.

Алкоголик ретінде тек өзіме ғана емес, айналамдағы адамдарға да зиян келтіргенімді түсінуім керек. Өз отбасыма келтірілген зиянды өтеу, сондай-ақ, басқа да алкоголиктердің әлі де азап шегіп жатқан отбасылары мен үшін маңызды. Өз тарапымнан болған зиянымды түсініп, оны қалпына келтіруге тырысу өмірлік ісім болмақ. Менің салауатты өмірім өзгелерге үлгі болып, ертеңгі күнге үміт пен сенім бере алады.');
INSERT INTO reflections (day, month, title, text) VALUES (14, 'Июнь', 'ҚИЫН СӘТТЕРДЕ', 'Өмірлік мақсат қиын сәттерде аман қалуға көмектеседі.

Мен АА-ға келгеннен кейін Достастықтың салауатты өмір сүруіме көмектесетінін түсіндім. Бірақ бұл ішімдікке қатысы жоқ өмірлік мәселелерді шешуде жұмыс істей ме? Бұл туралы бастапқыда күмәнда болдым. Сау өмірдің екі жарым жылынан кейін, көкейдегі сауалыма жауап алдым. Жұмысымды жоғалттым, денсаулығыммен мәселелер туындады, қант диабетімен ауыратын әкем аяғынан айырылды, ал сүйіктім тастап кетті. Мұның бәрі екі апта ішінде болды. Болып жатқан шынайы жағдайлар ауыр тиді. Қиын сәтте АА Достастығы мені қолдап, әрдайым жігерлендірумен болды. Саулықтың бастапқы кезеңінде үйренген қағидаларым өмірімнің тірегіне айналды. Сондықтан, қиын жағдайлардың бәрінен өтіп қана қоймай, жаңадан келгендерге көмектесуді де тоқтатпадым. АА маған дүрбелеңге бой алдырмауға, өмірдің қалай қалыптасып жатқанын түсініп, қабылдауға үйретті.');
INSERT INTO reflections (day, month, title, text) VALUES (15, 'Июнь', '', 'АА-ны ЖОҒАРҒЫ КҮШ ЕТУ

Сізге... АА-ны «Жоғарғы күш» деп санауға болады. Себебі, алкоголизм мәселесін шешуге шешім қабылдаған адамдар тобы осы әдіспен өз дерттерінен айыға алды. Олар Жоғарғы Күшке сенгендіктен еңсесі тіктеліп, түсініктері кеңейді.

Ішіп жүрген кезімде менен күшті адам болған жоқ. Шындығында, дәл сол уақытта айнаға қарап күлуге де батылым жетпейтін. АА-ға келгенде басқалардың Жоғарғы Күш туралы айтқандарын естідім. «Құдай қатал және дәл маған шарапаты түспес» деп сенгендіктен Жоғарғы күш ұғымын қабылдай алмадым. Үмітсіздіктен өзімнің Жоғарғы Күшім ретінде ағаш үстелді, содан кейін өзімнің АА тобымды таңдадым. Уақыт өте келе өмірім түзеліп, Жоғарғы күш туралы ойлана бастадым. Кейіннен сансыз сұрақтарға шырмалып, әр жағдайға төзімділік таныта жүріп, Құдайға деген сенімім артты. Енді онымен қарым-қатынасым маған бақытты да, салауатты өмір сүруге дем береді.');
INSERT INTO reflections (day, month, title, text) VALUES (16, 'Июнь', 'АШЫҚ КӨЗҚАРАС', 'Біз Құдайдың Оны іздегендерге тым қатал талаптар қоймайтынын анықтадық. Біз үшін Рух Патшалығы кең, жан-жақты және Оны шын жүректен іздейтіндерге қолжетімді. Рух Патшалығының есігі бәріне айқара ашық екеніне күмән келтірмейміз.

Жоғарғы Күшке бейтарап көзқарас рухани қақпаны ашады. Әртүрлі ілімдер мен сенімдерде жалпы адамзатқа ортақ руханиятты табамын. Мен руханиятқа өмірлік тәжірибемді өзгелермен бөлісу арқылы қол жеткіземін. Тек осылай ғана адамзат қауымдастығына қосылып, Құдайға жақындамақпын.');
INSERT INTO reflections (day, month, title, text) VALUES (17, 'Июнь', 'ЖАННЫҢ ТЕРЕҢІНДЕ', 'Жанымыздың түкпірінен Ұлы Ақиқатты таптық. Демек, Ақиқатты басқа жерден іздеу негізсіз...

Біздің тәжірибеміз, әр адамды өз «менін» зерттеуге ынталантырады... Осы дүниетанымды ұстансаңыз, жоғалып кетпейсіз. Ақырында сенімнің түсінігі қалыптасады.

Жалғыздықтың, депрессияның және үмітсіздіктің шыңырауында жатып, АА-ның көмегіне жүгіндім. Мен айыққан сайын өмірімнің күйрегенін көрдім. Кейіннен, АА Бағдарламасында айығудың мүмкіндіктері бар екенін білдім. Жиналыстарға қатысып, Қадамдармен жұмыс істеп сауыққан сайын жүрегімнің үніне көбірек құлақ аса аламын. Ғұмыр бойы аңсаған сүйіспеншілік пен ризашылыққа қол жеткіздім. Осы жолда өзімнің түсінігімдегі Құдайымды таптым.');
INSERT INTO reflections (day, month, title, text) VALUES (18, 'Июнь', 'ЕРКІНДІК БАУЫРЛАСТЫҒЫ', '...адамдарға толық еркіндік беріліп, олар ешкімге бағынбаса да, олар ортақ іс үшін өз еркімен бірігеді.

Мен бәзбіреудің немесе алкогольдің құзырында болмасам, жаңа еркіндікке ие боламын. Өткен күннің әлегінен, ұзақ уақыт арқалап келе жатқан артық жүктен арылғанда еркіндікті сезінемін. Мен еркіндік бауырластығына кірдім. Қадамдар жаңаша өмір сүрудің жолын ұсынады. АА-да «бұйрық» деген ұғым болмағандықтан, ешкім бұйрығын жүргізуге тырыспайды. Мен біреудің бұйрығымен емес, өз қалауым бойынша қызмет етемін. АА-ның басқа мүшелерінен көп дүние үйренемін, сол үйренгенімді топқа қайта қатарамын. «Ізгілік» тек еркін адамдар ортасында ғана қанат жая алады.');
INSERT INTO reflections (day, month, title, text) VALUES (19, 'Июнь', 'АА-ДА ҚАЙТА ЖАҢҒЫРДЫҚ', 'АА-да қайта жаңғыру қарама-қайшылығы: толық жеңіліп, әлсіздігіңді мойындағанда, бір ғажап Күш пайда болады. Адам ескі өмірінен ажырамай, жаңа өмірге бет бұра алмайды.

«Сұр Жылан» (ішімдік) мені мың рет шақса да, жеңілгенімді мойындата алмады. «Тентек досты» жеңу, менің моральдық міндетім деп ойладым. АА-ның алғашқы жиналысында аурудан жеңіліс тапқаныма қуандым, ол дерттің «моральдық тұрақтылығыма» еш қатысы жоқ екенін түсіндім. Мен инстинкті түрде АА есігін ашқан бойда үлкен сүйіспеншілік кеңістігіне кіргенімді түсіндім. Өзіңді шартсыз сүю дұрыс қадам. Бұл Құдайдың қалауымен анықталып қойған іс. Өз ойымның құлдығынан жаңа сезімдер арқылы босап шықтым. Мен ризамын.');
INSERT INTO reflections (day, month, title, text) VALUES (20, 'Июнь', 'ҮРЕЙДЕН АРЫЛУ', 'Қорқыныш мәселесін шешудің екі жолы бар. Біз үрейден арылып, максималды еркіндікке қол жеткізуіміз керек. Бұл мәселені ақылмен шешуге батылдық пен мейірім қажет болады.

Менің шешімдерімнің көпшілігі қорқынышқа негізделген. Алкоголь өмірлік қиындықтарды жеңілдетті. Бірақ уақыт өте келе алкоголь қорқынышқа қарсы тұратын құрал бола алмады. Батыл түрде Құдайдың көмегімен әрекет ете алуым, АА-да жүріп тапқан ең үлкен сыйлығым десем артық емес. Салауатты өмірдің бес жылынан кейін қатты қорқынышқа тап болдым. Құдай маған жағдайды түсініп, қорқынышты жеңуге көмектесетін адамдарды берді. Он Екі Қадам бойынша жұмыс істей отырып, өзім қалаған адам бола алдым. Бұл үшін шын жүректен ризашылығымды білдіремін.');
INSERT INTO reflections (day, month, title, text) VALUES (21, 'Июнь', 'ҮРЕЙ МЕН СЕНІМ', 'Қорқыныштан арылу — бұл өмір бойы жалғасатын іс, оны толығымен аяқтау екіталай. Кенеттен болатын қатерлі ауру немесе басқа да қауіпті жағдайларда жаман немесе жақсы эмоциялық күйді өткереміз. Тек өздерін алдайтындар ғана толығымен қорқыныштан арылдым деп айтады.

Бойымда сенім аз болса, қорқыныш мені азапқа салады. Кенеттен пайда болған қорқыныш қуанышты, бақытты, сабырлы кезімді талқандап тастай алады. Жоғары Күшім көп трагедияларды оңай өткеруге, сондай-ақ, өз құндылығымды сезініп, сенімімді шыңдауға көмектеседі. Қорқыныштарымның бәрін Жоғары Күшіме тапсырмай, өзімді еркін сезіне алмаймын.');
INSERT INTO reflections (day, month, title, text) VALUES (22, 'Июнь', 'БҮГІН ЕРКІНМІН', 'Сау ақылмен қарасақ, бұл менің көптеген жағдайларда шарасыз екенімді  көрсетті.	Алкогольдің алдында әлсіздігімді мойындағандай, басқа жағдайларда да әлсіздігімді мойындауым керек. Маған сабырға келіп, өзімнің Құдай емес екенінімді түсінуім керек.

Жан тыныштығын сақтау үшін кез келген жағдайды қабылдауды үйренемін. Бір кезде өмір мен үшін тұрақты күрес болды. Маған жеңіске жету үшін өзіммен және басқалармен күн сайын күресу керек сияқты көрінетін. Соңында бұл шайқаста жеңілдім. Әрқашан ішіп алып, өзімнің аянышты жағдайымды жоқтап отыратынмын. Өмірдің ағысын бақылауға тырыспай, бәрін бір Құдайға тапсырғанда жан тыныштығын таптым. Бүгінде, мен еркін адаммын. Маған енді ешкіммен күресудің қажеті жоқ.');
INSERT INTO reflections (day, month, title, text) VALUES (23, 'Июнь', 'ӨЗГЕЛЕРГЕ СЕНІМ АРТУ', 'Өзгелердің немесе өзіңіздің көңіл қалауларына сенім арту үшін бәрінен мақрұм қалуды талап ете ме? Бұл жағдай ақымақтық болар еді, басқа ештеңе емес. Керісінше, біз сенетін адамның қаншалықты жамандық пен жақсылық жасай алатынын бағалай алуымыз керек. Әр іске нақты баға бере алуымыз сенім дәрежесін көрсетеді.

Мен адамдардың құрбаны емеспін. Керісінше, өзім қабылдаған шешімдердің, өз үмітімнің құрбанымын. Адамдар менің қалауымнан шықпай қалған кезде азапқа түсемін. Бойымды менмендік билегенде, өзіме сенімсіз болып, жалғыз қаламын. Егер, барлық істе адалдық таныта алсам, өзіме деген сенімділік артады. Қауіпті жағдайлардан аулақ болуым үшін, өз қадамдарымды түсінуге тырысып, әр істе адал болуым керек. Сондай-ақ, өзімнен бөлек, өзгелерге сенім артуға мүдделімін.');
INSERT INTO reflections (day, month, title, text) VALUES (24, 'Июнь', 'РУХАНИ БАЛАБАҚША', 'Біз маскүнемдіктен арылып, толыққанды өмір сүруге мүмкіндік беретін шапағатқа ие болу үшін, адамдарға мүмкіндік беретін рухани балабақшаға жауаптымыз.

Алкогольдің кесірінен тұйыққа тіреліп, АА-ға келдім. Ішімдіктің азабынан құтылғым келді. Бірақ аты жаман дерттен арылудың жолдарын білмедім. Достастыққа менен бұрын келіп айыққан жандардың тәжірибесімен танысу үшін, осы АА-да қалуға шешім қабылдадым. Кенеттен санама Құдай туралы ой келді! Маған Жоғары Күшті табуыма кеңес берді. Бірақ Ол Құдірет жайында ешқандай түсінігім болған жоқ. Әрине, осы уақытқа дейін әр сенім иелерінің Жоғарғы Күштері бар екенін білетінмін. Маған АА-да Құдай туралы нақтыланған ешқандай ілім жоқ екенін айтты. Қандай да бір қалыптасқан сенімге байланбай, өз түсінігімдегі Құдыретті табуым керек екені ескертілді. Кейіннен қиын сәтте қолдау көсеткен Жоғарғы Күшті таптым. Осы Құдыреттен сау ақыл беруін сұрадым.

Ішімдікке деген әуестік жоғалып, өмірім жаңа арнаға бұрылды. Сау қалыпта өмір сүруді үйрендім.');
INSERT INTO reflections (day, month, title, text) VALUES (25, 'Июнь', 'КӨШЕДЕГІ ЕКІ ЖАҚТЫ ҚОЗҒАЛЫС', 'Егер, біз Құдайдан сұрасақ, Ол біздің қателіктерімізді кешіреді. Бірақ Жоғарғы Күштің ығына жығылмай, жан-дүниемізді тазармайды.

Дұға еткенде кешірім сұрауға тиісті дүниелердің көпшілігі назарымнан тыс қалды. Құдайға ол сырларымды айтпасам «ешқашан білмейді» деген түсінікте болдым. Бірақ өз-өзімді кешіре алсам, Құдайдың да мені кешіретініне еш күмәнданған емеспін. АА-ға келгенге дейін, мені әрқашан өмір сапарына дайындалуға үйреткен еді. Алайда өмірдің өзі саяхат екенін түсіне алмаппын. Мен өзгерістерді қабылдап, өз өміріме жауапкершілік алмай, бақытқа апарар саяхатым басталмайды.');
INSERT INTO reflections (day, month, title, text) VALUES (26, 'Июнь', 'УАҚЫТТЫҢ ЕНШІСІНДЕГІ СЫЙ-СИЯПАТ', 'Көптеген адамдар үшін алкоголь достарымен бірге көңіл көтеріп, қарым-қатынас жасаудың құралы. Бұл жай ғана жалаң қиялды оятып, қамқорлықтан, зерігуден және уайымнан алыстауды қамтамасыз етеді. Ішімдік ішу достармен уақытты көңілді өткізуге септігін тигізгенмен, шынайы өмірден алыстатады.

Қаншалықты алкогольдік иллюзиялық ойды көп қусам, соғұрлым жаныма шаттық сыйлайтын сезімдер қол жетімсіз болды. Алайда Үлкен Кітаптың осы үзіндісін қолдана отырып, АА Бағдарламасының арқасында жаңа керемет өмір ашылғанын білдім. Өмір шын мәнінде күннен-күнге «жақсара» бастады. Осы сөздерді оқыған сайын күйбең тірлік жеңілдеп, өмірімде қуаныш пен жылулық көбейе береді. Сау болу — уақыт өткен сайын еселене беретін сый-сияпат.');
INSERT INTO reflections (day, month, title, text) VALUES (27, 'Июнь', 'АА ӨМІР САЛТЫНА БАҒЫНУ', 'Біз АА Қадамдары мен Дәстүрлерін шын жүректен қалағандықтан орындауға тырысамыз. Бұл жақсы мен жаманның мәселесі емес. Бұл біздің жұдырықтай жұмылып, бір істе әрекет етуіміздің көрінісі. Бұл біздің әрдайым Құдайдың шарапаты мен сүйіспеншілігінде болуымызды білдіреді.

АА-дағы рухани өсуімді бақылаған бір қызық дүние. Бастапқыда Достастықтың қағидаларына бағынуға қарсы болдым. Бірақ қарсыласу арқылы ауыртпалықтарға тап болдым. Ақырында АА өмір салтын таңдаған кезде ғана, Құдайдың шарапаты түсетініне көзім жетті. Осы жағдайдан кейін не үшін АА мүшесі болуым керектігін түсіне бастадым.');
INSERT INTO reflections (day, month, title, text) VALUES (28, 'Июнь', 'АА НЕГІЗІН ҚАЛАУШЫЛАРДЫҢ ТАБАНДЫЛЫҒЫ', '...Бұл үшеуі жарты жыл ішінде тағы жеті адамды құтқара алды.

Егер, АА негізін қалаушылар бұл істе табанды болмаса, Достастық қоғамның басқа игіліктері сияқты тез жойылып кетер еді. Біздің қаламызда апта сайын жүздеген жиналыстар өтетінін және АА тәулігіне 24 сағат қолжетімді екенін білемін. Ішуді тоқтатамын деген ұмтылысым үшін ғана барлық жер қабылдай бермейді. Осы сәтте көңілім қалып, жанға жайлы жол іздеп, ескі әуеніме қайта басатын едім.');
INSERT INTO reflections (day, month, title, text) VALUES (29, 'Июнь', 'КӨҢІЛ ТОЛҚЫНЫ', 'Бақытты өмір сүруді үйренген соң, өзгелерге де жол көрсетеміз... Бұл біздің [АА-да] арманымыз. Алкоголиктер қалыптаспаған идеалистер болғандықтан, бәрі табиғи жолмен, шынайы ықыласпен жүзеге асады. Неге салауатты өмір салтының құпиясын басқа жандармен бөліспеске?

Салауатты өмірдің «жақсылығын» күллі әлеммен бөлісіп, жаһанға жар салғым келеді. Алайда, ішімдік ішіп жүрген кездегі теріс ойларға қайта берілемін. Салауатты өмір салтын ұстансам да, дүркін-дүркін көңілімнің толқитынын байқадым. Осы жағдайдан өзімнің сауығуыма назар аудару қиынға соғатынын түсіндім. Сол себепті негізгі мақсатымнан ауытқымай, сау қалпымда басқа да алкоголиктердің сауығуына көмектесуге мүдделімін. Бұл игі ісім есімді жоғалтпай, сау ақылмен өмір сүруіме күш-жігер береді.');
INSERT INTO reflections (day, month, title, text) VALUES (30, 'Июнь', 'ҚҰРБАНДЫҚ= БІРЛІК = ТІРШІЛІК', 'АА-ның бірлігі, тиімділігі және өміршеңдігі жеке басымыздың құмарлықтарынан бас тартуымызбен тікелей байланысты. Бұл көптің игілігі үшін қажет дүние.

АА игілігі үшін кейбір қисық мінезімнен арылу керек екенін түсіндім. Нәтижесінде марапаттан кенде қалмадым. Жалған мақтанышқа бедел арқылы қол жеткізуге болатын шығар. Бірақ Алтыншы Дәстүрмен өмір сүре отырып, оның орнына сүйіспеншілікпен марапатталамын. Шынайы ықылассыз белгілі бір ұйыммен ынтымақтастық орнату алысқа апармайды. Сондай-ақ, сыртқы жағдайды бақылауға тырыспасам, АА қағидасына сай өз- өзімді басқаруым жеңілдейді. Осы жағдайдың бәрі Достастықтың іргесі берік ұйым ретінде, болашақ ұрпақ үшін жұмыс істеуіне ықпал етеді.');
INSERT INTO reflections (day, month, title, text) VALUES (1, 'Июль', 'БҮГІНГІ КҮННІҢ ИГІЛІГІ', 'Біздің қағидаларымыз өрлеу жолындағы нұсқаулық болып табылады.

Мүсінші қалаған нәтижеге жету үшін әртүрлі құралдарды пайдаланады. Сол сияқты, АА-ның құралы ретінде Он Екі Қадам өмірлік нәтижелерге қол жеткізу үшін қолданылады. Мен өзіме әлі қанша жұмыс істеу керек екенін жоспарлап, күйбең тірліктің мәселелерін жүктемеймін. Қазіргі өмірім Жоғары Күштің қолында екенін түсінемін. Сол себепті де жаным тыныш. Ол Жоғарғы Күш өмірімнің әр сәтін бірегей өнер туындысына айналдыра алатын шебер! Бағдарлама бойынша жұмысымның сапасы бүгін істей алатын ең игі ісіммен өлшенеді. Біз өзіміздің емес, Құдайдың қалауын істегенде жанымыз жай таппақ!');
INSERT INTO reflections (day, month, title, text) VALUES (2, 'Июль', 'САУЫҒУДЫҢ ШЫНАЙЫ МӘНІ', 'Бағдарламаның рухани жағы қиындық тудырмайтынын анықтап алуымыз керек. Ниет, адалдық және ашықтық сауығудың таптырмас қасиеттері.

Өзімді осы қалпымда қабылдай алатындай шынайымын ба?! Өзгелерге шынайы болмысымды көрсете аламын ба?! Салауатты өмір салтын ұстану үшін бәрін істеуге дайынмын ба? Естуім керек дүниені естуге, ойлауым керек дүниені ойлауға, сезінуім керек дүниені сезінуге қаншалықты дайынмын?! Осы сауалдарға «иә» деп жауап бере алсам, Бағдарламаның рухани құндылығын белгілі деңгейде түсінгенім. Он Екі Қадам бойынша жұмыс істеген сайын, шынайы саулық пен жан тыныштығының мәніне жақындай түсемін. Бұл жолға өз түсінігімдегі Құдайдың қалауымен өзімнен бөлек, өзгелер де бет бұрады.');
INSERT INTO reflections (day, month, title, text) VALUES (3, 'Июль', 'ӨМІРДЕ ЕҢ ЖАҚСЫ ҰСТАЗ — ТӘЖІРИБЕ', 'Тәжірибеміз аз болып, жақында ғана Құдаймен байланыс орнатқандықтан шабыт алуымыз қиын.

Өмірде «ең жақсы ұстаз — тәжірибе» екені жиі айтылады. Осы нақыл сөзбен келіспеске амалым жоқ. Құдайдың сүйіспеншілігін, өзім сол махаббатқа тәуелді болмай білген емеспін. Басында Ол Құдыреттің өмірімді басқара алатынына сенімді болмадым. Бірақ қазір Жоғарғы Күштің қалауына сай әрекет етсем, берекетін де беретініне сенемін. Сол себепті әрдайым Құдайым назарынан тыс қалдырмай, жол көрсетсе деп тілеймін.');
INSERT INTO reflections (day, month, title, text) VALUES (4, 'Июль', 'ТАБИҒИ СЕНІМ', '...әр ер адамның, әр әйелдің және әр баланың жүрегінің тереңінде Құдайдың негізгі идеясы бар. Ол қайғы-қасіретпен, астамшылдықпен немесе басқа заттарға табынумен жабылып тұруы мүмкін. Бірақ ол сенім ешқайда жоғалмайды. Бұл адамзат жаратылғалы бері келе жатқан көне сенім. Сондай-ақ, бізден әлдеқайда мықты Күштің ғажайып орната алатынына деген сенім болмақ.

Мен Құдайдың көрінбейтін істерін бүкіл елдегі АА орындарында көрдім. Қалпына келтіру ғажайыптарын барлық жерде көруге болады. Енді мен Құдайдың осы бөлмеде де, жүрегімде де бар екеніне сенемін. Әлбетте, бұрынғы агностик үшін «СЕНІМ» тыныс алу, тамақтану және ұйықтау сияқты табиғи нәрсе. Он Екі Қадам өзгеруіме көп көмектесті. Ең бастысы Жоғары Күшті таптым.');
INSERT INTO reflections (day, month, title, text) VALUES (5, 'Июль', 'ЖАҢА ЖЕТЕКШІЛІК', 'Көңіл қалауымызды басқаратын ішкі қорларымыз жеткіліксіз болды... Күн сайынғы әрекетімізде Құдайдың көрегенділігін жетекшілікке алуымыз керек...

Бәзбіреулердің айтуынша «жігерсіз» алкоголик болсам да, бірақ, мен жер бетіндегі ең табанды жандардың бірімін! Өз өмірімді сақтап қалу үшін ерік-жігерім жеткіліксіз екенін білемін. Менің мәселем «әлсіздік» мәселесі емес, керісінше басшылық мәселесі. Шынайы түрде өзімнің тұлғалық ақауларымды қабылдап, Құдайдан басшылық сұраған кезде, кемшіліктерім қасиетке айналады. Дұрыс бағытталған ізгі ниетім Бағдарламаның уәделері күнделікті шындығыма айналғанша жұмыс істеуге мәжбүр етеді.');
INSERT INTO reflections (day, month, title, text) VALUES (6, 'Июль', 'ҮРЕЙДІ ТАНЫП-БІЛУ', 'Бойымыздағы кемшілік, өзімшілдік үрейден туындайды. Бұл негізгі фактор.

Жайсыздыққа тап болып ашуға бой алдырсам немесе депрессияға түскенде әп-сәтте қорқыныш менің серігіме айналады. Бұл «зұлым және шіріген жіп» менің азаптарымның қайнар көзі екенін жасыра алмаймын. АА-да алған тәжірибем, маған қуаныш пен еркіндік әкеледі. Сондай-ақ, менің қорқынышпен өмір сүргенімді қаламайтын Жоғары Күшті таптым. Осы істің нәтижесінде сәтсіздік қорқынышы, басқалардың пікірінен қорқу, зұлымдықтан қорқу, біреуге зиян тигізуден қорқу және басқа да көптеген қорқыныштардан арылдым. Мен енді ішіп жүрген кезімдегі өмірімді басқарған тұлғалық ақауларыммен өмір сүргім келмейді. Жетінші Қадам — тұлғалық ақаулықпен күрес жолы. Әрдайым Құдайдан жәрдем сұрап, бойымдағы үрейден арылтуын сұраймын. Бұл әдіс әрқашан тиімді жұмыс істейді. Бұл әдіс АА Достастығында жүріп тапқан ғажайыптарымның бірі екенін айтқым келеді.');
INSERT INTO reflections (day, month, title, text) VALUES (7, 'Июль', '...БҰДАН ДА ЕРКІНДІК АЛУҒА МҮМКІНДІК БАР', '«Барымызды жоғалтып, қалағанымға қол жеткізе алмай қаламыз  ба?»	деген қорқыныш бұрыннан болатын. Қанағатсыздығымыздан әрдайым сары уайымға түсіп, қобалжуда

болатынбыз. Біз қолда барға қанағат етуді үйренбей, жанымыз жай таппады. Міндет қылу мен өтініш айтудың ара-жігін түсіндірудің қажеті жоқ деген ойдамыз.

Бойкүйез үміттен арылмай жаныма тыныштық жоқ. Көңілімді қанағатсыздыққа билетсем, артынша жүрегімде үрей мен қобалжу үстемдік құратыны сөзсіз. Бұл, әрине, менің эмоциялық тұрақтылығыма ықпал етпеуі мүмкін. Бірақ тасадан пайда болған қыңыр ойларды жоққа шығарып, әрдайым Құдайға тәуелді екенімді мойындап отыруым керек. Тек сол кезде ғана, жан тыныштығына қол жеткізіп, рухани қауіпсіздігімді қамтамасыз етемін.');
INSERT INTO reflections (day, month, title, text) VALUES (8, 'Июль', 'ДАМЫЛСЫЗ ДАМУ ҮСТІНДЕГІ ЕРКІНДІК', 'Жетінші Қадам бізге өмірлік ұстанымымызды өзгертіп, сүйіспеншілікті басшылыққа алуға мүмкіндік береді. Сол себепті біз

«менмендігімізден» ажырап, өзге жандармен және Құдаймен кездесуге бет аламыз.

Мен, Құдайдан шарапатының сәулесін түсірмей тұрған дүниелерді алып тастауын сұрадым. Ол тілегім қабыл болып, үш ұйықтасам түсіме кірмейтін саяхатқа шықтым. Өзімнің тым тұйық мінезімнен арылдым. Осы қарапайым Қадамның арқасында өзімді тазарғандай сезінемін.

Құдайға және өзімнің серіктестеріме пайдалы бола алғандықтан, бұл Қадамды анық түсінемін.Себебі Жоғарғы Күш мені ерекше сезіммен сүйіншілеп, Өз қалауын орындауға ерік-жігер беретіне еш күмән келтірмеймін. Мен Құдайдың еркіндемін. Сондай-ақ, өзгелерге пайдамды тигізе алғаныма қуаныштымын.');
INSERT INTO reflections (day, month, title, text) VALUES (9, 'Июль', 'МЕН ЖАЙ ҒАНА СЕБЕПШІМІН', 'Біз Одан біздің кемшіліктерімізді түзетуін сұрадық.

Мойынсұну өте күрделі мәселе. Мойынсұну өзіме шынайы қарап, өзімді қабылдауға мүмкіндік береді. Мен жай ғана себепші болсам, өз жетістіктеріме қалайша мақтана аламын? Менің ойымша, мен істеген әр игілікті, шын мәнінде Құдай менің қолыммен істейді. Бұл  ой  мені  асқақтаудан,  тәкәппарлықтан  сақтайды.  АА-да

«сүйіспеншілік танытып, қызмет көрсетуім үшін» күн сайын, Құдайдан кемшіліктерімнен арылтуын сұраймын.');
INSERT INTO reflections (day, month, title, text) VALUES (10, 'Июль', 'ЖАН ТЫНЫШТЫҒЫНА БЕЙБІТ ҚАДАМ ЖАСАУ', '...Егер біз кейбір кемшіліктерімізді анықтап, оларды талқыға салып, олардан құтылуға ұмтылсақ, мойынсұну туралы түсінігіміз терең мәнге ие болады.

Жан тыныштығымды бұзатын жағдайлар туындаған кезде, жүрегімдегі ауыртпалық Құдайдан жол сұрауға түрткі болады. Осы сәтте белгілі бір жағдайдағы өз рөлімді түсіне аламын. Өзімнің дәрменсіздігімді мойындап, болған жағдайды қабылдай алатындай күш-қуат беруін сұраймын. Қалыптасқан жағдайда мінез- құлқымның кемшіліктері қалай әсер еткенін түсінуге тырысамын. Мен ұзақ уақыт бойы шыдамдылық таныта алар ма едім? Мен шыдамсыз болдым ба? Өзімдікін дәлелдеуге тырыстым ба? Мен қорқып тұрмын ба?

Осы сауалдар арқылы кемшіліктерім анықтап, өзімшілдігімнен арыламын. Құдайдың құзырана құлдық ұрып, осы кемшіліктерден құтқаруын сұраймын. Жағдай өзгермеуі мүмкін, бірақ мойынсұна берсем, сенім мен жан тыныштығын табамын. Бұл іс менің өзімнен әлдеқайда мықты Күшке сенуімнің белгісі.');
INSERT INTO reflections (day, month, title, text) VALUES (11, 'Июль', 'БЕТБҰРЫС', 'Мойынсұну біз үшін қажет нәрсе емес, қаласақ та, қаламасақ та ие болуымыз керек деп санасақ, бұл біздің өміріміздің бетбұрыс кезеңі болады.

АА өмір салты бағым ба, әлде, сорым қайнап алкоголизмнің қараңғы тұңғиығына қайта ораламын ба?! Мен Құдайдың құзыретіне шынайы құлдық ұрғанда, ауыртпалықтан арылып, өмірімде қуанышты сәттер болады. Кемелдікке ұмтылған кезде адал болсам, салауатты өмір мен жан тыныштығына, еркіндік пен шаттыққа қол жеткізе алатынымды түсінемін. Ал өмірдің қара түнегі шуақты сәулемен нұрланады. Жоғары Күшіме деген сенім күшейіп, бүкіл болмысым сүйіспеншілікке толады. Мен үшін мойынсынған жандардың қатарында болу, өзіме және Құдай алдында адал болу дегенді білдіреді. Тек сонда ғана «мойынсұну» менің «шынайы қалауым» болмақ.');
INSERT INTO reflections (day, month, title, text) VALUES (12, 'Июль', 'НЕГІЗГІ РӨЛДЕН БАС ТАРТУ', '…өз дәрменсіздігіне мойынсұнбаған ешбір маскүнем сау қалпын сақтап қала алмайды... Онсыз олар өздеріне пайдалы мақсат қоя алмайды. Сондай-ақ, өмірдің сынақтарында табан тірейтін сенім нүктесі жоқ.

Мен неге «мойынсұну» деген сөзге қарсы тұрамын? Мен адамдарға емес, өзім түсінетін Құдайға бағынамын. Мен үшін мойынсұну, бір Құдайға «бағынышты екеніңді құрметтеу» дегенді білдіреді. Мойынсұнған сайын, өзімді жердің кіндігі емес екенімді түсінемін. Ішкен кезімде жалаң мақтаныш пен менмендіктің тұтқынында болдым. Әлем менің құзырымда, өз тағдырымның иесімін деген ойдан ажыраған емеспін. Мойынсұну маған өмір кедергілерін аттап өтіп, кемшіліктерімнен арылып, рухани өсуіме септігін тигізеді. Сондай-ақ, Құдайға деген сенімімді күшейтіп, құлшылығымды көбейтеді. Кәсіби біліктілігімді арттыру үшін, әрдайым күрделі мәселелерді шешуге тиіспін. Ал жолымда кездескен қиындықтарда Құдайдан жәрдем сұрап үйренуім керек. Күнделікті бір Жаратушының барын ұмытпау, менің мойынсұнғанымның белгісі. Өзімді Құдай санауымды тоқтатсам, әр істе шын Жаратушының назарында болатыныма еш күмәным жоқ.');
INSERT INTO reflections (day, month, title, text) VALUES (13, 'Июль', 'МОЙЫНСҰНУДЫҢ СЫЙ-СИЯПАТЫ', 'Біз әуелі өз күшімізге сенсек, Жоғары Күшке сүйену мүмкін емес. Мойынсұнбай Құдайдың ырқына көніп, шарапатына бөлене алмаймыз.

АА-ға алғаш келгенде «мойынсұну» деп аталатын ғайыптық күшті бойыма сіңіргім келді. «Өзім қалаған нәрсеге қол жеткізуге көмектеседі» деп санайтындықтан мойынсұнуды іздейтінімді түсінбедім. Құдай әр ісімді марапаттаса, өзгелер үшін бәрін жасауға дайын едім. Қазір күні бойы кездескен адамдар Үлкен Ғаламның бөлшегі екенін есте сақтауға тырысамын. Демек, маған ешкім жат емес. Бүгін Құдайдың еркін табу үшін дұға етуім керек. Сондай-ақ, басымнан өткен өмірлік ауыр тәжірибем арқылы, адамдарға қалай көмектесе алатынымды естен шығармауға тиіспін. Егер, осы түсінікте болсам, «мойынсұнуды» іздеудің қажеті жоқ, ол мені өзі тапқаны.');
INSERT INTO reflections (day, month, title, text) VALUES (14, 'Июль', 'ҚОРЕКТІК ЗАТ', 'Өткенде «мойынсұну» бейне бір тұзсыз ботқамен мәжбүрлі түрде тамақтандыру сынды болса, енді жан тыныштығын әкелетін пайдалы қоректік затқа айналды.

Мен өз мәселелерім мен көңілсіз сәттеріме қаншалықты жиі байланып қаламын?! Егер күнім жақсы өтсе, сол мәселелер маңыздылығын жоғалтып, ал менің оларға деген алаңдаушылығым азаяды. «Жақсы күндердің» «ғажайыптарын», оны «жаман күндерімнің» қайғыларына қолдана алсам, жақсы болмас па еді? Шешімін таптым! Ауыртпалықтан қашып, ойымнан мәселелерді қуып жіберудің орнына, мойынсұну туралы дұға ете аламын! Мойынсұну   ауыртпалықты   емдейді.   Мойынсұну   мені

«менмендігімнен» ажыратады. Мен мойынсұнуды өзімнен мықты Күштен  сұрай  аламын.  Мойынсұну   өмірімдегі  тепе-теңдікті

қалпына келтіреді. Мойынсұну жаңа болмысымды қуанышпен қабылдауға мүмкіндік береді.');
INSERT INTO reflections (day, month, title, text) VALUES (15, 'Июль', 'ТӘКАППАРЛЫҚ', 'Мыңдаған жылдар бойы біз әрдайым беделді, әрдайым сүйіспеншілікте болу үшін өзімізге тиесілі үлестен артық үлесті талап етіп келдік. Ойлағанымызға қолымыз жеткенде, біз одан да үлкен армандармен ауырып ішіп алдық. Болмашы сәтсіздікке ұшырағанда, бәрін ұмыту үшін тағы іштік. Біз өзіміздің межемізді біліп тоқтай алмадық.

Осы талпыныстардың бәрінде мойынсұну болмады. Жеке тұлғаның дамуы мен рухани құндылықтарына назар аудару ойымызға кіріп шықпады. Материалдық қажеттіліктер өмірдің басты мақсаты бола алмайтынын түсінбедік.

Мен Жетінші Қадамға бірнеше рет жақындап, артқа шегініп, назар аудардым. Бірдеңе анық жетіспеді, мен, бұл Қадамның мағынасын жоғалттым. Мен нені жіберіп алдым? Барлық Қадамдардың, яғни, бүкіл АА Бағдарламасының негізі болып табылатын бір ғана сөз оқылды, бірақ ол сөз еленбеді. Бұл сөз -

«мойынсұну». Мен өзімнің кемшіліктерімді түсіндім: мен шешімді

«кейінге» қалдырамын, тез ашуланамын, өзіме деген аяушылық сезім басым. Мен неге өзім туралы ойлай бастадым? Содан кейін есіме түсті: «Менмендік құлдырауға апарады». Осы сөздің астарына терең үңіле алғандықтан өмірімнен менмендікті алып тастадым.');
INSERT INTO reflections (day, month, title, text) VALUES (16, 'Июль', 'МОЙЫНСҰНУДЫҢ ӨЛШЕМІ', 'Әр ауыртпалық жаңа өмірдің өтемі іспеттес болды. Бірақ бұл төлемнен өзіміз күткеннен көп пайда көрдік. Біз мойынсұна алатын болдық, ал мойынсұну ауыртпалықты емдейтін болып шықты.

Сәттілік менен алыстаса да, өмірімді бақылаудан бас тарту өте ауыр болды. Сәтсіздіктерге тап болған сайын бәрін ұмыту үшін

ішетінмін. Өмірді бәз қалпында қабылдау тек мойынсұну арқылы жүзеге асады. Сондай-ақ, өз түсінігімдегі Құдайға өз еркімді және өмірімді тапсырмай, барлық амалдарым зая кетпек. Менің өмірім Құдайдың қамқорлығында болғанда, қорқыныш, белгісіздік пен ашу-ызадан арылып, өмірімнің жағымсыз жайттарында күйзеліске түсуді тоқтаттым. Осындай қиын сәттердегі ауыртпалықты «маған өмір сүруге рухани күш берілген» деген түсінікпен жеңуге болады.');
INSERT INTO reflections (day, month, title, text) VALUES (17, 'Июль', 'КАПИТУЛЯЦИЯ ЖӘНЕ ӨЗ-ӨЗІҢДІ ТАЛДАУ', 'Менің тұрақтылығым алудан гөрі беруге деген ұмтылысымнан туындады.

Менің ойымша, мұндай көзқарас эмоционалды байсалдылыққа қол жеткізуге де қолайлы. Біз кез келген қиыншылықты талдайтын болсақ, онда біз оның негізінде кейбір жаман әдеттерімізбен қатар, орынсыз талаптарымыздың куәсы боламыз. Құдайдың көмегімен осы орынсыз талаптарымыздан бас тартайық. Сонда біздің жүрегімізде жаңа өмір мен сүйіспеншілікке орын беріледі. Кейіннен біз Он Екі Қадамның көмегімен өзімізді және басқаларды эмоционалды саулыққа жетелей аламыз.

Көңіл-күйді өзгертетін химиялық зат алкогольге тәуелді кезімде достарыммен эмоционалды қарым-қатынас жасау қабілетімді жоғалттым. Мен тәуелсіз болуым керек, өмірде тек өзіме сеніп өзімді басқарамын, ешкімге сенуге болмайды деген түсініктің жетегінде болдым. Ақырында, мен өзімді құрметтеуден қалдым. Тәуелділікпен бетпе-бет келіп, өзге тұрмақ, өзіме сенбейтін болдым. Капитуляция мен өзін-өзі талдау, жаңадан келгендермен сыр бөлісу, қалыптасқан жағдайға мойынсұнуды үйретті. Сондай-ақ, қиналған сәтте өзгелерден көмек сұрауға бейімдеді.');
INSERT INTO reflections (day, month, title, text) VALUES (18, 'Июль', 'ҚОЛДА БАРҒА ШҮКІРЛІК ЕТУ', 'Мойынсұнудың мағынасын аша отырып, біз Құдайға деген көзқарасымызды түбегейлі өзгерттік...

Бүгінде барлық дұғаларым негізінен Жоғары Күшке алғыс айтып, шүкіршілік етуден тұрады. Дегенмен, Құдайдың ырқына көніп, түзу жүру үшін Жаратқаннан күш-қуат сұрауым керек. Құдайдың ырқына көнбесем, әр минут сайын, өзім тілеп алған жағдайлардан құтқаруы үшін Жаратқанға жалбарынудың қажеті болмайды. Менің ойымша, менің шүкіршілігім тікелей мойынсұнумен байланысты. Барға қанағат етіп, шүкіршілігімнен айрылмасам, Жаратқан назарынан тыс қалдырмайды.');
INSERT INTO reflections (day, month, title, text) VALUES (19, 'Июль', 'ЖАЛҒАН ТӘКАППАРЛЫҚ', 'Біздің арамыздағы сенім иелері Құдай туралы түсінігінің шектеулі екенін түсінді. Әрқашан Жаратқанға жүгінуден бас тарта отырып, біз өзімізді Оның көмегінен айырдық.

Жалған мақтаныш көбінесе жалған ұғымдардан туындайды. Біздің АА-дағы үмітіміз лайықты өмір сүруге бағыт береді. Осы жолда «бір күн» ұғымымен жылдар бойы жүргендер Құдайдың құдыретінің шексіз, кімге болмасын рухани өсу мүмкіндігі бар екенін айтады. Егер бұл рас болса, онда ұзақ уақыттан бері салауатты өмір ұстанған АА мүшелері арқылы беріледі. Құдайдың адамдар арқылы әрекет ететінін түсінгеніме шүкірлік етемін. Ұзақ уақыт бойы сау қалпын сақтай алған АА мүшелерін көптің қызметіне жұмылдырып отырған Жаратқанға мыңда бір алғыс. АА- ның ардагерлері Достастыққа жаңадан қосылған жандарды жалған идеалдардан бас тартып, шынайы идеалдардың соңынан еру керектігіне сендіре алады. Өзгелер тек Достастыққа келсе болды, АА-дағылар кімнің болмасын жүрегіне сенім ұялатуға күш салады. Ал өзіме келетін болсам, Жоғары Күштен бойымдағы сенімсіздіктен арылтуын сұраймын.');
INSERT INTO reflections (day, month, title, text) VALUES (20, 'Июль', 'КЕМШІЛІКТЕРДЕН АРЫЛУ', 'Енді «Мен ешкім емеспін, бәрін Жоғары Күш шешеді» деген сөздер мағынаға ие болды. Бұл сөз қиын сәтте келетін көмектің кепілі іспеттес.

Жетінші Қадамды орындауға кіріскенде, ешқандай анықтама толтырудың қажеті жоқ екенін есте ұстаған жөн. Ол Қадамда

«Жаратқан кемшіліктерімізді тізімдеп, сол кемшіліктерді түзетеді» деп жазылмаған. Жылдар бойы мен «маған көмектес», «маған батылдық бер», «маған күш-қуат бер» және т.б. тармақтары бар қиялымдағы анықтамаларды толтырдым.

Жетінші Қадамда «Құдай менің кемшіліктерімді өзі түзейді» деп айтады. Ал, мен бар болғаны шынайы ықыласпен сұрап, мойынсұнсам болғаны. Бұл «мен ешкім емеспін, өмірімнің бәрін Жоғары Күш шешеді» деген түсінікті білдіреді.');
INSERT INTO reflections (day, month, title, text) VALUES (21, 'Июль', 'БАҒАСЫ ЖОҚ СЫЙ', 'Мүмкін, осы уақыт аралығында біз өзіміздің ең айқын кемшіліктерімізден аз да болса арылдық. Кейде біз шынайы жан тыныштығына ұқсас нәрседен ләззат аламыз. Бәрімізге депрессия немесе мазасыздық жағдайында тыныштыққа қол жеткізсек, баға жетпес сый болып көрінеді.

Оқиғалардың өз еркімен жүруіне мүмкіндік беріп, санамды артық ойдан таза ұстап, Құдайдың шарапатын қабылдауға, Құдайдың қалауына сенуді үйренудемін. Жоғары Күшке өзімді тапсыру арқылы, тыныштық пен еркіндікті сезіне аламын. Қобалжу кезінде күрестен бас тарту, керісінше сенімімді шыңдап, еркіндік пен жеңіс сыйлайтыны дәлелденді.');
INSERT INTO reflections (day, month, title, text) VALUES (22, 'Июль', 'ЖАҚСЫЛЫҚ ПЕН ЖАМАНДЫҚ', '«Жаратушы, мені бойымдағы жақсы да, жаман қасиетіммен қабылдағаныңды қалаймын».

Өмірдің қызығы өзгелердің қызметінде болып, қайырымды болу. Кейбір кемшіліктерімнен арылған кезде, мойынсұнуым күшейіп қызметке көп уақыт бөле аламын. Кемшіліктерімді Құдайға тапсырсам, Ол оларды жоя алады. Жетінші Қадамның мәні – мойынсұну. Мойынсұнғыш қасиетін бойға дарытудың ең жеңіл жолы - жақсы немесе жаман қалпыңда өзіңді Құдайға тапсыру. Ол жамандықтан алыстатып, жақсылықты қайтара алады.');
INSERT INTO reflections (day, month, title, text) VALUES (23, 'Июль', 'ҚҰДАЙДАН ШЕШІМІН СҰРАУ', '«Мінезімнің өзіме және өзгелерге пайдалы болуға кедергі келтіретін барлық кемшіліктерінен арылтуыңды сұраймын».

Өзімді дәрменсіз деп мойындағандықтан, өмірімді Құдайға тапсырғанмын. Сол себепті қандай кемшіліктер жойылуы керектігін, қандай ретпен немесе қай уақытта жүзеге асатынын мен шешпеймін. Жаратушым, өзіңе де, өзгеге де пайдалы болуға кедергі болатын барлық мінез-құлықтарымның кемшіліктерінен арылта гөр. Сенің қалауыңды орындауға күш-қуат бер.');
INSERT INTO reflections (day, month, title, text) VALUES (24, 'Июль', 'ӨЗГЕЛЕРГЕ ҚАМҚОРЛЫҚ', 'Біздің өмір сүруіміз (бұрын ішімдікке тым құмар болған адамдар ретінде) басқаларға деген тұрақты қамқорлыққа және біз оларға қаншалықты пайдалы бола алатынымызға байланысты.

Менің мәңгілік мәселем - өзімшілдік. Адамдар әрқашан мен үшін бірдеңе істеді. Менің өзімшілдігім соншалық, істерін азсынып, риза болмадым. Тіпті, өкпелеп наразылық білдірген кездерім көп. Неге мен басқаларға көмектесуім керек? Олар маған көмектесуі керек емес пе? Егер оларда қиындықтар болса, олар бұған лайық емес пе? Мен өзіме деген аяушылық сезіміне, ыза мен кекке көміліп қалдым. Содан кейін, мен ештеңе күтпестен басқаларға көмектесу

арқылы, өзімшілдікке деген құмарлықты жеңе алатынымды түсіндім. Сондай-ақ, осы Қадам арқылы мойынсұнуды түсінсем, жан тыныштығы мен ой айқындығына қол жеткізе алатынымды білдім. Енді маған ішудің қажеті жоқ!');
INSERT INTO reflections (day, month, title, text) VALUES (25, 'Июль', 'ӘЛІ ДЕ ҚИНАЛЫП ЖҮРГЕНДЕР БАР', 'Егер біз ауырып жүргендерге көмектеспесек, біздің өміріміз бен жан саулығымызға тұрақты қауіп төніп тұр.

Мен жүйкені тыныштандырып, қорқыныштан арылу үшін, ішудің азабы қандай екенін жақсы білемін. Тісті қайрап тұрып, ішуден бас тартудың ауыр екенін де білемін. Бір бейтаныс жан есімде. Ол үнсіз қиналып, ішімдіктен жеңілдік табуға тырысып жүр. Жоғары Күштен оның өмірін өзгертуге себепші болуымды сұраймын. Достастық маған басқа адамдармен бірге істей алмайтын дүниелерді істейтін күш-қуат беруін сұраймын.');
INSERT INTO reflections (day, month, title, text) VALUES (26, 'Июль', 'САЛАУАТТЫ ӨМІРДІҢ «БАҒАСЫ', 'Әрбір АА тобы өз күшіне толықтай сүйеніп, сырттан көмек алудан бас тартуы керек.

Дүкенге барған кезде, маған керек дүние болса, тиісті соманы төлеп, оны сатып аламын. Қазір сауығып жатырмын деген күннің өзінде, маған әлі де өмірімді түзетуім керек. Жиналыста қант пен сүт қосылған кофе ішемін. Бірақ қайырымдылық жинау басталған кезде, әмиянымды ашуға асықпаймын. Кейде ақшамның аздығын желеу етемін. Бірақ бұл жиналыс маған қажет емес пе?! Біреу жиналысқа қатысу үшін бір шөлмек сыраның құнын салуды ұсынғанын естідім.

«Бұл тым көп!» деп ойладым. Мен ешқашан бір доллардан артық бермейтінмін. Басқа көптеген адамдар сияқты, мен де Достастықты қаржыландыру жомарт жандардың мойнында деп ойлайтынмын. Мен ақшаның үйді жалға алу, кофе, қант және шыныаяқ сатып алу үшін қажет екенін ұмытып кетемін. Кафеде бір шыныаяқ кофе үшін

тоқсан цент төлеуге ақша табылатын. Сонымен, менің салауатты өмірім мен жан тыныштығым қанша тұрады?');
INSERT INTO reflections (day, month, title, text) VALUES (27, 'Июль', 'ЫҚЫЛАСПЕН ЖАҚСЫЛЫҚ ЖАСАУ', 'Біз АА-ның бірлігін сақтау үшін кез келген құрбандыққа барамыз. Біз мұны Құдайды және бір-бірімізді сүюді үйренгендіктен жасаймыз.

Ақша табу мінезімнің мықты жағы болмағандықтан, ішімдік ішіп жүрген кезімде өзімді қамтамасыз ету қиын болатын. Ал уақыт немесе ақша шығындары туралы сөз болғанда, әрқашан баға мәселесі де туындайтын.

Мен, АА-ға жаңадан келгенде «алу үшін, беру керектігін» ескертті. АА қағидаларын өмірімде қолдана бастаған кезде, қайырымдылық жасау абыройлы іс екенін түсіндім. Әр игі іс істеген сайын жүрегім шаттыққа бөленетін. Құдай мен адамдарға деген қайтарымсыз сүйіспеншілігім, менің өмірімдегі анықтаушы факторға айналды. Қазір қайырымдылық жасасам, Құдайдың мені жай ғана себепші қылғаны деп түсінемін.');
INSERT INTO reflections (day, month, title, text) VALUES (28, 'Июль', 'ӘЛІ ДЕ ҚИНАЛЫП ЖҮРГЕНДЕР БАР', 'Егер Құдай бізге қандай да бір әрекетте жетістікке жетуге қабілет берген болса, онда «бәріне себепшімін, бәрі маған тәуелді» деген мақтаншақ ойлардан аулақ болайық.

АА топтары алкоголиктердің салауатты өмір салтын ұстануға көмектесу үшін жұмыс істейді. Үлкен-кішкентай, орныққан немесе жаңадан құрылған, спикерлік, оқу-ағарту бөлімінің барлығының мақсаты әлі де қиналып жүрген алкоголикке біздің идеяларымыздың мәнін жеткізу. Топ әр алкоголиктің жаңа өмір салтын тауып, қуаныш пен шаттықта ғұмыр кешуі үшін қызмет қылады. Салауатты өмірге жету үшін көптеген алкоголиктер басқа алкоголиктер тобына қолдау көрсетіп, олар өз тәжірибелерімен, күш-қуаттарымен бөлісу

керек. Осылайша, менің саулығым және бәріміздің ортақ тіршілігімізге айналады. Бағдарламаның көмегімен салауатты өмірді бірінші орынға қоямын.');
INSERT INTO reflections (day, month, title, text) VALUES (29, 'Июль', 'АНОНИМДІ ЖАҚСЫ ІСТЕР', 'Біз, ішкіш алкоголиктер болғандықтан, үнемі қайыр-садақа іздедік.

Суреттелген Он Екі Дәстүр The Twelve Traditions Illustrated, p. 14

Жетінші Дәстүр тек қана басқалармен барыңды бөлісуден бөлек, бұл жолда жүрегімнің ақтығы сынға түседі. Мен ішіп жүргенде, ішу қабілетімді ғана дамыттым. Қазір барлық күш- жігерімді қуаныш пен жақсы істерге бағыттаймын.');
INSERT INTO reflections (day, month, title, text) VALUES (30, 'Июль', 'ЖАҚСЫЛЫҚ ЖАСАУ', '...ол алтыннан артық нәрсе тапты... Ол әлі де қандай қазынаға кенелгенін түсінбейді. Ол өмірінің соңына дейін қазса да таусылмайтын қазынаның бәрін тегін таратуға тырысады.

Жетінші Дәстүрге қатысуым бір шыныаяқ кофенің құнынан әлдеқайда жоғары. Бұл топ мүшесі ретінде өзімді қабылдауды білдіреді. Таңдау мүмкіндігім болғандықтан, алғаш рет, мен жауапкершілікті сезіне аламын. АА-ның «ісіне» араласу арқылы, қағидаларын түсініп, күнделікті өмірімдегі мәселелерді шешуге мүмкіндік аламын. Өзімді қамтамасыз ете отырып, мен АА-дан алғанымды АА-ға қайтара аламын!

АА-ға қайырымдылық жасау арқылы, өзімнің саулығыммен қатар, болашақ ұрпақ үшін де АА-ның өміршеңдігін қамтамасыз етемін.');
INSERT INTO reflections (day, month, title, text) VALUES (31, 'Июль', 'БАРЛЫҚ УАҚЫТТА ОҚЫЛАТЫН ДҰҒА', 'Құдайым, қолымнан келмейтін істі қабылдайтындай жан тыныштығы мен сана бер, қолымнан келетін істі атқаратындай қуат бер. Осы екеуін ажырататындай ақыл бер. Менің қалауым емес, Сенің еркің болсын.

Бұл дұғаның күші оның жан-жақтылығы мен АА Достастығы сияқты қарапайым және көркем болуында. Кейде оны қайталап жатып сүрініп кетемін. Бірақ бұл дұғаның шатастыратын бөлігін таңдасам, мәселенің неде екенін бірден түсінемін. Бұл жағдай алғаш рет орын алғанда, қорқып кеттім. Бірақ қазір осы дұғаны тиімді құрал ретінде пайдаланамын. Өмірді бәз қалпында қабылдай отырып, ақылдың анықтығы мен жан тыныштығын табамын. Белгілі бір әрекеттерді жасай отырып, батылдыққа ие боламын. Өзім шамам жететін іске нұсқаулық беріп, кей істен бас тартуым керектігін ұқтыратын Құдайыма алғыстан басқа айтарым жоқ. Қазіргі менің өмірім, қызметім, жан тыныштығым және осы Бағдарлама, бәрі-бәрі бұл - Құдайдың сыйы. Ал ақылдың айқындығы мен жан тыныштығы алға жылжып, биікке өрлеуіме мүмкіндік береді.');
INSERT INTO reflections (day, month, title, text) VALUES (1, 'Август', 'ОСЫ ЖОЛМЕН ӨМІР СҮРУ', 'Рухани өмір — бұл теория емес. Рухани өмірді, өмір сүру керек.

Бағдарламаға жаңадан келгенімде, Бағдарламаның рухани қырын түсініп, не үшін ол бойынша өмір сүру керектігін түсіне алмадым. Бірақ қазір салауатты өмір салтын ұстанғандықтан, онсыз өмірімді елестете алмаймын. Мен руханиятты іздедім. Ақырында өз түсінігімдегі Құдай, не үшін жиырма жыл бойы ішімдік ішкеніме жауап берді. Құдайдың қалауымен рухани өмір жетегінде өзімнің серіктестерімді жақсы көруді, қамқорлық жасауды, оларға жанашырлық танытуды, сондай-ақ, бұрын тек қорқынышты көрінген әлемде шаттыққа бөленуді үйрендім.');
INSERT INTO reflections (day, month, title, text) VALUES (2, 'Август', 'БІЗ НИЕТТІ БОЛДЫҚ', 'Қазіргі уақытта біз өз өмірімізді ретке келтіруге тырысамыз.

Бірақ бұл мақсат емес.

Сегізінші Қадамға барар жолда адасу мен үшін қаншалықты оңай! Алтыншы және Жетінші Қадамдармен жұмыс істеу барысында еркіндікке ұмтылып, өзгергім келді. Қазір маған бұрынғыдан да өзімшілдік пен жасырын ниеттерім қауіп төндіреді. Маған кешірім берген жандар мені кешірген кезде, даңдайсып кету мақсатым емес. Мақсатым, өзім істеген қателіктерді түзету арқылы, өзім де түзелгім келеді. Өзіміз қиянат жасаған адамдардың алдында өз айыбызды жуып-шаюға барынша күш саламын. Кейіннен, Құдайдың еркіне қарай қадам басамын.');
INSERT INTO reflections (day, month, title, text) VALUES (3, 'Август', '...ҚҰДАЙҒА ЖӘНЕ АЙНАЛАМЫЗДАҒЫЛАРҒА ҚЫЗМЕТ ЕТУ', 'Біздің шынайы мақсатымыз — өмірімізді Құдай мен айналамыздағы адамдарға барынша пайдалы болатындай етіп өзгерту.

Alcoholics Anonymous, p. 77 Құдайдың	мен	туралы	жоспары	сүйіспеншілік	арқылы көрінетіні анық. Құдай мені қатты жақсы көргендіктен қоқыс пен түрмеден шығарып, өз әлеміне пайдалы етті. Енді Оған жауап ретінде барлық адамзатқа сүйіспеншілікпен қызмет етіп, үлгі болуым керек. Құдай мені қалай сүйіспеншілікке бөлесе, өзгелердің

дәл сондай сүйіспеншілікке бөленгенін қалаймын.');
INSERT INTO reflections (day, month, title, text) VALUES (4, 'Август', 'СЕНІМНІҢ ДӘНЕГІ', 'Әрине,  сенім  қажет,  бірақ  сенімнің  өзі  жеткіліксіз.

Сенгенімізбен, Құдайдан алыс болуымыз әбден мүмкін.

Бала кезімде Құдайдың бар екеніне үнемі күмәнданатынмын. Мен сияқты «ғылыми ойшыл» үшін, бірде-бір жауап мұқият талдаусыз қалмайтын. Бір өте сабырлы әйел: «Сен сенімге ие болуың керек» деп айтпағанда, жалаң түсінікпен қашанға дейін өмір сүрерім белгісіз еді. Бұл қарапайым сөздер менің сауығуымның дәнін екті! Бүгінде, санамды алкоголизмнің арамшөптерінен тазартып, баяу өсіп келе жатқан, баяғыдағы сенімнің дәнегінің жайқалып гүлденуіне мүмкіндік беремін. Әр күн сайын бұл сенім бағына сүйіспеншілікпен жасаған күтімім, өз түсінігімдегі Жоғары Күшке жақындата түседі. Егер, Құдайға деген сенімім жоғалмаса, Ол өмірімнен ешқайда жоғалмайды. Мен Құдайдан Оның қалауын орындауға дайын болуымды сұраймын.');
INSERT INTO reflections (day, month, title, text) VALUES (5, 'Август', 'МҰҚИЯТ ТЫҢДАУ', 'Біз өзіміздің ойлау және әрекет ету құқығымызды дәлелдеп, талап етеміз.

Егер, Бағдарламаны тиімді пайдаланған жандардың кеңестерін қабылдап, олар сияқты әрекет ете алсам, өткенімнен құрсауынан шығуға мүмкіндік бар. Кейбір мәселелер жоғалады. Ал енді бір мәселелер шыдамдылық пен жақсы ойластырылған әрекеттерді қажет етеді. Өз тәжірибесімен бөлісетін адамдарды мұқият тыңдау, күтпеген мәселелердің шешімін табуға септігін тигізіп, интуитивті реакцияны дамытады. Ойланбаған әрекеттерден аулақ болғаным дұрыс. Жиналыстарға бару немесе басқа АА мүшесіне қоңырау шалу, әдетте кикілжіңді азайтады. Мен сияқты мәңгілік азап шегушінің жолын жеңілдетеді. Өз мәселем жайлы жиналыстарда немесе демеушімен жеке сөйлескенде, өзім тап болған жағдайға оң әсерін береді. Өз кемшіліктерімді анықтап, маған зиянын тигізіп жатқанын көремін. Бағдарламаның рухани күші мен өзгелердің көмегіне жүгіну арқылы, қажетті дүниені істеуге сенімді боламын.');
INSERT INTO reflections (day, month, title, text) VALUES (6, 'Август', 'БЕЙШАРА', 'Біз эгоизм, қорқыныш, пайдакүнемдік, өз-өзімізді алдау, өзін- өзі аяушылық сезімдерінің жетегінде жүріп, айналамыздағыларды өзімізден алыстаттық. Сәйкесінше, олар біздің қарым- қатынасымызға сай қайтымын жасады.

Эгоизм ішімдікті ішуімнің қозғаушы күші болды. Мен табысқа жету үшін де, қайғыларымнан арылу үшін де ішетінмін. Менің мәселемнің шешімі — мойынсұну. Қазір өз еркімді және өмірімді Құдайға тапсыруды үйреніп жатқан жайым бар. Демеушім қызмет ету сау қалпымды сақтайтынын айтады. Бүгінде «Құдайдың қалауын танып-білуге, Оның қалауындағы өзім істеуге міндетті істі орындауға тырысып жүрмін бе?! Мен өзімнің АА тобыма қызмет етемін бе?»');
INSERT INTO reflections (day, month, title, text) VALUES (7, 'Август', 'ӨМІР СҮРУ ӘДІСІ', 'Біз, кезінде, бұл шығар жолды суға батқан адам сияқты үмітпен іздедік. Бұл жол бастапқыда жіңішке таяқ сияқты көрінгенмен, кейіннен мейірімді, құдыретті Құдайдың ыстық алақаны болып шықты. Жаңа өмірдің есігі ашылды. Қаласаңыз, шынымен де, жол табуға көмектесетін «өмір сүру үлгісі» де бар.

Күн сайын Құдайға Достастық арқылы «өмір сүру үлгісін» көрсеткені үшін шын жүрегіммен алғыс айтамын. Бірақ шынымен');
INSERT INTO reflections (day, month, title, text) VALUES (8, 'Август', 'ТІЗІМ ЖАСАДЫҚ...', 'Біз зиян келтірген барлық адамдардың тізімін жасадық...

Сегізінші Қадамға келгенде, жасаған барлық әрекеттерімді қалай тізімдей аламын деп ойладым. Кесірім тиген жандардың саны көп, кейбіреулері бақилық болған шығар, кім білсін?! Сырт көзге мен істеген қателіктер маңызсыз болса да, бірақ мені қатты алаңдатты. Бұл Қадамның ең бастысы — өзің тигізген зиянды мүмкіндігінше жақсы жолмен өтеуге тырысу. Ниет болса, жол да табылады. Себебі өзімді жақсы сезіну үшін, өзімді кінәлау сезімінен арылуым керек. Бұл азапты ойлар жанға тыныштық бермесі анық. Егер, өзіме шынайы қарай алсам, Жоғарғы Күштің көмегімен осы жағымсыз сезімдерден арыла аламын.');
INSERT INTO reflections (day, month, title, text) VALUES (9, 'Август', 'КЕЛТІРГЕН ЗИЯНДЫ ӨТЕУ', '...оларға келтірген зиянымды өтеуге ниет еттім.

«Барлық» сөзі Сегізінші Қадамның негізгі сөздерінің бірі болып табылады. Мен тізімге біреуді қосып, енді біреуді қоспауға хақым жоқ. Бұл мен зиян келтірген барлық адамдардың тізімі. Бұл Қадам кешіріммен байланысты. Себебі, біреуді кешіргім келмесе, оны тізімге енгізбеймін. Бірінші, есімді тізімге енгізбес бұрын: «Мені қай кезде, қалай ренжіткеніне қарамастан барлық адамдарды кешіремін», - деген қысқа дұғаны оқыдым.

Әрбір дұға оқу алдында бір маңызды тіркес бар. «Біздің күнәларымызды, біз өзгелердің күнәларын кешкендей кешіріңіз», - деп сұраймын. Мен басқаларды кешіргенім сияқты, мені де кешіруін өтінемін. Егер осы дұға оқу кезінде жек көру мен өкпе-реніш бойымды билеп алса, Жоғарғы Күштен бұл сезімнен арылтуын сұраймын.');
INSERT INTO reflections (day, month, title, text) VALUES (10, 'Август', 'ТАЛПЫНЫСТАРДЫ ЕСЕЛЕУ', 'Өзінің моральдық қасиеттерін талдай отырып, кімге және нақты қандай зиян келтіргенін түсіну үшін, күш-жігерді екі есе арттыруы керек.

Менің салауатты өмір салтын ұстана отырып, рухани өсуім бойынша өзімді жақсы танимын. Сонымен қатар кез келген басқа адамды жеке тұлға ретінде қарастыру қабілетім артады. Бұл жағдай оларды ішіп жүргенде зияным тиген жандардың хәл-ахуалына түсіністікпен қарауға алып келеді. Мен жай ғана өтірік айтпадым, Том жайында өтірік айттым. Мен жай ғана алдамадым, Джо-ны алдадым. Өзімнің бейәдеп қылығыммен жеке тұлғалардың қадыр- қасиетін аяққа таптап, көңілдеріне қаяу түсірдім. Сау қалпымды сақтап, жаным жай табуы үшін ренжіткен жандармен қарым- қатынасымды реттеуге күш салуым керек.');
INSERT INTO reflections (day, month, title, text) VALUES (11, 'Август', 'СОҢҒЫ ТАМШЫДАН» АРЫЛУ', 'Моральдық сараптама жасау, қоғамға келтірген зиянымызды байыпты талдап, шынайы баға беруге ниеттену. Бұл жанымызды

жегідей жеп, іштен тынып жүрген сары уайымның «соңғы тамшысын» арылу.

Сегізінші Қадам бойынша жасалған тізімім жағымсыз әсер сыйлап, бойымды ыза-кекке толтырды. Төрт жыл бойы салауатты өмір ұстансам да, үрей мен тәкаппарлықтың ортасында сал болып қалғандай сезімде болдым. Бұл ауыр хәлден Қадамда айтылған сөздерді тілмен айтып қана қоймай, жүрекпен бекіткенде арылдым. Көп жылдар бойы алғаш рет ауыртпалыққа шыдамай, ашуға бой алдырдым. Бұл көңілімде белең алған қызыл, қара және сары түстердің жарылысы болды. Өз бейнеме қараған кезде көзімнен қуаныш пен бір жеңілдіктің жасы ағып жатты.

Өнер иесі үшін шығармашылығынан айрылу бір қасірет. Ауру кезімде өнерге беттей алмадым. Осы әрекетім арқылы өзімді ең ауыр жазамен жазаладым. Қалпына келу кезеңінде кемшіліктерімнен туындаған ауыртпалықтар Құдайдың сынағы екенін түсіндім. Жоғарғы Күш бұл сынақты еңсемді тіктеп, еркін өмір сүруім үшін жібергені анық.');
INSERT INTO reflections (day, month, title, text) VALUES (12, 'Август', 'ӨТКЕНГЕ ҚАРАУ', 'Ең алдымен, біз өткенімізге қарап, қашан және қай жерде қателескенімізді түсінуге тырысуымыз керек. Содан кейін бүлінген дүниелерді қалпына келтіру үшін белсенді әрекет жасауға тиіспіз...

«АА» деп аталатын Сауықтыру еліне қызықты саяхатқа шығу арқылы жан тыныштығын таптым. Ал өмір көкжиегі қара түнек тұманмен бүркемеленбей айқын көрініп тұрды. Қателіктерді табу үшін өткеніме көз жүгірту қауіпті және қиын міндет болған жайы жайы бар. Бұл бір азап іспеттес. Ескі жараның аузы тырналса

«сүрініп кетемін» деп қорықтым! Өткенді естен шығарып, қазіргі алтын уақытта өмір сүре аламын ба? Өзім зиян келтірген жандарды ұмытқан емеспін. Есіме түскен сайын, өткен күннің ауыртпалығы мен бүгінгі күннің жан тыныштығының ортасындағы бір өткелде қалып қойғандай әсерде боламын. Қайткен күнде Құдайдан өзім

ренжіткен жандармен шынайы келбетімде жүздесуге батылдық беруін сұрауым керек. Оларға келтірген зиянды анықтап, кінәмді өтеуге мүдделімін. Содан кейін ғана, менің рухани сапарым қайта басталуы мүмкін.');
INSERT INTO reflections (day, month, title, text) VALUES (13, 'Август', 'ТАЗАРУ', 'Өткен іс-әрекеттеріміздің салдарынан арылғаннан кейін, жаңа рухани біліміміздің негізінде адамдармен қалыпты қарым-қатынас құра аламыз.

Сегізінші Қадамға жақындаған кезде табысты жұмыс істеу үшін, алғашқы Жеті Қадамда өткен батылдық, адалдық, шынайылық, дайындық және тиянақтылық осы жерде қажет болатынын түсіндім. Бастапқыда бұл тапсырманы орындауға күшім жетпеді. Сол себепті де бұл Қадамда: «Дайын болдық...» делінеді. Маған батылдық - бастау үшін, адалдық - қателіктерімді көру үшін, шынайы ниет - бәрін өз орнына қою үшін, тиянақтылық - тізімді дайындауда мұқият болу үшін, дайындық – қызмет етуім үшін қажет. Жоғарғы Күштің көмегімен осы қасиеттерді дамыттым. Бұл маған осы Қадамды аяқтап, рухани өсуімді жалғастыруға мүмкіндік берді.');
INSERT INTO reflections (day, month, title, text) VALUES (14, 'Август', 'АЙЫПТЫ ӨТЕУ', 'Сан жылдар бойы санамызда жиналған қоқыстан тазарғымыз келсе, өзім білемдікпен қатар, өзгелерге үстемдік құрғымыз келетін қыңыр қылығымыздан арылуға тиіспіз. Әлі де санамызды теріс ойлар билеп тұрса, Құдайдан ниетімізді түзеуін сұрауымыз керек. Біз әу бастан «алкогольді жеңу үшін, кез келген құрбандыққа дайын боламыз» деп шешім қабылдағанымызды ұмытпайық.

Менен жапа шеккен жандардың тізімін жасау, мен үшін қиын емес еді. Олар менің Төртінші Қадамдағы тізімімде бар. Атап айтқанда, нақты немесе қиялымда ренжіткен адамдар. Қалпыма

келуімнің сәтті жүзеге асуы үшін, өзім зиян келтірген жандардың мені кешіруі маңызды емес. Маңыздысы, Құдаймен қарым- қатынасымды түзеп, өзім келтірген зиянның залалын өтеу үшін, қолдан келгеннің бәрін жасағаным...');
INSERT INTO reflections (day, month, title, text) VALUES (15, 'Август', 'БІЗ ЕШКІМДІ РЕНЖІТПЕДІК ПЕ?', '…кейбіреулеріміз басқа істе сүріндік. «Ішімдік ішуім өзімізге зиян тигізбесе, басқа ешкімге зияны тимеді» деп мәлімдедік.

Бұл Қадам маған өте қарапайым болып көрінді. Мен зиян келтірген бірнеше адамды анықтадым, бірақ олар қазір жақын жерде жоқ. Дегенмен, өзімді ыңғайсыз сезініп, бұл Қадам туралы айтудан аулақ болдым. Уақыт өте келе, мені мазалайтын өмірімнің көлеңкелі тұстарына шынайы көзбен қарауды үйрендім. Шынайы көзқарасымның нәтижесінде, алыстап кеткенім үшін ренжіп жүрген ата-анаммен бетпе-бет келдім. Сондай-ақ, жұмысқа шықпай қалуыма байланысты алаңдаушылық білдірген жұмыс берушіммен, ешқандай себепсіз достарыммен араласпай кету сынды көптеген олқылықтар бар екен. Адамдарға нақты зиян келтіргенімді көргенде ғана, Сегізінші Қадам жаңа мәнге ие болды. Енді өзімді жайсыз сезінбеймін, керісінше тазарып, жаңарып қалғандай әсердемін.');
INSERT INTO reflections (day, month, title, text) VALUES (16, 'Август', 'МЕН ҚАРЫМ-ҚАТЫНАСТАН АЙРЫЛЫП ҚАЛДЫМ', 'Біз «басқаларға зиян келтірдік» деп айтқанда нені меңзегенімізді сұрауға болады. Жалпы адамдар бір-біріне қандай

«зиян» келтіруі мүмкін? Біз «реніш» сөзін физикалық, психикалық, эмоционалды және рухани зиян келтіретін инстинкттердің соқтығысуының нәтижесі деп анықтай аламыз.

Сегізінші Қадам бойынша кездесулерге қатысқанда әрдайым:

«Мен іс жүзінде зиянды өзгелерге емес, өзіме келтірдім», - деп ойладым. Уақыт өте келе өз тізімімді жасадым, ол мен ойлағандай әлдеқайда  қысқа  болмады.  Бұл  тізімде  маған  ұнайтын,  не

ұнамайтын, қажет жандар болды. Өткен түсінікпен қарасам: Өзгелер мен қалағандай әрекет етпеген. Ал жақын қарым-қатынас орнату, жақындарымның негізсіз талаптарына байланысты мүмкін болмаған. Ал шынына келгенде, ішімдік жүрген кезімде	«қарым- қатынастан айырылып қалдым». Ешқашан ешкімге хат жолдамағам, қоңырауларға жауап бермедім, өзгелер үшін қолжетімді болмадым. Олардың не қуанышына, не қайғысына ортақтаспаған екенмін. Бұл жағдай өз түсінігімдегі Құдаймен жалғыз қалып, әр іске шынайы баға беріп, адамдармен қарым-қатынаста адал және жауапты болып,

дайындық жасауыма мүмкіндік берді.');
INSERT INTO reflections (day, month, title, text) VALUES (17, 'Август', 'ҚАТЕЛІКТЕРДІ ТҮЗЕТУ', 'Көптеген жағдайларда біз басқа адамдарға келтірген зиянның шынымен де болмашы екенін, бірақ өзімізге келтірген эмоционалдық зиянның әлдеқайда көп екенін анықтаймыз.

соншалықты маңызы жоқ деп ойлап жүрсіз бе?! Сондықтан, кешірім сұраудың қажеті жоқ па? Себебі, олар оны әлдеқашан ұмытып кеткен бе? Егер, бір адамға істеген қиянатым әр кез есіме түсіп, ар азабы мазалайтын болса, онда ол жанды тізімде бірінші орынға қойып, кешірім сұрауға дайындаламын. Сауығудың өте маңызды бөлігі аяқталғаннан кейін, өзімді осы ренжіткен адамның алдында жайлы сезінетінімді білемін.');
INSERT INTO reflections (day, month, title, text) VALUES (18, 'Август', 'ЖАҒДАЙДЫ ЖАҚСАРТУ', 'Өткен күннің бізді алаңдататын эмоционалды қақтығыстары, біздің санамыздың тереңінде жатқандықтан, біз оларды ұмытып кетеміз.

Ішімдік ішкен кездегі ұят немесе кінәларымнан тек жақсы істермен құтыла аламын. Мас кезімде: «Неге ішесің? Сен тек өзіңе зиян келтіресің», - деп достарым жиі айтатын. Алайда, олардың

сөздерінің қаншалықты дұрыс екенін түсіне бермейтінмін! Өзгелерге зиян келтіруіммен қатар, көптеген әрекеттерім жан дүниемде ауыр жарақаттар қалдырды. Сегізінші Қадам өзімді кешіруге мүмкіндік береді. Өзім зиян келтіргендердің тізімін жасай отырып, адамдарға келтірген зиянның шығынын анықтаймын. Зиянды өтеу арқылы, ауыр жүктен арылмақпын. Бұл менің айығуыма көмектеседі.');
INSERT INTO reflections (day, month, title, text) VALUES (19, 'Август', 'КӨЗҚАРАС', 'Тізімге оралайық. Басқалардың бізге келтірген жамандығын ұмытып, өз қателіктерімізді іздеуге бел будық. Қандай жағдайларда біз өзімшілдік, қорқақтық, пайдакүнемдік іс қылып, шынайылық таныта алмадық?

Alcoholics Anonymous, p. 67 Мен енді әріптестерімнің немесе жақсы көретін адамдардың тұрақты қолдап, мақтауына мұқтаж емеспін. Бұл мен үшін еркіндік! Өкінішке қарай, бұл Қадамды бұрын білмедім. Белгілі бір көзқарасты дамытқаннан кейін, бұл әрекеттің жағдайға сәйкес және жалғыз дұрыс әрекет екенін білдім.	Осы дұрыс көзқарастың нәтижесінде,  әрдайым  дұрыс  әрекет  етуге  қабілетті  екенімді

сезінемін.');
INSERT INTO reflections (day, month, title, text) VALUES (20, 'Август', 'ЭМОЦИОНАЛДЫ БОСТАНДЫҚ', 'Адамдармен бұзылған қарым-қатынасымыз біздің қиындықтарымыздың, соның ішінде алкоголизмнің тікелей себебі болғандықтан, бұл саланы талдау, басқа салаға қарағанда құндырақ нәтиже береді.

Дайындық - мен үшін ерекше жағдай. Әуелі, жағдайды түсінесің, кейіннен әрекет етуге итермелейтін жайсыз сезім пайда болады. Өзгелерге тигізген зиянды өтеп, өзімнен бөлек, өзгелерді кешіру ниетім, Сегізінші Қадамға аяқ басуыма негіз болды. Адамдармен жайсыз қарым-қатынастағы өз рөлімді түсінгенде,

өзгелерді кешіре алдым. Уәделерде айтылған ойдың анықтығы мен жан тыныштығын сезінгім келді. Алғашқы Жеті Қадам бойынша жұмыс істей отырып, кімге зиян тигізгенімді және өзімнің жауым өзім болғанымды түсіндім. Өзім өзгермей, қоршаған ортамен қарым- қатынасты қалпына келтіре алмайтыным анық болды. Өзіммен-өзім болып, басқалармен де үйлесімді, эмоционалды еркін өмір сүруді үйренгім келді. Сегізінші Қадам бойынша жасаған тізімім достарымнан және Құдайдан оқшаулануымның соңы болды.');
INSERT INTO reflections (day, month, title, text) VALUES (21, 'Август', 'БІЗ ЖАЙ ҒАНА ТЫРЫСУДАМЫЗ', 'Менің тұрақтылығым қайтымын сұрамай, жақсылық жасау ниетінен туындады.

Биллдің жағымды жақтары The Best of Bill, pp. 46–47

Жан-тәніммен өзгеден алғанымды, басқаларға қайтымын талап етпей бере алсам бәрі дұрыс болады. АА Бағдарламасына дейін ешқашан қайтымын талап етпей, жақсылық жасап көрмеппін. Ештеңе дәметпей, қолда барыммен бөліскенде ырыздығым артатынын бұрын білген емеспін. Бүгінде, Билл айтқан тұрақтылық сыйын алдым. Бұл менің АА Бағдарламасындағы тұрақтылығым, ішкі тұрақтылығым, ең бастысы өз түсінігімдегі Құдаймен қарым- қатынастағы тұрақтылық.');
INSERT INTO reflections (day, month, title, text) VALUES (22, 'Август', 'ЭМОЦИОНАЛДЫ ТҰРАҚТЫЛЫҚТЫ ІЗДЕУ', 'Дамуымыздың жоғары деңгейіне көтерілгенде, эмоционалды тұрақтылықтың қайнар көзі Құдай екенін түсіндік. Оның мінсіз әділдігіне, кешірімшілдігіне және сүйіспеншілігіне тәуелді болу, сау ақылға тән қылық. Дәрменсіз қалған кезде де, Жоғарғы Күш күтпеген жерден өзгелерді себепкер қылып көмектесе алады. Егер біз шынымен Құдайға тәуелді болсақ, біз өзгелердің алдында даңдайсып, өзімізді Құдай сезіне алмаймыз. Сондай-ақ, адамдардың бізді қорғауына, қолдауына толығымен тәуелді болып қалмаймыз.

Мен әрдайым эмоциялық қажеттіліктерім мен қорғанысымда адамдарға тәуелді болатынмын. Бірақ енді олай өмір сүре алмаймын. Құдайдың шарапатымен адамдар алдында және кей жағдайларда, дүние-мүлікке келгенде өзімнің дәрменсіздігімді мойындадым. Мен қарым-қатынаста болуға құмар едім. Қайда барсам да, көңілімді аулайтын біреу керек болатын. Мұндай әдіс тек зиян келтіреді. Себебі қаншалықты көптің назарында болуға тырыссам, соғұрлым өзім ойлағандай құрметке ие болған емеспін. Енді қандай да бір адами күш, мені осы қуыс кеуделіктен құтқара алатынына сенбеймін. Әлі де, АА қадамдары бойынша жұмыс істеуге тура келетін жаны нәзік адаммын. Алайда, жеке бас мүддесінен принципті жоғары қоямын. Себебі, тек мейірімі шексіз Құдай ғана ішкі тыныштық пен эмоционалдық тұрақтылығымды қамтамасыз ете алады.');
INSERT INTO reflections (day, month, title, text) VALUES (23, 'Август', 'АА ИДЕЯЛАРЫН ҮЙГЕ ӘКЕЛУДІҢ МӘНІ', 'Біз АА тобында көрсеткен сүйіспеншілік пен төзімділік рухын, бүлінген отбасылық өмірімізде көрсете аламыз ба?

Менің отбасым ауруымның салдарынан зардап шегеді. АА мүшелерін жақсы көріп, қабылдағандай, оларды да жақсы көріп, қабылдауға мүдделімін. Бұл әрекетім бойыма сүйіспеншілік пен төзімділік дарытып, үйлесімдікте өмір сүруіме жол ашады. Өзгелердің жеке шекараларын құрметтеу және түсініспеушілікте әдеп сақтау, саналы жанға тән дүние.');
INSERT INTO reflections (day, month, title, text) VALUES (24, 'Август', 'ӘРЕКЕТ ЕТЕТІН ЖҰМБАҚ', 'Біздің рухани тәжірибеге түсініктеме беруге болады. Мен көбіне өз тәжірибеме түсініктеме беруге тырыстым. Тек өз хикаямды түсіндіруде жетістікке жеттім. Мен бұл тәжірибе қандай сезім тудыратынын, нәтижесін де білемін. Бірақ оның «қайтіп, қалай» өміріме оң ықпал етіп жатқанын ешқашан толық түсінбеуім мүмкін.

АА-ның ашық жиналысында рухани күйзелісте болып:«Мен алкоголикпін!» деп айтуға мәжбүр болдым. Сол күннен бастап, мен ешқашан ішпедім. Ашық мойындаудан кейін, естіген сөздерімді және олардың маған қалай әсер еткенін айта аламын. Бірақ болған жағдайды түсіндіре алмаймын. Неге екенін білмеймін, өзімнен мықты Күш мені сауығу үшін таңдады деген сенімдемін. Әлі білмеген дүниелерге алаңдамауға және күмәнданбауға тырысамын. Оның орнына Қадамдар бойынша жұмыс істеп, АА принциптерін өмірімде қолданып, тәжірибеммен бөлісуді жалғастыра бермекпін. Бұл жол толысқан руханиятқа апаратынына күмән жоқ. Ол жерде көп нәрсе ашылады. Қазірше маған берілген үлкен сыйлық – бұл Құдайға сену, Қадамдар бойынша жұмыс істеу және өзгелерге көмектесу.');
INSERT INTO reflections (day, month, title, text) VALUES (25, 'Август', 'СЫРЛАСУ', 'Сенің қалауыңды ойдағыдай орындай алу үшін, мені өзімшілдік шынжырынан босатуыңды сұраймын.

Ішімдікті басқа адамдармен сырласу үшін ішетінмін. Алайда, ішімдік жүріп, жалғыздықтың құлдығына жегіліп қалдым. АА-да менен бұрын келгендермен, әлі келетіндермен сырласу мүмкіндігін алдым. Құдайдың осы жақсылығы үшін дән ризамын.');
INSERT INTO reflections (day, month, title, text) VALUES (26, 'Август', 'ЖАҚСЫЛЫҚ ЖАСАУ', 'Олар басқаларға көмектесудің арқасында ішпейтіндерін білсе де, бұл ынталандыру екінші орында болды. Олар үшін басқаларға көмектескенде алатын әсердің сезімі маңыздырақ болды.

Мен үшін бұл сөздер өз түсінігімдегі Құдайды жүрегіме енгізу. Ойлана отырып, Дұға етемін. Бұл әрекетім арқылы, Құдайдың патшалағына жол ашамын. Жоғарғы Күшпен дұрыс байланыс орнатамын. Әр күнгі дұрыс әрекетім салауатты өмірімнің кепілі

болмақ. Тегін алғанымды, тегін беру арқылы, тағы да бір күн сау қалпымды сақтап қаламын.');
INSERT INTO reflections (day, month, title, text) VALUES (27, 'Август', 'ЗЕЙІНДІ БОЛУ', 'Екінші Дүниежүзілік соғыс басталған кезде, біздің Жоғарғы Күшке деген тәуелділігіміз (АА мүшелері ретінде) алғашқы маңызды сынақтан өтті. АА мүшелері Қарулы Күштерге қабылданып, бүкіл әлемге таратылды. Олар тәртіпке бағына ма, отқа шыдай ма, төтеп бере ала ма?..

Мен Жоғарғы Күшке назарымды аударамын. Осы Күшке барымды беремін. Бүгінгі таңда рухани армияның күшін сезінетін, осы Күштің сарбазы боламын. Сүйіспеншілігім, мойынсұнуым және тәртіпке бағынуым рухани бірліктің толқынына жалғайды. Рухани бірлік толқыны Жоғарғы Күшпен байланыс орнатуға мүмкіндік береді. Осы Күш, мені әр күннің барлық қиындықтарынан алып өтеді. Бүгін жасаған қадамдарым менің сөздерімді және істерімді нығайтсын. Мен әрқашан өзімнен мықты Күшпен берілген идеяларымыздың мәні бар екенін есте ұстап, оны басқалармен бөлісемін.');
INSERT INTO reflections (day, month, title, text) VALUES (28, 'Август', 'ЖҮКТІ ЖЕҢІЛДЕТУ', '...Бізге қандай жағдайда келгенін, өзгелерге көрсету. Бұл біздің өмірімізді құндырақ етеді... Біздің қараңғы өткеніміз - басқалардың бақытты өміріне апаратын кілт.

Салауатты өмір салтын ұстануымның арқасында көптеген азаптардан арылдым. Атап айтқанда, серіктесімнің алдауы, ең жақсы досымның сатқындығы, анамның менен күдер үзуі бұрынғыдай жаныма батпайтын болды. Әрбір жағдайда Бағдарламада тағдырыма ұқсас дүние айтылды. Сәйкесінше, мен де өз басымнан өткен оқиғаммен бөлістім. Бұл жағдайдан сырлас жандар жанымыз жеңілдеп, қимай қоштастық.');
INSERT INTO reflections (day, month, title, text) VALUES (29, 'Август', 'АНОНИМ БОЛҒАНЫН ҚАЛАЙМЫН', 'АА-да ешқандай ережелер жоқ, сондықтан өзім қалаған жердемін. Аноним болуы да менің қалауым. Құдайымның осы Бағдарламаның құралдарының бірі ретінде, мені де пайдалануын қалаймын. Өзімшілдігімді кішіпейілділікке ауыстырып, өзімді құрбан етемін. Бұл өзімді тегін беру өнері. Сау қалпымда бүкіл әлемге: «Мен АА мүшесімін!» деп айқайлағым келген ұмтылысымды басып, жаным жай тауып, қуанышқа бөленемін. Адамдарға өмірімдегі өзгерістерді көруге мүмкіндік беремін. Олар менде қандай өзгеріс болғанын сұрайды деген үміттенемін. Мен рухани қағидаларды басқа адамдарды сынау, кемшіліктер іздеу және сынға алу сияқты әрекеттерден жоғары қоямын. Мен өзімнің тобыма әрдайым сүйіспеншілік тілеп, өзара қамқорлық көрсетуге дайынмын.');
INSERT INTO reflections (day, month, title, text) VALUES (30, 'Август', 'ЖАЛҒЫЗ ШАРТ', 'Үшінші Дәстүр үшін тек «ішпеймін» деген ниетім қажет болғанына ризамын. Жылдар бойы өз уәделерімді орындамадым. Достастықта бірдеңе уәде етуім немесе бұл үшін алаңдауым қажет болған жоқ. Өз үйімде екенімді түсіну үшін, маған бір-ақ жиналысқа қатысу қажет болды. Мәңгілік махаббатқа ант берудің қажеті жоқ еді. Белгісіз адамдар мені құшақтап: «Барлығы жақсарады. Күн сайын жағдайыңыз жақсаратын болады», - деді. Олар енді бейтаныс емес, қамқор достар айналды. Құдайдан салауатты өмірді қалайтын жандарға көмектесуін сұраймын. Жаратушым, көңілдің асқақтауынан сақтап, ризашылықта болуыма көмектес!');
INSERT INTO reflections (day, month, title, text) VALUES (31, 'Август', 'ЕРЕКШЕ БАҒДАРЛАМА', 'Анонимді Алкоголиктер ешқашан кәсіби маман болмайды. Біз ежелгі сөздердің мәнін белгілі бір дәрежеде түсіндік: «тегін алған нәрсені, тегін бер». Кәсіби деңгейде руханилық пен ақша сыйыспайтынын анықтадық.

Менің ойымша, АА алкоголизмді емдеуде бірегей жол ұстанады. Себебі, ол тек бір алкоголиктің басқа алкоголикпен бөлісу принципіне негізделген. Бағдарламаның бірегейлігі де осында. Мен ішуді тоқтатам деп шешім қабылдаған кезде, АА-дағы өзім білетін әйелге жүгіндім. Ол маған АА идеясы туралы айтты. Ол ешқандай ақшалай өтемақы алған жоқ. Бірақ ол өтеміне, тағы да бір күн өзін сау қалыпта сақтап қалды. Бүгінгі таңда мен де көрсеткен қызметіме, тағы бір күн сау болуымнан басқа ешқандай ақы сұрай алмаймын. Менің жұмысым мәрттікпен өтеледі.');
INSERT INTO reflections (day, month, title, text) VALUES (1, 'Сентябрь', 'РУХАНИ ӨСУГЕ ДАЙЫНДЫҚ', 'Біз көбірек сый алғымыз келсе, оянуды жалғастыруымыз керек.

Тұрақтылық алкоголизмнен туындаған «қуыс кеудені» толтырады. Кейде өзімді жақсы сезінгенім сонша, жұмыс аяқталды деп ойлай бастаймын. Алайда, қуаныш — бұл тек қана азаптан құтылу емес, ол рухани оянудың жалғасы. Қалпына келтірудің қағидаларын күнделікті өмірде белсенді қолданып, сонымен қатар, өз тәжірибеңді басқалармен бөліскенде, біз шаттыққа бөлене аламыз. Менің Жоғарғы Күшім маған рухани оянудың тереңдеуіне көптеген мүмкіндіктер береді. Мен, тек осы өсуге дайын болуым қажет. Бүгінгі таңда рухани өсуге дайынмын.');
INSERT INTO reflections (day, month, title, text) VALUES (2, 'Сентябрь', 'СЕНУ ҮШІН СЕБЕП ТАБУ КЕРЕК', 'Өсуге дайындық — бұл барлық рухани дамудың мәні.

Бір әннің мәтінінде: «…Мен сену үшін себеп іздеймін…» дейтін тіркес бар. Бұл тіркес өмірімнің түзелетініне сену үшін, себеп таба алмаған кездерді еске салады. АА-ға келу менің өмірімді сақтап қалғанымен, үш айдан кейін қайтадан ішіп кеттім. Біреу маған: «Сен сенуге мәжбүр емессің. Тіпті оның мәнін түсінбесең де, өміріңде бір мән бар екеніне сенгің келмей ме?» — деді. Мен өз өмірімде мән бар екеніне сенгім келетінін түсінгенде, Қадамдар бойынша жұмыс істей бастадым. Қазір: «Иә, менде ниет бар…» деген сөзімді әрекетке, адалдыққа және менімен өмір бойы бірге болған, Жоғарғы Күш алдында ашықтыққа апаратын кілт ретінде пайдаланамын.');
INSERT INTO reflections (day, month, title, text) VALUES (3, 'Сентябрь', 'ЖАҢА ӨМІР БАСТАУ', 'Біз «ішуді тоқтату жеткілікті» деп ойлайтындар қателеседі деп есептейміз.

Тоғызыншы Қадам туралы ойланған кезде, тек сау қалыпта жүру жеткіліксіз екенін көремін. Бойымды мас кезімдегі үмітсіздік сезімі билегенде, салауатты өмірді қалайтыным анық. Алайда, өзгелер үшін менің сау қалыпта жүруім жеткіліксіз. Сондықтан, Құдай берген жаңа өмірді жақындарым мен отбасым үшін бастауым керек. Сондай-ақ, АА жолымен жүргісі келетіндерге де көмектесуді ұмытпауға тиіспін.

Құдайдан саулық сыйын өзгелермен бөлісе алатындай күш- қуат сұраймын. Осылайша Оның игіліктері өзім жақсы көретін жандарға қолжетімді болады.');
INSERT INTO reflections (day, month, title, text) VALUES (4, 'Сентябрь', 'ҚАЛЫПҚА КЕЛУ', 'Бізді ұзақ қалпына келтіру кезеңі күтіп тұр…

Күн сайын, бірінші стақаннан аулақ болуым, айығу процесіндегі негізгі мақсатым. Бұл тапсырма АА Қадамдарымен жұмыс істегенде тиімді шешімін табады. Рухани өмір - бұл теория емес, шынайы өмір сүруді қажет етеді. Екінші Қадам менің рухани жолымның бастауы болды. Тоғызыншы Қадам, мені рухани өмір сүруге үйреткен Қадамдардың соңғы кезеңіне жақындатады. Жоғарғы Күштің басшылығынсыз айығудың әртүрлі кезеңдерінен өтуім мүмкін емес еді. Құдай мені біреуге себепкер қылса, маған да басқа біреуді себепкер қылатынын түсіндім. Құдай ішімдіктен бетімді қайтарып, өзім істей алмайтын істі істеді. Бұл ақиқатты түсінсем, осының өзі дәлел бола алады. Мен, күн сайын Құдайдың басшылығын іздеуді жалғастыруым керек. Жаратушы күнделікті сау қалпымды сақтап, өмірімді қалпына келтіруге қажетті күш-қуат береді.');
INSERT INTO reflections (day, month, title, text) VALUES (5, 'Сентябрь', 'ЭМОЦИОНАЛДЫ ТЕҢДІК', 'Өзгелерге тигізген зиянымызды мүмкіндігінше өтедік…

Маскүнем кезімдегі күндерге қайта қарасам, өзімнің қыңыр қылығыммен кездейсоқ кездескен көптеген жандардың жүйкесіне тигенім есіме түседі. Бұл адамдарды тауып, олардан кешірім сұрау мүмкін емес. Бұл олқылықтың орнын тағдырымда жанама кездескен жандарға жақсылық жасау арқылы толтыра аламын. Әрдайым сыпайы, мейірімді болу эмоционалды теңдікте және үйлесімдікте өмір сүруіме көмектеседі.');
INSERT INTO reflections (day, month, title, text) VALUES (6, 'Сентябрь', 'ҚАУІПТЕРДІҢ АЛДЫН АЛУ', '…өзімізге немесе біреуге зиян келтіруі мүмкін жағдайлардағы қауіптердің алдын алу.

Тоғызыншы Қадам, мені тек бүкіл адамзатпен ғана емес, сонымен қатар күнделікті өмірімдегі адамдармен қарым- қатынасымды қалпына келтіреді. Біріншіден, бұл Қадам, мені АА қамқорлығынан шығарып, адамдармен «сол жерде», яғни, АА сыртында қандай да бір шарттарсыз араласуға мүмкіндік береді. Бұл қорқынышты, бірақ қалыпты өмірге оралу үшін қажет. Екіншіден, Тоғызыншы Қадам, менің адамдармен қарым-қатынасымды қалпына келтіріп, жүйелейді. Менің салауатты өміріме қауіп төндіретін өткеннің қирандыларын тазалайды. Тоғызыншы Қадам жайлы да, тыныштықтағы сау қалыпты өмірге апарар жолды көрсетеді.');
INSERT INTO reflections (day, month, title, text) VALUES (7, 'Сентябрь', 'ӨЗ АУЛАҢДЫ ТАЗАЛАУ', 'Біз өз ауламызды таза ұстамай, өзгелерден тазалық талап ете алмаймыз. Сол сияқты өз кемшіліктерімізден арылмай, өзгелердің кемшілігін түзетуге тырысқанымыз құптарлық іс емес. Біздің басты ұранымыз: «Біреудің мінін тергенше, жамандығын көргенше, өзіңмен алыс өлгенше».

Мен ішуді тоқтатқаннан көп ұзамай, әкемнің алдындағы кінәмді жоюға тырыстым. Бұрын әкемді өз қиындықтарыма кінәлағандықтан, ол менің сөздеріме құлақ аспады. Бірнеше айдан кейін жаңа әрекетке көштім. Бұл жолы оны кінәламай, қателіктерін бетіне баспай хат жаздым. Осы әрекетім оң әсерін берді. Түсінгенім, мен өз аулама жауаптымын. Құдайдың арқасында АА-ға кір жұқтырмадым.');
INSERT INTO reflections (day, month, title, text) VALUES (8, 'Сентябрь', 'БІЗ ОДАН ҚОРҒАН СҰРАЙМЫЗ', 'Біз бәрінен бас тартып, Жаратушыдан қамқор болуын сұрадық.

Өз өмірімді жалғыз басқаруға шамам жетпеді. Қанша тырыссам да, сәтсіздікке ұшыраумен болдым. «Ең үлкен күнәм» мені құлдырауға түсірді. Өз өмірімді басқармақ түгілі, қара басымды алып жүріп үшін көмекке мұқтаж екенімді түсіндім.

Дереу күресті тоқтатып, өзімді толығымен Құдайға тапсырғанда ғана, рухани өсе бастадым. Құдай мені кешірді. Дәрігерлер өміріме жауап бере алмағандықтан, мені тек Жоғарғы Күш құтқара алды. Қазір, мен өзімді кешіріп, бұрын-соңды болмаған еркіндікке қол жеткіздім. Қарсыласпай Жоғарғы Күштің санам мен жүрегіме енуіне мүмкіндік бердім. Білген сайын, білмегенім көбейіп барады. Бұл жағдай кішіпейілділікке үйретіп, шынымен рухани өсуімді жалғастырғым келеді. Өмірімді толықтай Құдайға тапсырмай, жан тыныштығынан рахат ала алмаймын. Мен өзіме адал болып, Жаратқаннан көмек сұрасам, өмір мені марапаттан кенде қалдырмайды.

Бүгін Құдайдың қалауымен саумын. Бүгін ішімдіктен алыстатқан Құдайға шүкірлік етемін. Бүгін өмір керемет!');
INSERT INTO reflections (day, month, title, text) VALUES (9, 'Сентябрь', 'ЖАҢА ЕСІКТЕР АШЫЛАДЫ', 'Айтылған Уәделерге мүмкін біреу кеш, мүмкін біреу ерте қол жеткізді. Бұл жағдай көпшілігіміздің басымыздан өтті.

Бұл үзіндіде айтылған Бағдарламаның Уәделері біртіндеп орындалуда. Тоғызыншы Қадамды іс жүзінде қолдануымның нәтижесінде сөнген үмітім, қайта жанды. Бұл Қадам айығу бойынша міндеттерді көріп, өз алдыма тапсырма қоюыма септігін тигізді.

Ескі әдеттер мен қыңыр мінезді өзгерту қиын. Бірақ, Тоғызыншы Қадам бойынша жұмыс істеу арқылы, бұрынғы маскүнемдіктің есігі жабылып, сау алкоголик ретінде жаңа даңғылға жол ашылады. Мен үшін зиянның өтемін жасау өте маңызды. Мен қарым-қатынасты реттеп, мінез-құлқымды түзеткен сайын, сау қалыпта жақсы өмір сүре аламын! Бірнеше жыл сау жүрсем де,

«өткеннің қалдықтарын» тазалап отыру керек. Бұл істе дұрыс жұмыс істей алсам, Тоғызыншы Қадам әрдайым көмектеседі.');
INSERT INTO reflections (day, month, title, text) VALUES (10, 'Сентябрь', 'АЙЫҒУ ҮШІН КІМГЕ СЕНУ КЕРЕК?', 'Егер, күш салсаңыз, мұның бәрі, яғни, Уәделер орындалады.

Кейде: «Зиянды өтеудің жолы ауыр! Былай масқара болу мүмкін емес!» деген ойда боламын. Алайда, кішіпейілділік мені Рухтың нұрына жақындатады. Әрі қарай айығып, шаттықта, үйлесімдікке толы өмір сүргім келсе, АА - менің жалғыз үмітім.');
INSERT INTO reflections (day, month, title, text) VALUES (11, 'Сентябрь', 'ЗИЯННЫҢ ӨТЕМІН ЖАСАУ', 'Ең алдымен, бұл істі тек қорыққандықтан кейінге қалдырмайтынымызға көз жеткізуіміз керек.

Батылдық пен қорықпау — бұл менің салауатты өміріме берілген марапат. Олар маған өзімді қадірлеп, кішіпейілділікпен көмек сұрауға және ары қарай зиянды өтеу күш-қуат береді. Зиянды өтеу үшін шынайылық қажет. Бұл істе Құдайдың көмегімен және өзгелердің даналығына сүйене отырып, жүрегіме терең үңіліп, нақты әрекетке қажетті күш таба аламын. Адамдар менің кешірімімді қабылдауы немесе қабылдамауы мүмкін. Бірақ кешірім сұрағаннан кейін, өзімді еркін сезініп, тек бүгінгі күн үшін жауапты екенімді түсінемін.');
INSERT INTO reflections (day, month, title, text) VALUES (12, 'Сентябрь', 'МЕН ЖАУАПТЫМЫН', 'Тоғызыншы Қадамның мәні — Өткен іс-әрекеттерімізге толық жауапкершілік алып қана қоймай, өзгелердің де амандығы үшін жауапкершілік алуға дайын болу.

АА арқылы сауыққан кезде, өз еркіндігімнен қорқатынымды түсіндім. Бұл қорқыныш кез келген жауапкершілікті алудан туындайды. Себебі, әр істен бас тартып, елемей, өзгелерді кінәлап, қашумен болдым. Кейіннен өткенге көз жүгіртіп, бәрін мойындап және қабылдадым. Шынайы еркіндік - өткенге қарау, мойындау және қабылдаудан тұрады. Бұл жолда: «Иә, мен жауаптымын», - деп айтуға үйренемін. Осы сөзді өзімді алдамай, шын ықыласпен айтпай, еркін бола алмаймын.');
INSERT INTO reflections (day, month, title, text) VALUES (13, 'Сентябрь', 'ЖОҒАЛТҚАН ДҮНИЕЛЕРДІ ҚАЛПЫНА КЕЛТІРУ', 'Ақылмен пайымдау, уақытты дұрыс таңдау, батылдық және ақылдылық — бұл Тоғызыншы Қадамды жүзеге асыру үшін қажет қасиеттер.

Зиянды өтеу екі түрлі болуы мүмкін. Біріншіден, мысалы, мен көршінің қоршауын сындырсам, оны қалпына келтіремін — бұл

«тікелей өтеу». Екіншіден, әрекеттерім біреуге зиян келтіргендіктен,

мінез-құлқымды өзгертіп, болашақта бұл қателіктерді қайталамауға тырысамын. Мен өмір сүру жолымды өзгертемін, бұл жанама өтеу болып табылады. Қай әдіс жақсы? Әлбетте, ешкімге зиян келтірмесе, онда осы әдістің дұрыс болғаны. Қалыптасқан жағдайға байланысты, оқиғаға басқа қырынан қарасақ екеуі де дұрыс. Мен зиян келтірсем, жағдайды түзетуге тырысамын. Бұл — шынайы зиянды өтеу.');
INSERT INTO reflections (day, month, title, text) VALUES (14, 'Сентябрь', 'ЖАН ТЫНЫШТЫҒЫ', 'АА-ның кеңесшісімен немесе рухани жетекшісімен осы мәселені талқылау жөн бе? Әлде, Құдайдан жәрдем сұрап, Оның жетекшілік етуін шын жүректен сұрау керек пе? Бәлкім, өзіміз нені дұрыс деп санасақ сол жаққа қарай бет бұрамыз ба?!

Жоғарғы Күшке сену, Тоғызыншы Қадам бойынша жұмысымның маңызды бөлігі болып табылады. Кешірім, уақытты таңдау және дұрыс ниет осы Қадамның құрамдас бөліктері. Бұл Қадам бойынша жұмыс істеуге дайындық, артып келе жатқан тәжірибемнен туындайды. Бұл тәжірибе маған зиян келтірген адамдармен жаңа және шынайы қарым-қатынасқа есік ашады. Жауапты әрекеттерім Бағдарламаның рухани қағидаларына — сүйіспеншілікке және қызметке жақындатады. Содан кейін жан тыныштығы мен сенім күшейеді.');
INSERT INTO reflections (day, month, title, text) VALUES (15, 'Сентябрь', 'ЖАҢА ӨМІР', 'АА Достастығының көмегімен қара түнек өткенімізді шуақты күндермен алмастыруға болады. Өмірімізге мән дарып, шаттыққа кенелеміз...

Алкогольсіз өмір жақсырақ. АА мен Жоғарғы күш менің сау қалпымды сақтайды, ал, Құдайдың рақымы оны одан да байытады. Қызмет ету арқылы өмірімде мән пайда болады. АА бағдарламасымен танысу, АА-ның не екенін және ол не істейтінін');
INSERT INTO reflections (day, month, title, text) VALUES (16, 'Сентябрь', 'БІЗ БІРЛІКТЕ БОЛМАСАҚ ҚҰЛАЙМЫЗ', '…ерлер мен әйелдердің кез келген Достастығы тұрақты бірлікке мұқтаж. Біз, алкоголиктер, бірге жұмыс істеп, бір-бірімізге сүйеу болмасақ көпшілігіміз жалғыздықтан өлеміз.

АА-ның Он Екі Қадамы да, Он Екі Дәстүрі де белгілі бір реттілікпен жазылғаны кездейсоқ емес. Бірінші Қадам мен Бірінші Дәстүрдің міндеті — аман қалу мүмкіндігін беретіндей мойынсұнуды сіңіру. Олар барлық Қадамдар мен Дәстүрлердің негізін құрайды. Бұл өзін-өзі төмендету амалы жеке тұлға ретінде рухани өсуіме және топтың пайдалы мүшесі бола жүріп, Дәстүрлер арқылы өсуге мүмкіндік береді. Бірінші Дәстүрді толық қабылдау, игілікке зиян келтіретін жеке бас талаптарынан, қорқыныштар мен ашу-ызадан бас тартуға ықпал етеді. Осылайша ол бізді көптің амандығы үшін, басқа алкоголиктермен жұмыс істеуге ықпал етеді. Бірінші Дәстүрсіз топтық жұмыс үшін қажетті бірлікті сақтау мүмкіндігі аз. Онсыз мен қалған Дәстүрлерді, Достастықты және өмірімді жоғалтуым мүмкін.');
INSERT INTO reflections (day, month, title, text) VALUES (17, 'Сентябрь', 'ҚОРҚЫНЫШТАН АРЫЛУ', 'Біз, Құдайдың көмегімен өз тағдырымызды сабырмен қабылдағанымызды түсінген кезде, ішкі қайшылықтан арылдық. Өзгелерге де қорқыныштан арылуға болатынын көрсете алатынымызды түсіндік. Біз, үрейден арылу, өзге де дүниелік қажеттіліктерден маңызды екеніне көзіміз жетті.

Көптеген жылдар бойы белсенді алкоголизм кезеңінде, менің өміріме материалды құндылықтар билік етті. Олардың мені бақытты

ететініне сенімді болдым. Бірақ өзім армандаған дүниелерге иелік етсем де, өзімді жайсыз сезіндім. Алғаш рет АА-ға келгенде, мен басқа өмір салты туралы білдім. Өзгелерге сенуді үйрене отырып, өзімнен  мықты  Күшке  сенуді  бастадым.  Сенім  мені  өзімнің

«менмендігімнің» шынжырынан босатты. Материалдық құндылықтарды рухани құндылықтармен алмастырған сайын, менің өмірім бір ізге түсіп жүйеленді. Ақырында, өз тәжірибемді басқа алкоголиктермен бөлісуді жөн көрдім.');
INSERT INTO reflections (day, month, title, text) VALUES (18, 'Сентябрь', 'СҮЙІСПЕНШІЛІКПЕН САУЫҒУ', '«Өзін-өзі қамтамасыз ету» деген қымбат философиямыздан бас тартуымыз керек болды. Бұл жаңа фактілерді қабылдауға дайын болу мәселесі болғандықтан, әдеттегі ерік-жігерімізбен осы істі жүзеге асыру мүмкін болмады. Біз қашып кетпедік, бірақ күрескен де жоқпыз. Біз қабылдадық. Содан кейін біз еркін болдық.

Бұрынғы мені құл ететін «өзімнен» бос бола аламын. Ақырында өзім де жақсы нәрсе көре алатыныма сендім. Өзімді сүйетін және сауығуға жетелейтін, Жоғарғы Күштің мені қорғап тұрғанын көремін. Менің Жоғарғы Күшім үнемі ғажайып жасайтын сүйіспеншілік пен құдыреттің көзіне айналады. Мен саумын… Сау болғаныма ризамын.');
INSERT INTO reflections (day, month, title, text) VALUES (19, 'Сентябрь', 'ҚАБЫЛДАУ', 'Бойымызда сарқылған қара күшке сеніп, алкогольден бас тарта алмайтынымызды мойындадық. АА тобымыз арқылы тағдырымызды өз түсінігіміздегі Құдайға тапсырдық. Сол Жоғарғы Күш осы уақытқа дейін мүмкін емес болып көрінген істі, істей алатынына имандай сенім білдірдік. Осы фактілерді толық қабылдаған сәттен бастап, біз алкогольге тәуелділіктен арыла бастадық.

Мен ерік-жігерімді және өмірімді өз түсінігімдегі Құдайға тапсырғанда ғана, еркіндікке ие болдым. Қаңыраған қуыс кеудеме Жоғарғы Күшті енгізбей, айналамның бәрі қайнаған өмір екенін сезініп, жан тыныштығына қол жеткізе алмадым. Сол сәттен бастап, Ол Құдырет барлық істе жетекші болып келеді. Жағдайды өзім қалағандай емес, сол қалпында қабылдаған кезде рухани өсіп, жаным жай табады.');
INSERT INTO reflections (day, month, title, text) VALUES (20, 'Сентябрь', 'ЖОҒАРҒЫ КҮШ БАҒЫТТАЙДЫ', 'Құдаймен үнемі шынайы қарым-қатынаста болу керек. Сонда ғажайып орнап, сізден бөлек, жақындарыңыздың өмірінде маңызды оқиғалар болады. Бұл біз үшін Ақиқат.

Бастапқыда Құдаймен дұрыс қарым-қатынас орнату, маған мүмкін емес сияқты көрінді. Менің кінә мен ар азабын арқалаған өткенім «Құдайдың кереметіне» күмән қалдырды. АА-да ерік- жігерімді және өмірімді өз түсінігімдегі Құдайдың құзыретіне беруім керек екені ескертілді. Барар жерім, басар тауым қалмағасын тізерлеп тұрып: «Құдайым, мен бұдан әрі шыдай алмаймын! Маған көмектесші, өтінемін!», - деп жылап жібердім. Мен өз дәрменсіздігімді мойындаған кезде ғана, шыбын жаным нұрға бөленді. Құдайға өз тағдырымды тапсырғанда жүрегімде өмір сүруге деген ниет пайда болды. Артынша Құдайдың қалауымен өмірімде маңызды оқиғалар орын алып, салауатты өмірге қол жеткіздім.');
INSERT INTO reflections (day, month, title, text) VALUES (21, 'Сентябрь', 'СОҢҒЫ УӘДЕ', 'Біз кенеттен, Құдай өзіміз істей алмайтын істі істегенін түсінеміз.

Үлкен Кітаптың Соңғы Уәдесі менің сау кезімдегі алғашқы күні орындалған екен. Сол күні Құдай менің санамды сергек етті. Содан кейін әр күнімді Құдайдың құзыретіне тапсырып отырдым. Өзгелерге назар аударып, олардың сау қалпын сақтап және рухани

өсуіне көмектесуім үшін, Жоғарғы Күш мені бағыттап отырды. Құдай өз қалағанын жүзеге асыру үшін мені себепкер қылады. Нақтырақ айтқанда, Жоғарғы Күш менің ішімде дүмпу жасайды, мен сол дүмпуді сыртқы әлемге жеткіземін. Құдайым өзім көтере алмайтын жүкті мойныма артпайды. Жоғарғы Күш мен арқылы сәтті әрекет ете алуы үшін, әрқашан дайын болуым керек.');
INSERT INTO reflections (day, month, title, text) VALUES (22, 'Сентябрь', 'ҚАЗЫНАЛЫ КЕН ОРНЫ', 'Біз алтын кеніне кезіккен кедей кенші сияқтымыз, біз шексіз үмітсіздік тізбегін жеңгеннен кейін, қуанышымыз шексіз болды. Ол алтыннан да көп дүние тапқанын сезеді. Кейде пейілі тарылып, қазынаның бір бөлігін жасырып қалуға тырысады. Бірақ сарқылмас қазынаны тегін таратқанда ғана, өзіне пайда әкелетінін түсінбейді.

АА-ға жаңадан келген кісімен сөйлескенде, менің өткенім алдымнан шығып тұрады. Үміті әлі сөне қоймаған, қайғы-мұңға толы көздерді көремін. Мен көмек қолын созғанда, ғажайып орын алып, сауығамын. Менің мәселелерім сол дірілдеген жанға, көмек қолын созғанда жоғалады.');
INSERT INTO reflections (day, month, title, text) VALUES (23, 'Сентябрь', 'МЕН ЕРЕКШЕ ЕДІМ...', '[Билл В.] маған жұмсақ әрі тым қарапайым үнмен: «Сіз біздің қатардансыз ба?» - деп сұрады.

Ішімдік ішіп жүрген кезімде, өзімнің ерекшелігіме сенімді едім. Мен өзімді жалпы қабылданған қоғамдық талаптардан жоғары ұстап, қандай жағдай болмасын кешірімге лайықпын деп ойладым. Бұл көзқарастарым өзімді «оқшаулау» екенін түсінбедім. Бастапқыда АА-да өзімді басқалармен тек алкоголик ретінде салыстыратынмын. Кейіннен «адамдар бәрін жақсы істесе, мен де солай істеймін» деген түсінік санамды жаңғыртты! Мен үлкен ғаламның бөлшегі болғаным сияқты, олардың да бас қайғысы мен қуаныштары өмірімнің бір бөлігіне айналды.');
INSERT INTO reflections (day, month, title, text) VALUES (24, 'Сентябрь', 'ҚЫРАҒЫЛЫҚ', 'Біз тағы да «Егер, сіз, алкоголик болсаңыз, мәңгі алкоголик болып қаласыз» деген мәлімдеменің шындығына көз жеткіземіз. Ұзақ уақыт бойы ішімдік ішпегеннен кейін, ішуді бастасақ, біз тез арада бұрынғы қалпымызға қайта ораламыз. Егер ішімдікті тастағыңыз келсе, бұл нақты шешіміңіз болуы тиіс. «Өзгелер сияқты алкогольді қалыпты ішіп үйренемін» деген ойды мүлдем естен шығарыңыз.

Бүгін алкоголикпін. Ертең де өзгерместен сол алкоголик қалпымда қаламын. Алкоголизм менен бір елі ажырамайтын айықпас дертім. Маған ешқашан өзімнің кім екенімді ұмытуға болмайды. Алкоголик екенімді күн сайын мойындап отырмасам, ішімдік менің түбіме жетеді. Бұл өмірдің өткінші сәтсіздіктері емес. Мен емделмейтін және міндетті түрде дәрі қажет ететін науқаспын. Сол себепті күнделікті өз дертімді мойындап, өзіме күтім жасап отырудан басқа амалым жоқ.');
INSERT INTO reflections (day, month, title, text) VALUES (25, 'Сентябрь', 'НЕГІЗГІ МӘСЕЛЕ— БІРІНШІ ОРЫНДА', 'Көпшілігіміз өзіміз үшін қарапайым шындықты түсіндік. Бізде жұмыс бар ма, жоқ па, жұбайымыз бар ма, жоқ па, біз Құдайға емес, адамдарға сенетін болсақ, ішуді жалғастырамыз.

АА-ға келгенге дейін: «Ол айтты...», «Кеше мені жұмыстан шығарды...», «Бүгін мен жұмысымды жақсы орындадым...» деген сынды қырық сылтаумен әрқашан ішімдік ішуге себеп табатынмын. Егер қайтадан ішуді бастасам, менің өмірімнің ешбір саласы жақсы болмайды. Сау қалпымда өмірім күн сайын жақсарады. Сау қалпымды сақтау үшін, әрдайым Құдайға сеніп, АА-ның белсенді мүшесі болуым керек. Бүгінгі таңда ішімдікті Құдайдан және АА- дан жоғары қоя алмаймын.');
INSERT INTO reflections (day, month, title, text) VALUES (26, 'Сентябрь', 'БІЗДІҢ БАЛАЛАРЫМЫЗ', 'Кейде алкоголиктерге балаларымен қарым-қатынасты қалпына келтіру қиынға соғады... Уақыт өте келе олар әкесінің басқа адамға айналғанына көз жеткізіп, таңданыстарын жасыра алмайды... Осы сәттен бастап қарым-қатынастың дамуы жылдам жүреді. Мұндай татуласудан кейінгі нәтижелер таң қалдырады.

Айығу кезеңінде ақшаға сатып ала алмайтын сыйлық алдым. Бұл менің студент ұлымнан келген ашықхат болды, ол: «Әке, бәрі жақсы болғанына сенбеймін. Туған күніңмен! Мен сені жақсы көремін!» - деп жазыпты. Ұлым бұрын да мені жақсы көретінін айтқан болатын. Өткен Рождество мерекесінде ол жылап тұрып:

«Әке, мен сені жақсы көремін! Өзіңе не істеп жатқаныңды көрмейсің бе?» - деді. Бірақ, мен көрмедім.

Ұлымның соңғы хатын алған кезде толқып, көзіме жас алдым.

Бірақ бұл жолы шарасыздықтан емес, қуаныштан жылаған едім.');
INSERT INTO reflections (day, month, title, text) VALUES (27, 'Сентябрь', 'ЕШКАНДАЙ ТАЛҚЫЛАУДЫ ҚАЖЕТ ЕТПЕЙДІ', 'Ризашылыққа толы адамның жүрегі, әр соққысымен сүйіспеншілік сәулесін шашады...

Егер адамдарға қызмет етуім, мені тәкаппарлыққа алып келсе, бұл жағдайдың себебі туралы ойлануым керек. Сүйіспеншілікпен істелген іс ешқандай шартсыз, қайтымын сұрамай істеледі. Себебі рухани өскен сайын, сүйіспеншілікпен қанша берсем, рухани түрде одан да көп шаттыққа кенелетінімді түсінемін.');
INSERT INTO reflections (day, month, title, text) VALUES (28, 'Сентябрь', 'ШАРТСЫЗ СҮЙІСПЕНШІЛІК', 'Тәжірибе көрсеткендей, басқа алкоголиктермен белсенді жұмыс істеу алкогольге қарсы тұрақты иммунитет қалыптастырады.

Кеңес беру, маған екі тосынсый сыйлады. Біріншіден, менің қамқорлығымдағы жандар маған қамқор болды. Олардың маған айтқан «алғысы» сүйіспеншілікке ұқсайды. Олар менің бақытты болуымды, рухани өсуімді және сау болуымды қалады. Олардың маған деген осындай көзқарасы мені талай рет ішуден тоқтатты.

Екіншіден, мен басқа адамға жауапкершілікпен, оның рухани өсуіне шынайы құрметпен қарап, қамқорлық жасауды үйрендім. Бұған дейін «басқа адамның әл-ауқатына шын мәнінде қамқорлық жасау қабілетім жоқ, я болмаса бұл істе тәжірибем болмағандықтан біреуге бас-көз болуға қабілетім жеткіліксіз», - деген ойда болдым. Бағдарламаның ең үлкен сыйлықтарының бірі әлемге қызғанышсыз, қобалжымай сүйіспеншілікпен қарай аламын. Осы ризашылығым көптеген жылдар бойы сау қалпымды сақтайды.');
INSERT INTO reflections (day, month, title, text) VALUES (29, 'Сентябрь', 'БӘРІМІЗ БІРДЕЙМІЗ', 'Жаңадан келгендермен жақын және жиі байланыста болу, біздің өміріміздегі жарқын оқиғаларға айналды.

Жиналысқа бір маскүнем келіп, сөйлеп тұрған адамның сөзін бөліп, орнынан тұрды да, жейдесін шешіп, шу шығарып, шайқалып кофе ішіп, өзіне сөз беруін талап етті. Соңында топ хатшысын боқтап, шығып кетті. Мен оның келгеніне қуаныштымын. Себебі өзімді бұрынғы қалпымда қайта көрдім. Сонымен қатар, өзімнің кім екенімді, сондай-ақ, қандай бола алатынымды да түсіндім. Көптің назарын аударту үшін, жұрттан ерекшеленіп мас болу міндет емес. Бұрын өзгелер менімен қарапайым адам сияқты қарым-қатынас жасаса жиі ренжитінмін. Ақырында теріс қылығыммен айналамдағыларды ренжітіп тынатынмын. Сол маскүнем өзін ерекше көрсетуге тырысқан сайын, оның бізден еш айырмашылығы жоқ, бәріміз бірдей екенімізді түсіндім.');
INSERT INTO reflections (day, month, title, text) VALUES (30, 'Сентябрь', 'ШЕҢБЕР ЖӘНЕ ҮШБҰРЫШ', 'Шеңбер АА-ның бүкіл әлемін, ал үшбұрыш АА-ның үш қағидасын бейнелейді: Саулық, Бірлік, Қызмет. Біздің жаңа керемет әлемімізде, өлімге апаратын құмарлық құрсауынан шықтық.

АА-ға алғаш келгенде қызметпен айналысып, біздің символымыздың түсіндірмесін таптым. Біріншіден, тең қабырғалы үшбұрыш бейнеленген шеңбер - сүйіспеншілік пен қызмет көрсетудің белгісі. Оның негізі Он Екі Қадам бойынша, біздің қалыпқа келуімізді білдіреді. Үшбұрыштың үш қабырғасында Сауығу, Бірлік, Қызмет бейнеленген. Үшбұрыштың үш қабырғасы да тең. АА-дағы рухани дамуымды осы символмен сәйкестендіремін. Мен шеңбермін, ал үшбұрыштың қабырғалары - менің тұлғалық үш қасиетімнің бейнесі. Атап айтқанда: физикалық, эмоционалдық, рухани. Бұл үш ұғым бірігіп, менің сау-саламатты, шаттыққа толы өмірімнің тірегі болмақ.');
INSERT INTO reflections (day, month, title, text) VALUES (1, 'Октябрь', 'ДАҢДАЙСЫП КЕТУДЕН САҚТАНУ', 'Барлық рухани Бағдарламаны тастап, жетістіктерімізге сүйеніп отыру оңай. Егер біз сол жетістіктерімге марқайып, даңдайсып кетсек, алдымызда қиындықтар күтіп тұр. Алкогольдің тым айлакер жау екенін ұмытпайық.

Бір кездері бәрі жақсы болып, жағдайым дұрысталғанда даңдайсып кететінім бар. Ал, кейде мәселені шешудің орнына жалқауланып, кейінге қалдыра беремін. Осындай сәттерде дереу әрекет етіп, өз жағдайымды сыни бағалап, қайда екенімді және қайда бара жатқанымды нақтылауым керек. Күнделікті өзін-өзі талдау жан тыныштығын қалпына келтіру үшін, не өзгерту керектігін айтып отырады. Құдай мен басқа адамдардың алдында жан дүниемнен не тапқанымды айтып, бөлісіп отыруға мүдделімін. Бұл іс адалдығым мен кішіпейілдігімді сақтап қалуға мүмкіндік береді.');
INSERT INTO reflections (day, month, title, text) VALUES (2, 'Октябрь', 'АЩЫ СЫНАҚ', 'Алғашқы Тоғыз Қадам бойынша жұмыс істей отырып, біз жаңа өмірдің оқиғаларына дайындалып жатырмыз. Бірақ, біз, Оныншы Қадамға жетсек, бұл біздің АА принциптері бойынша өмір сүруге дайын болғанымыздың белгісі. Бейнелеп айтқанда ыстық-суығын көтеруге дайын екенімізді көрсетеді. Ауыр сынақтың сәті келеді: біз кез келген жағдайда сау қалпымызды сақтай аламыз ба? Эмоционалды тепе-теңдікті сақтап, мақсатымызды көре аламыз ба?

Мен өз тәжірибемнен АА Уәделерінің орындалатынын білемін. Сол  Уәделердің  көбеюі  үшін,  күн  сайын  Оныншы  Қадамды

қолданамын. Бұл Қадам маған мазасызданған кезімде, жан-дүниемде ақау болатынын көрсетті. Басқа адам да қателесуі мүмкін, бірақ менің міндетім тек өз сезімдеріммен айналысу. Мен ренжігенде немесе қобалжығанда себебін өзімнен іздеп, содан кейін қателіктерімді мойындап, оларды түзетуім керек. Бұл оңай емес. Бірақ рухани өсіп келе жатқанымды білгендіктен, бар күш-жігерімді саламын. Мен азаптануды өзімнің бөлшегім екенін түсіндім. Азаптану бұл тән ауруы сияқты, менің эмоцияларымда ақау бар екенін ескертеді. Мен Он Екі Қадамды орындағанда, ауыртпалық бірте-бірте жоғалатына сенемін.');
INSERT INTO reflections (day, month, title, text) VALUES (3, 'Октябрь', 'ДАУЫЛДАН КЕЙІНГІ ТЫНЫШТЫҚ', 'Бұл тәжірибені бастан өткерген адам, ауыртпалықты рухани өсудің негізгі сынағы деп атады. Біз, АА мүшелері, мұнымен толық келісеміз...

Эмоционалды құйындар менің "шатырымды жұлып" кеткенде, мен рухани өсу ауыртпалық арқылы келетінін жиі еске саламын. АА Бағдарламасында өзімшілдікке қарсы тұрып, қандай ауыртпалықты болса да, ішкі өзгерістерді бастан кешіруім керектігін үйрендім. Егер, жан тыныштығын қаласам, рухани өсуіме ықпал етіп жатқан эмоционалды күйзелістерге төтеп беріп, ризашылық білдіруім керек.');
INSERT INTO reflections (day, month, title, text) VALUES (4, 'Октябрь', 'АРТЫҚ ДҮНИЕДЕН АРЫЛУ', 'Алкоголиктердің жан жарасы сау кезінде де маза бермейді.

Эмоциялық ақаулар жан тыныштығын бұзады.

Мен өзімнің жайқалған гүлдеріме су құйып, артық бұталарын кесіп күтім жасағанды жақсы көремін. Жұмыспен айналысып жатқан кезімде көршім келіп: "Керемет гүлдер, олардың бұталарын кесіп тастау обал емес пе?!" - деді. Мен болсам: "Мен сені түсінемін, бірақ олар бұрынғыдан да жайқалып өсу үшін, артық нәрсені алып тастау

қажет", - деп жауап бердім. Артынша гүлдерім ауыруы мүмкін деп ойладым. Бірақ Құдай да, мен де бұл жоспардың бір бөлігі екенін білеміз. Кейіннен бұл әрекетімнің оң нәтижесін көрдім. Бұл жағдай АА Бағдарламасында бәріміздің ауыртпалық арқылы өскенімізді еске түсірді. Жаныма ауыр тисе де, Құдайдан бойымдағы артық дүниелерді алып тастауын сұраймын. Бұл алдағы уақытта өзімді жайлы сезінуім үшін керек.');
INSERT INTO reflections (day, month, title, text) VALUES (5, 'Октябрь', 'КЕШЕГІ КҮННІҢ ЖҮГІ', 'Күнделікті өзін-өзі талдамай, ізденісінің нәтижелерін мойындап қабылдамайынша, табандылықпен өзінің кемшіліктерін түзетпей, адамның өмірде көп нәрсеге жете алмайтынын ақылды жандар білетін.

Бүгінгі уайымдарымның жүгі аз емес. Сол себепті кешегі күннің жүгін арқалап жүре алмаймын. Егер, ертеңгі тапсырмаларды орындауға мүмкіндік алғым келсе, бүгінгі күннің істерін аяқтауым керек. Осы сәтте: «Мен қай жерде қателестім? Осындай мінез- құлықтан қалай аулақ болуға болады?», - деп өзіме сұрақ қоямын. Біреуді ренжіттім бе? Біреуге көмектестім бе? Бүгінгі күннен ертеңге не өтетін болады? Осы әдіспен күн сайын адалдықпен өз- өзіме талдау жасасам, көп нәрсені алып жүруім қажет болмайды.');
INSERT INTO reflections (day, month, title, text) VALUES (6, 'Октябрь', 'ӨЗІҢМЕН БЕТПЕ-БЕТ КЕЛУ', '...Қорқыныш: «Сен батыл бола алмайсың!», - деп сыбырлайды:

Ішіп жүрген кезімде мәселелерді шешуден қашатынмын. Себебі әр мәселе көзіме өте үлкен болып көрінетін! Сау кезімде де бұл үрейден арылмағанымды аңғардым. Бірақ моральдық бүтінделу аяқталғанда иллюзияның шындықтан үлкенірек екенін түсіндім. Өзімді шынайы көруге деген қорқыныш, мені әрекетсіз қалдырды. Демек, қандай да бір елеске негіздеп, өзімнің рухани өсуімді тежеп

тұрдым. Бұл қағаз бен қалам алуға дайын болғанша жалғасып, көңіл күйім дәптерге түскеннен кейін бәрі ұмыт болды.');
INSERT INTO reflections (day, month, title, text) VALUES (7, 'Октябрь', 'КҮНДЕЛІКТІ БАҚЫЛАУ', 'Өзін-өзі талдауды жалғастыру...

Оныншы Қадамның өзгермес рухани қағидасы: біз бір нәрсеге ренжіген кезде, таяқтың бір ұшы бізге де тиеді. Ақталуға жол жоқ. Өзгелер қаншалықты ақылсыз болса да, теріс реакциям үшін тек мен жауап беремін. Айналамда не болып жатқанына қарамастан, іштегі дүмпуге өзім жауаптымын. Осылайша, өзімнің шынайы шындығымды қалыптастыра аламын.

Күнделікті өзін-өзі талдау барысында, адамдарды айыптауды тоқтатуым керек екенін түсінемін. Егер, оларды айыптасам, өзімді де айыптауға мүдделі боламын. Мені ренжіткен адам, менің ең жақсы ұстазым болып табылады. Бұл жағдайдан менің үйренетінім көп, сол адамға шын жүрегіммен ризашылық білдіруім керек.');
INSERT INTO reflections (day, month, title, text) VALUES (8, 'Октябрь', 'КҮНДЕЛІКТІ ӨЗ-ӨЗІҢДІ ТАЛДАУ', '...қателіктер жібергенде, оны бірден мойындады.

Мен, жаңа салауатты өмірге әдеттен тыс ынтамен жақындадым. Жаңа достар пайда болып, бұзылған бұрынғы қарым-қатынастарды қалпына келтірдім. Өмір қызықты болып, тіпті маған жұмысым ұнай бастады. Кейбір клиенттерімізге жеткілікті назар аударылмай жатқаны туралы баяндама жазуға батылым жетті. Көп ұзамай ешкімге ескертпей, жоғарғы бастыққа жазып жіберген баяндамам бастығыма ұнамай, ренжігенін әріптесімнен естідім. Бұл баяндама бастығымды қиын жағдайға қалдырды. Мәселе баяндамаға байланысты екенін түсініп, өзімді бастығымның қиындықтары үшін жауаптымын деп санадым. Әріптесім: «Бұл жағдай үшін кешірім сұраудың қажеті жоқ», - деп сендіруге тырысты. Көп ұзамай не болса да, бірдеңе істеуім керек деген қорытындыға келдім. Басшыма

барып, жұмыс барысында туынған қиындықтарын өз мойныма алдым. Ол қатты таң қалды. Біздің кездесуіміздің нәтижесі тіптен қызық болды. Күтпеген жерден, біз, болашақта ашық әрі тиімді ынтымақтастық туралы келісімге келдік.');
INSERT INTO reflections (day, month, title, text) VALUES (9, 'Октябрь', 'ӨЗГЕРМЕС РУХАНИ ҚАҒИДА', 'Егер, біз, сыртқы фактордың әсерінсіз, яғни, себептен- себепсіз көңіл-күйіміздің бұзылуы жан дүниемізде ақау бар екенін көрсетеді. Бұл өзгермес рухани қағида.

Мен, Оныншы Қадамның өзгермес рухани қағидасын басымнан бір оқиға өтпейінше түсіне алмадым:

Жатын бөлмеде кітап оқып отырдым. Кеш батып, кенеттен иттерім үре бастады. Олардың үргені көршілерге ұнамайтын. Бойымды ашу, ұят және қорқыныш сезімі билеп, иттерді үйге шақырдым. Біраз уақыттан кейін, бұл жағдай тағы да қайталанды. Бірақ, сол сәтте өзіммен үйлесімде болғандықтан, жағдайды сол қалпында қабылдай алдым. Иттер үргенде оларды жай ғана шақырдым. Осыған ұқсас жағдайда адамдар әр түрлі әрекет ететінін түсіндім. Адамның сезіміне сыртқы жағдайлар емес, ішкі әлемі жауапты екені анық болды. Менің ішкі күйім тербелмесе, қалыптасқан жағдайға дұрыс жауап бере аламын.');
INSERT INTO reflections (day, month, title, text) VALUES (10, 'Октябрь', 'ӨЗГЕНІ ЕМЕС, ӨЗІҢДІ ТӘРБИЕЛЕУ', 'Егер, біреу ренжіткенде. ауыртпалық сезінсеңіз, бұл да кемшілікті көрсетеді.

Бұл сөздерді естігенде бір еркіндік сезіндім! Кенеттен пайда болған өзімнің ашуыма қандай да бір шара қолдана алатынымды түсіндім. Өзгелермен алысқанша, өзімді ретке келтіре аламын. Бұл шешімім ашуланғанда шектен шығып кететін болғандықтан өзге емес, өзім үшін тиімді. Сол себепті шарасыз қалуды білдірмейді. Қандай жағдай болмасын өзімнің тек адам екенімді және қолымнан

келгенді істеп жатқанымды естен шығармауым керек. Сондықтан, Құдайдан мені ашудан арылтып, ыза-кектен алыстатуын сұраймын.');
INSERT INTO reflections (day, month, title, text) VALUES (11, 'Октябрь', 'ӨЗ-ӨЗІҢДІ БАҚЫЛАУДА ҰСТАУ', 'Біз бірінші кезекте өзімізді бақылауда ұстап үйренуіміз керек.

Бұл бізге берілген бірінші тапсырма.

Жұмысқа бара жатқан уақытымды өзімді талдауға арнаймын. Бір күні осындай сапарымда сау жүрген кезеңімді талдап бастадым. Бірақ нәтижесіне қанағаттанбадым. Жұмыс күнінің барысында бұл мазасыз ойларым ұмытылып кетеді деп үміттендім. Бірақ қайғыма қайғы жамалып, ішкі дүмпуім күшейе берді.

Асханаға барып, күннің қалған бөлігін қалай тиімді өткізуге болатынын ойладым. Бұрынғы кездері бір іс мен ойлағандай болмай қалса, инстинкті түрде "шабуылға шығатынмын". Бірақ АА Бағдарламасында болған қысқа уақыт ішінде артқа шегініп, өзіме сырттай қарауды үйрендім. Әлі де өзім қалағандай адам емес екенімді мойындадым. Бірақ бұрынғыдай эмоциямен әрекет етуден арылыппын. Ескі әдеттерім маған да, өзгелерге де опа берген емес.

«Осы күнді пайдалы өткіземін» деген ниетпен жұмыс орныма қайта оралдым. Бүгін рухани өсуіме мүмкіндік берген Құдайыма алғыс білдірдім!');
INSERT INTO reflections (day, month, title, text) VALUES (12, 'Октябрь', 'АСЫҚПА', 'Біз сөйлегенде немесе әрекет еткенде асығыс болсақ, біздің ақыл-ойымыз бен шыдамдылығымыз бірден жоғалады.

Парасатты, шыдамды болуға күн сайын ұмтылуға мүдделімін. Өз түсінігімдегі Құдайдан жақындарыммен және қоршаған ортаның кей жағымсыз қылықтарына сабыр мен шыдам беруін сұраймын. Қатты ашулансам іштен тынуға тырысамын. Орынсыз ашу өзгелерді

де, өзімді де психологиялық күйзеліске түсіретіні анық. Дұға оқу, терең оймен өзін-өзі талдау — бұл парасаттылықтың кілті.');
INSERT INTO reflections (day, month, title, text) VALUES (13, 'Октябрь', 'ӘР ІСТІ БАҒАМДАЙ БІЛУ', 'Менменшілдік, адал болмау, реніш және қорқыныш сияқты қыңыр қылықтардың қайта пайда болмауын қадағалаңыз. Олар пайда болған кезде, Құдайдан оларды жоюды сұрау керек. Бұл мәселені біреумен талқылап, осы жағымсыз мінезден арылуға амал жасаған жөн. Біреуді ренжітсек, дереу кешірім сұрап, татуласуымыз керек. Содан кейін ғана, ойымыз тазарып біреуге көмектесе аламыз.

Дұрыс емес ойларымызды немесе әрекеттерімізді дереу мойындау – көптеген жандар үшін қиын тапсырма. Өзімшілдікке, қорқынышқа және мақтанышқа бейімділген, мен сияқты айығып жатқан алкоголик үшін екі есе қиын болмақ.

АА Бағдарламасының ұсынған еркіндігін қабылдау үшін, өзімнің ойларым мен әрекеттерімді мойындап, жауапкершілік алуға мүдделімін. Сонда ғана мойынсұнудың не екенін тереңнен түсіне аламын. Өз кінәмді мойындауға дайын болуым, рухани өсуіме ықпал етеді. Сондай-ақ, өзгелерді де түсініп, оларға пайдалы болуыма көмектеседі.');
INSERT INTO reflections (day, month, title, text) VALUES (14, 'Октябрь', 'ӨМІРЛІК БАҒДАРЛАМА', 'Біз ұйқыға жатқанда, өткен күнді ойша бағалаймыз... Таңертең оянғанда, алдағы 24 сағат өмірімізді ойлау керек... Күннің басында біз Құдайдан ойларымызды дұрыс бағытқа бағыттап, өзімізге деген аяушылық, адал болмау және ашкөздіктен сақтауды сұраймыз.

Маған жан тыныштығы жетіспеді. Жұмыстар әрқашан мен ойлағаннан көп болып, үлгеру мүмкін емес болып көрінді. Қанша тырыссам да, істейтін ісім көбеймесе, азаймады. Кейіннен, кешегі істелмеген істер мен ертеңгі күнге деген алаңдаушылық тиімді жұмыс істеуіме кедергі келтіргендіктен, берекемді кетіріп, құтымды

қашыратынын түсіндім. Оныншы және Он Бірінші Қадамдарды орындамас бұрын, жоғарыда келтірілген үзінділерді оқып бастадым. Назарымды өзімнің мәселелеріме емес, Құдайдың қалауына аударуға тырыстым. Жаратқанның менің күнімді жүйелеп беретініне сендім. Бұл әрекетім баяу болса да, өз жемісін берді!');
INSERT INTO reflections (day, month, title, text) VALUES (15, 'Октябрь', 'СІЗДІҢ ЕМЕС, МЕНІҢ ТІЗІМІМ', 'Ашу мен ыза-кектің түп тамыры – өсек. Қаңқу сөз кісінің беделін күл-талқан қылып, сыпайы түрде өлтіреді. «Сөз сүйектен өтеді» деген осы. Көп жағдайда, адамдардың өздері сынға алған жандарға көмектесейін деген ниеті болмайды. Жай ғана біреудің беделін түсіру арқылы, өз абыройын көтергісі келеді.

Кейде өсек айтқанымды, тек кеш батып, өзімнің күнделікті іс- әрекеттерімді талдай бастағанда ғана түсінемін. Бұл өсек жап-жақсы өткен күнімді қара түнекпен тұмшалап тастаған болып тұр. Мен қай кезде өсек айтамын?! Өсек, үзіліс кезінде немесе әріптестермен кофе ішкенде өзінің сұрқия жүзін көрсетеді. Жұмыстан кейін, кешкісін біреудің беделін түсіру арқылы, өз абыройымды көтеру үшін өсек айтады екенмін.

Он Екі Қадамды орындап, айығу үшін жұмыс істемесем, осындай өсек айтуым әдетке айналып кетеді екен. Құдай тарапынан маған берілген сый - менің даралығым. Өмірімде кездескен жандар да мен сияқты қайталанбас дара тұлға екенін ұмытпауым керек. Бүгінгі таңда мен істейтін жалғыз іс бар. Ол жеке басымның шаруасы. Басқаларды айыптауды Жоғарғы Сот, яғни, Құдайдың құзыретіне тапсырамын.');
INSERT INTO reflections (day, month, title, text) VALUES (16, 'Октябрь', 'ӘР КҮН САЙЫН', 'Бұл бір күнде болмайды. Бұл өмір бойы жалғасатын міндет.

АА-дағы	алғашқы	жылдарымда,	мен	Оныншы	Қадамды адамдарға  және  жағдайларға  деген  өзімнің  мінез-құлқым  мен

реакциямды тұрақты бақылап отыру үшін, нұсқаулық ретінде қабылдадым. Егер бірдеңе дұрыс болмаса, оны мойындауым керек еді. Кешірім сұрау қажет болса, кешірім сұрадым. Бірнеше жыл саулықтан кейін, өзімді жиі талдауым керек екенін түсіндім. Тек бірнеше жыл сауыққаннан кейін ғана, Оныншы Қадамның толық мағынасын ұқтым. "Жалғастырды" деген сөзді тереңінен түсіне алдым. "Жалғастырды" дегеніміз жиі-жиі деген ұғым емес. Бұл күні бойы, күн сайын дамылсыз әрекет ету дегенді білдіреді.');
INSERT INTO reflections (day, month, title, text) VALUES (17, 'Октябрь', 'КҮНДЕЛІКТІ СҰРАУ', 'Күн сайын біз өз әрекеттерімізге Құдайдың қалауын енгізуіміз керек.

Өзімнің рухани жағдайымды қалай жетілдіремін? Мен үшін бұл оңай: таңертең Жоғарғы Күшімнен алдағы күнге саулық сыйлауын сұраймын! Қайтадан ішіп кеткен көптеген алкоголиктермен сөйлесіп: "Сіз бірінші стақан ішкен күні, сау қалпыңызды сақтау үшін дұға еттіңіз бе?", - деп сұрадым. Олардың ешқайсысы "иә" деп жауап бермеді. Оныншы Қадамды орындап, күн сайын санамдағы "үйімді" таза ұстауға тырысамын. Жаратқаннан ішімдік ішуді бір күндік кешіктіруін сұрасам, тілегім орындалатынын білемін!');
INSERT INTO reflections (day, month, title, text) VALUES (18, 'Октябрь', 'ЖАҢА ҚАТЫНАС', 'Шынайы мойынсыну мен бейтарап ойлар бізді сенімге әкеледі

Менің алкогольдік ойлауым спирттік ішімдікті басқара алатыныма сендірді. Бірақ олай болмай шықты. Мен АА-ға келгенде, топ арқылы Құдай менімен тілдесетінін түсіндім. Менің санам Жаратқанның көмегіне мұқтаж болғандықтан, айтылған барлық пікірге ашық болды. АА-ны шынайы, адал қабылдауым үшін көп уақытым кетті. Бірақ сол аралықта мойынсұнуды үйрендім. Қазір қаншалықты ессіз болғанымды білемін. Маған қайтарылған ақылым, сау алкоголик екенімді түсінуге мүмкіндік берді. Сол үшін

шексіз ризамын. Бүгін АА-сыз өмір сүрген күніме қарағанда әлдеқайда жақсымын! Себебі, жаңа өмір бастадым, саумын!');
INSERT INTO reflections (day, month, title, text) VALUES (19, 'Октябрь', 'АА-НЫҢ "НЕГІЗГІ ТАМЫРЫ', 'Біз алкоголь алдында толық жеңілісімізді мойындамайынша, ешқандай сенімді тірек таба алмаймыз. Бұл қағида біздің Достастықтың тамыр жайып, гүлденуіне ықпал етеді.

Мен, АА-ның есігін алғаш ашқан кезде қаңыраған, бейне бір қираған күйде келдім. Жалғыз болғандықтан, алдымдағы белгісіздіктен қорықтым. Қандай да бір Тылсым Күш орнымнан тұрғызып, АА кеңсесіне телефон шалуға үндеді. Содан кейін, сол Тылсым автобус аялдамасына жетелеп, АА-ның есігіне алып келді. АА-ға кіре сала, жүзі жылы жандарды көріп, мені ыстық ықыласпен қабылдайтынын сездім. Бұл менің балалық шақтан бері сезінбеген сезімім еді. Алғашқы кеште АА-да сезінген қуанышты әсерімнен ешқашан айрылғым келмейді.');
INSERT INTO reflections (day, month, title, text) VALUES (20, 'Октябрь', 'САБЫР САҚТАП, ЖАЙЛЫЛЫҚТЫ СЕЗІНУ', 'Сенімнен алыстаған адам қатты қобалжуда болатыны анық. Ол:

«...енді ешқашан бойыма сенім дарыта алмаймын», - деп ойлайды. Дүниеден күдер үзгені соншалық, үмітсіздікке салынып тек абдыраумен болады.

АА-да болған алғашқы жылдарымда Құдай ұғымымен күрестім. Санамдағы өткен күннен қалған үрейден, өзімді айыптау сынды дүрбелеңдерден айырылуым қиын болды. Содан кейін досым Эд Жоғарғы Күш туралы түсінігін айтты. Досыма бала кезінде күшік бағуға рұқсат беріпті. Бірақ тек күшіктің уақытылы тамағын беріп, жуындырып отыру керек болған. Бастапқыда әр таң сайын күшіктің нәжістерін көріп, ашуланғанын айтты. Кейіннен "бұл күшіктің табиғаты" екенін түсініп, ренжуін қойған. Біз, күшіктерді итке тән кемшіліктерімен қабылдап, қамқор болсақ, Құдай да біздің адамға

тән кемшіліктерімізге түсіністікпен қарап, жылулықпен қарайтынын ескертті. Бір нәрсеге ашулансам, Эдтің Құдай туралы айтқан сөзін есіме алып, жаныма жұбаныш табамын.');
INSERT INTO reflections (day, month, title, text) VALUES (21, 'Октябрь', 'ҚАРАҢҒЫДА ЕШТЕҢЕ ӨСПЕЙДІ', 'Біз қандай қиын жағдайда болсақ та, бойымыздағы жақсы қасиеттеріміздің дамуына мүмкіндік беруіміз керек.

Оныншы Қадамның тәжірибесінен алған терең түсінігімнің арқасында, салауатты өмірдің артықшылықтарын түсіне бастаймын. Оныншы Қадамның нәтижесінде, тек алкогольден бас тартып қана қоймай, өмірімнің барлық салаларын ретке келтіре алдым.

Үміт пен сенімім жаңарып, бір заманда жоғалтқан қадірімді қайтара алдым. «Тағы...» дейтін түсінік бар. «... тағы қателік жасасақ, оны бірден мойындауға мүдделіміз».

Адам болғасын қателесетінімді түсінгеннен кейін, өзімді көптің бірі ретінде қабылдап, саулық пен жан тыныштығының кереметін сезіне аламын.');
INSERT INTO reflections (day, month, title, text) VALUES (22, 'Октябрь', 'ШЫНАЙЫ ТӨЗІМДІЛІК', 'Біз өзімізден бөлек, өзгелердің де эмоционалды тұрғыдан тұрақсыз болғандықтан жиі қателесетіні анық. Осы түсініктің арқасында біз шынайы төзімділікті және адамдарға деген шынайы сүйіспеншіліктің мәнін түсінеміз.

Барлық адамдар белгілі бір дәрежеде эмоционалды ауру екенін түсіндім. Басқаша қалай болуы мүмкін? Арамызда кім рухани мінсіз? Ал эмоциялық тұрғыдан кім мықты? Ал физикалық тұрғыдан ше? Сол себепті бір-біріміздің кей әрекеттерімізге шыдамды болып, түсіністікпен қараудан басқа амал жоқ. Бұл шынайы сүйіспеншіліктің белгісі.');
INSERT INTO reflections (day, month, title, text) VALUES (23, 'Октябрь', 'БІЗ НЕНІ ЖАҚСЫ БІЛЕМІЗ...', '«Егер, сен, етікші болсаң, өміріңнің соңына дейін етікші болып қал!»... Әр істің басын бір шалғаннан, бір істің шебері болған жөн. Бұл Дәстүрдің негізгі тақырыбы. Осының арқасында біздің Достастығымыздың бірлігі қалыптасады. АА-ның өміршеңдігі тікелей осы қағидаға байланысты.

АА-ның өміршеңдігі бірлікке байланысты. Егер топ жұмысқа орналастыру бюросы, емдеу орталығы немесе әлеуметтік көмек агенттігі болса жағдай қалай болмақ?! Мамандандырылған көп саланы қамту күш-жігерді шашыратып, құлдырауға әкеледі. Мен өз тәжірибеммен, айығу әдістерімен бөлісуді үйрендім. АА-ның негізгі мақсатына адал болу саулықтың керемет сыйлығын жоғалтпауды қамтамасыз етеді. Сол себепті менің үлкен жауапкершілігім бар. Миллиондаған алкоголиктердің өмірі, «әлі де зардап шегетін алкоголикке біздің идеяларымыздың мәнін жеткізу қабілетімізбен» тығыз байланысты. Бізге жүктелген негізгі міндет осы!');
INSERT INTO reflections (day, month, title, text) VALUES (24, 'Октябрь', 'СЕНІММЕН ЖҰМЫС ІСТЕ', 'Достастықтың құрылымы тәжірибемен қалыптасты... Сенім мен әрекет көп тәжірибе жинақтауымызға негіз болды. Біздің тәжірибеміз Анонимді Алкоголиктердің Он Екі Дәстүрінде өміршеңдігін жалғастырады. Сондай-ақ, Құдайдың қалауымен бірлігімізді сақтайтын болады.

Құдай маған Достастығымыздың қазіргі күйінде сақталып қалуы үшін, қателік жасауға мүмкіндік берді. Егер, Құдайдың қалауын бірінші орынға қоятын болсам, АА болашақта да дәл осы қалпында, өзгеріссіз қалады.');
INSERT INTO reflections (day, month, title, text) VALUES (25, 'Октябрь', 'АА-НЫҢ ӨМІРШЕҢДІГІ', 'Бірлік болмаса, АА жұмысын тоқтатады...

Бірлік болмаса АА-да сауыға алмаймын. АА-ның басқа мүшелерімен және Достастықтың барлық деңгейінде бірлік қағидасын ұстандым. Осы істің нәтижесінде, Құдайдың қалауымен жасалған ғажайыптың бір бөлігі екенімді нақты түсінемін. Билл У. мен доктор Бобтың бірлесіп жұмыс істеп қалдырған рухани мұрасы: АА-дан тегін алғаныңды, тегін беріп, өзімізбен қатар, өзгелерді сақтап қаламыз. Бірлік – бұл бірлік, ал Достастық бәрімізге ортақ дүние!');
INSERT INTO reflections (day, month, title, text) VALUES (26, 'Октябрь', 'БІР ҒАНА ЖОҒАРЫ БЕДЕЛ ИЕСІ БАР', 'Біздің топтың ісінде мейірімді Құдайдан басқа жоғары билік жоқ. Оның құдыреті біздің топтық сана-сезімімізде көрініс табады.

АА-да кішкентай міндеттер мойныма жүктелгенде, Құдайдан шыдамдылық, бейтараптықпен қатар, адалдығымды сақтауын сұраймын. Өзімді «басшы», «мұғалім» немесе «нұсқаушы» сезініп кетпей, тек сенім білдірген орындаушы екенімді есте сақтауым керек. Құдай менің сөздерім мен әрекеттерімді бағыттап отырады. Ал, мен Оның ұсыныстарын орындауға жауаптымын. Сенім — менің ұраным. Мен басшылық етушілерге сенемін. Біздің Достастығымызда барлық билік, ең жоғарғы билік те Құдайдың құзыретінде!');
INSERT INTO reflections (day, month, title, text) VALUES (27, 'Октябрь', 'БҮКІЛ ӘЛЕММЕН БӨЛІСУ', 'Салауатты өмірдің кілтін өзі тауып келген алкоголик қашан да маңызды болмақ. Ондай жандар Достастыққа тез сіңіскендіктен, оларға өз тәжірибеңмен бөлісіп, айығу әдістерін ұсыну оңай. Мұндай қарым-қатынас Тәңірдің бізге берген сыйы болмақ. Ал,

әлемдегі барлық АА топтарының мақсаты - салауатты өмір идеясын насихаттау.

АА-ның күші, әлемнің кез-келген бұрышындағы әрбір мүшесінің өз тәжірибесімен қатар, қолдау Қадамдарын басқа алкоголиктермен бөлісуге деген ниетінде жатыр. Сол себепті, АА- ның әр мүшесі маңызды рөл атқарады. Жоғарғы Күшпен саналы байланыста бола отырып, басқаларға көмектесуге деген ниетімді жүзеге асыруға күшім жететініне сенімдімін. Бұл әрекетім АА-ның ғажайып Достастығының тізбегін үзбеуге септігін тигізеді.');
INSERT INTO reflections (day, month, title, text) VALUES (28, 'Октябрь', 'БҰЗЫЛМАҒАН ДӘСТҮР', 'Біз, Достастықты сақтауды және оның қызметін кеңейтуге топ болып үлес қоса аламыз. Әр алкоголиктің аман қалуы біз үшін маңызды.

Бұзылмаған Дәстүр, мені Билл У. мен доктор Бобпен сан жылдардан бері көрінбейтін жіп арқылы байланыстырып тұр! Тұрақтылығымды жоғалтпас үшін, Достастықтан бір елі ажырағым келмейді. АА энергиясының шашырамай, Достастық мүшелерінің әрқайсысының саулығына тікелей бағытталғанына ризамын.

Мені адам ететін дүние - менің сенімдерім. Мен өз пікіріме ие болуға құқығым бар. Бірақ көп жыл бұрын тұжырымдалған АА-ның мақсаты менің сау қалпымды сақтаудан тұрады. Осы мақсатқа жету үшін, тәулік бойы кездесулер өтті. Мыңдаған еріктілер, мыңдаған кеңселер жұмыс істеді. АА-ның күллі әлемдік топтық жұмысы менен бөлек, миллиондаған жүректерге сенім сыйлап, үміт отын жақты. АА-ның бұл Дәстүрі сан жылдар бойы бұзылмай келе жатыр, әлі де жалғасын табатынына сенім мол.');
INSERT INTO reflections (day, month, title, text) VALUES (29, 'Октябрь', 'ТІРШІЛІК ҮШІН КҮРЕС', 'Алкоголизмнен құтылу тірі қалуымыз үшін маңызды болғандықтан, АА дейтін өмір сүру құралымызды бабында ұстау маңызды.

АА мүшелері кездесулерде көрсететін адалдық, менің жүрегіме сенім ұялатады. Адалдық ағынынан келетін энергияны ешнәрсе тоқтата алмайды. Бұл ағынға тек мас болып қана кедергі жасауға болады. Тіпті, сол кездің өзінде есік қаққан кісіге АА-ның есігі ашық. Саулық сыйын алған кезден бастап, әрбір АА мүшесі күн сайын адалдық Бағдарламасын қабылдау қажеттілігімен бетпе-бет келеді. Жоғарғы Күш, мені өмірдегі қандай да бір мақсат үшін жаратты. Мен, сол Тылсым Күштен рухани жолмен саяхатымды жалғастыру үшін адалдықпен қатар, күш-жігер сұраймын. Жаратқанның үнін жүрекпен естіп, қалауын түсіну үшін дұға етемін.');
INSERT INTO reflections (day, month, title, text) VALUES (30, 'Октябрь', 'ӨЗІҢ ӨМІР СҮР ЖӘНЕ БАСҚАЛАРҒА ДА ӨМІР СҮРУГЕ МҮМКІНДІК БЕР', 'АА негізі қаланғаннан бері бірде-бір даулы мәселелер орын алып, ұйым жікке бөлінбеді. Біздің Достастық ешқашан соғысып жатқан екі тараптың біреуіне болысқан емес. Бұл саудаға салынған ізгілік емес. Біздің Достағымыздың осы ізгілік қасиетпен дүниеге келгенін айтуға болады... «Біз бұл дауларды жеке талқыламағандықтан, көпшілік алдында да талқыламайтынымыз сөзсіз».

Менің өз пікіріме құқығым бар екені сөзсіз. Бірақ басқалардың менің пікіріммен келіспеуге құқығы бар екенін білемін бе?! Бұл "Өзің өмір сүр және басқаларға да өмір сүруге мүмкіндік бер" ұранының рухани мәні. Ақыл-ой дұғасы «өзгерте алмайтын нәрсені қабылдауым» керек екенінімді еске салады. Мен, әлі де басқаларды өзгертуге тырысып жүрмін бе? «Өзгерте алатын дүниелерге» келетін болсақ, әр тараптар өз көзқарастарында қалатынын түсіне аламын

ба? Мен әлі де өзіммен-өзім болудан қорқамын ба? «Бір-бірінен ажырату даналығына» қатысты айтатын болсақ, менің көзқарастарым, менің тәжірибемнен туындайтынын ескерем бе? Мен бір іске өз көзқарасыма сүйеніп, қарсылық білдіргенде өзімді бәрін білуші Құдырет ретінде сезініп жүрген жоқпын ба?!');
INSERT INTO reflections (day, month, title, text) VALUES (31, 'Октябрь', 'БАҚТАЛАСУДАН АЛЫС БОЛУ', 'Тарих беттеріне үңілсек, бәсекелес ұлттар мен күрескен топтардың мысалдары жеткілікті. Түбінде бақталасудың соңы жақсылыққа апармай ыдырап кетті. Адамдардың бір бөлігі өздерінің ерекше түсінігіндегі "алтын ғасырды" адамзаттың қалған бөлігіне жүктеуге тырысқан кезде, бәрі құрдымға кеткен.

АА мүшесі және тәлімгер ретінде, мен, медициналық, материалдық немесе діни мәселелер бойынша біреуге кеңес беруге тырыссам, Достастыққа зиян келтіретінімді білемін. Мен дәрігер де, кеңесші де, адвокат та емеспін. Мен ешкімге қалай өмір сүру керектігін айтпауым керек. Дегенмен, алкогольсіз өмірім туралы тәжірибеммен, сондай-ақ, АА Қадамдары мен Дәстүрлері қалай көмектесетіндігі жайлы бөлісе аламын.');
INSERT INTO reflections (day, month, title, text) VALUES (1, 'Ноябрь', 'ЖЕЛДІҢ БАҒЫТЫН ӨЗГЕРТЕ АЛМАЙМЫН', 'Бүкіл рухани Бағдарламаны бір жаққа қойсақ жағада қалуымыз оңай. Алкогольдің сұрқия дұшпан екенін ескерсек, бұл жағдайда бізге қауіп төнеді.

Менің алғашқы тәлімгерім дұға мен терең ой жүгірту туралы мынаны есте сақтау керек екенін айтты: біріншіден, бастау керек, екіншіден, жалғастыру керек. Мен, АА-ға рухани дағдарысқа ұшырап келдім. Мен бір істі бастауға ерік-жігерім жетпегенде, бойымды үрей билегенде ғана Құдайдан жәрдем сұрайды екенмін.

Бүгінде жаңа өміріме ризамын. Бұл айтқаным алғыс дұғалары. Дұға еткенде, сөйлегенімнен тыңдағаным көп. Бүгін, мен жел бағытын өзгерте алмасам да, желкенді дұрыс бағыттай аламын. Ырым мен руханияттың айырмашылығын білемін. Ақиқаттың жолы сүйіспеншілік, ал қалған жолдардың жалған екенін түсінемін.');
INSERT INTO reflections (day, month, title, text) VALUES (2, 'Ноябрь', 'ЖАҚСЫЛЫҚТАН ҮМІТТІ БОЛУ', 'Басқа Қадамдар бізге сау қалпымызды сақтауға және өз-өзімізді ұстауға көмектеседі. Ал, Он бірінші Қадам бізді рухани өсіреді...

Сауыққан алкоголикке өмірге деген құлшынысын сақтау әлдеқайда жеңіл. Әр жағдайдан жаманшылықты емес, жақсылықты көре алады. Физикалық саулығым жалғасып келе жатқанда, мен тұманнан шығып, нақты қай бағытқа қарай қозғалу керек екенін жақсы түсінемін. Бірақ физикалық саулықтан кем емес, мен үшін үлкен рухани әлеуетке жету маңызды. Ал, бұл Жоғары Күштің сәулесі көкірек көзіме түскенде жүзеге асады. Ол үшін АА Бағдарламасының қағидаларын зерттеп, іс жүзінде қолдануым керек. Физикалық және рухани саулықтың үйлесімі, өмірге деген көзқарасымды оң бағытқа бұрады.');
INSERT INTO reflections (day, month, title, text) VALUES (3, 'Ноябрь', 'ЗЕЙІНДІ БОЛУ ЖӘНЕ ТЫҢДАУ', 'Өзін-өзі талдау, медитация және дұға арасында тікелей байланыс бар. Жеке-жеке алғанда, олар адамға көп пайдасын тигізіп, жеңілдік әкеледі.

Егер, мен, алдымен өзімді-өзім талдаумен айналыссам, артынша дұға оқып, ой-толғау жасап мойынсұнуға ие боламын. Осы әдісті өзім құп көремін. Кейбіреулер дұғадан бастап, бәрін аяқтай салады. Ал, өзін-өзі талдау мен медитация сол күйі қалып қояды. Енді бірі жасырын немесе әлі белгісіз кемшіліктері туралы Құдайдан кеңес естуге ұмтылып, терең ой-толғаудан бастайды. Басқалары ауызша немесе жазбаша түрде өздерінің кемшіліктерімен жұмыс істеп, алғыс дұғасымен аяқтайды. Бұл үш ұғым: өзін-өзі талдау, ой-толғау және дұға — басы мен соңы жоқ шеңберді құрайды. Қай жерде және қалай бастайтыныма қарамастан, ақырында ең жақсы өмірге қол жеткізуге мүмкіндік береді.');
INSERT INTO reflections (day, month, title, text) VALUES (4, 'Ноябрь', 'КҮНДЕЛІКТІ ТӘРТІП', '...олар логикалық түрде байланысқанда (өзін-өзі талдау, ой- толғау және дұға) адам өмірінің берік негізін құрайды.

Бағдарламаның соңғы үш қадамы мейірімді Құдайдың көмегімен, менің өзімшіл табиғатымды ұстап тұрады. Егер, кешке күні бойы болған негізгі оқиғаларды қарауға бірнеше минут бөлсем, олардың ең жағымсыз қырларын атап өтіп мойындасам, өзімнің жеке тарихымды жинақтаймын. Бұл өзіңді тану үшін өте маңызды. Осы әдіс арқылы рухани өскенімді немесе өспегенімді анықтай аламын. Жаратқаннан жанды жегідей жеп жатқан азаптан арылтуын сұраймын. Медитация мен дұғаның арқасында әр іске зейінім ашылып, тыңдап үйрендім. Құдайдың қалауы мен жетекшілігін сұрап дұға еткенде, күндіз құмарлықтан арылып, жан тыныштығын сезінемін. Құдайдан жетілуге деген ұмтылысыма көмектесуін сұрағанымда, өмірге жаңаша қарауға мүмкіндік аламын. Жақсы

атқарылған жұмыс құрметке лайық болса керек. Күнделікті дұға және ой-толғау жүйкемнің саулығын қамтамасыз етеді. Ішімдікке деген құмарлықтан арылтып, жақсы көңіл-күйде болуға мүмкіндік береді.');
INSERT INTO reflections (day, month, title, text) VALUES (5, 'Ноябрь', 'СЕНІМ САПАСЫ', 'Мәселе сенім сапасында... Егер жалпы өлшеммен өлшейтін болсақ, біз өзіміздің ақыл-ой қасиеттерімізге ешқашан байыпты және терең сыни баға беруді қолға алмағанбыз... Біз дұға ете алмайтынбыз. Біз әрқашан: «Сенің қалауың болсын» деудің орнына,

«Менің қалауымды орында» дейтінбіз.

Құдай материалдық игіліктерді беріп, мені азап пен қиыншылықтан құтқармайды. Есесіне жан тыныштығы мен өмірдің қиыншылықтарымен күресе алатын қабілет береді. Менің дұғаларым қарапайым. Бірінші, қандай қиын жағдайда болсам да, өмірімдегі барлық игіліктер үшін алғыс айтамын. Екінші, Құдайдың қалауын орындау үшін, күш-қуат пен даналық сұраймын. Жоғарғы Күш қиындықтарымды жеңілдету арқылы жауап беріп, әр күнді сабырмен өткізуіме күш-қуат береді. АА қағидаларын күнделікті істерде қолдану, ерік-жігерімді күшейтіп, еңсемді тіктейді.');
INSERT INTO reflections (day, month, title, text) VALUES (6, 'Ноябрь', 'АҒЫСҚА ҚАРСЫ', 'Өз түсінігіміздегі Құдаймен қарым-қатынасты тереңдетуге дұғаның күшімен және ой-толғау арқылы ұмтылдық...

Таңертең айтатын алғашқы сөздерім: «Құдайым, сенің қалауыңды орындау үшін ұйқымнан ояндым». Бұл мен білетін ең қысқа дұға. Бұл менің санам мен жанымда терең таңбаланған. Дұға Құдайдың маған деген көзқарасын өзгертпейді, керісінше менің Құдайға деген көзқарасымды өзгертеді. Ой-толғаудың дұғадан айырмашылығы — бұл үнсіздік уақыты. Зейінді болу дегеніміз —

физикалық шиеленісті жойып, эмоционалды тұрақтылықты сақтау арқылы, жан тыныштығына қол жеткізу.

Құдаймен саналы байланысты сақтап, оны жақсартудың бірден бір жолы – Оған деген ризашылық пен шүкірлік сезімін жоғалтпау. Мен ризамын, менің өмірімде көптеген жақсылықтар болады. Жақсылықтың ағынын Құдай емес, менің жағымсыз көзқарасым бөгейді.');
INSERT INTO reflections (day, month, title, text) VALUES (7, 'Ноябрь', 'БӘРІН БІР ҚҰДАЙҒА ТАПСЫРУ', '...Құдайдың қалауы туралы білгеннен кейін, оны орындауға күш-қуат сұрап дұға етеміз.

«Бәрін бір Құдайға сеніп тапсырғанда» әр ойым айқындалып, кемелдене түсемін. Уайымдатқан мәселеден назарымды аударсам, шартты түрде ауыртпалық пен жайсыздықтан арыламын. Өз күшіммен азаптайтын ойлар мен сезімдерден «арылу» қиын. Сол себепті Құдайдан бұл жағымсыз әсерден арылтуын сұраймын. Содан кейін алаңдатарлық ойлар, қолайсыз сезімдер мен қара түнек естеліктер мазалауын қояды. Құдайдың қолдауымен кез келген мәселенің күн сайын шешімін тауып келемін. Сондай-ақ, алкогольді жеңіп, сау қалпымда бақытты да, баянды өмір сүре аламын.');
INSERT INTO reflections (day, month, title, text) VALUES (8, 'Ноябрь', 'ҒАЖАЙЫП САЯХАТ', 'Медитация өнері әрқашан жақсаруы мүмкін. Оның көлемінде ешқандай шектеулер жоқ. Осындай нұсқаудан кейін... медитация — бұл белгісіз жерге жеке саяхат, оны әрқайсымыз өзіміз жасайтынымыз түсінікті болады.

Рухани тұрғыдан алғанда, Құдайдың көмегімен шарықтап, бір ғажайып әлемге жайғасамын. Күнделікті ой-толғау мен дұға, менің әл-ауқатымның қайнар көзін нығайтып, жаңартады. Кейіннен, Құдай ұсынатын барлық дүниені қабылдауға дайын боламын. Өзімнің ғажайып  саяхатым  Құдай  қалағандай  болатынына  сенімдімін.

Әрдайым мейірімнен кенде қылмайтын бір Құдайдың барына шүкірлік етемін!');
INSERT INTO reflections (day, month, title, text) VALUES (9, 'Ноябрь', 'РУХАНИ СӘУЛЕГЕ ҰМТЫЛУ', 'Ештеңе қараңғыда өсе алмағандықтан, бізге әуелі күн сәулесі керек. Терең ой-толғау бізді күн сәулесіне алып барады.

Кейде ой-толғауға және дұға етуге уақытым жоқ деп ойлаймын. Бірақ кезінде ішімдік ішуге әрқашан уақыт тапқанымды ұмытып кетемін. Шын ниеттенсем, кез келген іске уақыт табуға болады. Күнімді жоспарлағанда, күнделікті дұғалар мен медитацияларға уақыт бөлу керек. Таңертең Достастықтың кітаптарынан бір бет оқып, кешке жатарда: «Рақмет саған, Құдайым!» деп айтамын. Дұға оқу әдетке айналған кезде, тығыз жұмыс күніме қарамастан сыйынуға көбірек уақыт бөлемін. Маған дұға қылу қиын болса, жай ғана «Біздің Жаратушымыз» деген сөзді қайталаймын. Тым қысқа болса да, бұл дұға шынымен де бәрін қамтиды. Кейіннен, өмірімде бар игіліктердің тізімін жасап, Жаратқанға алғыс айтамын.

Маған дұға қылу үшін арнайы орынның қажеті жоқ. У-шудан ойша алыстап, адам толы бөлмеде де дұға оқи беремін. Дұға оқи берген сайын, маған арнайы бір сөздерді айтудың қажеті жоқ екенін түсінемін. Себебі Жаратушым менің ойымды оқып, жүрегімнің үнін естиді.');
INSERT INTO reflections (day, month, title, text) VALUES (10, 'Ноябрь', 'ҒАЛАМНЫҢ БӨЛШЕГІ ЕКЕНІҢДІ СЕЗІНУ', 'Біздің дұғаларымыз бен медитацияларымыз үшін берілетін ең үлкен сыйлардың бірі, бәлкім, бұл үлкен істің бөлшегі болу.

Терең ой-толғаудан кейін мені шаттыққа бөлейтін сезім өзгелермен қарым-қатынас жасау, достастық сезімі екенін түсіндім. Себебі тұйықталмай, әрдайым қарым-қатынаста болсам өзімді жеңіл, еркін сезінеді екенмін. Яғни, үлкен іске араласып, ғаламның бір бөлшегі  болғаныма  шаттанамын.  Жан  дүниемдегі  ішкі

қайшылықтарды жоюға дайын екенімді түсіндім. Өзімнің әзілкештігімді жақсы көремін. Күн сайын Құдайдың әлеміндегі шығармашылық ағынға қосылу үшін ұмтыламын. АА өмір салтына дұға мен медитацияның тікелей енуі бәріміз үшін өте пайдалы.');
INSERT INTO reflections (day, month, title, text) VALUES (11, 'Ноябрь', 'ӨЗ-ӨЗІҢДІ ҚАБЫЛДАУ', 'Құдайдың бізге сүйіспеншілікпен қарайтынын жүрегіміз сезеді. Әрқашан біз Жаратқанға жүгінгенде, бәрі жақсы болатынын білеміз...

Мен, Құдайдың адам кейпінде жаратқан қасиетті де, ерекше тіршілік иесімін. Сол себепті менің міндетім — өзімді тану, қадірлеу, тәрбиелеу. Осы ізгі мақсатты естен шығармас үшін дұға етемін. Өзімді бәз қалпымда қабылдай алсам, Құдайдың да қалауын қабылдаймын. Демек, өзімді танып, құрметтеу арқылы, Құдайды да танып, құрмет көрсете аламын. Өзімді тәрбиелеуім, Құдайдың қалауын орындағаным.

Тәкаппарлықтан, өзімді қатаң сынаудан арылу үшін дұға етемін, бұл Құдайды шын ықыласпен ұлықтауыма мүмкіндік береді. Ақырында, өзімнің қазіргі хәліме мойынсұнып, рухани серпін жасаймын.');
INSERT INTO reflections (day, month, title, text) VALUES (12, 'Ноябрь', 'ТАҢҒЫ ОЙЛАР', 'Жаратушыдан таңертеңгі ой-толғауда: «әлі ауырып жүрген жандарға тағы не істей аламын?» деп сұраңыз...

Көптеген жылдар бойы: «Құдайдың маған деген қалауы қандай екен?!» деген ойда болдым. Маңдайыма «ұлы тағдыр» жазылған деп сенген кездерім де болды. Негізінде, белгілі бір діни-сенім ұстанатын отбасында дүниеге келдім. Сол себепті: «Сен таңдаулысың» деген сөзді естіп өскенім рас. Кейіннен бұл сөздің астарына үңіле келе, Құдайдың маған жүктеген міндетін таптым. Маған жүктелген міндет қарапайым. Күнделікті Он Екінші Қадам

бойынша жұмыс істесем болғаны. Бұл істі өз күшіммен, бойымда бар қабылетіммен атқаруым керектігін түсіндім. Көп ұзамай осы іс- тәжірибе әр күннің қызықты сәттерінен қалыс қалмай, белсенді болуыма көмектескен жайы бар.');
INSERT INTO reflections (day, month, title, text) VALUES (13, 'Ноябрь', 'ӨЗІМШІЛДІГІМНЕН АЛЫСТАУ', 'Біз Жаратқаннан өзіміз үшін ештеңе сұрамау керектігін білеміз. Егер бұл басқаларға пайда әкелетін болса, біз өзіміз үшін бірдеңе сұрауға мүмкіндігіміз бар. Біз өзіміздің эгоистік мақсаттарымызды орындау үшін, ешқашан дұға етпейміз.

Белсенді алкоголик ретінде өзімшілдіктің өмірімде кең таралуына жол бердім. Мен ішімдікке және өзімшіл әдеттерге берілгендіктен, адамдардың көңілі мен моральдық принциптер әрқашан екінші орында болатын. Қазір оқыған дұғама «өзімшілдік мүдделерімді» емес, басқалардың әл-ауқатын қосамын. Осы арқылы бауырластарыма қамқорлық жасап, өзімшілдіктен бас тартуды үйреніп жатырмын. Барлық пендешілік қасиеттерден арылуға дайындық үстіндемін. Сонда ғана өзгеден емес, өзімнен асып түсе аламын!');
INSERT INTO reflections (day, month, title, text) VALUES (14, 'Ноябрь', 'ШАБЫТТАНУ МЕН ТҮЙСІК', '...Құдайдан шабыт сұрауымыз керек. Шабыт сұрау арқылы танымды ойлар келіп, күрделі мәселелердің шешімін таба аламыз. Біз сабырлы және байсалды боламыз. Біз ешкіммен және ешнәрсемен күреспейміз.

Мен шынымен жақсы көретін іске уақытымды жұмсаймын. Он Бірінші Қадам — Жоғары Күшпен бірге болуыма мүмкіндік береді. Сондай-ақ, тәртіпті сақтау, Құдайдың көмегімен шабыттанып, танымды ойларға ие болуым мүмкін екенін еске салады. Осы Қадамды үнемі орындау арқылы, өзімді қадірлеуді үйренемін. Жоғары Күшпен саналы байланысымды жақсартуға табанды түрде

күш салуым керек. Себебі, бұл әрекетім бір кездегі өзімнің Құдайын танымай асқақтап кеткен өткенімді еске салады. Жаратқанның қалауын орындауға күш сұрағанда, өзімнің дәрменсіздігімді түсінемін. Мойынсұну мен өзіңді қадірлеу сәтті үйлеседі. Бұл, Он Бірінші Қадам бойынша жұмыс істеудің жемісі.');
INSERT INTO reflections (day, month, title, text) VALUES (15, 'Ноябрь', 'ӨМІРЛІК МАҢЫЗЫ БАР ҚОЛДАУ', 'Кез келген тіршілік иесі ауасыз, тамақсыз немесе күн сәулесінсіз өмір сүре алмайды. Сол сияқты дұға етуді әдетке айналдырғандар дұға етпесе, демі тарылып, аяқ алысы қиындайды. Біз өзімізді ауадан, жарықтан немесе тағамнан айырғанда, біздің тәніміз зардап шегеді. Айтқандай-ақ, біз медитация мен дұғадан бас тартсақ өз санамызды, сезімімізді, жан дүниемізді қажетті қорегінен айырамыз.

Он Бірінші Қадам мені басып тастамауы керек. Құдаймен саналы байланыс орнату, адамдарға деген қарым-қатынасымыздан көрініс табады. Сол себепті өзгелерге жылы шырай танытып, мұң- мұқтажын тыңдап, қателіктерін кешіре алуым керек. Өмірімде кездескен адамға жылы қабақ таныта алсам, Құдайдың бар екенін мойындап дұға еткенім. Құдайдың жаратылысының көркемдігін басқа адамдардан қаншалықты көп іздесем, соншалық, Жаратқанның бар екеніне сенгенім. Осы әрекетіммен Жоғары Күшке бір табан жақындай аламын.');
INSERT INTO reflections (day, month, title, text) VALUES (16, 'Ноябрь', 'КҮН САЙЫН КЕЙІНГЕ ҚАЛДЫРУ', 'Рухани өсуіміздің шарты ретінде шешімді (ішімдік ішу туралы) кейінге қалдыру мүмкіндігі беріледі.

Менің рухани күйімді сақтау, күнделікті жұмыс жоспарын құруға, марафонға, жарысқа, жүзуге дайындыққа ұқсас. Нақты

айтқанда, жан дүниені қалпында ұстау, дұға мен ой-толғауды қажет етеді. Мен үшін Жоғары Күшпен саналы байланысымды жақсартудың жалғыз және ең маңызды жолы - дұға ету және ой- толғау. Мен ағын суды теріс ағыза алмайтыным сияқты, алкогольді жеңе алмаймын. Алкоголизмнен ешкім құтқара алмайтыны да анық. Бүгінгі күн қаншалықты ауыр болуы мүмкін. Осы сәтте жолдан тайдыратын алкогольдің қулық-сұмдығынан бостандықта қалу үшін, Бағдарламаның күшіне сүйене аламын. Бұл шешімді кейінге қалдыруымның нәтижесі.

Алайда, қазір қуаныш, бақыт және ақыл-ойдың таза ауасымен дем ала аламын. Айналамда болып жатқан «керемет дүниелердің» куәсі болып, тағы басқа оқиғаларға сүйіспеншілікпен қарауға күш- қуатым бар.');
INSERT INTO reflections (day, month, title, text) VALUES (17, 'Ноябрь', 'ЖАЛҒЫЗДЫҚТАН АРЫЛУ', 'Барлық алкоголиктер жалғыздықтың азабын біледі. Біздің маскүнемдік жантүршігерлік жағдайға жеткенде, адамдар бізден алыстады. Бәріміз дерлік қоғамнан шеттетіліп, зардап шегетінбіз.

Жан дүниемде жиі сезінетін азап пен бос сезім, бүгінгі өмірімде сирек кездеседі. Мен жалғыздықтан қалай құтылуды үйрендім. Мен Құдаймен тек жалғыз және тыныштықта ғана байланыса аламын. Бірақ кеудем қаңырап тұрса, Ол да менімен байланыса алмайды. Бірақ Құдаймен кез келген уақытта байланыста болған дұрыс. Жағдай тым жаман кезде, ой-толғау жасап, дұға оқу өте маңызды.');
INSERT INTO reflections (day, month, title, text) VALUES (18, 'Ноябрь', 'ҚОРҒАНЫС ТОРЫ', 'Кейде ішіміздегі дүмпу күшті болғаны соншалық, мүлде дұға еткіміз келмейді. Егер, осындай жағдай орын алса, біз, өзімізді тым қатаң жазалауға тиіспіз. Мүмкіндігінше қайтадан дұға етуіміз керек, бұл бізге пайдасын тигізбесе, зиянын тигізбейтінін ұмытпағанымыз жөн.

Кейде айқайлап, ашуға бой алдырғаным соншалық, Жоғары Күшімнен теріс айналамын. Сол сәтте ауруым маған жеңілгенімді айтады. Егер, мен, ашулануымды жалғастырсам, сөзсіз ішемін. Мұндай еріксіздік жардан құлап, бір қолмен ұстанып тұрғанмен тең. Жоғарыдағы айтылған дұға ету, мені аман сақтап қалатын тор іспеттес. Неде болса қолымды босатып, торға құлап, бар күш- жігерімді жинап дұға етуге талпынуым керек.');
INSERT INTO reflections (day, month, title, text) VALUES (19, 'Ноябрь', 'МЕН ТЕЗ ҚҰЛАДЫМ', 'Біз, АА мүшелері, белсенді адамдармыз: біз, өмірдің қиындықтарын шешуден рахаттанамыз... Сондықтан, медитация мен дұғаны маңызды деп санамай, оған немқұрайлы қарайтынымыз таңқаларлық іс емес.

Мен, бір кезде Бағдарламадан алшақтап, күйредім. Достастықтың қасиетті Он Бірінші Қадамымен жұмыс істеуге мәжбүрлеген өлім қаупі қайтарды. Он бес жыл ішпей, белсенді түрде бағдарлама бойынша жұмыс істесем де, саулық сапамның айтарлықтай нашарлағанын түсіндім. Он сегіз айдан кейін денсаулығымнан қатерлі ісік анықталды. Дәрігерлердің болжамы бойынша, алты айдан кейін өлуім керек еді. Маған емдеу курсы тағайындалған кезде, бойымды үмітсіздік биледі. Кейіннен екі инсультты бастан өткердім, бұл тағы екі ми ісігінің пайда болуына әкелді. Құлдырауға түскен сайын «неге басымнан ауыр жағдайлар өтіп жатыр?» деп сұрай бастадым. Құдай бұл әрекетімен адал емес екенімді көзіме көрсетіп, өмір сыйлады. Қайтадан өмір сүруді үйреніп, ғажайыптарға кенеле бастадым. Бірақ бұған дейін Он Бірінші Қадамды білсем де, қайтадан қаншалықты маңызды екенін түсінуіме тура келді. Менің әлі де денсаулығым жоқ. Бірақ денсаулығымның жоқтығы, бәрін жоғалтып алу қаупімнің жанында бір болмашы дүние.');
INSERT INTO reflections (day, month, title, text) VALUES (20, 'Ноябрь', 'МЕНІҢ ЕМЕС, СЕНІҢ ҚАЛАУЫҢ БОЛСЫН', 'Біз, Құдайдан өзімізге қажеттіні сұрағаннан кейін сөз соңында:

«Егер, сенің қалауың болса» деген сөзді қосып отырғанымыз жөн. Себебі, Жаратушы бізге не керек екенін, өзімізге қарағанда жақсы біледі.

Мен, күні бойы Құдайдың қалауын түсініп, сондай-ақ, сол қалауын абыроймен атқаратындай ақыл-парасат пен күш-қуат сұраумен боламын. Күнделікті әр түрлі жағдайдайларда не істерімді білмей қалсам: «Менің емес, Құдайдың қалауы болсын» деймін. Әр істе тек өз әрекетіме жауап беремін. Ал берекеті, яғни нәтижесі Жоғарғы Күштің қалауына қарай жүзеге асады. «Менің емес, Сенің қалауың болсын» деп қайталап, өзімді артық жүктен босатып, Құдайға сенім арта аламын. Жаратушының қалауын іздеуге ұмтылуым, мені өзімшілдік мүдделерімнен алыстатады.');
INSERT INTO reflections (day, month, title, text) VALUES (21, 'Ноябрь', 'ДӘСТҮРЛІ ДҰҒА', '«Құдайым, мен, арқылы адамдарға Сенің шарапатың жетсін: жеккөрушілік болған жерде, сүйіспеншілік сыйлайын; жамандық болған жерде, кешірімді болайын; дау болған жерде, сабыр сақтайын; қателіктер болған жерде, шындықты айтайын; күмән болған жерде, сенімді серік етейін; үмітсіздік болған жерде, үміт берейін; қараңғы жерді жарықтандырайын; қайғы басқан жерде, қуаныш сыйлайын. Құдайым, мен жылатуды емес, жұбатуды; айыптауды емес, түсіністік танытуға; ұрысуды емес, ұғысуды; сүйікті болуды емес, сүйе білуді үйренуге тырысамын. Себебі өзіңді ұмытып, өзіңді табасың. Өзгелерді кешіріп, кешірім аласың. Өліп, Мәңгілік өмірге оянасың. Аумин».

Менің рухани өсу кезеңіме қарамастан, осы дәстүрлі дұға өз түсінігімдегі Құдаймен саналы қарым-қатынасымды жақсартуға көмектеседі. Менің Құдайға сенімімнің үлкен артықшылықтарының бірі - оны түсінбеуім деп ойлаймын. Мүмкін, бұл менің Жоғары

Күшпен қарым-қатынасым соншалықты жемісті болғандықтан, оны түсінудің қажеті жоқ шығар. Мен сенімдімін – егер, Он Бірінші Қадамды үнемі толықтай қолдансам, міндетті түрде Құдаймен саналы қарым-қатынасымды нығайтамын, Оның қалауын түсініп, оны орындауға шамам жетеді.');
INSERT INTO reflections (day, month, title, text) VALUES (22, 'Ноябрь', 'ЕКІ-АҚ КЕДЕРГІ БАР', '...екі-ақ кедергі бар: біріншісі - басқа адамның өсуіне кедергі жасау, екіншісі - өзіңнің өсуіңе кедергі жасау.

Бақыт — өте иллюзиялық күй. Менің басқаларға арналған

«дұғаларымның» астарында жатқан, өз өтініштерім пен мүдделерім нені білдіреді? Бақытты болуға талпынысым өзімнен бөлек, өзгелердің рухани өсуіне қаншалықты кедергі жасап жатыр?! Әр іске мойынсұнып, рухани өсу жолдарын іздеу, бастапқыда жақсылық сияқты көрінбеуі мүмкін, бірақ уақыт өте келе, өз жемісін береді. Өткеніме қарасам, ауыртпалықтар мен сәтсіздіктер ақыр соңында, Бағдарлама арқылы рухани өсуіме, яғни, жан тыныштығын табуыма ықпал етіпті.');
INSERT INTO reflections (day, month, title, text) VALUES (23, 'Ноябрь', 'ЖАРЫҚҚА БЕТ БҰРУ', 'Ештеңе көрмесеңіз де, нық сеніммен жарыққа бет бұрыңыз.

Қазан айындағы жексенбі күннің бірі болатын. Таңертеңгі медитация кезінде тереземнің алдындағы күл ағашына қарадым. Мен оның керемет алтын түсіне бірден таңғалдым! Мен Құдайдың өнер туындысын тамашалап, таңдана қарап тұрғанда, жапырақтар түсіп, бірнеше минут ішінде бұтақтар жалаңаштанып қалды. Қыс жақындап келе жатқанына қынжылдым. Бірақ табиғи процестер туралы ойланып тұрғанымда бір ой келді. Күзде жапырақтары түсіп, көктемде қайта гүлдейтін ағаш сияқты, Құдай мені өзімшіл әдеттерімнен тазалап, АА-ның сау және бақытты мүшесі болуым

үшін құтқарса керек. Маусымның өзгергені секілді, үнемі өзгеріп, жаңарып жатқан өмірім үшін, Құдайға ризашылығымды білдіремін.');
INSERT INTO reflections (day, month, title, text) VALUES (24, 'Ноябрь', 'ЖАН-ЖАҚТЫ БОЛУ', 'Бойында иманы бар адамдардың нені дұрыс істейтінін түсінуге тырысыңыз. Олар ұсынған нәрсені пайдаланыңыз.

Мен, барлық рухани сұрақтарға жауаптарым бар деп мәлімдемеймін. Сондай-ақ, алкоголизм туралы да бәрін білемін деп айтудан аулақпын. Жер бетінде рухани ізденістегі адамдар көп. Егер, өзгелердің пікіріне ашық болсам, көп нәрсе үйреніп, түсіне аламын. Сол себепті өз дінімнің құндылықтарын ұстанатын болсам, Он Бірінші Қадам бойынша жұмысым жемісті болады. Салауатты өмірім бапталып, шыңдала түспек. Алкогольден аулақ болуым үшін, жан тәніммен барлық рухани дереккөздерден ақпарат алуға күш саламын.');
INSERT INTO reflections (day, month, title, text) VALUES (25, 'Ноябрь', 'ҚУАТТЫ ДӘСТҮР', '«Анонимді Алкоголиктер» кітабы жарық көргенге дейін, біздің Достастықтың аты жоқ еді. Кітапты «Шығар жол бар» деп атау туралы аз ғана дауыс айырмашылығымен шешім қабылданды. Кейіннен алғашқы мүшелеріміздің бірі «Анонимді Алкоголиктер» деген атпен жарияланған Он Екі Кітапты тапты. Осылайша біз өз тәжірибемізді, рухани маңызды қозғалысымызды «Анонимді Алкоголиктер» деп атадық.

АА Дәстүрлері - олардың қалай дамығаны жайында

A. A. Tradition: How It Developed, pp. 35–36 Билл У. Акрон штатында қонақүйдің сыраханасына барудың орнына, телефон соғу туралы шешім қабылдады. Сол кезден бастап Жоғары Күштің сындарлы сәтте өзін қалай көрсеткенін көрдік! Бұл біз үшін тарихи сәт еді.	Бастапқыда топтағы аз ғана адамдар анонимділік принципінің кейін маңызға ие болатынын болжаған еді.

Біздің Достастықтың атауы кездейсоқ таңдалған болып көрінуі мүмкін.

Негізі, Құдай анонимділікке жат емес және ол «сәттілік»,

«кездейсоқтық» сияқты ұғымдар арқылы адамдардың іс- әрекеттерінде жиі көрінеді. Егер, анонимділік, кездейсоқ болған күннің өзінде, біздің Дәстүрлеріміздің рухани тірегіне айналды. Бәлкім, Құдай біздің атымыздан анонимді түрде әрекет еткен шығар...');
INSERT INTO reflections (day, month, title, text) VALUES (26, 'Ноябрь', 'ЖАРИЯЛАУ ҚАУІПТІ', 'Көпшілік қоғамдық қозғалыстар мен идеяларды жариялағасы келеді. Бұл түпсанадағы маңызды психологиялық қажеттілік. Біз, АА мүшелері бұған күмәнданбаймыз. Бірақ, біз үшін әрдайым назарда болу қауіпті екенін бағамдап, түсінуіміз керек.

Айыққан алкоголик ретінде АА Бағдарламасының адалдық, шынайылық және кішіпейілділікке негізделген қағидаларын іс жүзінде қолдануға тырысуым керек. Ішіп жүргенде әрқашан назарда болуға ұмтылдым. Енді өткен қателіктерімді қайталағым келмейді. Беделге ұмтылуым, АА идеяларын насихаттаумен байланысты болса да, өзімді ақтауға тұрарлық іс емес. АА-ның адамдардың өмірін өзгертіп жатқан ғажайыбы атақтан артық іс емес пе?! Достастықтың көмегімен жаңа өмірге бет бұрып, рухани өсіп жатқан бізге қарап, АА-ның жұмысына қоғам өзі баға бергені жөн. Бұл менің Достастықты көпшілікке дәріптегенімнен, әлдеқайда жақсы ұсыныс болады.');
INSERT INTO reflections (day, month, title, text) VALUES (27, 'Ноябрь', 'НАЗАРДА БОЛУ ҚАУІПТІ', 'Алғашында баспасөз біздің жарнамаға қатысудан бас тартуымызды түсінбеді. Олар біздің анонимділік талабымызға шын жүректен таң қалды. Содан кейін, олар істің мәнін түсінді. Біздің әлемде өз принциптерін жарнамалағысы келетін, бірақ өз мүшелерін жарнамалағысы келмейтін ұйым сирек кездеседі. Баспасөз мұндай көзқарасқа таң қалды. Содан бері олардың АА-ға деген ықыласы, АА-ның ең адал мүшелерінің ықыласынан асып түседі.

Өз өміріммен қатар, Достастықтың өміршеңдігі үшін, АА-ны жеке танымалдылыққа қол жеткізетін құрал ретінде пайдалана алмаймын. Анонимділік мен үшін мойынсұнуды күшейтудің жолы болып табылады. Ең қауіпті кемшіліктерімнің бірі - мақтаншақтық. Ал, мен үшін мақтаншақтықты жеңудің ең тиімді жолы - мойынсұну. АА Достастығы өзінің жұмысын және принциптерін түрлі әдістермен жарықтандыру арқылы бүкіл әлемде танымалдылыққа ие болуда. Ал, оның жеке мүшелері өзін-өзі жарнамалауға мүдделі емес. Өз мүддемнен көптің мүддесін бірінші орынға қоюуым, АА-ның әл-ауқаты үшін, өзімді жарнамалағаннан әлдеқайда қайырлы.');
INSERT INTO reflections (day, month, title, text) VALUES (28, 'Ноябрь', 'ҮГІТ-НАСИХАТ ЕМЕС, ТАРТЫМДЫЛЫҚ МАҢЫЗДЫ', 'Қиын сынақтардан өтіп, біз, өз саясатымызды әзірледік деп ойлаймыз. Бұл әдеттегі жарнамалық тәжірибеге қарама-қарсы. Біздің басты қағидамыз үгіт-насихат емес, тартымдылық қағидасы болуы керек екенін түсіндік.

Ішіп жүрген кезімде, мені өзгертуге тырысқандарға ашуланып, маған аяушылық танытуын талап етіп, қарсыласумен болдым. Менің бар талабым қоғам мені шынайы қалпымда қабылдауын сұраппын. Бұл жағдайды АА-ға келгенде түсіндім. Қазір Достастықтың қоғаммен қарым-қатынастағы қағидасы болып табылатын, тартымдылық тұжырымдамасын сақтауға тырысамын. Тартымдылық - әлі де зардап шегіп жатқан алкоголиктің назарын аудартатын дүние.

Мен, тұрақты Қадамдар мен Дәстүрлер бағдарламасының тартымдылығы үшін Құдайға ризамын. Достастықтың сау мүшелері маған өздерінің кішіпейілділігімен және қолдауымен ұнады. Мен, АА-ға үгіт-насихат арқылы емес, тартымдылығы үшін келдім. Сол тартымдылық жаңа өмір салтын ұстануыма негіз болды.');
INSERT INTO reflections (day, month, title, text) VALUES (29, 'Ноябрь', 'БЕЛСЕНДІ ҚОРҒАУШЫЛАР', 'Біз үшін бұқаралық ақпарат құралдарының үгіт-насихатынан гөрі, ұтымды саясат маңызды. Бұл өз мүддеңді мүлдем жоққа шығару емес. Бұл Дәстүр, бізге үнемі АА-да жеке бас талаптарына орын жоқ екенін еске салады. Әрбір АА мүшесі Достастықтың мүдделерін белсенді түрде қорғауы керек.

Мойынсұнудың негізгі тұжырымдамасы, Он Бірінші Дәстүрде баяндалған. Мойынсұну Бағдарламаға қарапайым көптің бірі болып қатысып, үлкен тұтастықтың ажырамас бөлігі болуымды қамтамасыз етеді. Мойынсұну мені тұтастық пен бірліктің шынайы рухына жақындатады. Онсыз, мен, сау қалпымды сақтай алмаймын. Әрбір Достастық мүшесі - саулықтың үлгісі. Бәрі анонимділікті қолдап, еркіндікті сезініп, Он Бірінші Дәстүр бойынша өмір сүреді.');
INSERT INTO reflections (day, month, title, text) VALUES (30, 'Ноябрь', 'БӘРІНЕ АРНАЛҒАН ҚОҒАНЫС', 'Жалпы анонимділік барлық Достастық мүшелерін қоғам алдында алкоголик ретінде танылудан қорғайды. Бұл, әсіресе, жаңадан келгендер үшін өте маңызды. Бұқаралық ақпарат құралдарында, радио, теледидар және кино деңгейінде анонимділік Достастық мүшелерінің теңдігі айтылады. Бұл АА-ға тиесілі мүмкіндікті пайдаланып, билік пен жеке бас пайдасын көздейтіндерге жол бермеу үшін қажет.

Анонимділікті түсіну Understanding Anonymity, p. 5

Тартымдылық - АА Достастығының басты күші. АА-дағы сау алкоголиктердің жалғасып келе жатқан ғажайыптары, бұл жағдайды күн сайын растайды. Достастық әйгілі қоғам қайраткерлері арқылы, радиодан және теледидардан жарнамалап, өзін насихаттаса көп ұзамай құлдырайтын еді. Себебі, олар кенеттен қайта ішіп кетсе, біздің қозғалысымыз туралы теріс пікір қалыптасады. Бұл жағдай ғасыр кереметінің шынайылығына күмән келтіріп, әлі ауырып жүрген алкоголиктердің АА-дан теріс айналуына әкеліп соғады. «Анонимді Алкоголиктер» Достастағы анонимді емес, бірақ оның мүшелері анонимді болуы керек.');
INSERT INTO reflections (day, month, title, text) VALUES (1, 'Декабрь', 'ҰСЫНЫЛҒАН ҚАДАМДАР', 'Бір ескертпеме тәлімгерімнің барлық Қадамдар «ұсынылады» дегені есімде. «Бұл Қадамдардың барлығы құлап бара жатқан ұшақта кісіге парашют ұсынғанмен тең» деп жауап берген болатын. Сол себепті менің амандығым үшін, Он Екі Қадам бойынша жұмыс

«ұсынылғанын» қатаң ескертті. Мен әрқашан Он Екі «ұсынылған» Қадамға негізделген, айығудың тұтас бағдарламасы бар екенін есте сақтауға тырысамын.');
INSERT INTO reflections (day, month, title, text) VALUES (2, 'Декабрь', 'ЖАН ТЫНЫШТЫҒЫ', 'Бұл Қадамдардың нәтижесі рухани оянуға жету...

Жиналыстарға қатысу және Қадамдар бойынша жұмыс істеу кезінде өзгеріс бола бастады. Мен жаңа пайда болған сезімдерімнің табиғатын түсінбегендіктен абдырап қалдым. Кейіннен бұл жан тыныштығы екенін түсіндім. Бұл жағымды әсер қайдан пайда болды? Артынша бұл өзгерістер Қадамдар нәтижесі екенін түсіндім. Бағдарламаны іс-жүзінде қолдану әрдайым оңай емес. Бірақ жан тыныштығына тек Қадамдар бойынша жұмыс істеп қана қол жеткізгенімді мойындауым керек. Мен Қадамдар бойынша өмірімнің барлық салаларында жұмыс істеп, осы қағидаларды әр істе қолданып, Құдайға, адамдарға және өзіме көңілім ашылғанын түсіндім. Қадамдар бойынша жұмысымның нәтижесінде қол жеткізген рухани оянуым - жалғыз емес екенімді түсіну.');
INSERT INTO reflections (day, month, title, text) VALUES (3, 'Декабрь', 'БІЗДІҢ БАРЛЫҚ ІСІМІЗДЕ…', '...біз өз идеяларымыздың мәнін басқа алкоголиктерге жеткізуге және осы қағидаларды барлық істерімізде қолдануға тырыстық.

Басқа алкоголиктерге айығу идеясын жеткізу, мен үшін оңай деген ойдамын. Себебі, бұл маған сау қалпымды сақтап, сенімді болуыма көмектеседі. Бұл қағидаларды барлық істе қолдану қиынырақ. Мен үшін АА-дан алған жақсылықтармен бөлісу, әсіресе үйде бөлісу маңызды. Алкоголиктерге көрсететін шыдамдылығымды, тыңдай білетін қабілетімді неге отбасыма да көрсетпеске?! Әрдайым күнді қайта қарап, өзімнен сұрауға тырысамын: «Бүгін біреуге дос бола алдым ба?! Дос болуға ниетті жанды елеусіз қалдырмадым ба?!», «Жайсыз жағдайда сабыр сақтай алдым ба?», «Келеңсіз сәтте кешірім сұрай алдым ба?». Ішімдік ішпеуім өз алдына бөлек мәселе... Бірақ айыққаным, өмірімнің барлық қырынан көрінсе деймін.');
INSERT INTO reflections (day, month, title, text) VALUES (4, 'Декабрь', 'ІСКЕ КІРІСУ', 'АА - бұл жай ғана қағидалар жиынтығы емес; бұл белсенді алкоголиктердің қоғамы. Біз бұл идеяны жеткізуіміз керек, әйтпесе біз құримыз. Сондай-ақ, бұл жолға жете алмағандар өліп қалуы мүмкін.

Мен қатты өмір сүргім келді. Бірақ аман қалу үшін, Құдай берген Бағдарламаға белсенді қатысуым керек еді. Кейінірек менің тобыма айналған топқа қосылып, кеңсеге жауапты болдым, кофе дайындадым және бөлмені тазаладым. Үш айдай саулықта болғанымда, тәжірибесі бар бір АА мүшесі Он Екінші Қадам бойынша жұмыс істеп жатқанымды айтты. Мұны білу мен үшін қаншалықты қуанышты болды! Мен шынымен бір нәрсеге қол жеткізгенімді сездім. Құдай маған тағы бір мүмкіндік берді, АА жол көрсетті, ал, бұл мен үшін баға жетпес сыйлықтар болды! Енді жаңадан келгендердің өсуін қуана бақылап отырмын. Олар маған

қайдан келгенімді, қазір қайда екенімді және менің алдымда қандай шексіз мүмкіндіктер ашылатынын еске салады. Жиналыстарға қатысуым керек, себебі олар қажет болған кезде, жарық шашуым үшін батареямды зарядтайды. Мен қызмет көрсетуді енді бастадым, бірақ бергеннен де көп алдым. Егер, көптің игілігі үшін іс қылмасам, өзімнің сау қалпымды сақтай алмаймын. Біреу көмек сұрағанда жауап беремін. Сол үшін де сау болуым керек!');
INSERT INTO reflections (day, month, title, text) VALUES (5, 'Декабрь', 'САНАНЫҢ ЖАҢА ДЕҢГЕЙІ', 'Мұндай адам жаңа сана мен жаңа өмірге тең сыйлық алады.

Көптеген адамдар АА-да рухани оянудың не екенін түсінбей қалады. Мен әсерлі, таң қалдыратын ғажайып іздеуге бейім болдым. Бірақ әдетте, әл-ауқат пен тыныштық сезімі, бізді жаңа сана деңгейіне шығарады. Менің жағдайымда бұл осылай жүзеге асты. Ессіздік пен ішкі жайсыздық жоғалып, үміт, сүйіспеншілік, тыныштық сынды руханият патшалығындағы жаңа өлшемге ендім. Бұл шат көңіл, жаңа сезімдер АА-ның Он Екі Қадамымен жұмыс істегендегі шынайылық, сүйіспеншілік және адалдықпен тікелей байланысты деп ойлаймын.');
INSERT INTO reflections (day, month, title, text) VALUES (6, 'Декабрь', 'ШЕШУШІ СӘТ', 'Біз дамуымыздың жоғары деңгейіне көтерілгенде, эмоционалды тұрақтылықтың қайнар көзі - Құдай екенін анықтадық. Біз, Жаратушының мінсіз әділдігіне, кешіріміне және сүйіспеншілігіне тәуелді болсақ, жан саулығына ықпал ететінін және еш жерден көмек күту мүмкіндігі болмаған кезде, көмектесетінін білдік. Егер, біз, Құдайға шын мәнінде тәуелді болсақ, бөзгелердің алдында өзімізді Құдай сезінбейміз. Сондай-ақ, ешкімнің қорғауы мен қолдауына толықтай тәуелді болып қалмаймыз.

Өз тәжірибемнен білемін, барлық мүмкіндіктер сарқылғандай көрінгенде, мені ешқашан тастамайтын Біреу бар. Оның үстіне, Ол

әрқашан менімен бірге, менің қуанышымды бөлісіп, дұрыс жолға бағыттайды. Сондай-ақ, Оған сенім артқандай, ешкімге сенім арта алмаймын. Менің мал-мүлкімді адамдық күш-жігермен көбейтіп немесе азайтуға болатын болса, ал жан дүниемді тек Құдай ғана сүйіспеншілікпен қоректендіре алады. Күнделікті рухани саулығым сол қорекке байланысты...');
INSERT INTO reflections (day, month, title, text) VALUES (7, 'Декабрь', 'НАҒЫЗ ТАЛАП', 'Нағыз талап - біз ойлағандай емес. Бұл - пайдалы болуға деген ұмтылыс және Құдайдың шарапатында кішіпейілдікпен өмір сүру.

Мен ішіп жүргенде: «Айналамдағылардың бәрі мен туралы жоғары пікірде болуы керек» деген бір ғана қайғым болды. Әр істеген ісімнен «бәрінен биік болсам» деген ұмтылысым көрініп тұратын. Ішкі даусым әрқашан басқаша айтатын, бірақ оны қабылдай алмадым. Әрқашан бетперде киіп жүретінімді мойындағым келмеді. Ақырында, бетпердем сыпырылғанда, амалсыз өз түсінігімдегі Құдайға жалындым. Құдай оңдап, АА Достастығы, менің тобым және Он Екі Қадам көзіме көрінді. Мен ренішті келісімге, қорқынышты үмітке, ашуды сүйіспеншілікке айналдыруды үйрендім. Қайтымын күтпей, адамдарға сүйіспеншілік сыйлауды, достарыммен өз уайымдарды бөлісіп, оларға қамқорлық жасай алдым. Нәтижесінде әр күннің қуанышты және жемісті бола алатынын білдім. Ертелі-кеш мені осы күнге жеткізген мейірімі шексіз Құдайға алғыс білдіремін!');
INSERT INTO reflections (day, month, title, text) VALUES (8, 'Декабрь', 'ҚЫЗМЕТ', 'Сіздің өміріңіз жаңа мағынаға ие болады. Адамдардың қалпына келіп, басқаларға көмектесе бастағанын, айналамызда бауырластықтың пайда болғанын көріңіз. Достардың көбеюі құнды тәжірибені өзімен бірге алып жүреді, оны елемеуге болмайды... Жаңадан келгендермен және бір-бірімізбен жиі байланыс орнату, сіздің өміріңіздің жарқын оқиғаларына айналады.

Ең үлкен марапаттарды тек қызмет арқылы алуға болады. Бірақ басқаларға шынайы, пайдалы және тиімді қызмет ету үшін, ең алдымен өзіммен жұмыс істеуім керек. Бұл өзімді Құдайға тапсырып, кемшіліктерімді мойындап, өткен өмірімді тазартып алуымды білдіреді. Шабыт пен тәжірибені біріктіріп, өзім аңсаған жан тыныштығына қол жеткіздім. Бұл өзіммен дұрыс жұмыс істеуімнің нәтижесі. Жаһандық салауатты өмірдің бір күре тамыры бола алғаныма қуанамын!');
INSERT INTO reflections (day, month, title, text) VALUES (9, 'Декабрь', 'ЕШҚАНДАЙ ШАРТСЫЗ СҮЙІСПЕНШІЛІК', 'Он Екінші Қадамның мағынасын толық түсіну, құны шексіз сүйіспеншіліктің не екенін түсінуге мүмкіндік береді.

Он Екінші Қадаммен жұмыс істеу үшін, шынайылық пен адалдықты ту етіп, мойынсұнып үйренуім керек еді. Біздің идеяларымыздың мәнін басқаларға жеткізу үшін, жинақтаған саулық жылдарыңнан бөлек, бұл іске өзіңді арнауың керексің. Армандарым шындыққа айнала алады. Мен алған дүниелеріммен бөлісіп, өз саулығымды күшейтемін. Қазір, айығуға келген бірінші күннен бастап, басқа алкоголиктің қалпына келуіне, рухани өсуіне көмектесе алғанымды көремін. Басқа алкоголикке көмектесу ниеті, жан саулығымның кілті болып табылады. Бірақ ешқашан Құдай мен арқылы әрекет ететінін ұмытпаймын. Мен, жай ғана себепкермін. Нақтырақ айтқанда, Құдайдың ізгілік жасаушы құралымын.

Басқа адам өзгеруге дайын болмаса да, мен ұтылмаймын. Оған бағытталған күш-жігерім саулығымды күшейтіп, төзімімді шыңдады. Он Екінші Қадам бойынша үздіксіз жұмыс істеу - сәттіліктің кепілі. Бүгін шаттыққа кенеліп күле аламын. Бірақ Құдайым мені сол бір аянышты күндерді ұмытудан сақтасын, көзіме жас алдым. Көз жасым шүкірлік етпесем, қиын күндердің ауылы алыс емес екенін еске салады!');
INSERT INTO reflections (day, month, title, text) VALUES (10, 'Декабрь', 'ИДЕЯЛАРЫМЫЗДЫҢ МӘНІН ЖЕТКІЗУ', 'Ал, Он Екінші Қадамның мазмұны қандай? Оның ғажайып энергиясының сәулесі, басқа да азапталып жүрген алкоголикке біздің хабарымызды жеткізетін ынталы әрекет. Ақырында, Он Екі Қадам барлық ісімізде, өмірімізде орын алады. Бұл АА-ның бізге берген марапаты мен жанға жағымды шындығы.

Ішімдік ішпеу алкогольдік әлемнен алыстауды білдірмейді. Бірақ жоғары бағалайтын принциптер бойынша әрекет ету керек. Яғни, ішімдіктен зардап шегіп жүргендерді өзім сезінген жан тыныштығына жеткізу. Егер, бұл мақсатқа шын жүректен берілсем, ішер ас пен киер киім мен үшін уайым болмайды. Менің міндетім - айығу идеясын жеткізу және оны үгіт-насихатсыз, үлгі арқылы көрсету.');
INSERT INTO reflections (day, month, title, text) VALUES (11, 'Декабрь', 'ШЫНАЙЫ МОЙЫНСҰНУ', 'Бізге берілген үлкен ырыздық жолдан тайдырмас үшін, біз шынайы мойынсұну қағидасын ұстануымыз керек. «Басы ауырмаған кісінің Құдаймен ісі жоқтың» кейпін кешіп кетпегеніміз жөн.

Менің тәжірибем, алкогольдік тұлғамды керемет дүниеге айналдыруға болатынын көрсетті. Мен «дұрыс ісімді» жүзеге асыру үшін, жақсы ниетпен әрекет етсем де, кейде біртүрлі жағдай болады. Менің өзімшілдігім, мені басып озып, бастапқы мақсатымды ұмытып кетемін. Мен, тіпті өмірімдегі Құдайдың ісін өзіме меншіктеп аламын. Өзін-өзі асыра бағалау сезімі менің саулығым үшін өте қауіпті және АА-ға жалпы зиян келтіруі мүмкін. Менің қорғанысым - бұл мені мойынсұнуға апаратын Он Екінші Дәстүр. Мен, өз жетістіктерімді мақтан тұта алмайтынымды және «Өзіміз үшін істей алмаған істі Құдай істей алатынын» жеке адам ретінде де, Достастық мүшесі ретінде де түсінемін.');
INSERT INTO reflections (day, month, title, text) VALUES (12, 'Декабрь', 'ОРТАҚ ШЕШІМ', 'Әрқайсымыздың мәселемізді шешетін жалпыға ортақ кілт таптық.	Бәріміздің келісіміміз болғандықтан, үйлесімді бауырластық одақта бірыңғай механизмде қозғала аламыз. Маскүнемдіктен зардап шеккен кітап өз алдына... Бұл жаңа дүниелердің жиынтығы болмақ.

Он Екінші Қадам бойынша атқарған ең игі ісіміз: Бұл Үлкен Кітап - «Анонимді Алкоголиктердің» жариялануы болды. Онымен салыстыратын дүние аз, ол АА идеяларын таратады. Мен өзімнен өзім алыстап, қолымнан келетін істі істеуім керек. Мені тәлімгер болуға шақырмаса және телефоным сирек шырылдаса да, Он Екінші Қадам бойынша жұмыс істеуге қабілеттімін. Мен «бауырластыққа негізделген үйлесімді әрекетпен» айналысамын. Мен адамдармен сәлемдесіп, өз тәжірибемді, үмітім мен барымды бөлісу үшін кеңсеге ертерек келемін. Әлбетте, кеңсені тазалау, адамдарды күтіп алу сынды қызметтер назарымнан тыс қалмайды. Мен өз күшімнің шамасына қарай әрекет етемін. Жоғарғы Күш айығуымның осы кезеңінде, мен үшін не маңызды екенін анықтайды. Егер, Жаратушыға сенім артсам, Он Екінші Қадам бойынша жұмыс істеуге дайын боламын.');
INSERT INTO reflections (day, month, title, text) VALUES (13, 'Декабрь', 'ӨЗГЕЛЕРДІ ОЙЛАУ', 'Біздің өмір сүруіміз (алкоголиктер) өзгелерге қамқорлық жасап, қоғамға пайдалы болуымызға байланысты.

Мен өзгелер туралы ойлауға тырысқан емеспін. АА Бағдарламасымен жұмыс істеу барысында да: «Бүгін өзімді қалай сезінемін? Мен бақыттымын ба, қуаныштымын ба, еркінмін бе?» деп ойлаймын.

Бағдарлама ойларымды айналамдағы адамдарға бағыттау керектігін ескертті: «Жаңадан келген адам біреумен сөйлескісі келе ме?», «Бұл адам бүгін қайғылы көрінеді, оны жігерлендіре аламын

ба?» деген сауалдар болу керек. Өзгелерге көңіл бөле бастағанда, өз мәселем ұмытылып, жаным жай тауып, Құдайымды таниды екенмін.');
INSERT INTO reflections (day, month, title, text) VALUES (14, 'Декабрь', 'ӨЗГЕЛЕРМЕН БЕТПЕ-БЕТ КЕЛУ', 'Алкоголиктерге моральдық және рухани биіктен қарауға тырыспаңыз. Тек айығуыңызға септігін тигізген рухани мүмкіндіктер туралы баяндаңыз.

Жаңадан келген адамға АА-да жеткен жетістіктерім тұрғысынан қараймын ба? Достастықтағы көптеген таныстарыммен салыстырамын ба? Менің сөздерімде, мен оған АА туралы айтқанда, насихат пен ақыл айтудың көлеңкесі бар ма? Менің оған деген шынайы қарым-қатынасым қандай? Жаңадан келген адамға АА идеясын кішіпейілділікпен, қарапайымдылықпен және мәрттікпен жеткізіп жатқанымды тексеру үшін, өзімді талдауым керек. Бұл қорқынышты аурудан – алкоголизмнен әлі де зардап шегіп жүрген адам, мені бейне бір ұстаз емес, дос, сырлас ретінде қабылдай алуы керек. Сонда ғана АА идеясын еркін, түсіндере алмақпын. АА-ға келгенде менің де досым болды. Енді мен, алкоголик аға-әпкеме сүйіспеншілікпен қол ұшын созып, оларға бақытқа апаратын жолды көрсетуге мүдделімін.');
INSERT INTO reflections (day, month, title, text) VALUES (15, 'Декабрь', 'КӨМЕКТЕСУ ҮШІН БАР КҮШТІ САЛУ', 'Алкоголикке көмегіңіз бен достығыңызды ұсыныңыз. Егер ол ішуді тоқтатқысы келсе, сіз оған көмектесу үшін бар күшіңізді салатыныңызды айтыңыз.

Он Екінші Қадам бойынша, менімен жұмыс істеген екі АА бауырымды қалай жақсы көргенімді есіме аламын. Олар өздерінде бар дүниені ешқандай шартсыз ала алатынымды айтты. Менен бір ғана дүние талап етілді. Ол - айығу жолына қосылу туралы шешім қабылдау. Жаңадан келген адамды мені қалай қабылдады, дәл солай

ыстық ықыласпен қабылдауға мүдделімін. Егер, олай істей алмасам өткенімді ұмытып, есіргенім...');
INSERT INTO reflections (day, month, title, text) VALUES (16, 'Декабрь', 'САУЫҒУ ЖОЛЫНДАҒЫ СЕРІКТЕСТЕР', '...басқа алкоголиктермен қарқынды жұмыс істеу, алкогольге ең тұрақты иммунитет береді. Өз қамқорлығыңыздағы жанмен күн сайын рухани даму жолымен жүруіңіз керек. Жоғарғы Күштің нұсқауларын орындаңыз, уақыт өте келе, баянды болашақта жаңа ғажайып әлемде өмір сүретін боласыз.

Дұрыс және ақылға қонымды әрекет ету - менің менмендігім мен өзімшілдігімді бақылаудың жолы. Мен, Жоғарғы Күшке тәуелді болсам, жан тыныштығына, бақытқа және саулыққа жол ашылатынын түсінемін. Күн сайын өткен қателіктерді қайталамай, өзгелерге пайдалы болуға тырысып, дұға етемін.');
INSERT INTO reflections (day, month, title, text) VALUES (17, 'Декабрь', 'БАҒА ЖЕТПЕС МАРАПАТ', '...басқа алкоголиктермен жұмыс істеу. Ол басқа барлық құралдар пайдасыз болған жерде көмектеседі.

«Өмір жаңа мағынаға ие болады», - деп айтылады Үлкен кітапта (Анонимді Алкоголиктер, 89-бет). Бұл Уәде мені өзімшілдіктен және өзіме деген аяушылықтан құтылуға көмектесті. Адамдардың осы керемет Бағдарламада қалай өсіп, олардың өмір сүру сапасы қалай жақсарғанын көру - бұл мен үшін баға жетпес марапат. Бірақ салауатты өмір ұстанғаның үшін басқа да сыйақылар бар - бұл өз- өзіңді талдауға қабілеттілік, сан жылдан бері аңсаған жан тыныштығы. Басқа адамдарды сәттілік жолында көргенде, оларға осы ғажайып жолмен жүру қуанышын бөліскенде, өміріме жаңа мән беретін энергия аламын.');
INSERT INTO reflections (day, month, title, text) VALUES (18, 'Декабрь', 'ЖАҢАДАН КЕЛГЕНДЕРМЕН ШЫНАЙЫ БОЛУ', 'Оған	барлық	шындықты	айтыңыз.	Қалай	рухани айыққаныңызды ерекше атап өтіңіз.

АА-ның керемет жері – басымнан өткен, өтіп жатқан дүниелерді ғана айтамын. Мен әлеуетімді жаңадан келгендерге кеңес беруге уақыт жұмсамаймын. Себебі, кеңес көмектесетін болса, ешкім АА-ға келмейтін еді. Мен істеуім керек дүние – салауатты өмір салтын ұстанып, өмірімнің қалай өзгергенін көрсету. Егер, АА бағдарламасының рухани бағытын ерекше атап өтпесем, адал болмағаным. Жаңадан келген адамда саулық туралы жалған түсінік болмауы керек. Мен тек Жоғарғы Күштің ықпалымен саумын, сондықтан өз тәжірибемді өзгелермен бөлісе аламын.');
INSERT INTO reflections (day, month, title, text) VALUES (19, 'Декабрь', 'АЛКОГОЛИЗМНІҢ АУРУ ЕКЕНІН ТҮСІНУ', 'Алкоголикпен жұмыс істегенде, бұл адамның қалай соншалықты әлсіз, ақымақ және жауапсыздығына қарап жиі ашуланасыз. Ал, сіз бұл ауру туралы көбірек білгенде, бұл сезім күшейуі мүмкін.

Алкоголизмнен зардап шеккендіктен, бұл ауруды түсінуім керек. Бірақ кейде АА-да табысқа жете алмайтын адамға ашуланып, тіпті жиіркенемін. Мұндай сезім пайда болғанда, бұл менің өзімнің жалаң түсінікке елігіп, асқақтап бара жатқанымды білдіреді. Мен, бұл жерде тек Құдайдың шарапатымен жүргенімді есте сақтауым керек.');
INSERT INTO reflections (day, month, title, text) VALUES (20, 'Декабрь', 'АҚЫ ТАЛАП ЕТПЕЙТІН СЫЙЛЫҚТАР', 'Бұл берілген сыйлықтар ақысына ештеңе талап етпейді. Алкоголизммен ауыратын адамнан ешқандай төлем немесе сүйіспеншілік күтпейді. Бұл өзін-өзі қамтамасыз ету сыйлықтары, басқа алкоголикке көмектесе алсақ та, көмектесе алмасақ та беріледі.

Мен Он Екінші Қадам бойынша жұмыс істеу барысында қайтарымсыз жақсылық жасау арқылы, қандай сыйақы алатынымызды түсіндім. Бастапқыда басқа адамдар да қалпына келеді деп күттім, бірақ көп ұзамай бұлай бола бермейтінін көрдім. Он Екінші Қадам бойынша жұмыс, әрдайым табысты бола бермейтінін қабылдаған кезде, қайтымын күтпей жақсылық жасауға бейімделемін. Сондай-ақ, Жоғарғы Күш әр игі ісімді марапатсыз қалдырмайтыны анық.');
INSERT INTO reflections (day, month, title, text) VALUES (21, 'Декабрь', 'ТЫҢДА, БАРЫҢМЕН БӨЛІС, ДҰҒАДА БОЛ', 'Алкоголик пен оның отбасына көмектескенде, олардың жанжалдарына араласпау керек. Аралассаңыз, бұл адамдарға болашақта көмектесу мүмкіндігінен айырыласыз.

Мен серіктес алкоголикке көмек барысында, кеңес беруге жиі тырысамын. Бұл менің табиғи құлшынысым болуы мүмкін. Бірақ өзгелердің де қателік жасауына мүмкіндік беру керек. Менің өзгелер үшін қолымнан келетіні, тыңдау, жеке тәжірибеммен бөлісу және дұға ету. Бұл айтуға оңай болғанмен, орындалуы қиын шаруа.');
INSERT INTO reflections (day, month, title, text) VALUES (22, 'Декабрь', 'ТҰЛҒАЛАР ЕМЕС, ҚАҒИДАЛАР', 'Кейбір «құрметті» алкоголиктер «лайықсыздарды» сынауға тырысады. Бұл сырт көзге бір алкоголиктің, екінші алкоголикті ішімдік ішкені үшін соттап жатқандай күлкілі көрінеді.

Өзгелерді сынайтын мен кіммін? Мен, Достастыққа алғаш келгенде, бәрі маған ұнады. Түптеп келгенде АА менің ішімдіксіз жаңа, жақсы өмір сүруіме көмектесуі керек еді. Дегенмен, бәрін бірдей жақсы көре алмадым, мен де біреулерге ұнамадым. Ақырында, рухани өсе келе, жай ғана тыңдау арқылы, кімді болмасын кемшілігіне қарамастан, жақсы көруді  үйрендім. Анау

алыстағы немесе жанымдағы кісі маған қажет нәрсені жеткізу үшін, Құдай таңдаған адам болуы мүмкін. Мен әрқашан жеке тұлғалардан гөрі қағидаларды жоғары қоюым керек.');
INSERT INTO reflections (day, month, title, text) VALUES (23, 'Декабрь', 'САУЫҒУ, БІРЛІК, ҚЫЗМЕТ', 'Біздің Он Екінші Қадамымыз - идеяларымызды жеткізу. Бұл АА Достастығының қызмет етудегі негізгі формасы болып табылады. Бұл біздің басты міндетіміз және өмір сүруіміздің негізгі мақсаты.

Менен бұрын келгендер үш Уәдені, яғни, Сауығу, Бірлік және Қызметті ұмытпау керек екенін ескерткен еді. Сол үшін оларға алғыс айтамын. Менің тобымда ілінген тақтайшада жазулы тұр: «Үш аяқты орындық, бір немесе екі аяғы жоқ болса қолданысқа жарамсыз болады. Сол себепті біздің үш Уәдеміз бұзылмай, бүтін болуы керек. Сауығуда біз бірге жазыламыз, Бірлікте Қадамдарымыз бен Дәстүрлеріміздің игілігі үшін, бірге жұмыс істейміз, Қызмет көрсету арқылы, біз ақысыз алғанымызды, тегін береміз». АА қағидаларына сай бірыңғай механизмде сауығу жолын ұстанбасам, өзгелермен бөлісер ештеңем болмайды.');
INSERT INTO reflections (day, month, title, text) VALUES (24, 'Декабрь', 'ӨЗГЕЛЕР ҮШІН САНАЛЫ, БАҚЫТТЫ ӨМІР СҮРУ', 'Біздің ойымыз көкте болғанымен, бірақ жерде екі аяғымызды нық басып жүруіміз керек. Барлық достарымыз және негізгі жұмысымыз жерде екенін ұмытпаған абзал. Бұл өміріміздің шынайы көрінісі. Біз ниетімізді өзгелерге көмектесуге бағыттасақ, бақытты өмірдің үйлесімін тауып, жан тыныштығына қол жеткіземіз.

Іс-әрекетпен расталмаған дұға мен медитацияның ешқандай құны болмайды. Мен өмірімнің барлық саласында АА қағидаларын қолдана отырып, Құдайдың қамқорлығын сезінемін. Дүниеден алыстап, жүрегіме терең бойлағанда, Құдай менің әлеміме енеді.');
INSERT INTO reflections (day, month, title, text) VALUES (25, 'Декабрь', 'ҮЙЛЕСІМДІ ӨМІР', 'Әр күнгі әрекеттерімізде Құдайдың қалауын жүзеге асыруымыз керек. «Саған қалай қызмет етемін? Менің емес, Сенің қалауың болсын».

Күн сайын таңертең осы үзіндіні оқып, «бұл қағидаларды барлық істе қолдануым керек екенін» үнемі еске саламын. Мен, Құдайдың қалауын үнемі есімде ұстасам, істей алмайтын істерді істей аламын. Бұл менің өзіме, өмірге, және Құдайға деген көзқарасымды түзейді.');
INSERT INTO reflections (day, month, title, text) VALUES (26, 'Декабрь', 'СӘТТІЛІКТІ ДЕ, СӘТСІЗДІКТІ ДЕ ҚАБЫЛДАУ', 'Нәтижесі белгісіз, бізге тиімді немесе тиімсіз аяқталатын жағдайда не істемек керек?! Бұл жағдай қалай аяқталса да, көңіл толқытпай қабылдай аламыз ба? Тиімді болса асқақтап кетпей, тиімсіз болса қапаланбай, өзімізді бір қалыпта ұстай аламыз ба?! Кедейлікке, ауруға, жалғыздыққа және жоқшылыққа шыдамдылық танытып, мойынсұна аламыз ба?! Өзіміз аңсаған дүниеге қолымыз жетпей қалғанда, еш уайымсыз қолда барға қанағат етіп, қуана аламыз ба?!

Ішуді тоқтатып, АА-ны тапқаннан кейін, Бірінші Қадамның не себепті: «алкоголь алдында толық дәрменсіздік және өз-өзіңді бақылауды жоғалту» деген екі тараудан тұратынын түсіну үшін біраз уақыт қажет болды. Сол сияқты, Он Екі Қадаммен жүру, тек

«алкоголиктерге осы идеяларды жеткізу» деп қателесіп келдім. Бұл тым асығыс тұжырым екен. Мен, барлық Он Екі Қадамды, Он Екінші Қадамның бір ғана ережеден тұрмайтынын ұмытып кеттім. Ақырында, өз өмірімнің барлық салаларында осы қағидаларды қолдануым керек екенін түсіндім. Барлық Қадамдармен тыңғылықты жұмыс істеу арқылы, тек сау болып қана қоймай, басқалардың да саулыққа қол жеткізуіне көмектесемін. Өмірдегі барлық қиындықтарды қуанышқа айналдырамын.');
INSERT INTO reflections (day, month, title, text) VALUES (27, 'Декабрь', 'МӘСЕЛЕЛЕРДІ ШЕШУ', 'Менің барлық мәселелерімді рухани қағидалар шешетінін білдім.

Үлкен Кітапта сипатталған айығу процесінде, алкоголизммен жұмыс істеуге арналған барлық ұсыныстар, өмірдің көптеген басқа салаларына да қатысты екенін түсіндім. Мен ашуланғанда немесе көңілім қалған кезде, бұл менің ішкі негізгі мәселемнің, алкоголизмнің көрінісі деп есептеймін. Қадамдармен жүйелі жұмыс істей алсам, қиындықтар Он Екінші «ұсынысқа» жетпей тұрып шешіледі. Қалғандары өз идеяларымызды басқаларға жеткізуге күш салғанда «емделеді». Бұл қағидалар менің мәселелерімді шынымен шешеді! Бұл мәлімдемеден ешқандай ерсілік көрмедім. Бұл қағидалар, менің қоғамда пайдалы ғұмыр кешуіме ықпал етіп, салауатты өмір салтына жетеледі.');
INSERT INTO reflections (day, month, title, text) VALUES (28, 'Декабрь', 'ӨЗІҢДІ РЕТКЕ КЕЛТІРІП, СЫРТҚА ШЫҚ', 'Бір кезеңде әлемнен оқшауланып қалғанымыз жасырын емес. Қазір сол қоғамның толық қанды мүшесі болуға ұмтыламыз. АА- ның сауығудан бөлек, бізге берер тағы бір сыйы осы. Бұл соңғы мақсат болғанмен, Он Екі Қадамның бірінші және соңғы кезеңі емес.

«Өзіңді ретке келтіріп, сыртқа шық» дейтін ескі мақал бар. Бұл өте маңызды болғандықтан, нақыл сөзді өзіме ұран етіп алғанмын. Әр күн сайын шықсам да, шықпасам да болады. Бұл менің таңдауым. Жиналыстарға қатысып, өзімді топтың бір бөлігі ретінде сезінемін. Сондай-ақ, жиналыста айтқанымды іс жүзінде жүзеге асыруға тырысамын. Мен жаңадан келгендермен сөйлесіп, өз тәжірибеммен бөлісе аламын. Бұл әрекетім сенім, адалдық және қайырымдылықтың белгісі. «Өзіңді ретке келтіріп, сыртқа шық» деген нақыл сөз - шынайы өмірге оралу жолындағы нақты әрекеттің көрінісі.');
INSERT INTO reflections (day, month, title, text) VALUES (29, 'Декабрь', 'ӨМІРЛІК ҚУАНЫШ', '...өмірлік қуаныш - АА-ның Он Екінші Қадамының тақырыбы.

АА - қуанышты бағдарлама! Алайда, кейде алға жылжысам шаттыққа кенелетінімді білсем де «тоқтауға» мәжбүр боламын. Егер, бұл әрекеттер өмірімнің ең осал жақтарына, яғни, мойынсұнуыма, ұстанған қағидаларыма керағар болмаса, қарсы әрекет етпес едім. Дүниенің сауық-сайраны өзіме ұнағанмен, арты жақсылықпен аяқталмайтыны анық. Әлбетте, мені бұл жағдайдан АА-ның барлық мүшелеріне көмектесе алатын, қуаныштың күші тоқтатады.');
INSERT INTO reflections (day, month, title, text) VALUES (30, 'Декабрь', 'АНОНИМДІК', 'Анонимдік - барлық Дәстүрлеріміздің рухани негізі, ол бізге үнемі жеке тұлғаларға емес, қағидаларға назар аударуымыз керектігін еске салады.

Он Екінші Дәстүрдің маңыздылығын, салауатты өмірімнің алғашқы күндерінде-ақ сезіндім. Он Екі Қадаммен бірге, ол менің айығуымның міндетті шарты болып қала береді. АА-ға келгелі, мінезімде ақаулар бар екенін аңғардым. Дәстүр идеясының нәтижесінде, алкогольге, онымен байланысты ашу-ызаға дұрыс реакция білдіруге болатынын түсіндім. Он Екінші Дәстүрді «менің» ашуымды басудың бірден бір амалы ретінде қабылдаймын. Сондай- ақ, Бағдарлама қағидаларын, өмірдің барлық саласына жарамды әдіс ретінде қарастырамын. Барлық Қадамдар, әсіресе, бұл Дәстүр, мені сан жылдан бері саулық жолымен жетелеп келеді. Қиналған кезімде менімен болғандардың бәріне ризамын.');
INSERT INTO reflections (day, month, title, text) VALUES (31, 'Декабрь', 'КҮНДЕЛІКТІ ШЕШІМ', '«24 сағат өмір сүру» идеясы негізінен адамның эмоционалдық ахуалын қамтиды. Эмоциялық тұрғыдан біз кешегі немесе ертеңгі күнмен өмір сүрмеуіміз керек.

Жаңа жыл: 12 ай, 52 апта, 365 күн, 8760 сағат, 525600 минут - болашақтағы мақсаттарды, бағыттарды, әрекеттерді ойланатын уақыт. Қалыпты өмір сүру үшін, көп дүниелерді жоспарлауым керек. Бірақ эмоционалды түрде жиырма төрт сағаттық шеңберден шықпауға тиіспін. Сол себепті бүкіл жаңа жылға жоспар құрудың қажеті жоқ! Мен әр күнді Жаңа жыл күніне айналдыра аламын! Күн сайын: «Бүгін мен мұны істеймін... Бүгін мен мынаны істеймін», - деп шешім қабылдауға мүмкіндігім бар. Сондай-ақ, бүгінгі күнімнің кешегіден жақсы, һәм мән-мағыналы өтуіне күш саламын. Әр істе АА Бағдарламасының қағидаларынан аттамай, Құдайдың қалауын орындауға тырысатын боламын.');